DateTime? _trackerParseServerInstant(dynamic value) {
  final raw = '${value ?? ''}'.trim();
  if (raw.isEmpty || raw == 'null') return null;
  final normalized = raw.replaceFirst(' ', 'T');
  final hasZone = RegExp(r'(Z|[+-]\d{2}:?\d{2})$', caseSensitive: false)
      .hasMatch(normalized);
  if (hasZone) return DateTime.tryParse(normalized)?.toUtc();

  final naive = DateTime.tryParse(normalized);
  if (naive == null) return null;
  // Серверные MySQL-строки без timezone считаем UTC.
  return DateTime.utc(
    naive.year,
    naive.month,
    naive.day,
    naive.hour,
    naive.minute,
    naive.second,
    naive.millisecond,
    naive.microsecond,
  );
}

DateTime? _trackerMoscowDateTime(dynamic value) {
  final instant = _trackerParseServerInstant(value);
  if (instant == null) return null;
  final moscow = instant.add(const Duration(hours: 3));
  // Возвращаем wall-clock Moscow без зависимости от timezone устройства.
  return DateTime(
    moscow.year,
    moscow.month,
    moscow.day,
    moscow.hour,
    moscow.minute,
    moscow.second,
    moscow.millisecond,
    moscow.microsecond,
  );
}

DateTime _trackerMoscowFromEpochMs(int millisecondsSinceEpoch) {
  final moscow = DateTime.fromMillisecondsSinceEpoch(
    millisecondsSinceEpoch,
    isUtc: true,
  ).add(const Duration(hours: 3));
  return DateTime(
    moscow.year,
    moscow.month,
    moscow.day,
    moscow.hour,
    moscow.minute,
    moscow.second,
    moscow.millisecond,
    moscow.microsecond,
  );
}

class TrackerAnalyticsSelectionState {
  TrackerAnalyticsSelectionState({
    required Iterable<int> sessionIds,
    required Iterable<int> playerIds,
    required this.useAllSessionsForPeriod,
    required this.selectedDate,
    required this.sessionKindFilter,
    Iterable<TrackerSessionModel> sessionRows = const <TrackerSessionModel>[],
  })  : sessionIds = List<int>.unmodifiable(
          sessionIds.where((id) => id > 0).toSet().toList()..sort(),
        ),
        playerIds = List<int>.unmodifiable(
          playerIds.where((id) => id > 0).toSet().toList()..sort(),
        ),
        sessionRows = List<TrackerSessionModel>.unmodifiable(sessionRows);

  final List<int> sessionIds;
  final List<int> playerIds;
  final bool useAllSessionsForPeriod;
  final DateTime selectedDate;
  final PlayerTrainingCalendarMode sessionKindFilter;
  final List<TrackerSessionModel> sessionRows;
}

class _AnalyticsBundleMemoryEntry {
  const _AnalyticsBundleMemoryEntry(this.bundle, this.savedAt);

  final _AnalyticsBundle bundle;
  final DateTime savedAt;
}

final Map<String, _AnalyticsBundleMemoryEntry> _analyticsBundleMemory =
    <String, _AnalyticsBundleMemoryEntry>{};

