  String _bundleRequestKey() {
    final sessionIds = _selectedSessionIds.toList()..sort();
    final playerIds = _selectedPlayerIds.toList()..sort();

    // V171: локальные live-точки не должны инвалидировать архивную аналитику.
    // Пока пользователь смотрит уже выбранную/сохранённую сессию, фоновые
    // recovery/live heartbeat могут менять workspace.localPoints. Раньше длина
    // этого списка входила в ключ FutureBuilder и выбранная сессия бесконечно
    // перезапускала загрузку.
    final hasSavedSessionSelection =
        widget.selectedSession != null || _selectedSessionIds.isNotEmpty;
    final liveScopeActive = widget.liveRunning && !hasSavedSessionSelection;
    final localPointsRevision =
        liveScopeActive ? widget.localPoints.length : 0;
    // V117.5: внутри карты выбранные карточки игроков — это локальный
    // визуальный фильтр текущей сессии. Не перезагружаем весь analytics bundle
    // при каждом клике/сравнении: командные GPS-точки уже загружены.
    final mapSessionLocalSelection = _tab == 1 && _selectedSessionIds.isNotEmpty;
    return <Object?>[
      widget.teamId,
      mapSessionLocalSelection ? 0 : (widget.selectedPlayer?.id ?? 0),
      mapSessionLocalSelection ? true : _mapForceTeamScope,
      widget.selectedField?.id ?? 0,
      _dateIso(_selectedDate),
      _timeParam(_startTime) ?? 'all',
      _timeParam(_endTime) ?? 'all',
      widget.selectedSession?.id ?? 0,
      _useAllSessionsForPeriod,
      sessionIds.join('-'),
      mapSessionLocalSelection ? 'map-local' : playerIds.join('-'),
      _sessionKindApiValue(),
      liveScopeActive,
      localPointsRevision,
      _tab == 3
          ? 'pulse'
          : ((_tab >= 6 && _tab <= 11) ? 'report-lite' : 'base'),
      _reload,
    ].join('|');
  }

  Future<_AnalyticsBundle> _bundleFutureForCurrentSelection() {
    final key = _bundleRequestKey();
    if (_bundleFuture == null || _bundleFutureKey != key) {
      _bundleFutureKey = key;
      final remembered = _analyticsBundleMemory[key];
      final freshRemembered = remembered != null &&
          DateTime.now().difference(remembered.savedAt) <
              const Duration(seconds: 45);

      if (remembered != null) {
        // V177: при переходе Аналитика → другое окно → Аналитика StatefulWidget
        // создаётся заново. Не показываем пустой loader: сразу восстанавливаем
        // последний готовый bundle для точно того же набора session/player ids.
        _lastBundle = remembered.bundle;
      }

      if (freshRemembered) {
        _bundleLoadProgress = 1.0;
        _bundleLoadStage = 'Готово';
        _bundleFuture = Future<_AnalyticsBundle>.value(remembered.bundle);
      } else {
        _bundleLoadProgress = .06;
        _bundleLoadStage = 'Подготовка сессии';
        _bundleFuture = _loadBundle(key).then((bundle) {
          _lastBundle = bundle;
          _analyticsBundleMemory[key] =
              _AnalyticsBundleMemoryEntry(bundle, DateTime.now());
          // Не даём памяти расти вместе с каждым временным фильтром.
          if (_analyticsBundleMemory.length > 24) {
            final oldestKey = _analyticsBundleMemory.entries
                .reduce((a, b) => a.value.savedAt.isBefore(b.value.savedAt) ? a : b)
                .key;
            _analyticsBundleMemory.remove(oldestKey);
          }
          _publishBundleProgress(key, 1.0, 'Готово');
          return bundle;
        });
      }
    }
    return _bundleFuture!;
  }

  void _publishBundleProgress(String key, double progress, String stage) {
    if (!mounted || _bundleFutureKey != key) return;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || _bundleFutureKey != key) return;
      final next = progress.clamp(0.0, 1.0).toDouble();
      if ((_bundleLoadProgress - next).abs() < .005 &&
          _bundleLoadStage == stage) return;
      setState(() {
        _bundleLoadProgress = next;
        _bundleLoadStage = stage;
      });
    });
  }

  // V169: аналитика не имеет права зависать бесконечно на одном API-вызове.
  // Если GPS / Polar / heatmap endpoint не ответил вовремя, показываем уже
  // доступную часть сессии и оставляем подробный запрос для следующего refresh.
  Future<T> _analyticsRequestOr<T>(
    Future<T> request, {
    required T fallback,
    required String label,
    Duration timeout = const Duration(seconds: 10),
  }) async {
    try {
      return await request.timeout(timeout);
    } on TimeoutException {
      widget.onDebug('Analytics request timeout', <String, dynamic>{
        'request': label,
        'timeout_sec': timeout.inSeconds,
        'tab': _tab,
        'session_id': widget.selectedSession?.id,
      });
      return fallback;
    } catch (error) {
      widget.onDebug('Analytics request fallback', <String, dynamic>{
        'request': label,
        'error': '$error',
        'tab': _tab,
        'session_id': widget.selectedSession?.id,
      });
      return fallback;
    }
  }

  Widget _analyticsLoadingStrip() {
    final percent = (_bundleLoadProgress * 100).clamp(1, 100).round();
    return Material(
      color: Colors.white.withOpacity(.985),
      child: Container(
        height: 28,
        padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 5),
        child: Row(
          children: [
            Expanded(
              child: ClipRRect(
                borderRadius: BorderRadius.circular(99),
                child: LinearProgressIndicator(
                  minHeight: 3.5,
                  value: _bundleLoadProgress <= 0 ? .03 : _bundleLoadProgress,
                  backgroundColor: const Color(0xFFF0F3F1),
                  color: _AA.green,
                ),
              ),
            ),
            const SizedBox(width: 12),
            ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 170),
              child: Text(
                _bundleLoadStage,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                  color: Color(0xFF66716A),
                  fontSize: 9.8,
                  fontWeight: FontWeight.w600,
                ),
              ),
            ),
            const SizedBox(width: 8),
            SizedBox(
              width: 38,
              child: Text(
                '$percent%',
                textAlign: TextAlign.right,
                style: const TextStyle(
                  color: _AA.green,
                  fontSize: 10.2,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ),
          ],
        ),
      ),
    );
  }
  String _reportPlayerSelectionKey() {
    final ids = _selectedPlayerIds.toList()..sort();
    return ids.isEmpty ? 'all' : ids.join('-');
  }

  List<TrackerSessionModel> _aiSelectedSessionRows(List<int> sessionIds) {
    final byId = <int, TrackerSessionModel>{};
    for (final session in _trackerCalendarSessions) {
      if (session.id > 0) byId[session.id] = session;
    }
    final selected = widget.selectedSession;
    if (selected != null && selected.id > 0) byId[selected.id] = selected;

    final rows = sessionIds
        .map((id) => byId[id])
        .whereType<TrackerSessionModel>()
        .toList(growable: false);
    if (rows.isNotEmpty) return rows;
    return selected == null
        ? const <TrackerSessionModel>[]
        : <TrackerSessionModel>[selected];
  }

  Map<String, dynamic> _aiSessionRowPayload(TrackerSessionModel session) {
    return <String, dynamic>{
      'session_id': session.id,
      if ((session.playerId ?? 0) > 0) 'player_id': session.playerId,
      if ((session.playerName ?? '').trim().isNotEmpty)
        'player_name': session.playerName!.trim(),
      'title': session.title,
      'created_at': session.createdAt,
      if (session.sessionGroupKey.trim().isNotEmpty)
        'session_group_key': session.sessionGroupKey.trim(),
      'personal_session': session.personalSession,
      'participant_ids': session.participantIds,
      'participant_names': session.participantNames,
      'participants_count': session.participantsCount,
      'duration_sec': session.durationSec,
      'distance_m': session.distanceM,
      'avg_speed_kmh': session.avgSpeedKmh,
      'max_speed_kmh': session.maxSpeedKmh,
      'sprint_count': session.sprintCount,
      'sprint_distance_m': session.sprintDistanceM,
      'acceleration_count': session.accelCount,
      'deceleration_count': session.decelCount,
      'load_score': session.loadScore,
      'gps_duration_sec': session.gpsDurationSec,
      'polar_duration_sec': session.polarDurationSec,
      'heart_rate_samples_count': session.heartRateSamplesCount,
      'processing_status': session.processingStatus,
    };
  }


  Future<void> _showSectionLoadProgress(String label) async {
    // V170: убрали искусственную вторую полосу прогресса для
    // «Локомоторики / Механики / Микроцикла». Она не отражала сетевой запрос
    // и визуально накладывалась на реальный bundle progress. Теперь во всём
    // Analytics отображается только один источник состояния загрузки.
    if (!mounted) return;
    if (_sectionLoadProgress != 0 || _sectionLoadStage.isNotEmpty) {
      setState(() {
        _sectionLoadProgress = 0.0;
        _sectionLoadStage = '';
      });
    }
  }

  Widget _sectionLoadingStrip() => const SizedBox.shrink();

  Map<String, dynamic> _analyticsAiSelectionPayload({
    Map<String, dynamic> extra = const <String, dynamic>{},
  }) {
    final sessionIds = _selectedSessionIds.where((id) => id > 0).toList()
      ..sort();
    final fallbackSessionId = widget.selectedSession?.id ?? 0;
    if (sessionIds.isEmpty && fallbackSessionId > 0) {
      sessionIds.add(fallbackSessionId);
    }

    final playerIds = _selectedPlayerIds.where((id) => id > 0).toList()..sort();
    final playerNames = playerIds
        .map((id) => _playerById(id)?.name.trim() ?? '')
        .where((name) => name.isNotEmpty)
        .toList(growable: false);
    final singlePlayerId = playerIds.length == 1 ? playerIds.first : null;
    final singlePlayerName = playerNames.length == 1 ? playerNames.first : null;
    final tabLabel =
        _tab >= 0 && _tab < _tabs.length ? _tabs[_tab].label : 'Аналитика';

    final selectedRows = _aiSelectedSessionRows(sessionIds);
    final expectedPlayerIds = <int>{};
    final expectedPlayerNames = <String>{};
    for (final row in selectedRows) {
      expectedPlayerIds.addAll(row.participantIds.where((id) => id > 0));
      final directId = row.playerId;
      if (directId != null && directId > 0) expectedPlayerIds.add(directId);
      expectedPlayerNames.addAll(
        row.participantNames.map((name) => name.trim()).where(
              (name) => name.isNotEmpty && !_looksGenericPlayerName(name),
            ),
      );
      final directName = (row.playerName ?? '').trim();
      if (directName.isNotEmpty && !_looksGenericPlayerName(directName)) {
        expectedPlayerNames.add(directName);
      }
    }
    final groupKeys = selectedRows
        .map((row) => row.sessionGroupKey.trim())
        .where((key) => key.isNotEmpty)
        .toSet()
        .toList(growable: false);
    final gpsRows = selectedRows
        .where((row) =>
            row.distanceM > 0 || row.gpsDurationSec > 0 || row.maxSpeedKmh > 0)
        .length;
    final polarRows = selectedRows
        .where((row) =>
            row.heartRateSamplesCount > 0 || row.polarDurationSec > 0)
        .length;
    final averageSpeeds = selectedRows
        .map((row) => row.avgSpeedKmh)
        .where((value) => value > 0)
        .toList(growable: false);
    final averageSpeed = averageSpeeds.isEmpty
        ? 0.0
        : averageSpeeds.reduce((a, b) => a + b) / averageSpeeds.length;
    final logicalTraining = <String, dynamic>{
      'scope': 'logical_training',
      'representative_session_id': sessionIds.isEmpty ? null : sessionIds.first,
      'session_ids': sessionIds,
      'session_rows_count': selectedRows.length,
      if (groupKeys.length == 1) 'session_group_key': groupKeys.first,
      'expected_player_ids': expectedPlayerIds.toList()..sort(),
      'expected_player_names': expectedPlayerNames.toList()..sort(),
      // Старые get_tracker_sessions.php не всегда возвращают player_id/players,
      // хотя каждая техническая строка групповой тренировки относится к игроку.
      // Не отправляем ИИ заведомо неверное «0 участников».
      'expected_players_count': math.max(
        math.max(expectedPlayerIds.length, expectedPlayerNames.length),
        !_useAllSessionsForPeriod
            ? math.max(selectedRows.length, sessionIds.length)
            : 0,
      ),
      'gps_players_count': gpsRows,
      'polar_players_count': polarRows,
      'channels': <String, dynamic>{
        'gps': gpsRows > 0,
        'polar': polarRows > 0,
        'partial_data_allowed': true,
      },
      'summary': <String, dynamic>{
        'duration_sec': selectedRows.fold<int>(
          0,
          (value, row) => math.max(value, row.durationSec),
        ),
        'distance_m': selectedRows.fold<double>(
          0,
          (sum, row) => sum + row.distanceM,
        ),
        'avg_speed_kmh': averageSpeed,
        'max_speed_kmh': selectedRows.fold<double>(
          0,
          (value, row) => math.max(value, row.maxSpeedKmh),
        ),
        'sprint_count': selectedRows.fold<int>(
          0,
          (sum, row) => sum + row.sprintCount,
        ),
        'acceleration_count': selectedRows.fold<int>(
          0,
          (sum, row) => sum + row.accelCount,
        ),
        'deceleration_count': selectedRows.fold<int>(
          0,
          (sum, row) => sum + row.decelCount,
        ),
      },
      'session_rows': selectedRows
          .map(_aiSessionRowPayload)
          .toList(growable: false),
    };

    return <String, dynamic>{
      'source': 'tracker_analytics_selection',
      'analytics_tab': tabLabel,
      'selected_date': _dateIso(_selectedDate),
      'session_ids': sessionIds,
      if (sessionIds.isNotEmpty) 'session_id': sessionIds.first,
      'player_ids': playerIds,
      'player_names': playerNames,
      'selection_mode': playerIds.isEmpty
          ? 'team'
          : (playerIds.length == 1 ? 'single_player' : 'players'),
      if (singlePlayerId != null) 'player_id': singlePlayerId,
      if (singlePlayerName != null) 'player_name': singlePlayerName,
      'session_kind': _sessionKindApiValue(),
      'all_sessions_for_period': _useAllSessionsForPeriod,
      'logical_training': logicalTraining,
      'expected_player_ids': logicalTraining['expected_player_ids'],
      'expected_player_names': logicalTraining['expected_player_names'],
      'context_resolution': const <String, dynamic>{
        'explicit_ui_selection_first': true,
        'resolve_session_id_or_live_session_id': true,
        'resolve_logical_team_training': true,
        'team_mode_does_not_require_single_player': true,
        'accept_partial_gps_or_polar': true,
        'reject_stale_dialogue_selection': true,
      },
      'response_depth': 'deep_coach_dialogue',
      'response_contract': const <String>[
        'data_quality',
        'what_happens',
        'why',
        'players_attention',
        'coach_action',
        'next_training_plan',
        'follow_up_suggestions',
      ],
      if (_timeParam(_startTime) != null) 'from_time': _timeParam(_startTime),
      if (_timeParam(_endTime) != null) 'to_time': _timeParam(_endTime),
      ...extra,
    };
  }

  void _notifyAiContextChanged({
    Map<String, dynamic> extra = const <String, dynamic>{},
  }) {
    widget.onAiContextChanged?.call(
      _analyticsAiSelectionPayload(extra: extra),
    );
  }

  Future<void> _openReportSelectorModal(
    TrackerSessionModel session, {
    List<int> sessionIds = const <int>[],
  }) async {
    const routeName = 'tracker_report_workspace';
    var closing = false;

    Future<void> closeReportWorkspace() async {
      if (closing) return;
      closing = true;

      // Сначала возвращаем аналитику в «Обзор». Затем закрываем ровно один
      // внешний route отчёта. popUntil здесь не используется: при изменении
      // размера окна или во время анимации он мог остановиться на уже
      // закрывающемся внутреннем Dialog и оставлять белый экран.
      if (mounted) {
        setState(() {
          _tab = 0;
          _coachInsight = null;
          _inlineAnalyticsPicker = null;
        });
      }

      await Future<void>.delayed(const Duration(milliseconds: 180));
      if (!mounted) return;

      final navigator = Navigator.of(context, rootNavigator: true);
      if (navigator.canPop()) navigator.pop();
    }

    await showGeneralDialog<void>(
      context: context,
      useRootNavigator: true,
      routeSettings: const RouteSettings(name: routeName),
      barrierDismissible: false,
      barrierLabel: 'Выбор отчёта',
      barrierColor: Colors.black12,
      transitionDuration: const Duration(milliseconds: 140),
      transitionBuilder: (context, animation, secondaryAnimation, child) {
        return FadeTransition(
          opacity:
              CurvedAnimation(parent: animation, curve: Curves.easeOutCubic),
          child: child,
        );
      },
      pageBuilder: (_, __, ___) => Material(
        color: Colors.transparent,
        child: SafeArea(
          minimum: const EdgeInsets.all(6),
          child: TrackerTrainingReportScreen(
            key: ValueKey(
              'analytics_report_modal_${session.id}_${sessionIds.join('-')}_${_reportPlayerSelectionKey()}',
            ),
            sessionId: session.id,
            sessionIds: sessionIds,
            clubId: widget.clubId,
            userId: widget.userId,
            teamId: widget.teamId,
            teamName: widget.teamName,
            embedded: true,
            personalSessionMode: widget.personalMode,
            selectionOnly: true,
            autoOpenSelection: true,
            initialSelectedPlayerIds: _activePlayerFilterIds(),
            rosterPlayers: widget.players,
            onSelectionClosed: closeReportWorkspace,
          ),
        ),
      ),
    );

    if (!mounted) return;
    if (_tab != 0 || _coachInsight != null || _inlineAnalyticsPicker != null) {
      setState(() {
        _tab = 0;
        _coachInsight = null;
        _inlineAnalyticsPicker = null;
      });
    }
    widget.onDebug('Закрыт выбор отчёта — возврат в обзор', {
      'session_id': session.id,
    });
  }

  @override
  void initState() {
    super.initState();
    _tab = widget.initialTab.clamp(0, _tabs.length - 1).toInt();
    if (widget.directMapToFullMatch && _tab == 1) {
      _mapFullscreenRequested = true;
      _mapFullscreenMatchRequested = true;
    }
    _sessionKindFilter =
        widget.lockedSessionKind ?? widget.initialCalendarMode;

    final restoredSelection = widget.initialSelectionState;
    if (restoredSelection != null) {
      _selectedSessionIds.addAll(restoredSelection.sessionIds);
      _selectedPlayerIds.addAll(restoredSelection.playerIds);
      _selectedSessionRows = restoredSelection.sessionRows
          .where((row) => row.id > 0)
          .toList(growable: true);
      _useAllSessionsForPeriod = restoredSelection.useAllSessionsForPeriod;
      _sessionKindFilter =
          widget.lockedSessionKind ?? restoredSelection.sessionKindFilter;
      _selectedDate = DateTime(
        restoredSelection.selectedDate.year,
        restoredSelection.selectedDate.month,
        restoredSelection.selectedDate.day,
      );
    }

    final fixedPlayerId = widget.fixedPlayerId;
    if (fixedPlayerId != null && fixedPlayerId > 0) {
      _selectedPlayerIds
        ..clear()
        ..add(fixedPlayerId);
    }
    final speedProfile = _YouthSpeedProfile.fromLabel(widget.teamName);
    _teamHsrThresholdKmh = speedProfile.hsrKmh;
    _teamSprintThresholdKmh = speedProfile.sprintKmh;
    _hsrThresholdKmh = _teamHsrThresholdKmh;
    _sprintThresholdKmh = _teamSprintThresholdKmh;
    _syncSelectedSessionFromWidget();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      widget.onDebug('GPS-аналитика открыта', {
        'team_id': widget.teamId,
        'player_id': widget.selectedPlayer?.id,
        'field_id': widget.selectedField?.id,
        'local_points': widget.localPoints.length,
      });
      _notifyAiContextChanged();
      unawaited(_loadPersistedReadinessThresholds());
    });
  }

  void _publishSelectionState() {
    final callback = widget.onSelectionStateChanged;
    if (callback == null) return;
    callback(
      TrackerAnalyticsSelectionState(
        sessionIds: _selectedSessionIds,
        playerIds: _selectedPlayerIds,
        useAllSessionsForPeriod: _useAllSessionsForPeriod,
        selectedDate: _selectedDate,
        sessionKindFilter: _sessionKindFilter,
        sessionRows: _selectedSessionRows,
      ),
    );
  }

  void _clearSelectedSessionRows() {
    _selectedSessionRows = <TrackerSessionModel>[];
  }

  void _rememberSelectedSessionRows(Iterable<TrackerSessionModel> rows) {
    final byId = <int, TrackerSessionModel>{};
    for (final row in rows) {
      if (row.id > 0) byId[row.id] = row;
    }
    _selectedSessionRows = byId.values.toList(growable: true);
  }

  @override
  void didUpdateWidget(covariant TrackerActionAnalyticsSuite oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.dataRevision != widget.dataRevision) {
      widget.api.clearAnalyticsCache();
      // Offline recovery пишет точки в ту же final_session. Старый Future/cache
      // иначе продолжал рисовать неполный маршрут до ручной смены вкладки.
      _bundleFuture = null;
      _bundleFutureKey = null;
      // Не очищаем уже показанный bundle: recovery должен тихо обновить данные
      // поверх текущего экрана, а не возвращать пользователя на пустой loader.
      _trackerCalendarSessions = const <TrackerSessionModel>[];
      _trackerCalendarRequest++;
      _reload++;
    }
    if (oldWidget.initialTabSignal != widget.initialTabSignal) {
      final nextTab = widget.initialTab.clamp(0, _tabs.length - 1).toInt();
      if (_tab != nextTab) {
        _tab = nextTab;
        _coachInsight = null;
      }
      // V188: левое CMR-меню «Аналитика → Карта» — это прямой вход
      // в полный матч. Никакого промежуточного экрана карты между ними нет.
      if (widget.directMapToFullMatch && nextTab == 1) {
        _inlineAnalyticsPicker = null;
        _mapFullscreenRequested = true;
        _mapFullscreenMatchRequested = true;
      }
    }
    if (oldWidget.sessionPickerSignal != widget.sessionPickerSignal) {
      // V168: выбор сессии живёт в левом CMR-блоке. Сам календарь/список
      // остаётся нативным для Analytics Suite, поэтому никакие возможности
      // выбора даты, нескольких сессий и игроков не теряются.
      _showInlineAnalyticsPicker('calendar');
    }
    if (oldWidget.teamName != widget.teamName ||
        oldWidget.teamId != widget.teamId) {
      final speedProfile = _YouthSpeedProfile.fromLabel(widget.teamName);
      _teamHsrThresholdKmh = speedProfile.hsrKmh;
      _teamSprintThresholdKmh = speedProfile.sprintKmh;
      _hsrThresholdKmh = _teamHsrThresholdKmh;
      _sprintThresholdKmh = _teamSprintThresholdKmh;
    }
    if (oldWidget.teamId != widget.teamId ||
        oldWidget.selectedPlayer?.id != widget.selectedPlayer?.id) {
      _hsrThresholdKmh = _teamHsrThresholdKmh;
      _sprintThresholdKmh = _teamSprintThresholdKmh;
      unawaited(_loadPersistedReadinessThresholds());
    }
    if (oldWidget.initialCalendarModeSignal !=
        widget.initialCalendarModeSignal) {
      _sessionKindFilter =
          widget.lockedSessionKind ?? widget.initialCalendarMode;
      _trackerCalendarSessions = const <TrackerSessionModel>[];
      _trackerCalendarRequest++;
      _reload++;
    }
    if (oldWidget.selectedSession?.id != widget.selectedSession?.id) {
      // didUpdateWidget и так вызывает последующий build. setState/addPostFrame здесь
      // провоцировали rebuild календаря во время desktop mouse update.
      final incomingId = widget.selectedSession?.id;
      final belongsToCurrentTraining =
          incomingId != null && _selectedSessionIds.contains(incomingId);
      _syncSelectedSessionFromWidget(force: !belongsToCurrentTraining);
      _reload++;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) _notifyAiContextChanged();
      });
    }
  }

  Future<void> _loadPersistedReadinessThresholds() async {
    final playerId = widget.selectedPlayer?.id ?? widget.fixedPlayerId;
    final request = ++_readinessThresholdRequest;
    if (playerId == null || playerId <= 0) return;
    final now = DateTime.now();
    final referenceDate =
        '${now.year.toString().padLeft(4, '0')}-${now.month.toString().padLeft(2, '0')}-${now.day.toString().padLeft(2, '0')}';
    try {
      final snapshot = await TrackerReadinessApi(
        apiBaseUrl: widget.api.apiBaseUrl,
      ).load(
        clubId: widget.clubId,
        teamId: widget.teamId,
        playerId: playerId,
        referenceDate: referenceDate,
      );
      var hsr = _teamHsrThresholdKmh;
      var sprint = _teamSprintThresholdKmh;
      final profile = snapshot.profile;
      if (profile.thresholdMode == 'manual' &&
          profile.hsrThresholdKmh != null &&
          profile.sprintThresholdKmh != null) {
        hsr = profile.hsrThresholdKmh!.clamp(7.0, 30.0).toDouble();
        sprint = math
            .max(hsr + 1, profile.sprintThresholdKmh!)
            .clamp(8.0, 38.0)
            .toDouble();
      } else if (profile.thresholdMode == 'history' &&
          (profile.referenceMaxSpeedKmh ?? 0) > 0) {
        hsr = math
            .max(7.0, profile.referenceMaxSpeedKmh! * .75)
            .toDouble();
        sprint = math
            .max(hsr + 1, profile.referenceMaxSpeedKmh! * .90)
            .toDouble();
      }
      if (!mounted || request != _readinessThresholdRequest) return;
      setState(() {
        _hsrThresholdKmh = hsr;
        _sprintThresholdKmh = sprint;
      });
    } on TrackerReadinessApiUnavailable {
      // V157 server package is optional during a staged mobile rollout.
    } catch (error) {
      widget.onDebug('Персональные пороги недоступны', {
        'team_id': widget.teamId,
        'player_id': playerId,
        'error': '$error',
      });
    }
  }

  void _syncSelectedSessionFromWidget({bool force = false}) {
    final session = widget.selectedSession;
    if (session == null || session.id <= 0) return;
    final dt = _sessionDateTime(session);
    if (dt != null) _selectedDate = DateTime(dt.year, dt.month, dt.day);
    if (force || _selectedSessionIds.isEmpty) {
      _useAllSessionsForPeriod = false;
      _selectedSessionIds
        ..clear()
        ..add(session.id);
      _rememberSelectedSessionRows(<TrackerSessionModel>[session]);
    } else if (_selectedSessionRows.isEmpty &&
        _selectedSessionIds.contains(session.id)) {
      _rememberSelectedSessionRows(<TrackerSessionModel>[session]);
    }
  }

  void _openCoachInsight(_CoachInsight insight) {
    if (!mounted) return;
    setState(() => _coachInsight = insight);
  }

  void _closeCoachInsight() {
    if (!mounted) return;
    setState(() => _coachInsight = null);
  }

  void _refresh() {
    widget.api.clearAnalyticsCache();
    setState(() => _reload++);
    widget.onRefresh();
    widget.onDebug('GPS-аналитика обновлена', {
      'tab': _tab,
      'team_id': widget.teamId,
      'player_id': widget.selectedPlayer?.id,
      'field_id': widget.selectedField?.id,
    });
  }

  void _toggleInlineAnalyticsPicker(String mode) {
    if ((mode == 'players' && (widget.fixedPlayerId ?? 0) > 0) ||
        (mode == 'type' && widget.lockedSessionKind != null)) {
      return;
    }
    _deferMouseSafe(() {
      if (!mounted) return;
      setState(() {
        _inlineAnalyticsPicker = _inlineAnalyticsPicker == mode ? null : mode;
      });
      if ((mode == 'calendar' || mode == 'players') &&
          _inlineAnalyticsPicker == mode) {
        _ensureTrackerCalendarSessions();
      }
    }, milliseconds: 80);
  }

  void _showInlineAnalyticsPicker(String mode) {
    if ((mode == 'players' && (widget.fixedPlayerId ?? 0) > 0) ||
        (mode == 'type' && widget.lockedSessionKind != null)) {
      return;
    }
    _deferMouseSafe(() {
      if (!mounted) return;
      setState(() => _inlineAnalyticsPicker = mode);
      if (mode == 'calendar' || mode == 'players') {
        _ensureTrackerCalendarSessions();
      }
    }, milliseconds: 80);
  }

  void _closeInlineAnalyticsPicker() {
    _deferMouseSafe(() {
      if (!mounted) return;
      setState(() => _inlineAnalyticsPicker = null);
    }, milliseconds: 80);
  }

  void _applyInlinePlayerFilter(Set<int> ids) {
    final fixedPlayerId = widget.fixedPlayerId;
    if (fixedPlayerId != null && fixedPlayerId > 0) {
      if (_selectedPlayerIds.length != 1 ||
          !_selectedPlayerIds.contains(fixedPlayerId)) {
        setState(() {
          _selectedPlayerIds
            ..clear()
            ..add(fixedPlayerId);
        });
      }
      return;
    }
    _deferMouseSafe(() {
      if (!mounted) return;
      final chosenIds = Set<int>.from(ids);
      setState(() {
        _selectedPlayerIds
          ..clear()
          ..addAll(chosenIds);
        _mapForceTeamScope = false;
        _useAllSessionsForPeriod = true;
        _selectedSessionIds.clear();
        // Не очищаем _trackerCalendarSessions при выборе игрока: этот список
        // используется для визуальной подписи в карточках игроков внутри панели
        // «Выбор». Иначе сразу после тапа карточка становится активной, но
        // подпись временно меняется на «сессии на дату нет», хотя сессия есть.
        _reload++;
      });
      if (chosenIds.length == 1) {
        final id = chosenIds.first;
        if (widget.selectedPlayer?.id != id) widget.onSelectPlayer(id);
      } else if (chosenIds.length > 1 &&
          (widget.selectedPlayer == null ||
              !chosenIds.contains(widget.selectedPlayer!.id))) {
        widget.onSelectPlayer(chosenIds.first);
      }
      _publishSelectionState();
      widget.onDebug('Игроки аналитики выбраны inline', {
        'player_ids': chosenIds.toList(),
        'comparison_mode': chosenIds.length > 1,
        'date': _dateIso(_selectedDate),
      });
      _notifyAiContextChanged();
    }, milliseconds: 80);
  }

  void _applyMapPlayerFilter(Set<int> ids) {
    final fixedPlayerId = widget.fixedPlayerId;
    if (fixedPlayerId != null && fixedPlayerId > 0) {
      if (_selectedPlayerIds.length != 1 ||
          !_selectedPlayerIds.contains(fixedPlayerId)) {
        setState(() {
          _selectedPlayerIds
            ..clear()
            ..add(fixedPlayerId);
          _mapForceTeamScope = false;
        });
      }
      return;
    }
    _deferMouseSafe(() {
      if (!mounted) return;
      final chosenIds = Set<int>.from(ids);
      final localSessionScope = _tab == 1 && _selectedSessionIds.isNotEmpty;
      setState(() {
        _selectedPlayerIds
          ..clear()
          ..addAll(chosenIds);
        _mapForceTeamScope = chosenIds.isEmpty;
        // V117.5: на карте выбранной сессии карточки игроков не должны
        // переключать глобального focus-player и запускать новый API цикл.
        // Иначе режим «Сравнить» визуально терял игроков после каждого тапа.
        if (!localSessionScope) _reload++;
      });
      if (!localSessionScope) {
        if (chosenIds.length == 1) {
          final id = chosenIds.first;
          if (widget.selectedPlayer?.id != id) widget.onSelectPlayer(id);
        } else if (chosenIds.length > 1 &&
            (widget.selectedPlayer == null ||
                !chosenIds.contains(widget.selectedPlayer!.id))) {
          widget.onSelectPlayer(chosenIds.first);
        }
      }
      _publishSelectionState();
      widget.onDebug('Игроки анализа движения выбраны', {
        'player_ids': chosenIds.toList(),
        'comparison_mode': chosenIds.length > 1,
        'session_ids': _selectedSessionIds.toList(),
        'date': _dateIso(_selectedDate),
      });
      _notifyAiContextChanged();
    }, milliseconds: 60);
  }

  void _applyInlineSessionKind(PlayerTrainingCalendarMode mode) {
    if (widget.lockedSessionKind != null) return;
    _deferMouseSafe(() {
      if (!mounted) return;
      setState(() {
        _sessionKindFilter = widget.lockedSessionKind ?? mode;
        _useAllSessionsForPeriod = true;
        _selectedSessionIds.clear();
        _clearSelectedSessionRows();
        _selectedPlayerIds.clear();
        _trackerCalendarSessions = const <TrackerSessionModel>[];
        _trackerCalendarRequest++;
        _reload++;
      });
      _publishSelectionState();
      _ensureTrackerCalendarSessions(force: true);
      widget.onDebug('Тип сессий аналитики выбран inline',
          {'kind': _sessionKindApiValue(mode)});
      _notifyAiContextChanged();
    }, milliseconds: 80);
  }

