  @override
  Widget build(BuildContext context) {
    final size = MediaQuery.sizeOf(context);
    final width = size.width;
    // V121 PERSONAL PARITY: личный кабинет использует те же responsive-точки,
    // что и командная аналитика. Раньше personalMode принудительно включал
    // mobile-shell до 1100 px, поэтому на Mac/планшете исчезал полноценный
    // workspace карты (Запись/Ghost/Pit Wall) и обзор выглядел урезанным.
    // Границы данных по-прежнему задаются fixedPlayerId + lockedSessionKind.
    final mobile = width < 720;
    final compact = width < 1100;

    Widget filters() => _DateFilterBar(
          selectedDate: _selectedDate,
          onlySelectedDate: _onlySelectedDate,
          startTime: _startTime,
          endTime: _endTime,
          selectedPlayer: widget.selectedPlayer,
          playerFilterLabel: _playerFilterLabel(),
          selectedField: widget.selectedField,
          selectedSession: widget.selectedSession,
          sessionFilterLabel: _sessionFilterLabel(),
          liveRunning: widget.liveRunning,
          localPointsCount: _visibleLocalPoints().length,
          sessionKindLabel: _sessionKindLabel(_sessionKindFilter),
          onOpenSessionKindPicker: () => _toggleInlineAnalyticsPicker('type'),
          onOpenPlayerPicker: () => _toggleInlineAnalyticsPicker('players'),
          onOpenSessionPicker: () => _toggleInlineAnalyticsPicker('calendar'),
          onOpenCalibration: widget.onOpenCalibration,
          onClearField: widget.onClearField,
          onRefresh: _refresh,
          onPrev: () => _shiftDate(-1),
          onNext: () => _shiftDate(1),
          onToday: () => _setDate(DateTime.now()),
          onPick: () => _toggleInlineAnalyticsPicker('calendar'),
          onPickStart: () => _pickTime(isStart: true),
          onPickEnd: () => _pickTime(isStart: false),
          onClearTime: _clearTimeFilter,
          onToggleMode: (v) {
            _deferMouseSafe(() {
              setState(() {
                _onlySelectedDate = v;
                _reload++;
              });
              widget.onDebug('Фильтр сессий изменён', {
                'date': _dateIso(_selectedDate),
                'only_date': v,
                'from_time': _timeParam(_startTime),
                'to_time': _timeParam(_endTime),
              });
              _notifyAiContextChanged();
            });
          },
        );

    Widget tabs() => _TabStrip(
          selected: _tab,
          // V120 PERSONAL PARITY: личный игрок видит тот же набор разделов,
          // что и тренер в командной аналитике. fixedPlayerId + lockedSessionKind
          // ниже по стеку по-прежнему жёстко ограничивают данные одним игроком
          // и только его личными тренировками.
          visibleTabIndices: null,
          mobileAiCircle: widget.personalMode,
          filterActive:
              _inlineAnalyticsPicker != null || _hasActiveAnalyticsFilters(),
          filterLabel: _analyticsFilterButtonLabel(),
          onFilterTap: () => _toggleInlineAnalyticsPicker('calendar'),
          onSelect: (i) {
            final selected =
                _effectiveSelectedSession(_trackerCalendarSessions);
            final label = _tabs[i].label;
            if ((label == 'Отчёты' || label == 'ИИ-анализ') &&
                selected == null) {
              _toggleInlineAnalyticsPicker('calendar');
              return;
            }
            if (label == 'Карта' && !mobile) {
              if (selected == null) {
                _toggleInlineAnalyticsPicker('calendar');
                return;
              }
              _deferMouseSafe(() {
                setState(() {
                  _tab = i;
                  _coachInsight = null;
                  _inlineAnalyticsPicker = null;
                  _mapFullscreenRequested = true;
                  _mapFullscreenMatchRequested = false;
                });
                widget.onDebug('Открыта полноэкранная карта аналитики', {
                  'session_id': selected.id,
                  'date': _dateIso(_selectedDate),
                });
                _notifyAiContextChanged();
              });
              return;
            }
            if (label == 'ИИ-анализ') {
              final session = selected!;
              if (mobile && widget.personalMode) {
                widget.onDebug('Открыт мобильный ИИ-анализ в модальном окне', {
                  'session_id': session.id,
                  'session_ids': <int>{session.id, ..._selectedSessionIds}.toList(),
                  'date': _dateIso(_selectedDate),
                  'player_ids': _selectedPlayerIds.toList(growable: false),
                });
                unawaited(_openMobileAiModal(session));
                return;
              }
              _deferMouseSafe(() {
                setState(() {
                  _tab = i;
                  _coachInsight = null;
                  _inlineAnalyticsPicker = null;
                });
                widget.onDebug('Открыт встроенный ИИ-анализ', {
                  'session_id': session.id,
                  'session_ids':
                      <int>{session.id, ..._selectedSessionIds}.toList(),
                  'date': _dateIso(_selectedDate),
                  'player_ids': _selectedPlayerIds.toList(growable: false),
                });
                _notifyAiContextChanged();
              });
              return;
            }
            _deferMouseSafe(() {
              setState(() {
                _tab = i;
                _coachInsight = null;
                _inlineAnalyticsPicker = null;
              });
              widget
                  .onDebug('GPS-аналитика вкладка', {'tab': i, 'label': label});
              unawaited(_showSectionLoadProgress(label));
              _notifyAiContextChanged();
            });
          },
        );

    Widget loadedContent(_AnalyticsBundle bundle) {
      final visibleLocalPoints = _visibleLocalPoints();
      final analysisPoints = widget.liveRunning
          ? visibleLocalPoints
          : (bundle.sessionPoints.isNotEmpty
              ? bundle.sessionPoints
              : visibleLocalPoints);
      final effectiveSelectedSession =
          _effectiveSelectedSession(bundle.sessions);
      final selectedTrainingGroups = _groupTrackerSessions(bundle.sessions);
      List<int> reportSessionIds(TrackerSessionModel session) {
        final ids = <int>[session.id];
        if (!_useAllSessionsForPeriod) {
          for (final id in _selectedSessionIds) {
            if (id > 0 && !ids.contains(id)) ids.add(id);
          }
        }
        return ids;
      }

      List<TrackerSessionModel> reportSessionRows(
        TrackerSessionModel session,
      ) {
        if (_useAllSessionsForPeriod || _selectedSessionIds.isEmpty) {
          return <TrackerSessionModel>[session];
        }
        final rows = bundle.sessions
            .where((row) => _selectedSessionIds.contains(row.id))
            .toList(growable: false);
        return rows.isEmpty ? <TrackerSessionModel>[session] : rows;
      }

      List<int> reportParticipantIds(TrackerSessionModel session) {
        final ids = <int>[];
        for (final row in reportSessionRows(session)) {
          for (final id in row.participantIds) {
            if (id > 0 && !ids.contains(id)) ids.add(id);
          }
          final id = row.playerId;
          if (id != null && id > 0 && !ids.contains(id)) ids.add(id);
        }
        return ids;
      }

      List<String> reportParticipantNames(TrackerSessionModel session) {
        final names = <String>[];
        void addName(String? value) {
          final name = (value ?? '').trim();
          if (name.isEmpty || _looksGenericPlayerName(name)) return;
          if (!names.any(
            (existing) => existing.toLowerCase() == name.toLowerCase(),
          )) {
            names.add(name);
          }
        }

        for (final row in reportSessionRows(session)) {
          for (final name in row.participantNames) {
            addName(name);
          }
          addName(row.playerName);
        }
        return names;
      }

      final pulseScopeLabel = _useAllSessionsForPeriod
          ? 'Весь выбранный день · ${selectedTrainingGroups.length} ${_trackerTrainingWord(selectedTrainingGroups.length)}'
          : selectedTrainingGroups.length == 1
              ? '${selectedTrainingGroups.first.personalSession ? 'Личная тренировка' : 'Командная тренировка'} · ${selectedTrainingGroups.first.participantsCount} ${_trackerPlayerWord(selectedTrainingGroups.first.participantsCount)}'
              : '${selectedTrainingGroups.length} ${_trackerTrainingWord(selectedTrainingGroups.length)} · ${bundle.heartRate.effectivePlayersCount} игроков';
      final local = _LocalTrackAnalysis.fromPoints(analysisPoints,
          sprintThresholdKmh: _sprintThresholdKmh,
          hsrThresholdKmh: _hsrThresholdKmh);
      Widget content;
      switch (_tab) {
        case 0:
          content = _OverviewTab(
            compact: compact,
            teamName: widget.teamName,
            clubName: widget.clubName,
            bundle: bundle,
            local: local,
            selectedPlayer: widget.selectedPlayer,
            playerFilterLabel: _playerFilterLabel(),
            selectedField: widget.selectedField,
            selectedSession: effectiveSelectedSession,
            heatmap: bundle.heatmap,
            usingLatestFallback: bundle.usingLatestFallback,
            fallbackMessage: bundle.fallbackMessage,
            onOpenCalibration: widget.onOpenCalibration,
            onOpenSessions: widget.onOpenSessions,
            onOpenInsight: _openCoachInsight,
            personalMode: widget.personalMode,
          );
          break;
        case 1:
          // На планшете личная карта использует тот же полноценный workspace,
          // что и командная: Pit Wall, Ghost, аватар и расширенный режим.
          // V122: личный игрок на телефоне тоже получает полный MapTab.
          // Урезанный _MobileMapDashboard оставляем только для командного
          // мобильного режима. Так на личной карте доступны Запись, Ghost,
          // Pit Wall, playback-аватар и все фильтры, как на планшете.
          content = (mobile && !widget.personalMode)
              ? _MobileMapDashboard(
                  points: bundle.heatmap,
                  localPoints: analysisPoints,
                  field: widget.selectedField,
                  selectedPlayer: widget.selectedPlayer,
                  selectedSession: effectiveSelectedSession,
                  heatMode: _showHeatMapMode,
                  onHeatModeChanged: (v) =>
                      setState(() => _showHeatMapMode = v),
                  sprintThresholdKmh: _sprintThresholdKmh,
                  hsrThresholdKmh: _hsrThresholdKmh,
                  showSprintArrows: _showSprintArrows,
                  mapRotationDeg: _mapRotationDeg,
                  onOpenCalibration: widget.onOpenCalibration,
                  personalMode: widget.personalMode,
                )
              : _MapTab(
                  api: widget.api,
                  clubId: widget.clubId,
                  userId: widget.userId,
                  teamId: widget.teamId,
                  teamName: widget.teamName,
                  clubName: widget.clubName,
                  points: bundle.heatmap,
                  localPoints: analysisPoints,
                  field: widget.selectedField,
                  selectedPlayer: widget.selectedPlayer,
                  selectedSession: effectiveSelectedSession,
                  players: bundle.players.isNotEmpty ? bundle.players : widget.players,
                  heartRate: bundle.heartRate,
                  comparisonRows: _rowsForAnalytics(
                      bundle, effectiveSelectedSession, local, widget.selectedPlayer),
                  selectedPlayerIds: Set<int>.from(_selectedPlayerIds),
                  onPlayerSelectionChanged: _applyMapPlayerFilter,
                  heatMode: _showHeatMapMode,
                  onHeatModeChanged: (v) =>
                      setState(() => _showHeatMapMode = v),
                  sprintThresholdKmh: _sprintThresholdKmh,
                  hsrThresholdKmh: _hsrThresholdKmh,
                  showSprintArrows: _showSprintArrows,
                  mapRotationDeg: _mapRotationDeg,
                  onOpenCalibration: widget.onOpenCalibration,
                  onOpenTelemetryVideo: widget.onOpenTelemetryVideo,
                  onOpenTelemetryAi: widget.onOpenAiAnalysis,
                  initialCursorTimeMs: widget.initialMapCursorTimeMs,
                  autoOpenExpanded: _mapFullscreenRequested,
                  autoOpenExpandedMatch: _mapFullscreenMatchRequested,
                  onAutoOpenHandled: () {
                    if (!mounted || !_mapFullscreenRequested) return;
                    setState(() {
                      _mapFullscreenRequested = false;
                      _mapFullscreenMatchRequested = false;
                    });
                  },
                  onExpandedClosedToSessions: () {
                    if (!mounted) return;
                    // При прямом входе через «Аналитика → Карта» крестик полного
                    // матча возвращает туда же, куда нижняя кнопка: в «Обзор».
                    if (widget.directMapToFullMatch) {
                      widget.onBackToAnalyticsMenu?.call();
                      return;
                    }
                    setState(() {
                      // В новом CMR map-sidebar закрытие развёрнутой карты не
                      // выбрасывает пользователя из раздела «Карта». Оставляем
                      // карту на месте и лишь открываем выбор сессии. В старом
                      // интерфейсе сохраняем прежний возврат на «Обзор».
                      if (!widget.showDesktopMapSidebar) _tab = 0;
                      _coachInsight = null;
                      _inlineAnalyticsPicker = 'calendar';
                    });
                    _ensureTrackerCalendarSessions();
                  },
                  personalMode: widget.personalMode,
                  personalGhostSession: bundle.personalGhostSession,
                  personalGhostPoints: bundle.personalGhostPoints,
                  showDesktopSidebar: widget.showDesktopMapSidebar,
                  onBackToAnalyticsMenu: widget.onBackToAnalyticsMenu,
                );
          break;
        case 2:
          content = mobile
              ? _MobileSpeedDashboard(
                  bundle: bundle,
                  local: local,
                  selectedSession: effectiveSelectedSession,
                  hsrThresholdKmh: _hsrThresholdKmh,
                  sprintThresholdKmh: _sprintThresholdKmh,
                  personalMode: widget.personalMode,
                )
              : _SpeedTab(
                  bundle: bundle,
                  local: local,
                  selectedSession: effectiveSelectedSession,
                  hsrThresholdKmh: _hsrThresholdKmh,
                  sprintThresholdKmh: _sprintThresholdKmh,
                  onOpenInsight: _openCoachInsight,
                );
          break;
        case 3:
          content = mobile
              ? _MobileHeartDashboard(
                  heartRate: bundle.heartRate,
                  selectedPlayer: widget.selectedPlayer,
                  scopeLabel: pulseScopeLabel,
                  personalMode: widget.personalMode)
              : _HeartRateAnalyticsTab(
                  heartRate: bundle.heartRate,
                  selectedPlayer: widget.selectedPlayer,
                  rosterPlayers: widget.players,
                  scopeLabel: pulseScopeLabel,
                  onContextChanged: (heartContext) {
                    widget.onAiContextChanged?.call(
                      _analyticsAiSelectionPayload(extra: heartContext),
                    );
                  },
                  onOpenAiLoadPoint: widget.onOpenAiLoadPoint == null
                      ? null
                      : (point) => widget.onOpenAiLoadPoint!(<String, dynamic>{
                            ..._analyticsAiSelectionPayload(),
                            'player_id': point.playerId,
                            'player_name': point.playerName,
                            'player_ids': point.playerId == null
                                ? const <int>[]
                                : <int>[point.playerId!],
                            'player_names': point.playerName.trim().isEmpty
                                ? const <String>[]
                                : <String>[point.playerName.trim()],
                            'selection_mode': 'single_player',
                            'bpm': point.bpm,
                            'zone': point.zone,
                            'time_ms': point.timeMs,
                            'minute': point.minute,
                            'activity_type': point.activityType,
                            'hr_load': point.hrLoad,
                          }),
                );
          break;
        case 4:
          content = mobile
              ? _MobileTeamDashboard(
                  bundle: bundle,
                  selectedSession: effectiveSelectedSession,
                  local: local,
                  players: widget.players,
                  selectedPlayer: widget.selectedPlayer,
                  onSelectPlayer: widget.onSelectPlayer,
                )
              : _TeamTab(
                  bundle: bundle,
                  selectedSession: effectiveSelectedSession,
                  local: local,
                  players: widget.players,
                  selectedPlayer: widget.selectedPlayer,
                  onSelectPlayer: widget.onSelectPlayer,
                );
          break;
        case 5:
          content = mobile
              ? _MobileRatingsDashboard(
                  bundle: bundle,
                  local: local,
                  teamName: widget.teamName,
                  selectedPlayer: widget.selectedPlayer,
                  selectedSession: effectiveSelectedSession,
                )
              : _RatingsTab(
                  bundle: bundle,
                  local: local,
                  teamName: widget.teamName,
                  selectedPlayer: widget.selectedPlayer,
                  selectedSession: effectiveSelectedSession,
                );
          break;
        case 6:
        case 7:
        case 8:
          final reportSession = effectiveSelectedSession;
          final reportIds = reportSession == null
              ? const <int>[]
              : reportSessionIds(reportSession);
          final section = switch (_tab) {
            6 => 'locomotor',
            7 => 'mechanics',
            _ => 'microcycle',
          };
          content = reportSession == null
              ? _AnalyticsReportEmptyState(
                  onOpenSelection: () =>
                      _toggleInlineAnalyticsPicker('calendar'),
                )
              : TrackerTrainingReportScreen(
                  key: ValueKey(
                    'analytics_${section}_${reportIds.join('-')}_${_reportPlayerSelectionKey()}',
                  ),
                  sessionId: reportSession.id,
                  sessionIds: reportIds,
                  expectedParticipantIds: reportParticipantIds(reportSession),
                  expectedParticipantNames:
                      reportParticipantNames(reportSession),
                  clubId: widget.clubId,
                  userId: widget.userId,
                  teamId: widget.teamId,
                  teamName: widget.teamName,
                  embedded: true,
                  analyticsSection: section,
                  personalSessionMode: widget.personalMode,
                  initialSelectedPlayerIds: _activePlayerFilterIds(),
                  rosterPlayers: widget.players,
                );
          break;
        case 9:
          final reportSession = effectiveSelectedSession;
          final reportIds = reportSession == null
              ? const <int>[]
              : reportSessionIds(reportSession);
          content = reportSession == null
              ? _AnalyticsReportEmptyState(
                  onOpenSelection: () =>
                      _toggleInlineAnalyticsPicker('calendar'),
                )
              : TrackerTrainingReportScreen(
                  key: ValueKey(
                    'analytics_ai_${reportIds.join('-')}_${_reportPlayerSelectionKey()}',
                  ),
                  sessionId: reportSession.id,
                  sessionIds: reportIds,
                  expectedParticipantIds: reportParticipantIds(reportSession),
                  expectedParticipantNames:
                      reportParticipantNames(reportSession),
                  clubId: widget.clubId,
                  userId: widget.userId,
                  teamId: widget.teamId,
                  teamName: widget.teamName,
                  embedded: true,
                  analyticsSection: 'ai',
                  personalSessionMode: widget.personalMode,
                  initialSelectedPlayerIds: _activePlayerFilterIds(),
                  rosterPlayers: widget.players,
                );
          break;
        case 10:
          final reportSession = effectiveSelectedSession;
          final reportIds = reportSession == null
              ? const <int>[]
              : reportSessionIds(reportSession);
          content = reportSession == null
              ? _AnalyticsReportEmptyState(
                  onOpenSelection: () =>
                      _toggleInlineAnalyticsPicker('calendar'),
                )
              : TrackerTrainingReportScreen(
                  key: ValueKey(
                    'analytics_report_${reportIds.join('-')}_${_reportPlayerSelectionKey()}',
                  ),
                  sessionId: reportSession.id,
                  sessionIds: reportIds,
                  expectedParticipantIds: reportParticipantIds(reportSession),
                  expectedParticipantNames:
                      reportParticipantNames(reportSession),
                  clubId: widget.clubId,
                  userId: widget.userId,
                  teamId: widget.teamId,
                  teamName: widget.teamName,
                  embedded: true,
                  personalSessionMode: widget.personalMode,
                  selectionOnly: true,
                  inlineAnalyticsReport: true,
                  initialSelectedPlayerIds: _activePlayerFilterIds(),
                  rosterPlayers: widget.players,
                );
          break;
        case 11:
          content = _OfflineTab(
            liveRunning: widget.liveRunning,
            commandChannelReady: widget.commandChannelReady,
            offlineRecordsCount: widget.offlineRecordsCount,
            localPointsCount: widget.localPointsCount,
            offlineGpsMode: _offlineGpsMode,
            onToggleOfflineGpsMode: (v) {
              setState(() => _offlineGpsMode = v);
              widget.onDebug('Офлайн GPS режим изменён', {'enabled': v});
            },
            onRequestOfflineRecords: widget.onRequestOfflineRecords,
            onSaveOfflineSession: widget.onSaveOfflineSession,
            onOpenSessions: widget.onOpenSessions,
          );
          break;
        case 12:
          content = TrackerReadinessPanel(
            api: widget.api,
            clubId: widget.clubId,
            userId: widget.userId,
            teamId: widget.teamId,
            teamName: widget.teamName,
            players:
                bundle.players.isNotEmpty ? bundle.players : widget.players,
            selectedPlayer: widget.selectedPlayer,
            selectedSession: effectiveSelectedSession,
            localPoints: analysisPoints,
            defaultHsrThresholdKmh: _teamHsrThresholdKmh,
            defaultSprintThresholdKmh: _teamSprintThresholdKmh,
            onSelectPlayer: widget.onSelectPlayer,
            onThresholdsChanged: (hsrKmh, sprintKmh) {
              if (!mounted) return;
              setState(() {
                _hsrThresholdKmh = hsrKmh;
                _sprintThresholdKmh = sprintKmh;
              });
            },
            onDebug: widget.onDebug,
            personalMode: widget.personalMode,
          );
          break;
        default:
          final reportSession = effectiveSelectedSession;
          final reportIds = reportSession == null
              ? const <int>[]
              : reportSessionIds(reportSession);
          content = reportSession == null
              ? _AnalyticsReportEmptyState(
                  onOpenSelection: () =>
                      _toggleInlineAnalyticsPicker('calendar'),
                )
              : TrackerTrainingReportScreen(
                  key: ValueKey(
                    'analytics_report_${reportIds.join('-')}_${_reportPlayerSelectionKey()}',
                  ),
                  sessionId: reportSession.id,
                  sessionIds: reportIds,
                  expectedParticipantIds: reportParticipantIds(reportSession),
                  expectedParticipantNames:
                      reportParticipantNames(reportSession),
                  clubId: widget.clubId,
                  userId: widget.userId,
                  teamId: widget.teamId,
                  teamName: widget.teamName,
                  embedded: true,
                  personalSessionMode: widget.personalMode,
                  selectionOnly: true,
                  inlineAnalyticsReport: true,
                  initialSelectedPlayerIds: _activePlayerFilterIds(),
                  rosterPlayers: widget.players,
                );
          break;
      }
      if (mobile) return content;
      // Важно: планшетные вкладки нельзя оборачивать во внешний SingleChildScrollView:
      // внутри них уже есть Row/Expanded/ListView с жёсткими ограничениями высоты.
      // Иначе Flutter получает RenderSingleChildViewport без размера и падает на hit test.
      return _CoachInsightScaffold(
        insight: _coachInsight,
        onClose: _closeCoachInsight,
        child: content,
      );
    }

    Widget inlineSelector() {
      final mode = _inlineAnalyticsPicker;
      if (mode == null) return const SizedBox.shrink();
      return _TrackerInlineAnalyticsOverlay(
        mode: mode,
        selectedDate: _selectedDate,
        sessions: _trackerCalendarSessions,
        players: widget.players,
        selectedPlayerIds: Set<int>.from(_selectedPlayerIds),
        selectedKind: _sessionKindFilter,
        selectedKindLabel: _sessionKindLabel(_sessionKindFilter),
        loading: _trackerCalendarLoading,
        summary: _analyticsFilterButtonLabel(),
        onClose: _closeInlineAnalyticsPicker,
        onShowCalendar: () => _showInlineAnalyticsPicker('calendar'),
        onShowPlayers: () => _showInlineAnalyticsPicker('players'),
        onShowKind: () => _showInlineAnalyticsPicker('type'),
        onSelectDate: (date) {
          _setDate(date);
          _ensureTrackerCalendarSessions();
        },
        onSelectSession: (group) {
          _applyCalendarGroup(group);
          _closeInlineAnalyticsPicker();
        },
        onOpenSessionReport: _openCalendarGroupReport,
        onSelectPlayers: _applyInlinePlayerFilter,
        onSelectKind: _applyInlineSessionKind,
        lockPlayer: (widget.fixedPlayerId ?? 0) > 0,
        lockKind: widget.lockedSessionKind != null,
      );
    }

    Widget bodyFuture() => FutureBuilder<_AnalyticsBundle>(
          key: ValueKey('gps_analytics_${_bundleRequestKey()}'),
          future: _bundleFutureForCurrentSelection(),
          builder: (context, snapshot) {
            if (snapshot.connectionState == ConnectionState.waiting &&
                snapshot.data == null) {
              final cached = _lastBundle;
              if (cached != null) {
                return Stack(
                  children: [
                    Positioned.fill(child: loadedContent(cached)),
                    Positioned(
                      top: 0,
                      left: 0,
                      right: 0,
                      child: _analyticsLoadingStrip(),
                    ),
                  ],
                );
              }
              return Column(
                children: [
                  _analyticsLoadingStrip(),
                  const Expanded(
                    child: Center(
                      child: Text(
                        'Загружаем данные выбранной сессии…',
                        style: TextStyle(
                          color: Color(0xFF66716A),
                          fontSize: 11.5,
                          fontWeight: FontWeight.w600,
                        ),
                      ),
                    ),
                  ),
                ],
              );
            }
            if (snapshot.hasError) {
              return _ErrorBox(error: '${snapshot.error}', onRetry: _refresh);
            }
            return loadedContent(snapshot.data ?? _AnalyticsBundle.empty());
          },
        );

    Widget stackedBody() {
      return Stack(
        clipBehavior: Clip.none,
        children: [
          Positioned.fill(child: bodyFuture()),
          // V170: одна реальная полоса загрузки. Дополнительный декоративный
          // progress для отдельных вкладок удалён.
          if (_inlineAnalyticsPicker != null)
            Positioned.fill(
              top: mobile ? 4 : 6,
              left: mobile ? 2 : 6,
              right: mobile ? 2 : 6,
              bottom: mobile ? 4 : 6,
              child: inlineSelector(),
            ),
        ],
      );
    }

    if (mobile) {
      return ScrollConfiguration(
        behavior: const _TrackerNoDesktopScrollbarBehavior(),
        child: Container(
          color: Colors.transparent,
          child:
              Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            tabs(),
            Expanded(child: stackedBody()),
          ]),
        ),
      );
    }

    return ScrollConfiguration(
      behavior: const _TrackerNoDesktopScrollbarBehavior(),
      child: Container(
        color: _AA.bg,
        child: Column(
          children: [
            if (!widget.hideDesktopTabs) tabs(),
            Expanded(child: stackedBody()),
          ],
        ),
      ),
    );
  }

  String _sessionKindLabel(PlayerTrainingCalendarMode mode) {
    switch (mode) {
      case PlayerTrainingCalendarMode.team:
        return 'Командные';
      case PlayerTrainingCalendarMode.personal:
        return 'Личные';
      case PlayerTrainingCalendarMode.all:
        return 'Все';
    }
  }

  IconData _sessionKindIcon(PlayerTrainingCalendarMode mode) {
    switch (mode) {
      case PlayerTrainingCalendarMode.team:
        return Icons.groups_rounded;
      case PlayerTrainingCalendarMode.personal:
        return Icons.person_pin_circle_rounded;
      case PlayerTrainingCalendarMode.all:
        return Icons.layers_rounded;
    }
  }

  String _sessionKindApiValue([PlayerTrainingCalendarMode? mode]) {
    switch (widget.lockedSessionKind ?? mode ?? _sessionKindFilter) {
      case PlayerTrainingCalendarMode.team:
        return 'team';
      case PlayerTrainingCalendarMode.personal:
        return 'personal';
      case PlayerTrainingCalendarMode.all:
        return 'all';
    }
  }

  bool _sessionMatchesKind(TrackerSessionModel session) {
    switch (widget.lockedSessionKind ?? _sessionKindFilter) {
      case PlayerTrainingCalendarMode.team:
        return !session.personalSession;
      case PlayerTrainingCalendarMode.personal:
        return session.personalSession;
      case PlayerTrainingCalendarMode.all:
        return true;
    }
  }

  void _openSessionKindPicker() {
    if (widget.lockedSessionKind != null) return;
    final width = MediaQuery.maybeOf(context)?.size.width ?? 1200;
    final options = <PlayerTrainingCalendarMode>[
      PlayerTrainingCalendarMode.team,
      PlayerTrainingCalendarMode.personal,
      PlayerTrainingCalendarMode.all,
    ];

    void apply(PlayerTrainingCalendarMode mode) {
      if (!mounted) return;
      setState(() {
        _sessionKindFilter = widget.lockedSessionKind ?? mode;
        _trackerCalendarSessions = const <TrackerSessionModel>[];
        _trackerCalendarRequest++;
        _selectedSessionIds.clear();
        _clearSelectedSessionRows();
        _useAllSessionsForPeriod = true;
        _reload++;
      });
      _publishSelectionState();
      widget.onDebug('Тип тренировок в аналитике изменён', {'mode': mode.name});
    }

    if (width < 720) {
      showModalBottomSheet<void>(
        context: context,
        backgroundColor: Colors.transparent,
        barrierColor: Colors.black.withOpacity(.22),
        builder: (sheetContext) {
          final bottom = MediaQuery.of(sheetContext).padding.bottom;
          return SafeArea(
            top: false,
            child: Container(
              margin: const EdgeInsets.all(10),
              padding: EdgeInsets.fromLTRB(12, 12, 12, 12 + bottom),
              decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(_AA.sheetRadius)),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  const Text('Тип тренировок',
                      style: TextStyle(
                          color: _AA.text,
                          fontSize: 15,
                          fontWeight: FontWeight.w900)),
                  const SizedBox(height: 10),
                  for (final mode in options) ...[
                    _SessionKindOptionTile(
                      icon: _sessionKindIcon(mode),
                      title: _sessionKindLabel(mode),
                      subtitle: mode == PlayerTrainingCalendarMode.team
                          ? 'сессии, запущенные тренером'
                          : mode == PlayerTrainingCalendarMode.personal
                              ? 'игроки сами запустили «Мои тренировки»'
                              : 'командные и личные вместе',
                      active: _sessionKindFilter == mode,
                      onTap: () {
                        Navigator.of(sheetContext).pop();
                        apply(mode);
                      },
                    ),
                    const SizedBox(height: 8),
                  ],
                ],
              ),
            ),
          );
        },
      );
      return;
    }

    showDialog<void>(
      context: context,
      builder: (dialogContext) {
        return AlertDialog(
          backgroundColor: Colors.white,
          shape:
              RoundedRectangleBorder(borderRadius: BorderRadius.circular(14)),
          title: const Text('Тип тренировок в аналитике',
              style: TextStyle(color: _AA.text, fontWeight: FontWeight.w900)),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              for (final mode in options) ...[
                _SessionKindOptionTile(
                  icon: _sessionKindIcon(mode),
                  title: _sessionKindLabel(mode),
                  subtitle: mode == PlayerTrainingCalendarMode.team
                      ? 'сессии, запущенные тренером в командном Live'
                      : mode == PlayerTrainingCalendarMode.personal
                          ? 'игроки сами запустили тренировку в личном кабинете'
                          : 'смешанный архив команды и личных сессий',
                  active: _sessionKindFilter == mode,
                  onTap: () {
                    Navigator.of(dialogContext).pop();
                    apply(mode);
                  },
                ),
                const SizedBox(height: 8),
              ],
            ],
          ),
        );
      },
    );
  }

  void _openMobileAnalyticsMenu() {
    showModalBottomSheet<void>(
      context: context,
      useRootNavigator: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withOpacity(.24),
      isScrollControlled: true,
      builder: (sheetContext) {
        final bottom = MediaQuery.of(sheetContext).padding.bottom;

        void closeThen(VoidCallback action) {
          Navigator.of(sheetContext).pop();
          Future<void>.delayed(const Duration(milliseconds: 120), () {
            if (!mounted) return;
            action();
