  Future<void> _openSessionPicker() async {
    final date = _onlySelectedDate ? _dateIso(_selectedDate) : null;
    final fromTime = _timeParam(_startTime);
    final toTime = _timeParam(_endTime);
    var sessions = await widget.api.loadSessions(
      teamId: widget.teamId,
      playerId: null,
      date: date,
      fromTime: fromTime,
      toTime: toTime,
      limit: 500,
      sessionKind: 'all',
    );
    sessions = sessions
        .where(
            (s) => _sessionMatchesDateRange(s, date ?? _dateIso(_selectedDate)))
        .toList(growable: false)
      ..sort((a, b) => b.createdAt.compareTo(a.createdAt));

    if (!mounted) return;
    _trackerCalendarSessions = sessions;

    final tempSessions = Set<int>.from(_selectedSessionIds);
    final tempPlayers = Set<int>.from(_selectedPlayerIds);
    var tempAllSessions = _useAllSessionsForPeriod || tempSessions.isEmpty;
    var query = '';
    var onlyWithData = false;
    var tempSessionKind = _sessionKindFilter;

    await showModalBottomSheet<void>(
      context: context,
      useRootNavigator: true,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      barrierColor: Colors.black.withOpacity(.24),
      builder: (sheetContext) {
        return StatefulBuilder(builder: (context, modalSetState) {
          bool sessionHasData(TrackerSessionModel s) =>
              s.distanceM > 0 ||
              s.maxSpeedKmh > 0 ||
              s.sprintCount > 0 ||
              s.accelCount > 0 ||
              s.decelCount > 0 ||
              s.durationSec > 0;
          bool groupHasData(_TrackerTrainingGroup group) =>
              group.sessions.any(sessionHasData);

          bool matchesTempKind(TrackerSessionModel session) {
            switch (tempSessionKind) {
              case PlayerTrainingCalendarMode.team:
                return !session.personalSession;
              case PlayerTrainingCalendarMode.personal:
                return session.personalSession;
              case PlayerTrainingCalendarMode.all:
                return true;
            }
          }

          final summaries = <int, _SessionPickerPlayerSummary>{};
          for (final session in sessions.where(matchesTempKind)) {
            final id = session.playerId;
            if (id == null || id <= 0) continue;
            final roster = _playerById(id);
            final fallbackName = _sessionPlayerName(session);
            final name = (roster?.name.trim().isNotEmpty ?? false)
                ? roster!.name.trim()
                : fallbackName;
            final summary = summaries[id] ??
                _SessionPickerPlayerSummary(id: id, name: name, player: roster);
            summary.add(session);
            summaries[id] = summary;
          }
          final players = summaries.values.toList(growable: false)
            ..sort((a, b) => a.name.compareTo(b.name));

          final trainingGroups =
              _groupTrackerSessions(sessions.where(matchesTempKind));

          List<_TrackerTrainingGroup> filteredSessions() {
            return trainingGroups.where((group) {
              if (tempPlayers.isNotEmpty &&
                  !group.sessions.any((session) =>
                      _sessionMatchesPlayerIds(session, tempPlayers)))
                return false;
              if (onlyWithData && !groupHasData(group)) return false;
              if (query.isNotEmpty &&
                  !group.sessions.any(
                      (session) => _sessionSearchText(session).contains(query)))
                return false;
              return true;
            }).toList(growable: false);
          }

          List<_SessionPickerPlayerSummary> filteredPlayers() {
            return players.where((p) {
              if (onlyWithData && !p.hasData) return false;
              if (query.isEmpty) return true;
              final text =
                  '${p.name} ${p.player?.number ?? ''} ${p.player?.position ?? ''} ${p.id}'
                      .toLowerCase();
              return text.contains(query);
            }).toList(growable: false);
          }

          final filtered = filteredSessions();
          final selectedCount = tempAllSessions
              ? filtered.length
              : filtered
                  .where((group) => group.sessionIds.any(tempSessions.contains))
                  .length;
          final screen = MediaQuery.sizeOf(context);
          final bottom = MediaQuery.paddingOf(context).bottom;
          final tabletFullscreen = screen.width >= 720 && screen.width < 1280;
          final wide = screen.width >= 920;
          final sheetWidth = tabletFullscreen
              ? screen.width
              : (wide ? math.min(1240.0, screen.width - 24) : screen.width);
          final sheetHeight = tabletFullscreen
              ? screen.height
              : (wide ? math.min(860.0, screen.height * .94) : screen.height * .96);

          Widget modalButton(
              {required IconData icon,
              required String label,
              required VoidCallback onTap,
              bool primary = false}) {
            return _NoHoverTap(
              onTap: onTap,
              borderRadius: BorderRadius.circular(16),
              child: Container(
                height: 44,
                padding: const EdgeInsets.symmetric(horizontal: 13),
                decoration: BoxDecoration(
                  color: primary
                      ? _AA.green
                      : (primary ? _AA.greenSoft : _AA.card),
                  borderRadius: BorderRadius.zero,
                  border: Border.all(
                      color: primary ? _AA.green : _AA.line.withOpacity(.95)),
                  boxShadow: primary
                      ? const [
                          BoxShadow(
                              color: Color(0x2200A651),
                              blurRadius: 14,
                              offset: Offset(0, 6))
                        ]
                      : null,
                ),
                child: Row(
                    mainAxisSize: MainAxisSize.min,
                    mainAxisAlignment: MainAxisAlignment.center,
                    children: [
                      Icon(icon,
                          size: 17, color: primary ? Colors.white : _AA.green),
                      const SizedBox(width: 8),
                      Text(label,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: TextStyle(
                              color: primary ? Colors.white : _AA.text,
                              fontSize: 12.2,
                              fontWeight: FontWeight.w900,
                              letterSpacing: -.12)),
                    ]),
              ),
            );
          }

          Widget playerCard(_SessionPickerPlayerSummary p) {
            final active = tempPlayers.contains(p.id);
            return _NoHoverTap(
              onTap: () => modalSetState(() {
                if (active) {
                  tempPlayers.remove(p.id);
                } else {
                  tempPlayers.add(p.id);
                }
                tempAllSessions = true;
                tempSessions.clear();
              }),
              borderRadius: BorderRadius.circular(14),
              child: AnimatedContainer(
                duration: const Duration(milliseconds: 160),
                curve: Curves.easeOutCubic,
                margin: const EdgeInsets.only(bottom: 10),
                padding: const EdgeInsets.all(8),
                decoration: BoxDecoration(
                  color: active ? _AA.greenSoft : _AA.card,
                  borderRadius: BorderRadius.zero,
                  border: active
                      ? const Border(left: BorderSide(color: _AA.green, width: 3))
                      : null,
                ),
                child: Row(children: [
                  _SessionAvatar(player: p.player),
                  const SizedBox(width: 8),
                  Expanded(
                      child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                        Text(p.name,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: _AA.text,
                                fontSize: 13.4,
                                fontWeight: FontWeight.w900,
