  _AnalyticsHeartRate _restrictHeartRateToFixedPlayer(
      _AnalyticsHeartRate source) {
    if (!widget.personalMode || (widget.fixedPlayerId ?? 0) <= 0) return source;

    final selected = widget.selectedPlayer;
    final allowedIds = <int>{
      if ((widget.fixedPlayerId ?? 0) > 0) widget.fixedPlayerId!,
      if ((selected?.id ?? 0) > 0) selected!.id,
      ...?selected?.identityIds,
    };
    final selectedName = (selected?.name ?? '').trim().toLowerCase();

    bool matches(int? id, String name) {
      if (id != null && id > 0 && allowedIds.contains(id)) return true;
      final normalized = name.trim().toLowerCase();
      return selectedName.isNotEmpty &&
          normalized.isNotEmpty &&
          normalized == selectedName;
    }

    final players = source.players
        .where((p) => matches(p.playerId, p.playerName))
        .toList(growable: false);
    var timeline = source.timeline
        .where((p) => matches(p.playerId, p.playerName))
        .toList(growable: false);

    // Некоторые старые PHP возвращают timeline без player_id/name, хотя
    // player summary уже строго один. В личном режиме такую линию можно
    // сохранить только когда серверный ответ фактически одноигроковый.
    if (timeline.isEmpty && players.length == 1 && source.players.length <= 1) {
      timeline = source.timeline;
    }

    if (players.isEmpty && timeline.isEmpty) {
      return _AnalyticsHeartRate.empty();
    }

    final samplesFromPlayers =
        players.fold<int>(0, (sum, p) => sum + p.samplesCount);
    final totalWeight = players.fold<int>(
        0, (sum, p) => sum + (p.samplesCount > 0 ? p.samplesCount : 1));
    final avg = totalWeight <= 0
        ? 0.0
        : players.fold<double>(
                0,
                (sum, p) =>
                    sum + p.avgBpm * (p.samplesCount > 0 ? p.samplesCount : 1)) /
            totalWeight;
    final maxBpm = players.fold<int>(
        0, (maxV, p) => maxV > p.maxBpm ? maxV : p.maxBpm);

    return _AnalyticsHeartRate(
      players: players,
      timeline: timeline,
      avgBpm: avg,
      maxBpm: maxBpm,
      samplesCount:
          math.max(samplesFromPlayers, timeline.length).toInt(),
      playersCount: players.isEmpty ? (timeline.isEmpty ? 0 : 1) : 1,
    );
  }

  Future<_AnalyticsBundle> _loadBundle(String requestKey) async {
    try {
      final date = _onlySelectedDate ? _dateIso(_selectedDate) : null;
      final fromTime = _timeParam(_startTime);
      final toTime = _timeParam(_endTime);

      final dashboardFuture = _sessionKindFilter == PlayerTrainingCalendarMode.team
          ? widget.api.loadDashboard(
              teamId: widget.teamId,
              date: date,
              fromTime: fromTime,
              toTime: toTime)
          : Future<TrackerDashboardModel>.value(
              const TrackerDashboardModel(
                summary: <String, dynamic>{},
                players: <TrackerPlayerLoadRow>[],
                alerts: <Map<String, dynamic>>[],
              ),
            );
      final sessionsFuture = widget.api.loadSessions(
        teamId: widget.teamId,
        playerId: null,
        date: date,
        fromTime: fromTime,
        toTime: toTime,
        limit: _onlySelectedDate ? 300 : 700,
        sessionKind: _sessionKindApiValue(),
      );
      var dashboard = await _analyticsRequestOr<TrackerDashboardModel>(
        dashboardFuture,
        fallback: const TrackerDashboardModel(
          summary: <String, dynamic>{},
          players: <TrackerPlayerLoadRow>[],
          alerts: <Map<String, dynamic>>[],
        ),
        label: 'dashboard',
        timeout: const Duration(seconds: 9),
      );
      final rawSessions = await _analyticsRequestOr<List<TrackerSessionModel>>(
        sessionsFuture,
        fallback: const <TrackerSessionModel>[],
        label: 'sessions',
        timeout: const Duration(seconds: 9),
      );
      _publishBundleProgress(requestKey, .24, 'Сессии загружены');

      var sessions = date == null
          ? rawSessions
              .where(_sessionMatchesKind)
              .where(
                  (s) => _sessionMatchesDateRange(s, _dateIso(_selectedDate)))
              .toList(growable: false)
          : rawSessions
              .where(_sessionMatchesKind)
              .where((s) => _sessionMatchesDateRange(s, date))
              .toList(growable: false);
      final selectedPlayerIds = _activePlayerFilterIds();
      if (selectedPlayerIds.isNotEmpty) {
        sessions = sessions
            .where((s) => _sessionMatchesPlayerIds(s, selectedPlayerIds))
            .toList(growable: false);
      }
      // V177: выбранная командная тренировка — это набор technical rows.
      // Если сеть на секунду пропала или AnalyticsSuite был пересоздан после
      // перехода в другой раздел, API может вернуть пусто. Не схлопываем тогда
      // тренировку до одного representative row: дополняем ответ сохранёнными
      // строками выбранной тренировки.
      if (_selectedSessionIds.isNotEmpty && _selectedSessionRows.isNotEmpty) {
        final mergedById = <int, TrackerSessionModel>{
          for (final row in sessions)
            if (row.id > 0) row.id: row,
        };
        for (final row in _selectedSessionRows) {
          if (row.id > 0 && _selectedSessionIds.contains(row.id)) {
            mergedById.putIfAbsent(row.id, () => row);
          }
        }
        sessions = mergedById.values.toList(growable: false)
          ..sort((a, b) => b.createdAt.compareTo(a.createdAt));
      }

      final widgetSession = widget.selectedSession;
      if (widgetSession != null &&
          widgetSession.id > 0 &&
          _selectedSessionIds.contains(widgetSession.id) &&
          !sessions.any((s) => s.id == widgetSession.id)) {
        sessions = <TrackerSessionModel>[widgetSession, ...sessions];
      }

      const usingLatestFallback = false;
      const fallbackMessage = '';

      // Если за выбранную дату/время пусто — оставляем период пустым.
      // Не подставляем последнюю сессию, чтобы отчёт и карта не показывали чужой день.
      if (sessions.isEmpty && !widget.liveRunning && _onlySelectedDate) {
        dashboard = const TrackerDashboardModel(
            summary: <String, dynamic>{},
            players: <TrackerPlayerLoadRow>[],
            alerts: <Map<String, dynamic>>[]);
      }

      final activeSessions = _activeSessions(sessions);
      final singleSessionId = _singleSelectedSessionId(sessions);

      // V169: Локомоторика / Механика / Микроцикл / ИИ / Отчёты и
      // Офлайн GPS имеют собственные источники данных. Им нужен список
      // выбранных session rows, но не нужно ждать общий GPS+Polar bundle.
      // В V168 они могли навсегда оставаться на «Сессии загружены · 24%»,
      // если один GPS endpoint зависал. Теперь эти разделы открываются сразу.
      final lightweightReportTab = _tab >= 6 && _tab <= 11;
      if (lightweightReportTab && !widget.liveRunning) {
        _publishBundleProgress(requestKey, .96, 'Открываем раздел');
        return _AnalyticsBundle(
          dashboard: dashboard,
          sessions: activeSessions.isNotEmpty ? activeSessions : sessions,
          players: widget.players,
          heatmap: const <TrackerHeatPoint>[],
          sessionPoints: const <ActionTrackerGpsPoint>[],
          heartRate: _AnalyticsHeartRate.empty(),
          usingLatestFallback: usingLatestFallback,
          fallbackMessage: fallbackMessage,
        );
      }

      final shouldLoadSessionPoints =
          !_useAllSessionsForPeriod || selectedPlayerIds.isNotEmpty;
      final selectedSessionIds =
          (shouldLoadSessionPoints && activeSessions.isNotEmpty)
              ? activeSessions
                  .map((s) => s.id)
                  .where((id) => id > 0)
                  .toList(growable: false)
              : const <int>[];

      final hrSessionIds = singleSessionId == null
          ? activeSessions
              .map((s) => s.id)
              .where((id) => id > 0)
              .toList(growable: false)
          : const <int>[];
      Future<List<ActionTrackerGpsPoint>> pointsFuture() async {
        if (widget.liveRunning) return const <ActionTrackerGpsPoint>[];
        if (selectedSessionIds.length > 1) {
          // V88 TEAM SESSION: одна командная тренировка хранится как несколько
          // final session rows — по одной на игрока. Раньше каждый session_id
          // запрашивался без player_id, а затем все точки глобально сортировались
          // по абсолютному времени. При случайной чужой live-записи это давало
          // 1400+ минут и схлопывало GPS-bounds карты в угол.
          // Теперь каждый технический row грузим строго со своим player_id и
          // сохраняем треки блоками игроков. _segmentBreaks() разделяет их.
          final pointSessions = activeSessions
              .where((session) =>
                  session.id > 0 && selectedSessionIds.contains(session.id))
              .toList(growable: false);
          final chunks = await Future.wait(
            pointSessions.map(
              (session) => _analyticsRequestOr<List<ActionTrackerGpsPoint>>(
                widget.api.loadSessionPoints(
                  teamId: widget.teamId,
                  playerId: session.playerId,
                  sessionId: session.id,
                ),
                fallback: const <ActionTrackerGpsPoint>[],
                label: 'gps_session_${session.id}',
                timeout: const Duration(seconds: 8),
              ),
            ),
          );
          final rows = <ActionTrackerGpsPoint>[];
          for (final chunk in chunks) {
            if (chunk.isEmpty) continue;
            final sorted = [...chunk]
              ..sort((a, b) => a.timeMs.compareTo(b.timeMs));
            rows.addAll(sorted);
          }
          return rows;
        }
        TrackerSessionModel? singleSessionRow;
        if (singleSessionId != null) {
          for (final session in activeSessions) {
            if (session.id == singleSessionId) {
              singleSessionRow = session;
              break;
            }
          }
        }
        return _analyticsRequestOr<List<ActionTrackerGpsPoint>>(
          widget.api.loadSessionPoints(
            teamId: widget.teamId,
            playerId: singleSessionRow?.playerId ??
                (selectedPlayerIds.length == 1
                    ? selectedPlayerIds.first
                    : (_mapForceTeamScope ? null : widget.selectedPlayer?.id)),
            sessionId: singleSessionId,
            date: singleSessionId != null ? null : date,
            fromTime: singleSessionId != null ? null : fromTime,
            toTime: singleSessionId != null ? null : toTime,
          ),
          fallback: const <ActionTrackerGpsPoint>[],
          label: 'gps_points',
          timeout: const Duration(seconds: 9),
        );
      }

      final pointsRequest = pointsFuture();
      // Пульс можно грузить параллельно с GPS. Heatmap endpoint запускаем
      // только если GPS-точек реально нет: раньше запрос стартовал всегда и
      // Analytics ждал его даже когда затем полностью использовал gpsHeat.
      final heartRequest = _analyticsRequestOr<Map<String, dynamic>>(
        widget.api.loadHeartRateSummary(
        teamId: widget.teamId,
        // Пульс в аналитике грузим командой. Конкретного игрока выбираем уже
        // верхними чипами "Все / Игрок", иначе вкладка "Пульс" превращалась
        // в график только текущего фокус-игрока.
        playerId: null,
        sessionId: singleSessionId,
        sessionIds: hrSessionIds,
        date: (singleSessionId == null && hrSessionIds.isEmpty) ? date : null,
        fromTime:
            (singleSessionId == null && hrSessionIds.isEmpty) ? fromTime : null,
        toTime:
            (singleSessionId == null && hrSessionIds.isEmpty) ? toTime : null,
        sessionKind: _sessionKindApiValue(),
        ),
        fallback: const <String, dynamic>{},
        label: 'heart_rate_summary',
        timeout: const Duration(seconds: 8),
      );
      final sessionPoints = await pointsRequest;

      // PERSONAL GHOST: для личной аналитики Ghost сравнивает текущую
      // тренировку не со вторым игроком, а с предыдущей личной сессией
      // этого же игрока. Прогресс синхронизируется по относительному времени.
      TrackerSessionModel? personalGhostSession;
      List<ActionTrackerGpsPoint> personalGhostPoints =
          const <ActionTrackerGpsPoint>[];
      if (widget.personalMode &&
          !widget.liveRunning &&
          singleSessionId != null) {
        try {
          TrackerSessionModel? currentSession;
          for (final row in activeSessions) {
            if (row.id == singleSessionId) {
              currentSession = row;
              break;
            }
          }
          currentSession ??= widget.selectedSession;
          final fixedPlayerId = widget.fixedPlayerId ??
              currentSession?.playerId ??
              widget.selectedPlayer?.id;
          final history = await _analyticsRequestOr<List<TrackerSessionModel>>(
            widget.api.loadSessions(
              teamId: widget.teamId,
              playerId: null,
              date: null,
              limit: 120,
              sessionKind: 'personal',
            ),
            fallback: const <TrackerSessionModel>[],
            label: 'personal_ghost_sessions',
            timeout: const Duration(seconds: 7),
          );
          final candidates = history.where((row) {
            if (row.id <= 0 || row.id == singleSessionId) return false;
            if (!row.personalSession) return false;
            if (fixedPlayerId != null && fixedPlayerId > 0) {
              return _sessionMatchesPlayerIds(row, <int>{fixedPlayerId});
            }
            return true;
          }).toList(growable: false);
          final currentTime = currentSession == null
              ? null
              : _sessionDateTime(currentSession);
          final older = candidates.where((row) {
            final dt = _sessionDateTime(row);
            return currentTime == null || dt == null || dt.isBefore(currentTime);
          }).toList(growable: false)
            ..sort((a, b) {
              final ad = _sessionDateTime(a);
              final bd = _sessionDateTime(b);
              if (ad == null && bd == null) return b.id.compareTo(a.id);
              if (ad == null) return 1;
              if (bd == null) return -1;
              return bd.compareTo(ad);
            });
          if (older.isNotEmpty) {
            personalGhostSession = older.first;
            personalGhostPoints = await _analyticsRequestOr<List<ActionTrackerGpsPoint>>(
              widget.api.loadSessionPoints(
                teamId: widget.teamId,
                playerId: personalGhostSession.playerId ?? fixedPlayerId,
                sessionId: personalGhostSession.id,
              ),
              fallback: const <ActionTrackerGpsPoint>[],
              label: 'personal_ghost_points_${personalGhostSession.id}',
              timeout: const Duration(seconds: 7),
            );
            if (personalGhostPoints.length > 1) {
              personalGhostPoints = [...personalGhostPoints]
                ..sort((a, b) => a.timeMs.compareTo(b.timeMs));
            }
          }
        } catch (e) {
          widget.onDebug('Personal Ghost: предыдущая сессия недоступна', {
            'session_id': singleSessionId,
            'error': '$e',
          });
        }
      }
      _publishBundleProgress(requestKey, .54, 'GPS и движение');
      final heat = sessionPoints.isNotEmpty
          ? const <TrackerHeatPoint>[]
          : ((activeSessions.isEmpty && !widget.liveRunning)
              ? const <TrackerHeatPoint>[]
              : await _analyticsRequestOr<List<TrackerHeatPoint>>(
                  widget.api.loadHeatmap(
                    teamId: widget.teamId,
                    playerId: singleSessionId != null
                        ? null
                        : (selectedPlayerIds.length == 1
                            ? selectedPlayerIds.first
                            : (_mapForceTeamScope ? null : widget.selectedPlayer?.id)),
                    sessionId: singleSessionId,
                    fieldId: null,
                    date: singleSessionId != null ? null : date,
                    fromTime: singleSessionId != null ? null : fromTime,
                    toTime: singleSessionId != null ? null : toTime,
                  ),
                  fallback: const <TrackerHeatPoint>[],
                  label: 'heatmap',
                  timeout: const Duration(seconds: 8),
                ));
      final gpsHeat = _heatmapFromGps(sessionPoints, widget.selectedField);
      final effectiveHeat =
          _isHeatCollapsed(heat) ? gpsHeat : (heat.isNotEmpty ? heat : gpsHeat);
      _publishBundleProgress(requestKey, .70, 'Карта готова');
      final hrJson = await heartRequest;
      var heartRate = _restrictHeartRateToFixedPlayer(
        _AnalyticsHeartRate.fromJson(hrJson),
      );
      _publishBundleProgress(requestKey, .82, 'Пульс и нагрузка');

      // Новый endpoint ЧСС на старом сервере может вернуть не пустой, но
      // частичный ответ: например одного игрока из четырёх. Для выбранной
      // групповой тренировки всё равно дочитываем каждую её техническую запись
      // и объединяем Polar-данные. Иначе наличие хотя бы одной HR-точки
      // блокировало fallback и вкладка «Пульс» показывала одного участника.
      final selectedGroupHasSeveralRows =
          !_useAllSessionsForPeriod && activeSessions.length > 1;
      final needDetailedHeartFallback = _tab == 3;
      if (needDetailedHeartFallback &&
          (selectedGroupHasSeveralRows ||
              (heartRate.effectiveSamplesCount <= 0 &&
                  heartRate.timelineForChart.isEmpty))) {
        final polarFallbackRows = activeSessions
            .where((session) =>
                session.heartRateSamplesCount > 0 ||
                _trackerSessionHasPolar(session))
            .toList(growable: false);
        final fallbackRows =
            polarFallbackRows.isNotEmpty ? polarFallbackRows : activeSessions;
        final fallbackSessionIds = selectedGroupHasSeveralRows
            ? activeSessions
                .map((session) => session.id)
                .where((id) => id > 0)
                .toSet()
                .take(12)
                .toList(growable: false)
            : singleSessionId != null
                ? <int>[singleSessionId]
                : fallbackRows
                    .map((session) => session.id)
                    .where((id) => id > 0)
                    .toSet()
                    .take(12)
                    .toList(growable: false);
        if (fallbackSessionIds.isNotEmpty) {
          final reportHrRows =
              await Future.wait(fallbackSessionIds.map((sessionId) async {
            final reportHrJson = await _analyticsRequestOr<Map<String, dynamic>>(
              widget.api.loadTrainingReportHeartRate(
                teamId: widget.teamId,
                sessionId: sessionId,
                playerId: null,
              ),
              fallback: const <String, dynamic>{},
              label: 'report_hr_$sessionId',
              timeout: const Duration(seconds: 7),
            );
            return _AnalyticsHeartRate.fromJson(reportHrJson);
          }));
          final fallbackHeartRate = _restrictHeartRateToFixedPlayer(
            _mergeAnalyticsHeartRates(
              <_AnalyticsHeartRate>[heartRate, ...reportHrRows],
            ),
          );
          if (fallbackHeartRate.effectiveSamplesCount > 0 ||
              fallbackHeartRate.timelineForChart.isNotEmpty)
            heartRate = fallbackHeartRate;
        }
      }
      _publishBundleProgress(requestKey, .96, 'Формируем экран');
      return _AnalyticsBundle(
        dashboard: dashboard,
        sessions: activeSessions.isNotEmpty ? activeSessions : sessions,
        players: widget.players,
        heatmap: effectiveHeat,
        sessionPoints: sessionPoints,
        heartRate: heartRate,
        personalGhostSession: personalGhostSession,
        personalGhostPoints: personalGhostPoints,
        usingLatestFallback: usingLatestFallback,
        fallbackMessage: fallbackMessage,
      );
    } catch (e) {
      // Аналитика не должна закрывать весь экран из-за одной ошибки API.
      // Серверная причина остаётся видна в debug/console, а UI показывает пустой период.
      // ignore: avoid_print
      print('[TRACKER_ANALYTICS_BUNDLE] fallback: $e');
      return _AnalyticsBundle.empty();
    }
  }
}

List<TrackerHeatPoint> _heatmapFromGpsStatic(
    List<ActionTrackerGpsPoint> points, TrackerFieldModel? field) {
  if (points.length < 2) return const <TrackerHeatPoint>[];

  List<TrackerHeatPoint> buildFromOffsets(List<Offset> offsets) {
    final buckets = <String, double>{};
    for (final o in offsets) {
      final x = (o.dx.clamp(0.0, 1.0) * 105.0).toDouble();
      final y = (o.dy.clamp(0.0, 1.0) * 68.0).toDouble();
      final key = '${x.toStringAsFixed(1)}:${y.toStringAsFixed(1)}';
      buckets[key] = (buckets[key] ?? 0) + 1;
    }
    return buckets.entries.map((e) {
      final parts = e.key.split(':');
      return TrackerHeatPoint(
        x: double.tryParse(parts[0]) ?? 0,
        y: double.tryParse(parts[1]) ?? 0,
        value: e.value,
      );
    }).toList(growable: false);
  }

  if (_shouldUseFieldProjection(points, field)) {
    final projected = <Offset>[];
    for (final p in points) {
      final q = TrackerPitchProjector.projectGps(field,
          latitude: p.latitude, longitude: p.longitude);
      if (q != null) projected.add(Offset(q.clampedNx, q.clampedNy));
    }
    if (projected.length >= 2) return buildFromOffsets(projected);
  }

  final bounds = _Bounds.fromGps(points);
  final offsets = points.map((p) {
    final x = ((p.longitude - bounds.minLng) / (bounds.maxLng - bounds.minLng))
        .clamp(0.0, 1.0)
        .toDouble();
    final y = (1 -
            ((p.latitude - bounds.minLat) / (bounds.maxLat - bounds.minLat))
                .clamp(0.0, 1.0))
        .toDouble();
    return Offset(x, y);
  }).toList(growable: false);
  return buildFromOffsets(offsets);
}

bool _isHeatCollapsed(List<TrackerHeatPoint> points) {
  if (points.length < 2) return points.isNotEmpty;
  var minX = points.first.x,
      maxX = points.first.x,
      minY = points.first.y,
      maxY = points.first.y;
  var total = 0.0;
  for (final p in points) {
    minX = math.min(minX, p.x);
    maxX = math.max(maxX, p.x);
    minY = math.min(minY, p.y);
    maxY = math.max(maxY, p.y);
    total += p.value;
  }
  return total > 0 && ((maxX - minX).abs() < 1.0 && (maxY - minY).abs() < 1.0);
}

String _formatSessionDateTime(String raw) {
  final dt = _parseTrackerDateTime(raw);
  if (dt == null) return raw.isEmpty ? 'без времени' : raw;
  return '${dt.day.toString().padLeft(2, '0')}.${dt.month.toString().padLeft(2, '0')}.${dt.year} ${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}';
}

DateTime? _parseTrackerDateTime(String rawValue) =>
    _trackerMoscowDateTime(rawValue);

class _AnalyticsBundle {
  const _AnalyticsBundle({
    required this.dashboard,
    required this.sessions,
    required this.players,
    required this.heatmap,
    required this.sessionPoints,
    required this.heartRate,
    this.personalGhostSession,
    this.personalGhostPoints = const <ActionTrackerGpsPoint>[],
    this.usingLatestFallback = false,
    this.fallbackMessage = '',
  });

  final TrackerDashboardModel dashboard;
  final List<TrackerSessionModel> sessions;
  final List<TrackerPlayerOption> players;
  final List<TrackerHeatPoint> heatmap;
  final List<ActionTrackerGpsPoint> sessionPoints;
  final _AnalyticsHeartRate heartRate;
  final TrackerSessionModel? personalGhostSession;
  final List<ActionTrackerGpsPoint> personalGhostPoints;
  final bool usingLatestFallback;
  final String fallbackMessage;

  factory _AnalyticsBundle.empty() => _AnalyticsBundle(
        dashboard: const TrackerDashboardModel(
            summary: <String, dynamic>{},
            players: <TrackerPlayerLoadRow>[],
            alerts: <Map<String, dynamic>>[]),
        sessions: <TrackerSessionModel>[],
        players: <TrackerPlayerOption>[],
        heatmap: <TrackerHeatPoint>[],
        sessionPoints: <ActionTrackerGpsPoint>[],
        heartRate: _AnalyticsHeartRate.empty(),
      );
}

class _AnalyticsHeartRate {
  const _AnalyticsHeartRate(
      {required this.players,
      required this.timeline,
      required this.avgBpm,
      required this.maxBpm,
      required this.samplesCount,
      required this.playersCount});
  final List<_AnalyticsHrPlayer> players;
  final List<_AnalyticsHrPoint> timeline;
  final double avgBpm;
  final int maxBpm;
  final int samplesCount;
  final int playersCount;

  factory _AnalyticsHeartRate.empty() => const _AnalyticsHeartRate(
      players: <_AnalyticsHrPlayer>[],
      timeline: <_AnalyticsHrPoint>[],
      avgBpm: 0,
      maxBpm: 0,
      samplesCount: 0,
      playersCount: 0);

  factory _AnalyticsHeartRate.fromJson(Map<String, dynamic> json) {
    Map<String, dynamic> mapValue(dynamic raw) =>
        raw is Map ? Map<String, dynamic>.from(raw) : const <String, dynamic>{};
    List<dynamic> listValue(dynamic raw) {
      if (raw is List) return raw;
      if (raw is Map) {
        final nested = raw['items'] ??
            raw['points'] ??
            raw['timeline'] ??
            raw['players'] ??
            raw['data'];
        return nested is List ? nested : const <dynamic>[];
      }
      return const <dynamic>[];
    }

    final summary = <String, dynamic>{
      ...mapValue(json['summary']),
      // Старые/новые PHP могут отдавать эти поля на верхнем уровне.
      if (json.containsKey('avg_bpm')) 'avg_bpm': json['avg_bpm'],
      if (json.containsKey('heart_rate_avg_bpm'))
        'avg_bpm': json['heart_rate_avg_bpm'],
      if (json.containsKey('max_bpm')) 'max_bpm': json['max_bpm'],
      if (json.containsKey('heart_rate_max_bpm'))
        'max_bpm': json['heart_rate_max_bpm'],
      if (json.containsKey('samples_count'))
        'samples_count': json['samples_count'],
      if (json.containsKey('heart_rate_samples_count'))
        'samples_count': json['heart_rate_samples_count'],
      if (json.containsKey('players_count'))
        'players_count': json['players_count'],
    };

    final rawPlayers = listValue(json['items']).isNotEmpty
        ? listValue(json['items'])
        : (listValue(json['players']).isNotEmpty
            ? listValue(json['players'])
            : (listValue(json['heart_rate_players']).isNotEmpty
                ? listValue(json['heart_rate_players'])
                : (listValue(json['player_summaries']).isNotEmpty
                    ? listValue(json['player_summaries'])
                    : listValue(json['data']))));
    final rawTimeline = listValue(json['timeline']).isNotEmpty
        ? listValue(json['timeline'])
        : (listValue(json['heart_rate_timeline']).isNotEmpty
            ? listValue(json['heart_rate_timeline'])
            : (listValue(json['hr_timeline']).isNotEmpty
                ? listValue(json['hr_timeline'])
                : (listValue(json['heartRateTimeline']).isNotEmpty
                    ? listValue(json['heartRateTimeline'])
                    : listValue(json['points']))));

    final players = rawPlayers
        .whereType<Map>()
        .map((e) => _AnalyticsHrPlayer.fromJson(Map<String, dynamic>.from(e)))
        .where((p) => p.samplesCount > 0 || p.avgBpm > 0 || p.maxBpm > 0)
        .toList(growable: false);
    final timeline = rawTimeline
        .whereType<Map>()
        .map((e) => _AnalyticsHrPoint.fromJson(Map<String, dynamic>.from(e)))
        .where((p) => p.bpm > 0)
        .toList(growable: false)
      ..sort((a, b) => (a.timeMs > 0 ? a.timeMs : a.minute * 60000)
          .compareTo(b.timeMs > 0 ? b.timeMs : b.minute * 60000));
    final samplesFromPlayers =
        players.fold<int>(0, (sum, p) => sum + p.samplesCount);
    final weightedAvg = samplesFromPlayers <= 0
        ? (players.isEmpty
            ? 0.0
            : players.fold<double>(0, (sum, p) => sum + p.avgBpm) /
                players.length)
        : players.fold<double>(
                0,
                (sum, p) =>
                    sum +
                    p.avgBpm * (p.samplesCount > 0 ? p.samplesCount : 1)) /
            players.fold<int>(
                0, (sum, p) => sum + (p.samplesCount > 0 ? p.samplesCount : 1));
    return _AnalyticsHeartRate(
      players: players,
      timeline: timeline,
      avgBpm: _jsonDouble(summary['avg_bpm'], weightedAvg),
      maxBpm: _jsonInt(summary['max_bpm'],
          players.fold<int>(0, (maxV, p) => maxV > p.maxBpm ? maxV : p.maxBpm)),
      samplesCount: _jsonInt(
          summary['samples_count'],
          (samplesFromPlayers > timeline.length
              ? samplesFromPlayers
              : timeline.length)),
      playersCount: _jsonInt(summary['players_count'], players.length),
    );
  }

  List<_AnalyticsHrPoint> get timelineForChart =>
      timeline.isNotEmpty ? timeline : _analyticsHrTimelineFromPlayers(players);
  int get effectiveSamplesCount {
    if (samplesCount > 0) return samplesCount;
    final fromPlayers = players.fold<int>(0, (sum, p) => sum + p.samplesCount);
    return timeline.length > fromPlayers ? timeline.length : fromPlayers;
  }

  int get effectivePlayersCount {
    final identities = <String>{};
    void add(int? id, String name) {
      if (id != null && id > 0) {
        identities.add('id:$id');
        return;
      }
      final normalized = name.trim().toLowerCase();
      if (normalized.isNotEmpty) identities.add('name:$normalized');
    }

    for (final player in players) {
      add(player.playerId, player.playerName);
    }
    for (final point in timeline) {
      add(point.playerId, point.playerName);
    }
    return math.max(playersCount, identities.length);
  }

  double get effectiveAvgBpm {
    if (avgBpm > 0) return avgBpm;
    final withAvg = players.where((p) => p.avgBpm > 0).toList(growable: false);
    if (withAvg.isEmpty) return 0;
    final totalSamples = withAvg.fold<int>(
        0, (sum, p) => sum + (p.samplesCount > 0 ? p.samplesCount : 1));
    return withAvg.fold<double>(
            0,
            (sum, p) =>
                sum + p.avgBpm * (p.samplesCount > 0 ? p.samplesCount : 1)) /
        (totalSamples > 0 ? totalSamples : 1);
  }

  int get effectiveMaxBpm => maxBpm > 0
      ? maxBpm
      : players.fold<int>(0, (maxV, p) => maxV > p.maxBpm ? maxV : p.maxBpm);
}

List<_AnalyticsHrPoint> _analyticsHrTimelineFromPlayers(
    List<_AnalyticsHrPlayer> players) {
  final list = players
      .where((p) => p.avgBpm > 0 || p.maxBpm > 0)
      .take(12)
      .toList(growable: false);
  if (list.isEmpty) return const <_AnalyticsHrPoint>[];
  final out = <_AnalyticsHrPoint>[];
  for (var i = 0; i < list.length; i++) {
    final p = list[i];
    final avg = p.avgBpm.round();
    final max = p.maxBpm > 0 ? p.maxBpm : avg;
    if (avg > 0) {
      out.add(_AnalyticsHrPoint(
          playerId: p.playerId,
          playerName: p.playerName,
          timeMs: 0,
          minute: i * 2,
          bpm: avg,
          zone: _analyticsZoneFromBpm(avg),
          hrLoad: p.highZoneSamples.toDouble()));
    }
    if (max > avg) {
      out.add(_AnalyticsHrPoint(
          playerId: p.playerId,
          playerName: p.playerName,
          timeMs: 0,
          minute: i * 2 + 1,
          bpm: max,
          zone: _analyticsZoneFromBpm(max),
          hrLoad: p.highZoneSamples.toDouble()));
    }
  }
  return out;
}

String _analyticsZoneFromBpm(int bpm) {
  if (bpm >= 180) return 'z5';
  if (bpm >= 160) return 'z4';
  if (bpm >= 140) return 'z3';
  if (bpm >= 120) return 'z2';
  return 'z1';
}

class _AnalyticsHrPlayer {
  const _AnalyticsHrPlayer(
      {required this.playerId,
      required this.playerName,
      required this.avgBpm,
      required this.maxBpm,
      required this.samplesCount,
      required this.z1,
      required this.z2,
      required this.z3,
      required this.z4,
      required this.z5});
  final int? playerId;
  final String playerName;
  final double avgBpm;
  final int maxBpm;
  final int samplesCount;
  final int z1;
  final int z2;
  final int z3;
  final int z4;
  final int z5;
  int get highZoneSamples => z4 + z5;

  factory _AnalyticsHrPlayer.fromJson(Map<String, dynamic> json) =>
      _AnalyticsHrPlayer(
        playerId: int.tryParse('${json['player_id'] ?? ''}'),
        playerName: '${json['player_name'] ?? json['name'] ?? 'Игрок'}',
        avgBpm: _jsonDouble(json['avg_bpm'] ?? json['heart_rate_avg_bpm']),
        maxBpm: _jsonInt(json['max_bpm'] ?? json['heart_rate_max_bpm']),
        samplesCount:
            _jsonInt(json['samples_count'] ?? json['heart_rate_samples_count']),
        z1: _jsonInt(json['z1'] ?? json['hr_z1_samples']),
        z2: _jsonInt(json['z2'] ?? json['hr_z2_samples']),
        z3: _jsonInt(json['z3'] ?? json['hr_z3_samples']),
        z4: _jsonInt(json['z4'] ?? json['hr_z4_samples']),
        z5: _jsonInt(json['z5'] ?? json['hr_z5_samples']),
      );
}

class _AnalyticsHrPoint {
  const _AnalyticsHrPoint(
      {required this.playerId,
      required this.playerName,
      required this.timeMs,
      required this.minute,
      required this.bpm,
      required this.zone,
      required this.hrLoad,
      this.activityType = ''});
  final int? playerId;
  final String playerName;
  final int timeMs;
  final int minute;
  final int bpm;
  final String zone;
  final double hrLoad;
  final String activityType;

  factory _AnalyticsHrPoint.fromJson(Map<String, dynamic> json) {
    final measured =
        '${json['measured_at'] ?? json['created_at'] ?? json['time'] ?? ''}'
            .trim();
    final parsed = measured.isEmpty ? null : _parseTrackerDateTime(measured);
    final rawTimeMs =
        _jsonInt(json['time_ms'] ?? json['timestamp_ms'] ?? json['ts_ms']);
    final timeMs = rawTimeMs > 0
        ? rawTimeMs
        : (parsed == null ? 0 : parsed.millisecondsSinceEpoch);
    final bpm = _jsonInt(json['bpm'] ?? json['hr'] ?? json['heart_rate']);
    final zone =
        '${json['hr_zone'] ?? json['zone'] ?? ''}'.trim().toLowerCase();
    return _AnalyticsHrPoint(
      playerId: int.tryParse('${json['player_id'] ?? ''}'),
      playerName: '${json['player_name'] ?? json['name'] ?? ''}',
      timeMs: timeMs,
      minute: _jsonInt(json['minute'] ?? json['minute_index'] ?? json['t_min']),
      bpm: bpm,
      zone: zone.isEmpty ? _analyticsZoneFromBpm(bpm) : zone,
      hrLoad:
          _jsonDouble(json['hr_load'] ?? json['load'] ?? json['hr_exertion']),
      activityType:
          '${json['activity_type'] ?? json['training_type'] ?? json['mode'] ?? json['activity'] ?? ''}'
              .trim()
              .toLowerCase(),
    );
  }
}

_AnalyticsHeartRate _mergeAnalyticsHeartRates(
    Iterable<_AnalyticsHeartRate> source) {
  final rates = source
      .where((rate) =>
          rate.effectiveSamplesCount > 0 ||
          rate.timelineForChart.isNotEmpty ||
          rate.players.isNotEmpty)
      .toList(growable: false);
  if (rates.isEmpty) return _AnalyticsHeartRate.empty();

  final groupedPlayers = <String, List<_AnalyticsHrPlayer>>{};
  for (final rate in rates) {
    for (final player in rate.players) {
      final normalizedName = player.playerName.trim().toLowerCase();
      final key = player.playerId != null && player.playerId! > 0
          ? 'id:${player.playerId}'
          : 'name:$normalizedName';
      groupedPlayers.putIfAbsent(key, () => <_AnalyticsHrPlayer>[]).add(player);
    }
  }

  final players = <_AnalyticsHrPlayer>[];
  for (final rawRows in groupedPlayers.values) {
    final seen = <String>{};
    final rows = rawRows.where((player) {
      final signature =
          '${player.playerId}|${player.avgBpm}|${player.maxBpm}|${player.samplesCount}|${player.z1}|${player.z2}|${player.z3}|${player.z4}|${player.z5}';
      return seen.add(signature);
    }).toList(growable: false);
    final first = rows.first;
    final weight = rows.fold<int>(
        0,
        (sum, player) =>
            sum + (player.samplesCount > 0 ? player.samplesCount : 1));
    final avg = weight <= 0
        ? 0.0
        : rows.fold<double>(
                0,
                (sum, player) =>
                    sum +
                    player.avgBpm *
                        (player.samplesCount > 0 ? player.samplesCount : 1)) /
            weight;
    players.add(_AnalyticsHrPlayer(
      playerId: first.playerId,
      playerName: first.playerName,
      avgBpm: avg,
      maxBpm:
          rows.fold<int>(0, (value, player) => math.max(value, player.maxBpm)),
      samplesCount:
          rows.fold<int>(0, (sum, player) => sum + player.samplesCount),
      z1: rows.fold<int>(0, (sum, player) => sum + player.z1),
      z2: rows.fold<int>(0, (sum, player) => sum + player.z2),
      z3: rows.fold<int>(0, (sum, player) => sum + player.z3),
      z4: rows.fold<int>(0, (sum, player) => sum + player.z4),
      z5: rows.fold<int>(0, (sum, player) => sum + player.z5),
    ));
  }
  final seenTimeline = <String>{};
  final timeline = rates
      .expand((rate) => rate.timeline)
      .where((point) => seenTimeline.add(
          '${point.playerId}|${point.playerName}|${point.timeMs}|${point.minute}|${point.bpm}|${point.zone}'))
      .toList(growable: false)
    ..sort((a, b) => (a.timeMs > 0 ? a.timeMs : a.minute * 60000)
        .compareTo(b.timeMs > 0 ? b.timeMs : b.minute * 60000));

  // Некоторые версии report API возвращают Polar timeline по всем игрокам,
  // но блок players только по одному. Достраиваем недостающие строки прямо из
  // timeline, чтобы счётчик, карточки и фильтр «Все / игрок» видели одинаковый
  // состав выбранной тренировки.
  String playerKey(int? id, String name) {
    if (id != null && id > 0) return 'id:$id';
    return 'name:${name.trim().toLowerCase()}';
  }

  final knownPlayerKeys = players
      .map((player) => playerKey(player.playerId, player.playerName))
      .toSet();
  final timelinePlayers = <String, List<_AnalyticsHrPoint>>{};
  for (final point in timeline) {
    final key = playerKey(point.playerId, point.playerName);
    if (key == 'name:' || knownPlayerKeys.contains(key)) continue;
    timelinePlayers.putIfAbsent(key, () => <_AnalyticsHrPoint>[]).add(point);
  }
  for (final points in timelinePlayers.values) {
    if (points.isEmpty) continue;
    final first = points.first;
    final bpmValues = points
        .map((point) => point.bpm)
        .where((bpm) => bpm > 0)
        .toList(growable: false);
    if (bpmValues.isEmpty) continue;
    int zoneCount(String zone) =>
        points.where((point) => point.zone.toLowerCase() == zone).length;
    players.add(_AnalyticsHrPlayer(
      playerId: first.playerId,
      playerName: first.playerName.trim().isEmpty ? 'Игрок' : first.playerName,
      avgBpm:
          bpmValues.fold<int>(0, (sum, bpm) => sum + bpm) / bpmValues.length,
      maxBpm: bpmValues.fold<int>(0, math.max),
      samplesCount: bpmValues.length,
      z1: zoneCount('z1'),
      z2: zoneCount('z2'),
      z3: zoneCount('z3'),
      z4: zoneCount('z4'),
      z5: zoneCount('z5'),
    ));
  }
  players.sort((a, b) => a.playerName.compareTo(b.playerName));

  final totalWeight = players.fold<int>(
      0,
      (sum, player) =>
          sum + (player.samplesCount > 0 ? player.samplesCount : 1));
  final avgBpm = totalWeight <= 0
      ? 0.0
      : players.fold<double>(
              0,
              (sum, player) =>
                  sum +
                  player.avgBpm *
                      (player.samplesCount > 0 ? player.samplesCount : 1)) /
          totalWeight;
  return _AnalyticsHeartRate(
    players: players,
    timeline: timeline,
    avgBpm: avgBpm,
    maxBpm:
        players.fold<int>(0, (value, player) => math.max(value, player.maxBpm)),
    samplesCount:
        players.fold<int>(0, (sum, player) => sum + player.samplesCount),
    playersCount: players.length,
  );
}

int _jsonInt(dynamic value, [int fallback = 0]) {
  if (value is int) return value;
  if (value is num) return value.toInt();
  return int.tryParse('$value') ?? fallback;
}

double _jsonDouble(dynamic value, [double fallback = 0]) {
  if (value is num) return value.toDouble();
  return double.tryParse('$value'.replaceAll(',', '.')) ?? fallback;
}

class _HeartRateAnalyticsTab extends StatefulWidget {
  const _HeartRateAnalyticsTab({
    required this.heartRate,
    required this.selectedPlayer,
    required this.rosterPlayers,
    required this.scopeLabel,
    this.onOpenAiLoadPoint,
    this.onContextChanged,
  });
  final _AnalyticsHeartRate heartRate;
  final TrackerPlayerOption? selectedPlayer;
  final List<TrackerPlayerOption> rosterPlayers;
  final String scopeLabel;
  final ValueChanged<_AnalyticsHrPoint>? onOpenAiLoadPoint;
  final ValueChanged<Map<String, dynamic>>? onContextChanged;

  @override
  State<_HeartRateAnalyticsTab> createState() => _HeartRateAnalyticsTabState();
}

class _HeartRateAnalyticsTabState extends State<_HeartRateAnalyticsTab> {
  final Set<String> _selectedHrPlayerKeys = <String>{};
  _AnalyticsHrPoint? _focusedLoadPoint;
  String _activityFilter = 'all';
  bool _loadPointsExpanded = false;

  @override
  void didUpdateWidget(covariant _HeartRateAnalyticsTab oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.heartRate != widget.heartRate) {
      final available =
          _analyticsHrFilterOptions(widget.heartRate).map((e) => e.key).toSet();
      _selectedHrPlayerKeys.removeWhere((key) => !available.contains(key));
      _focusedLoadPoint = null;
    }
  }

  void _togglePlayer(String key) {
    setState(() {
      _focusedLoadPoint = null;
      if (_selectedHrPlayerKeys.isEmpty) {
        _selectedHrPlayerKeys.add(key);
      } else if (_selectedHrPlayerKeys.contains(key)) {
        _selectedHrPlayerKeys.remove(key);
      } else {
        _selectedHrPlayerKeys.add(key);
      }
    });
    _notifyContextChanged();
  }

  void _notifyContextChanged({_AnalyticsHrPoint? point}) {
    final options = _analyticsHrFilterOptions(widget.heartRate);
    final selected = _selectedHrPlayerKeys.isEmpty
        ? const <_AnalyticsHrFilterOption>[]
        : options
            .where((option) => _selectedHrPlayerKeys.contains(option.key))
            .toList(growable: false);
    final playerIds = selected
        .map((option) => option.playerId)
        .whereType<int>()
        .where((id) => id > 0)
        .toSet()
        .toList()
      ..sort();
    final playerNames = selected
        .map((option) => option.label.trim())
        .where((name) => name.isNotEmpty)
        .toSet()
        .toList(growable: false);
    final focused = point ?? _focusedLoadPoint;
    final focusedPlayerId = focused?.playerId;
    final focusedPlayerName = focused?.playerName.trim() ?? '';
    final effectivePlayerIds = focusedPlayerId != null && focusedPlayerId > 0
        ? <int>[focusedPlayerId]
        : playerIds;
    final effectivePlayerNames = focusedPlayerName.isNotEmpty
        ? <String>[focusedPlayerName]
        : playerNames;
    widget.onContextChanged?.call(<String, dynamic>{
      'analytics_tab': 'Пульс',
      'heart_rate_player_keys': _selectedHrPlayerKeys.toList(growable: false),
      'player_ids': effectivePlayerIds,
      'player_names': effectivePlayerNames,
      'selection_mode': focused != null
          ? 'single_player'
          : selected.isEmpty
              ? 'team'
              : (selected.length == 1 ? 'single_player' : 'players'),
      if (effectivePlayerIds.length == 1) 'player_id': effectivePlayerIds.first,
      if (effectivePlayerNames.length == 1)
        'player_name': effectivePlayerNames.first,
      'heart_rate_activity_filter': _activityFilter,
      if (focused != null) ...<String, dynamic>{
        'selected_heart_rate_point': true,
        'bpm': focused.bpm,
        'zone': focused.zone,
        'minute': focused.minute,
        'time_ms': focused.timeMs,
        'hr_load': focused.hrLoad,
        'activity_type': focused.activityType,
      },
    });
  }

  @override
  Widget build(BuildContext context) {
    final raw =
        _resolveAnalyticsHeartRate(widget.heartRate, widget.rosterPlayers);
    final teamMode =
        _selectedHrPlayerKeys.isEmpty && raw.effectivePlayersCount > 1;
    const title = 'Polar H10';
    if (raw.effectiveSamplesCount <= 0 &&
        raw.timelineForChart.isEmpty &&
        raw.players.isEmpty) {
      return const _Empty(
          icon: Icons.favorite_border_rounded,
          text:
              'По выбранному периоду нет данных Polar H10. Проверьте привязку датчика и время сессии.');
    }
    final playerFiltered = _selectedHrPlayerKeys.isEmpty
        ? raw
        : _analyticsHeartRateFiltered(raw, _selectedHrPlayerKeys);
    final heartRate = _activityFilter == 'all'
        ? playerFiltered
        : _analyticsHeartRateByActivity(playerFiltered, _activityFilter);
    return LayoutBuilder(builder: (context, c) {
      final compact = c.maxWidth < 720;
      final filter = _AnalyticsHrPlayerFilterBar(
        heartRate: raw,
        rosterPlayers: widget.rosterPlayers,
        selectedKeys: _selectedHrPlayerKeys,
        onAll: () {
          setState(() {
            _selectedHrPlayerKeys.clear();
            _focusedLoadPoint = null;
          });
          _notifyContextChanged();
        },
        onToggle: _togglePlayer,
      );
      final scopeBar = Container(
        height: 40,
        padding: const EdgeInsets.symmetric(horizontal: 12),
        decoration: BoxDecoration(
            color: _AA.greenSoft, borderRadius: BorderRadius.circular(14)),
        child: Row(children: [
          const Icon(Icons.event_available_rounded, color: _AA.green, size: 17),
          const SizedBox(width: 7),
          Expanded(
              child: Text(widget.scopeLabel,
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                      color: _AA.text,
                      fontSize: 11.8,
                      fontWeight: FontWeight.w700))),
          Text(
              teamMode
                  ? 'Все игроки'
                  : '${_selectedHrPlayerKeys.length} выбрано',
              style: const TextStyle(
                  color: _AA.green,
                  fontSize: 11.2,
                  fontWeight: FontWeight.w700)),
        ]),
      );
      final summary = _HeartRateSummaryPanel(heartRate: heartRate);
      final activityBar = _AnalyticsHrActivityBar(
        value: _activityFilter,
        onChanged: (value) {
          setState(() {
            _activityFilter = value;
            _focusedLoadPoint = null;
          });
          _notifyContextChanged();
        },
      );
      final chart = _Panel(
        title: 'Пульс по времени',
        cmrStyle: true,
        dotAccent: true,
        surfaceColor: const Color(0xFFFFF5F5),
        subtitle:
            'нажмите точку графика или событие нагрузки справа — откроется точное время и оценка',
        child: _AnalyticsHrLineChart(
            heartRate: heartRate, focusedPoint: _focusedLoadPoint),
      );
      final playerChart = _Panel(
          title: 'Средний / максимальный пульс',
          cmrStyle: true,
          dotAccent: true,
          surfaceColor: const Color(0xFFFFF8F8),
          subtitle: 'зелёная точка — средний bpm, красная — максимум',
          child: _AnalyticsHrPlayerSummaryChart(heartRate: heartRate));
      final zones = _Panel(
          title: 'Зоны ЧСС',
          cmrStyle: true,
          dotAccent: true,
          surfaceColor: const Color(0xFFFFF8F5),
          subtitle: 'распределение по Z1–Z5 по выбранным игрокам',
          child: _AnalyticsHrZonesPanel(heartRate: heartRate));
      final players = _Panel(
          title: title,
          cmrStyle: true,
          dotAccent: true,
          surfaceColor: const Color(0xFFF8FAF9),
          subtitle: 'игроки Polar H10 и внутренняя нагрузка',
          child: _AnalyticsHrPlayersList(
              heartRate: heartRate, rosterPlayers: widget.rosterPlayers));
      final loadEvents = _Panel(
        title: 'Точки нагрузки · ИИ',
        cmrStyle: true,
        dotAccent: true,
        surfaceColor: const Color(0xFFFFF7F7),
        subtitle:
            'красные интервалы Z4–Z5; нажмите, чтобы перейти к моменту на графике',
        trailing: IconButton(
          tooltip: _loadPointsExpanded ? 'Свернуть' : 'Развернуть',
          padding: EdgeInsets.zero,
          constraints: const BoxConstraints.tightFor(width: 28, height: 28),
          onPressed: () =>
              setState(() => _loadPointsExpanded = !_loadPointsExpanded),
          icon: Icon(
              _loadPointsExpanded
                  ? Icons.close_fullscreen_rounded
                  : Icons.open_in_full_rounded,
              size: 15,
              color: _AA.green),
        ),
        child: _AnalyticsHrLoadEventsPanel(
          heartRate: heartRate,
          rosterPlayers: widget.rosterPlayers,
          selected: _focusedLoadPoint,
          onSelect: (point) {
            setState(() => _focusedLoadPoint = point);
            _notifyContextChanged(point: point);
          },
          onOpenAi: widget.onOpenAiLoadPoint == null
              ? null
              : (point) {
                  _notifyContextChanged(point: point);
                  widget.onOpenAiLoadPoint!(point);
                },
        ),
      );
      final aiPassport = _Panel(
        title: 'ИИ-паспорт нагрузки',
        cmrStyle: true,
        dotAccent: true,
        surfaceColor: const Color(0xFFF4FAF6),
        subtitle:
            'интервалы Z4–Z5, восстановление, риск и рекомендации тренеру',
        child: _HrAiPassportPanel(
          heartRate: heartRate,
          rosterPlayers: widget.rosterPlayers,
          focusedPoint: _focusedLoadPoint,
          onFocus: (point) {
            setState(() => _focusedLoadPoint = point);
            _notifyContextChanged(point: point);
          },
        ),
      );
      if (compact) {
        return ListView(padding: const EdgeInsets.all(6), children: [
          scopeBar,
          const SizedBox(height: 7),
          SizedBox(height: 54, child: filter),
          const SizedBox(height: 7),
          SizedBox(height: 46, child: activityBar),
          const SizedBox(height: 7),
          SizedBox(height: 96, child: summary),
          const SizedBox(height: 7),
          SizedBox(height: 520, child: chart),
          const SizedBox(height: 7),
          SizedBox(height: 250, child: playerChart),
          const SizedBox(height: 7),
          SizedBox(height: 190, child: zones),
          const SizedBox(height: 7),
          SizedBox(height: _loadPointsExpanded ? 540 : 320, child: loadEvents),
          if (!_loadPointsExpanded) ...[
            const SizedBox(height: 7),
            SizedBox(height: 430, child: aiPassport),
            const SizedBox(height: 7),
            SizedBox(height: 260, child: players),
          ],
        ]);
      }
      final highPoints = heartRate.timelineForChart
          .where((p) => p.bpm >= 160 || p.zone == 'z4' || p.zone == 'z5')
          .length;
      final highPct = heartRate.timelineForChart.isEmpty
          ? 0
          : (highPoints / heartRate.timelineForChart.length * 100).round();
      return Padding(
        padding: const EdgeInsets.all(6),
        child: Row(children: [
          Expanded(
            flex: 7,
            child: Column(children: [
              scopeBar,
              const SizedBox(height: 7),
              SizedBox(height: 54, child: filter),
              const SizedBox(height: 7),
              SizedBox(
                height: 50,
                child: _HeartRateControlStrip(
                  activityBar: activityBar,
                  summary: _HeartRateSummaryStrip(heartRate: heartRate),
                ),
              ),
              const SizedBox(height: 7),
              Expanded(
                child: SingleChildScrollView(
                  physics: const BouncingScrollPhysics(),
                  child: SizedBox(height: 520, child: chart),
                ),
              ),
            ]),
          ),
          const SizedBox(width: 7),
          SizedBox(
            width: math.min(330.0, c.maxWidth * .31),
            child: Column(children: [
              Expanded(
                child: _Panel(
                  title: 'Точки нагрузки · $highPoints',
                  cmrStyle: true,
                  dotAccent: true,
                  surfaceColor: const Color(0xFFFFF7F7),
                  subtitle: _loadPointsExpanded
                      ? 'Расширенный просмотр · Z4–Z5 · $highPct% времени'
                      : 'Z4–Z5 · $highPct% времени · нажмите точку для перехода на график',
                  trailing: IconButton(
                    tooltip: _loadPointsExpanded
                        ? 'Свернуть точки нагрузки'
                        : 'Развернуть точки нагрузки',
                    padding: EdgeInsets.zero,
                    constraints:
                        const BoxConstraints.tightFor(width: 28, height: 28),
                    onPressed: () => setState(
                        () => _loadPointsExpanded = !_loadPointsExpanded),
                    icon: Icon(
                        _loadPointsExpanded
                            ? Icons.close_fullscreen_rounded
                            : Icons.open_in_full_rounded,
                        size: 15,
                        color: _AA.green),
                  ),
                  child: _AnalyticsHrLoadEventsPanel(
                    heartRate: heartRate,
                    rosterPlayers: widget.rosterPlayers,
                    selected: _focusedLoadPoint,
                    onSelect: (point) {
                      setState(() => _focusedLoadPoint = point);
                      _notifyContextChanged(point: point);
                    },
                  ),
                ),
              ),
              if (!_loadPointsExpanded) ...[
                const SizedBox(height: 7),
                _HrDetailLauncher(
                  icon: Icons.auto_awesome_rounded,
                  title: 'ИИ-паспорт',
                  value: 'Открыть',
                  note: 'риски, интервалы, восстановление',
                  tone: _AA.green,
                  builder: (_) => aiPassport,
                ),
                const SizedBox(height: 7),
                _HrDetailLauncher(
                  icon: Icons.monitor_heart_rounded,
                  title: 'Средний / максимум',
                  value:
                      '${heartRate.effectiveAvgBpm.toStringAsFixed(0)} / ${heartRate.effectiveMaxBpm}',
                  note: 'bpm по выбранным игрокам',
                  tone: _AA.green,
                  builder: (_) => playerChart,
                ),
                const SizedBox(height: 7),
                _HrDetailLauncher(
                  icon: Icons.donut_large_rounded,
                  title: 'Зоны ЧСС',
                  value: 'Z1–Z5',
                  note: 'распределение нагрузки',
                  tone: const Color(0xFFF97316),
                  builder: (_) => zones,
                ),
                const SizedBox(height: 7),
                _HrDetailLauncher(
                  icon: Icons.groups_rounded,
                  title: 'Polar H10',
                  value: '${heartRate.effectivePlayersCount}',
                  note: 'игроков · нажмите для списка',
                  tone: _AA.green,
                  builder: (_) => players,
                ),
              ],
            ]),
          ),
        ]),
      );
    });
  }
}

_AnalyticsHeartRate _resolveAnalyticsHeartRate(
    _AnalyticsHeartRate source, List<TrackerPlayerOption> roster) {
  TrackerPlayerOption? byId(int? id) {
    if (id == null || id <= 0) return null;
    for (final p in roster) {
      if (p.id == id || p.identityIds.contains(id)) return p;
    }
    return null;
  }

  String resolvedName(int? id, String raw) {
    final rosterPlayer = byId(id);
    if (rosterPlayer != null && rosterPlayer.name.trim().isNotEmpty)
      return rosterPlayer.name.trim();
    final value = raw.trim();
    final technical = value.isEmpty ||
        RegExp(r'^(игрок|player)(\s*\d+)?$', caseSensitive: false)
            .hasMatch(value);
    return technical ? (id != null && id > 0 ? 'Игрок $id' : 'Игрок') : value;
  }

  final players = source.players
      .map((p) => _AnalyticsHrPlayer(
            playerId: p.playerId,
            playerName: resolvedName(p.playerId, p.playerName),
            avgBpm: p.avgBpm,
            maxBpm: p.maxBpm,
            samplesCount: p.samplesCount,
            z1: p.z1,
            z2: p.z2,
            z3: p.z3,
            z4: p.z4,
            z5: p.z5,
          ))
      .toList(growable: false);

  final timeline = source.timeline
      .map((p) => _AnalyticsHrPoint(
            playerId: p.playerId,
            playerName: resolvedName(p.playerId, p.playerName),
            timeMs: p.timeMs,
            minute: p.minute,
            bpm: p.bpm,
            zone: p.zone,
            hrLoad: p.hrLoad,
            activityType: p.activityType,
          ))
      .toList(growable: false);

  return _AnalyticsHeartRate(
    players: players,
    timeline: timeline,
    avgBpm: source.avgBpm,
    maxBpm: source.maxBpm,
    samplesCount: source.samplesCount,
    playersCount: source.playersCount,
  );
}

TrackerPlayerOption? _analyticsRosterPlayer(
    List<TrackerPlayerOption> roster, int? id) {
  if (id == null || id <= 0) return null;
  for (final player in roster) {
    if (player.id == id || player.identityIds.contains(id)) return player;
  }
  return null;
}

Widget _analyticsPlayerAvatar(TrackerPlayerOption? player, {double size = 28}) {
  final avatar = player?.avatar?.trim() ?? '';
  return ClipRRect(
    borderRadius: BorderRadius.circular(size * .34),
    child: Container(
      width: size,
      height: size,
      color: Colors.white,
      child: avatar.isEmpty
          ? const Icon(Icons.person_rounded, color: _AA.green, size: 17)
          : Image.network(
              avatar,
              fit: BoxFit.cover,
              errorBuilder: (_, __, ___) =>
                  const Icon(Icons.person_rounded, color: _AA.green, size: 17),
            ),
    ),
  );
}

class _AnalyticsHrFilterOption {
  const _AnalyticsHrFilterOption(
      {required this.key,
      required this.label,
      required this.samples,
      required this.avgBpm,
      this.playerId});
  final String key;
  final String label;
  final int samples;
  final double avgBpm;
  final int? playerId;
}

String _analyticsHrEntityKey({int? playerId, required String playerName}) {
  if (playerId != null && playerId > 0) return 'id:$playerId';
  final name = playerName.trim().toLowerCase();
  return 'name:${name.isEmpty ? 'team' : name}';
}

List<_AnalyticsHrFilterOption> _analyticsHrFilterOptions(
    _AnalyticsHeartRate heartRate) {
  final byKey = <String, _AnalyticsHrFilterOption>{};
  for (final p in heartRate.players) {
    final key =
        _analyticsHrEntityKey(playerId: p.playerId, playerName: p.playerName);
    byKey[key] = _AnalyticsHrFilterOption(
        key: key,
        label: p.playerName.trim().isEmpty ? 'Игрок' : p.playerName.trim(),
        samples: p.samplesCount,
        avgBpm: p.avgBpm,
        playerId: p.playerId);
  }
  final counts = <String, int>{};
  final sums = <String, int>{};
  final labels = <String, String>{};
  for (final p in heartRate.timelineForChart) {
    final key =
        _analyticsHrEntityKey(playerId: p.playerId, playerName: p.playerName);
    counts[key] = (counts[key] ?? 0) + 1;
    sums[key] = (sums[key] ?? 0) + p.bpm;
    final name = p.playerName.trim();
    if (name.isNotEmpty) labels[key] = name;
  }
  for (final entry in counts.entries) {
    final old = byKey[entry.key];
    final avg = entry.value <= 0
        ? (old?.avgBpm ?? 0)
        : (sums[entry.key] ?? 0) / entry.value;
    byKey[entry.key] = _AnalyticsHrFilterOption(
      key: entry.key,
      label: old?.label ?? labels[entry.key] ?? 'Игрок',
      samples: math.max(old?.samples ?? 0, entry.value),
      avgBpm: avg.toDouble(),
      playerId: old?.playerId ??
          (entry.key.startsWith('id:')
              ? int.tryParse(entry.key.substring(3))
              : null),
    );
  }
  final list = byKey.values.toList();
  list.sort((a, b) => b.samples.compareTo(a.samples));
  return list;
}

_AnalyticsHeartRate _analyticsHeartRateFiltered(
    _AnalyticsHeartRate source, Set<String> keys) {
  if (keys.isEmpty) return source;
  final players = source.players
      .where((p) => keys.contains(_analyticsHrEntityKey(
          playerId: p.playerId, playerName: p.playerName)))
      .toList(growable: false);
  final timeline = source.timelineForChart
      .where((p) => keys.contains(_analyticsHrEntityKey(
          playerId: p.playerId, playerName: p.playerName)))
      .toList(growable: false);
  final samples = timeline.isNotEmpty
      ? timeline.length
      : players.fold<int>(0, (sum, p) => sum + p.samplesCount);
  final weighted = players.fold<int>(
      0, (sum, p) => sum + (p.samplesCount > 0 ? p.samplesCount : 1));
  final avg = timeline.isNotEmpty
      ? timeline.fold<int>(0, (sum, p) => sum + p.bpm) / timeline.length
      : (weighted <= 0
          ? 0.0
          : players.fold<double>(
                  0,
                  (sum, p) =>
                      sum +
                      p.avgBpm * (p.samplesCount > 0 ? p.samplesCount : 1)) /
              weighted);
  final maxBpm = timeline.isNotEmpty
      ? timeline.fold<int>(0, (maxV, p) => maxV > p.bpm ? maxV : p.bpm)
      : players.fold<int>(0, (maxV, p) => maxV > p.maxBpm ? maxV : p.maxBpm);
  return _AnalyticsHeartRate(
    players: players,
    timeline: timeline,
    avgBpm: avg.isNaN || avg.isInfinite ? 0 : avg,
    maxBpm: maxBpm,
    samplesCount: samples,
    playersCount: players.length,
  );
}

class _AnalyticsHrPlayerFilterBar extends StatelessWidget {
  const _AnalyticsHrPlayerFilterBar(
      {required this.heartRate,
