class _AnalyticsHrLineChart extends StatefulWidget {
  const _AnalyticsHrLineChart({required this.heartRate, this.focusedPoint});
  final _AnalyticsHeartRate heartRate;
  final _AnalyticsHrPoint? focusedPoint;
  @override
  State<_AnalyticsHrLineChart> createState() => _AnalyticsHrLineChartState();
}

class _AnalyticsHrLineChartState extends State<_AnalyticsHrLineChart> {
  double _zoom = 1;
  double _windowStart = 0;
  _AnalyticsHrPoint? _selectedPoint;

  @override
  void didUpdateWidget(covariant _AnalyticsHrLineChart oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.focusedPoint != null &&
        widget.focusedPoint != oldWidget.focusedPoint) {
      _selectedPoint = widget.focusedPoint;
      _zoom = math.max(_zoom, 4);
      final all = widget.heartRate.timelineForChart;
      if (all.isNotEmpty) {
        final minX =
            all.map(_analyticsHrPointSortKey).reduce((a, b) => a < b ? a : b);
        final maxX =
            all.map(_analyticsHrPointSortKey).reduce((a, b) => a > b ? a : b);
        final full = math.max(60000, maxX - minX);
        final visible = math.max(60000, (full / _zoom).round());
        final maxStart = math.max(1, full - visible);
        final target = _analyticsHrPointSortKey(widget.focusedPoint!) -
            minX -
            visible ~/ 2;
        _windowStart = (target / maxStart).clamp(0.0, 1.0).toDouble();
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final all = widget.heartRate.timelineForChart;
    if (all.isEmpty)
      return const _Empty(
          icon: Icons.show_chart_rounded,
          text:
              'Таймлайн ЧСС пока не получен. Нажмите Обновить после завершения Live или проверьте endpoint get_tracker_heart_rate_summary.php.');
    final sorted = [...all]..sort((a, b) =>
        _analyticsHrPointSortKey(a).compareTo(_analyticsHrPointSortKey(b)));
    final minX = _analyticsHrPointSortKey(sorted.first);
    final maxX = math.max(minX + 60000, _analyticsHrPointSortKey(sorted.last));
    final full = math.max(60000, maxX - minX);
    final visible = math.max(60000, (full / _zoom).round());
    final maxStart = math.max(0, full - visible);
    final start = minX + (maxStart * _windowStart).round();
    final end = start + visible;
    final points = sorted.where((p) {
      final x = _analyticsHrPointSortKey(p);
      return x >= start && x <= end;
    }).toList(growable: false);
    final redCount = points
        .where((p) => p.bpm >= 160 || p.zone == 'z4' || p.zone == 'z5')
        .length;
    final redPct =
        points.isEmpty ? 0 : (redCount / points.length * 100).round();
    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      _AnalyticsHrTimelineLegend(
          points: points, players: widget.heartRate.players),
      const SizedBox(height: 5),
      Container(
        padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 6),
        decoration: BoxDecoration(
            color: const Color(0xFFFFF7F7),
            borderRadius: BorderRadius.circular(10),
            border: Border.all(color: const Color(0xFFFFD5D5))),
        child: Row(children: [
          const Icon(Icons.warning_amber_rounded, color: _AA.red, size: 15),
          const SizedBox(width: 6),
          Expanded(
              child: Text(
                  redPct > 0
                      ? 'Высокая нагрузка: $redPct% выбранного отрезка в Z4–Z5'
                      : 'Красная зона нагрузки: Z4–Z5 (от 160 bpm)',
                  style: const TextStyle(
                      color: _AA.text,
                      fontSize: 10.4,
                      fontWeight: FontWeight.w800))),
          Text('Масштаб ${_zoom.toStringAsFixed(1)}×',
              style: const TextStyle(
                  color: _AA.red, fontSize: 9.6, fontWeight: FontWeight.w900)),
        ]),
      ),
      Row(children: [
        const Icon(Icons.zoom_out_rounded, size: 16, color: _AA.muted),
        Expanded(
            child: Slider(
                value: _zoom,
                min: 1,
                max: 8,
                divisions: 14,
                label: '${_zoom.toStringAsFixed(1)}×',
                onChanged: (v) => setState(() => _zoom = v))),
        const Icon(Icons.zoom_in_rounded, size: 16, color: _AA.muted),
      ]),
      if (_zoom > 1)
        SizedBox(
            height: 24,
            child: Row(children: [
              const SizedBox(width: 8),
              const Text('Положение',
                  style: TextStyle(
                      color: _AA.muted,
                      fontSize: 9.6,
                      fontWeight: FontWeight.w700)),
              Expanded(
                  child: Slider(
                      value: _windowStart,
                      min: 0,
                      max: 1,
                      onChanged: (v) => setState(() => _windowStart = v))),
            ])),
      Container(
        height: 38,
        margin: const EdgeInsets.only(bottom: 5),
        decoration: BoxDecoration(
            color: Colors.white, borderRadius: BorderRadius.circular(9)),
        child: CustomPaint(
            painter: _AnalyticsHrLoadMiniMapPainter(
                points: sorted,
                selectedPoint: _selectedPoint,
                windowStart: start,
                windowEnd: end),
            child: const SizedBox.expand()),
      ),
      if (_selectedPoint != null)
        Container(
          margin: const EdgeInsets.only(bottom: 5),
          padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 6),
          decoration: BoxDecoration(
              color: Colors.white, borderRadius: BorderRadius.circular(9)),
          child: Row(children: [
            Icon(Icons.my_location_rounded,
                size: 14, color: _analyticsZoneColor(_selectedPoint!.zone)),
            const SizedBox(width: 6),
            Expanded(
                child: Text(
                    '${_selectedPoint!.playerName} · ${_analyticsHrTimeLabel(_selectedPoint!, sorted)} · ${_analyticsHrMinuteFromStart(_selectedPoint!, sorted)} мин от старта · ${_activityLabel(_selectedPoint!.activityType)}',
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: _AA.text,
                        fontSize: 10.4,
                        fontWeight: FontWeight.w800))),
            Text(
                '${_selectedPoint!.bpm} bpm · ${_selectedPoint!.zone.toUpperCase()}',
                style: TextStyle(
                    color: _analyticsZoneColor(_selectedPoint!.zone),
                    fontSize: 10.4,
                    fontWeight: FontWeight.w900)),
          ]),
        ),
      Expanded(child: LayoutBuilder(builder: (context, chartSize) {
        return GestureDetector(
          behavior: HitTestBehavior.opaque,
          onTapDown: (details) {
            if (points.isEmpty || chartSize.maxWidth <= 76) return;
            final dx = (details.localPosition.dx - 46)
                .clamp(0.0, math.max(1.0, chartSize.maxWidth - 76));
            final target = start +
                (dx / math.max(1.0, chartSize.maxWidth - 76) * (end - start))
                    .round();
            final nearest = points.reduce((a, b) =>
                (_analyticsHrPointSortKey(a) - target).abs() <=
                        (_analyticsHrPointSortKey(b) - target).abs()
                    ? a
                    : b);
            setState(() => _selectedPoint = nearest);
          },
          child: ClipRect(
              child: CustomPaint(
                  painter: _AnalyticsHrLinePainter(
                      points: points, selectedPoint: _selectedPoint),
                  child: const SizedBox.expand())),
        );
      })),
    ]);
  }
}

class _AnalyticsHrTimelineLegend extends StatelessWidget {
  const _AnalyticsHrTimelineLegend(
      {required this.points, required this.players});
  final List<_AnalyticsHrPoint> points;
  final List<_AnalyticsHrPlayer> players;

  @override
  Widget build(BuildContext context) {
    final names = <String>[];
    for (final p in points) {
      final name = p.playerName.trim();
      if (name.isNotEmpty && !names.contains(name)) names.add(name);
    }
    if (names.isEmpty) {
      for (final p in players) {
        final name = p.playerName.trim();
        if (name.isNotEmpty && !names.contains(name)) names.add(name);
      }
    }
    final sorted = [...points]..sort((a, b) =>
        _analyticsHrPointSortKey(a).compareTo(_analyticsHrPointSortKey(b)));
    final from = sorted.isEmpty ? 0 : _analyticsHrPointSortKey(sorted.first);
    final to = sorted.isEmpty ? 0 : _analyticsHrPointSortKey(sorted.last);
    final durationMin = math.max(1, ((to - from).abs() / 60000).round());
    return Container(
      height: 34,
      padding: const EdgeInsets.symmetric(horizontal: 8),
      decoration: BoxDecoration(
          color: Colors.white, borderRadius: BorderRadius.circular(14)),
      child: Row(children: [
        const Icon(Icons.monitor_heart_rounded, color: _AA.red, size: 15),
        const SizedBox(width: 6),
        Expanded(
            child: Text(
                names.isEmpty
                    ? 'Команда · Polar H10 · $durationMin мин'
                    : '${names.take(4).join(', ')}${names.length > 4 ? ' +${names.length - 4}' : ''} · $durationMin мин',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                    color: _AA.text,
                    fontSize: 10.4,
                    fontWeight: FontWeight.w700))),
        Text('${points.length} HR',
            style: const TextStyle(
                color: _AA.muted, fontSize: 9.6, fontWeight: FontWeight.w700)),
      ]),
    );
  }
}

String _normalizeActivity(String raw) {
  final v = raw.trim().toLowerCase();
  if (v.contains('strength') || v.contains('сил')) return 'strength';
  if (v.contains('gym') || v.contains('зал') || v.contains('indoor'))
    return 'gym';
  if (v.contains('run') || v.contains('бег')) return 'run';
  if (v.contains('field') || v.contains('пол') || v.contains('football'))
    return 'field';
  return v.isEmpty ? 'unknown' : v;
}

String _activityLabel(String raw) {
  switch (_normalizeActivity(raw)) {
    case 'run':
      return 'Бег';
    case 'gym':
      return 'Зал';
    case 'strength':
      return 'Сила';
    case 'field':
      return 'Поле';
    default:
      return 'Режим не указан';
  }
}

_AnalyticsHeartRate _analyticsHeartRateByActivity(
    _AnalyticsHeartRate source, String activity) {
  final normalized = _normalizeActivity(activity);
  final timeline = source.timelineForChart
      .where((p) => _normalizeActivity(p.activityType) == normalized)
      .toList(growable: false);
  if (timeline.isEmpty) return source;
  final ids = timeline
      .map((p) =>
          _analyticsHrEntityKey(playerId: p.playerId, playerName: p.playerName))
      .toSet();
  final players = source.players
      .where((p) => ids.contains(_analyticsHrEntityKey(
          playerId: p.playerId, playerName: p.playerName)))
      .toList(growable: false);
  final avg = timeline.fold<int>(0, (s, p) => s + p.bpm) / timeline.length;
  final maxBpm = timeline.fold<int>(0, (m, p) => math.max(m, p.bpm));
  return _AnalyticsHeartRate(
      players: players,
      timeline: timeline,
      avgBpm: avg,
      maxBpm: maxBpm,
      samplesCount: timeline.length,
      playersCount: ids.length);
}

