String _analyticsHrTimeLabel(
    _AnalyticsHrPoint point, List<_AnalyticsHrPoint> all) {
  if (point.timeMs > 0) {
    final dt = DateTime.fromMillisecondsSinceEpoch(point.timeMs);
    return '${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}:${dt.second.toString().padLeft(2, '0')}';
  }
  return '${point.minute} мин';
}

int _analyticsHrMinuteFromStart(
    _AnalyticsHrPoint point, List<_AnalyticsHrPoint> all) {
  if (all.isEmpty) return math.max(0, point.minute);
  final same = all
      .where((p) => _analyticsHrGroupKey(p) == _analyticsHrGroupKey(point))
      .toList(growable: false);
  final source = same.isEmpty ? all : same;
  final minKey = source.map(_analyticsHrPointSortKey).reduce(math.min);
  return math.max(
      0, ((_analyticsHrPointSortKey(point) - minKey) / 60000).floor());
}

String _hrAiAssessment(_AnalyticsHrPoint p) {
  final zone = p.zone.isEmpty ? _analyticsZoneFromBpm(p.bpm) : p.zone;
  if (zone == 'z5' || p.bpm >= 180)
    return 'Пиковая внутренняя нагрузка. Для юношеского футболиста это короткий предельный отрезок: проверьте восстановление, технику движения и повторяемость пиков.';
  if (zone == 'z4' || p.bpm >= 160)
    return 'Высокая аэробно-анаэробная нагрузка. Подходит для интенсивных игровых серий, но важны длительность интервала и пауза восстановления.';
  if (zone == 'z3' || p.bpm >= 140)
    return 'Рабочая развивающая интенсивность. Оцените, соответствует ли она задаче упражнения и возрастной группе игрока.';
  return 'Умеренная нагрузка. Используйте вместе со скоростью, длительностью и субъективной оценкой самочувствия.';
}

class _AnalyticsHrLoadEventsPanel extends StatelessWidget {
  const _AnalyticsHrLoadEventsPanel(
      {required this.heartRate,
      required this.rosterPlayers,
      required this.selected,
      required this.onSelect,
      this.onOpenAi});
  final _AnalyticsHeartRate heartRate;
  final List<TrackerPlayerOption> rosterPlayers;
  final _AnalyticsHrPoint? selected;
  final ValueChanged<_AnalyticsHrPoint> onSelect;
  final ValueChanged<_AnalyticsHrPoint>? onOpenAi;

  @override
  Widget build(BuildContext context) {
    final all = [...heartRate.timelineForChart]..sort((a, b) =>
        _analyticsHrPointSortKey(a).compareTo(_analyticsHrPointSortKey(b)));
    final high = all
        .where((p) => p.bpm >= 160 || p.zone == 'z4' || p.zone == 'z5')
        .toList(growable: false);
    final events = <_AnalyticsHrPoint>[];
    for (final p in high) {
      if (events.isEmpty ||
          _analyticsHrGroupKey(events.last) != _analyticsHrGroupKey(p) ||
          (_analyticsHrPointSortKey(p) - _analyticsHrPointSortKey(events.last))
                  .abs() >=
              60000) events.add(p);
    }
    if (events.isEmpty)
      return const _Empty(
          icon: Icons.health_and_safety_rounded,
          text:
              'Точек Z4–Z5 нет. Нагрузка находится в контролируемом диапазоне.');
    return ListView.separated(
      padding: const EdgeInsets.all(7),
      itemCount: math.min(events.length, 40),
      separatorBuilder: (_, __) => const SizedBox(height: 6),
      itemBuilder: (context, i) {
        final p = events[i];
        final active = identical(selected, p) ||
            (selected != null &&
                _analyticsHrPointSortKey(selected!) ==
                    _analyticsHrPointSortKey(p) &&
                _analyticsHrGroupKey(selected!) == _analyticsHrGroupKey(p));
        final roster = _analyticsRosterPlayer(rosterPlayers, p.playerId);
        return InkWell(
          borderRadius: BorderRadius.circular(11),
          onTap: () {
            onSelect(p);
            onOpenAi?.call(p);
          },
          child: Container(
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
                color: active ? const Color(0xFFFFF1F2) : Colors.white,
                borderRadius: BorderRadius.circular(11),
                border: Border.all(color: active ? _AA.red : _AA.line)),
            child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              _analyticsPlayerAvatar(roster, size: 34),
              const SizedBox(width: 8),
              Expanded(
                  child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                    Row(children: [
                      Expanded(
                          child: Text(p.playerName,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: _AA.text,
                                  fontSize: 11.4,
                                  fontWeight: FontWeight.w700))),
                      Container(
                          padding: const EdgeInsets.symmetric(
                              horizontal: 6, vertical: 3),
                          decoration: BoxDecoration(
                              color: _AA.red,
                              borderRadius: BorderRadius.circular(99)),
                          child: Text('${p.bpm} bpm',
                              style: const TextStyle(
                                  color: Colors.white,
                                  fontSize: 10.4,
                                  fontWeight: FontWeight.w700))),
                    ]),
                    const SizedBox(height: 3),
                    Text(
                        '${_analyticsHrTimeLabel(p, all)} · ${_analyticsHrMinuteFromStart(p, all)} мин от старта · ${p.zone.toUpperCase()} · ${_activityLabel(p.activityType)}',
                        style: const TextStyle(
                            color: _AA.muted,
                            fontSize: 9.6,
                            fontWeight: FontWeight.w700)),
                    const SizedBox(height: 4),
                    Text(_hrAiAssessment(p),
                        maxLines: active ? 5 : 2,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: _AA.text,
                            fontSize: 9.6,
                            height: 1.25,
                            fontWeight: FontWeight.w600)),
                    const SizedBox(height: 4),
                    Row(children: [
                      const Icon(Icons.auto_awesome_rounded,
                          size: 12, color: _AA.red),
                      const SizedBox(width: 4),
                      Expanded(
                          child: Text(
                              onOpenAi == null
                                  ? 'Перейти к точке на графике'
                                  : 'Открыть точку в ИИ-чате',
                              style: const TextStyle(
                                  color: _AA.red,
                                  fontSize: 10.4,
                                  fontWeight: FontWeight.w700))),
                      if (onOpenAi != null)
                        const Icon(Icons.arrow_forward_rounded,
                            size: 12, color: _AA.red)
                    ]),
                  ])),
            ]),
          ),
        );
      },
    );
  }
}

class _HrHighInterval {
  const _HrHighInterval(
      {required this.playerId,
      required this.playerName,
      required this.start,
      required this.end,
      required this.peak,
      required this.points});
  final int? playerId;
  final String playerName;
  final _AnalyticsHrPoint start;
  final _AnalyticsHrPoint end;
  final _AnalyticsHrPoint peak;
  final int points;
  int get durationSec {
    final a = start.timeMs > 0 ? start.timeMs : start.minute * 60000;
    final b = end.timeMs > 0 ? end.timeMs : end.minute * 60000;
    return math.max(0, ((b - a) / 1000).round());
  }
}

List<_HrHighInterval> _hrHighIntervals(_AnalyticsHeartRate hr) {
  final grouped = <String, List<_AnalyticsHrPoint>>{};
  for (final p in hr.timelineForChart
      .where((e) => e.bpm >= 160 || e.zone == 'z4' || e.zone == 'z5')) {
    final key =
        _analyticsHrEntityKey(playerId: p.playerId, playerName: p.playerName);
    grouped.putIfAbsent(key, () => <_AnalyticsHrPoint>[]).add(p);
  }
  final out = <_HrHighInterval>[];
  for (final points in grouped.values) {
    points.sort((a, b) => (a.timeMs > 0 ? a.timeMs : a.minute * 60000)
        .compareTo(b.timeMs > 0 ? b.timeMs : b.minute * 60000));
    if (points.isEmpty) continue;
    var chunk = <_AnalyticsHrPoint>[points.first];
    void flush() {
      if (chunk.isEmpty) return;
      final peak = chunk.reduce((a, b) => a.bpm >= b.bpm ? a : b);
      final interval = _HrHighInterval(
          playerId: chunk.first.playerId,
          playerName: chunk.first.playerName,
          start: chunk.first,
          end: chunk.last,
          peak: peak,
          points: chunk.length);
      if (interval.durationSec >= 30 || chunk.length >= 3) out.add(interval);
    }

    for (var i = 1; i < points.length; i++) {
      final prev = points[i - 1].timeMs > 0
          ? points[i - 1].timeMs
          : points[i - 1].minute * 60000;
      final now =
          points[i].timeMs > 0 ? points[i].timeMs : points[i].minute * 60000;
      if ((now - prev).abs() <= 90000) {
        chunk.add(points[i]);
      } else {
        flush();
        chunk = <_AnalyticsHrPoint>[points[i]];
      }
    }
    flush();
  }
  out.sort((a, b) => b.peak.bpm.compareTo(a.peak.bpm));
  return out;
}

int? _hrRecoveryDrop(
    _AnalyticsHeartRate hr, _AnalyticsHrPoint peak, int seconds) {
  final key = _analyticsHrEntityKey(
      playerId: peak.playerId, playerName: peak.playerName);
  final base = peak.timeMs > 0 ? peak.timeMs : peak.minute * 60000;
  _AnalyticsHrPoint? best;
  var bestDelta = 1 << 62;
  for (final p in hr.timelineForChart) {
    if (_analyticsHrEntityKey(playerId: p.playerId, playerName: p.playerName) !=
        key) continue;
    final t = p.timeMs > 0 ? p.timeMs : p.minute * 60000;
    final d = (t - (base + seconds * 1000)).abs();
    if (d < bestDelta && d <= 20000) {
      bestDelta = d;
      best = p;
    }
  }
  if (best == null) return null;
  return peak.bpm - best.bpm;
}

class _HrAiPassportPanel extends StatelessWidget {
  const _HrAiPassportPanel(
      {required this.heartRate,
      required this.rosterPlayers,
      required this.focusedPoint,
      required this.onFocus});
  final _AnalyticsHeartRate heartRate;
  final List<TrackerPlayerOption> rosterPlayers;
  final _AnalyticsHrPoint? focusedPoint;
  final ValueChanged<_AnalyticsHrPoint> onFocus;

  @override
  Widget build(BuildContext context) {
    final intervals = _hrHighIntervals(heartRate);
    final points = heartRate.timelineForChart;
    final high = points
        .where((p) => p.bpm >= 160 || p.zone == 'z4' || p.zone == 'z5')
        .length;
    final highPct = points.isEmpty ? 0.0 : high / points.length * 100;
    final peak = focusedPoint ??
        (points.isEmpty
            ? null
            : points.reduce((a, b) => a.bpm >= b.bpm ? a : b));
    final r30 = peak == null ? null : _hrRecoveryDrop(heartRate, peak, 30);
    final r60 = peak == null ? null : _hrRecoveryDrop(heartRate, peak, 60);
    final r120 = peak == null ? null : _hrRecoveryDrop(heartRate, peak, 120);
    final recovery = r60 ?? r30 ?? r120;
    var readiness = 82;
    if (highPct > 35)
      readiness -= 18;
    else if (highPct > 20) readiness -= 9;
    if (recovery != null && recovery < 12) readiness -= 16;
    if ((peak?.bpm ?? 0) >= 195) readiness -= 12;
    readiness = readiness.clamp(0, 100);
    final risk = (peak?.bpm ?? 0) >= 200 ||
        (intervals.isNotEmpty && intervals.first.durationSec >= 300) ||
        (recovery != null && recovery < 10);
    final assessment = risk
        ? 'Нетипичная реакция: высокий пик или слабое снижение ЧСС. Проверьте самочувствие, гидратацию и восстановление; не увеличивайте интенсивность без оценки тренера.'
        : highPct >= 20
            ? 'Выраженная нагрузка Z4–Z5. Для футбольной работы это допустимо в интервальных сериях, но объём следующего интенсивного блока стоит уменьшить и проконтролировать восстановление.'
            : 'Нагрузка контролируемая. Можно продолжать план, сохранив разминку, паузы и наблюдение за восстановлением после пиков.';
    return ListView(
      padding: const EdgeInsets.all(8),
      children: [
        Row(children: [
          Expanded(
              child: _HrPassportScore(
                  label: 'Готовность',
                  value: '$readiness',
                  suffix: '/100',
                  color: readiness >= 75
                      ? _AA.green
                      : (readiness >= 55 ? const Color(0xFFF59E0B) : _AA.red))),
          const SizedBox(width: 6),
          Expanded(
              child: _HrPassportScore(
                  label: 'Z4–Z5',
                  value: highPct.toStringAsFixed(0),
                  suffix: '%',
                  color: highPct >= 25 ? _AA.red : const Color(0xFFF59E0B))),
          const SizedBox(width: 6),
          Expanded(
              child: _HrPassportScore(
                  label: 'Интервалы',
                  value: '${intervals.length}',
                  suffix: '',
                  color: _AA.text)),
        ]),
        const SizedBox(height: 8),
        Container(
          padding: const EdgeInsets.all(9),
          decoration: BoxDecoration(
              color: risk ? const Color(0xFFFFF1F2) : const Color(0xFFF0FDF4),
              borderRadius: BorderRadius.circular(10),
              border: Border.all(
                  color: risk
                      ? const Color(0xFFFDA4AF)
                      : const Color(0xFFBBF7D0))),
          child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Icon(
                risk ? Icons.warning_amber_rounded : Icons.auto_awesome_rounded,
                color: risk ? _AA.red : _AA.green,
                size: 18),
            const SizedBox(width: 8),
            Expanded(
                child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                  Text(risk ? 'Внимание тренера' : 'ИИ-оценка нагрузки',
                      style: TextStyle(
                          color: risk ? _AA.red : _AA.green,
                          fontSize: 10.4,
                          fontWeight: FontWeight.w900)),
                  const SizedBox(height: 3),
                  Text(assessment,
                      style: const TextStyle(
                          color: _AA.text,
                          fontSize: 9.6,
                          height: 1.3,
                          fontWeight: FontWeight.w600)),
                ])),
          ]),
        ),
        const SizedBox(height: 8),
        const Text('Восстановление после выбранного пика',
            style: TextStyle(
                color: _AA.text, fontSize: 10.4, fontWeight: FontWeight.w900)),
        const SizedBox(height: 5),
        Row(children: [
          Expanded(child: _HrRecoveryCell(label: '30 сек', value: r30)),
          const SizedBox(width: 5),
          Expanded(child: _HrRecoveryCell(label: '60 сек', value: r60)),
          const SizedBox(width: 5),
          Expanded(child: _HrRecoveryCell(label: '120 сек', value: r120)),
        ]),
        const SizedBox(height: 8),
        Row(children: [
          const Expanded(
              child: Text('Продолжительные интервалы Z4–Z5',
                  style: TextStyle(
                      color: _AA.text,
                      fontSize: 10.4,
                      fontWeight: FontWeight.w900))),
          Text('${intervals.length}',
              style: const TextStyle(
                  color: _AA.red, fontSize: 11.2, fontWeight: FontWeight.w900)),
        ]),
        const SizedBox(height: 5),
        if (intervals.isEmpty)
          const Text('Интервалы высокой нагрузки не обнаружены.',
              style: TextStyle(
                  color: _AA.muted, fontSize: 9.6, fontWeight: FontWeight.w600))
        else
          for (final i in intervals.take(5))
            InkWell(
              onTap: () => onFocus(i.peak),
              borderRadius: BorderRadius.circular(9),
              child: Container(
                margin: const EdgeInsets.only(bottom: 5),
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 7),
                decoration: BoxDecoration(
                    color: focusedPoint == i.peak
                        ? const Color(0xFFFFE4E6)
                        : Colors.white,
                    borderRadius: BorderRadius.circular(9),
                    border: Border.all(
                        color: focusedPoint == i.peak ? _AA.red : _AA.line)),
                child: Row(children: [
                  _analyticsPlayerAvatar(
                      _analyticsRosterPlayer(rosterPlayers, i.playerId),
                      size: 27),
                  const SizedBox(width: 7),
                  Expanded(
                      child: Column(
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                        Text(i.playerName,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                                color: _AA.text,
                                fontSize: 9.6,
                                fontWeight: FontWeight.w900)),
                        Text(
                            '${_analyticsHrTimeLabel(i.start, heartRate.timelineForChart)}–${_analyticsHrTimeLabel(i.end, heartRate.timelineForChart)} · ${math.max(1, (i.durationSec / 60).ceil())} мин · ${_activityLabel(i.peak.activityType)}',
                            style: const TextStyle(
                                color: _AA.muted,
                                fontSize: 9.6,
                                fontWeight: FontWeight.w700)),
                      ])),
                  Container(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 6, vertical: 4),
                      decoration: BoxDecoration(
                          color: _AA.red,
                          borderRadius: BorderRadius.circular(99)),
                      child: Text('${i.peak.bpm}',
                          style: const TextStyle(
                              color: Colors.white,
                              fontSize: 9.6,
                              fontWeight: FontWeight.w900))),
                ]),
              ),
            ),
      ],
    );
  }
}

class _HrPassportScore extends StatelessWidget {
  const _HrPassportScore(
      {required this.label,
      required this.value,
      required this.suffix,
      required this.color});
  final String label, value, suffix;
  final Color color;
  @override
  Widget build(BuildContext context) => Container(
      padding: const EdgeInsets.all(8),
      decoration: BoxDecoration(
          color: color.withOpacity(.07),
