class _AnalyticsHrZonesPanel extends StatelessWidget {
  const _AnalyticsHrZonesPanel({required this.heartRate});
  final _AnalyticsHeartRate heartRate;
  @override
  Widget build(BuildContext context) {
    var z = <int>[
      heartRate.players.fold<int>(0, (a, p) => a + p.z1),
      heartRate.players.fold<int>(0, (a, p) => a + p.z2),
      heartRate.players.fold<int>(0, (a, p) => a + p.z3),
      heartRate.players.fold<int>(0, (a, p) => a + p.z4),
      heartRate.players.fold<int>(0, (a, p) => a + p.z5),
    ];
    var total = z.fold<int>(0, (a, b) => a + b);
    if (total <= 0) {
      final points = heartRate.timelineForChart;
      z = <int>[
        points
            .where((p) =>
                (p.zone.isEmpty ? _analyticsZoneFromBpm(p.bpm) : p.zone) ==
                'z1')
            .length,
        points
            .where((p) =>
                (p.zone.isEmpty ? _analyticsZoneFromBpm(p.bpm) : p.zone) ==
                'z2')
            .length,
        points
            .where((p) =>
                (p.zone.isEmpty ? _analyticsZoneFromBpm(p.bpm) : p.zone) ==
                'z3')
            .length,
        points
            .where((p) =>
                (p.zone.isEmpty ? _analyticsZoneFromBpm(p.bpm) : p.zone) ==
                'z4')
            .length,
        points
            .where((p) =>
                (p.zone.isEmpty ? _analyticsZoneFromBpm(p.bpm) : p.zone) ==
                'z5')
            .length,
      ];
      total = z.fold<int>(0, (a, b) => a + b);
    }
    if (total <= 0)
      return const _Empty(
          icon: Icons.favorite_border_rounded,
          text: 'Зоны ЧСС пока не рассчитаны.');
    const labels = ['Z1', 'Z2', 'Z3', 'Z4', 'Z5'];
    return SingleChildScrollView(
      primary: false,
      physics: const ClampingScrollPhysics(),
      padding: const EdgeInsets.all(8),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        for (var i = 0; i < z.length; i++) ...[
          Row(children: [
            SizedBox(
                width: 28,
                child: Text(labels[i],
                    style: const TextStyle(
                        color: _AA.text,
                        fontSize: 11.2,
                        fontWeight: FontWeight.w700))),
            Expanded(
                child: ClipRRect(
                    borderRadius: BorderRadius.circular(99),
                    child: Stack(children: [
                      Container(height: 12, color: const Color(0xFFF3F4F6)),
                      FractionallySizedBox(
                          widthFactor:
                              (z[i] / total).clamp(0.0, 1.0).toDouble(),
                          child: Container(
                              height: 12,
                              color:
                                  _analyticsZoneColor(labels[i].toLowerCase())))
                    ]))),
            const SizedBox(width: 8),
            SizedBox(
                width: 52,
                child: Text('${(z[i] / total * 100).toStringAsFixed(0)}%',
                    textAlign: TextAlign.right,
                    style: const TextStyle(
                        color: _AA.muted,
                        fontSize: 10.4,
                        fontWeight: FontWeight.w700))),
          ]),
          if (i != z.length - 1) const SizedBox(height: 9),
        ],
      ]),
    );
  }
}

class _AnalyticsHrPlayersList extends StatelessWidget {
  const _AnalyticsHrPlayersList(
      {required this.heartRate, required this.rosterPlayers});
  final _AnalyticsHeartRate heartRate;
  final List<TrackerPlayerOption> rosterPlayers;

  List<_AnalyticsHrPoint> _pointsFor(_AnalyticsHrPlayer player) {
    final points = heartRate.timelineForChart.where((point) {
      if (player.playerId != null && point.playerId != null)
        return point.playerId == player.playerId;
      return point.playerName.trim().toLowerCase() ==
          player.playerName.trim().toLowerCase();
    }).toList(growable: false)
      ..sort((a, b) {
        final at = a.timeMs > 0 ? a.timeMs : a.minute * 60000;
        final bt = b.timeMs > 0 ? b.timeMs : b.minute * 60000;
        return at.compareTo(bt);
      });
    return points;
  }

  String _durationLabel(_AnalyticsHrPlayer player) {
    final points = _pointsFor(player);
    if (points.length < 2) return 'Нет длительности';
    final first = points.first.timeMs > 0
        ? points.first.timeMs
        : points.first.minute * 60000;
    final last = points.last.timeMs > 0
        ? points.last.timeMs
        : points.last.minute * 60000;
    final totalSeconds = math.max(0, ((last - first) / 1000).round());
    if (totalSeconds <= 0) return 'Менее 1 мин';
    final hours = totalSeconds ~/ 3600;
    final minutes = (totalSeconds % 3600) ~/ 60;
    if (hours > 0)
      return '${hours} ч ${minutes.toString().padLeft(2, '0')} мин';
    return '${math.max(1, minutes)} мин';
  }

  String _signalRange(_AnalyticsHrPlayer player) {
    final points =
        _pointsFor(player).where((p) => p.timeMs > 0).toList(growable: false);
    if (points.length < 2) return '${player.samplesCount} HR-точек';
    String clock(int ms) {
      final dt = _trackerMoscowFromEpochMs(ms);
      return '${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}';
    }

    return '${clock(points.first.timeMs)}–${clock(points.last.timeMs)} · ${player.samplesCount} HR';
  }

  @override
  Widget build(BuildContext context) {
    if (heartRate.players.isEmpty)
      return const _Empty(
          icon: Icons.groups_rounded, text: 'Нет игроков с Polar H10.');

    return LayoutBuilder(builder: (context, constraints) {
      final width = constraints.maxWidth;
      final columns = width >= 1120 ? 4 : (width >= 600 ? 3 : 1);
      final ratio = columns == 1 ? 3.55 : (columns == 3 ? 2.75 : 2.55);
      return GridView.builder(
        padding: const EdgeInsets.all(10),
        gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
          crossAxisCount: columns,
          crossAxisSpacing: 8,
          mainAxisSpacing: 8,
          childAspectRatio: ratio,
        ),
        itemCount: heartRate.players.length,
        itemBuilder: (context, i) {
          final player = heartRate.players[i];
          final high = player.z4 + player.z5;
          final highPct =
              player.samplesCount <= 0 ? 0.0 : high / player.samplesCount * 100;
          return Container(
            padding: const EdgeInsets.all(8),
            decoration: BoxDecoration(
              color: Colors.white,
              borderRadius: BorderRadius.circular(12),
            ),
            child: Row(crossAxisAlignment: CrossAxisAlignment.start, children: [
              _analyticsPlayerAvatar(
                  _analyticsRosterPlayer(rosterPlayers, player.playerId),
                  size: 36),
              const SizedBox(width: 10),
              Expanded(
                  child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                    Text(player.playerName,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: _AA.text,
                            fontSize: 11.5,
                            fontWeight: FontWeight.w800)),
                    const SizedBox(height: 4),
                    Text(
                        'Средний ${player.avgBpm.toStringAsFixed(0)} · максимум ${player.maxBpm} bpm',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: _AA.muted,
                            fontSize: 9.6,
                            fontWeight: FontWeight.w600)),
                    const Spacer(),
                    Row(children: [
                      const Icon(Icons.bluetooth_connected_rounded,
                          size: 13, color: _AA.green),
                      const SizedBox(width: 4),
                      Expanded(
                          child: Text('Подключение ${_durationLabel(player)}',
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: _AA.text,
                                  fontSize: 9.6,
                                  fontWeight: FontWeight.w800))),
                    ]),
                    const SizedBox(height: 3),
                    Text(_signalRange(player),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: _AA.muted,
                            fontSize: 9.6,
                            fontWeight: FontWeight.w600)),
                    const SizedBox(height: 5),
                    ClipRRect(
                      borderRadius: BorderRadius.circular(99),
                      child: LinearProgressIndicator(
                        minHeight: 5,
                        value: (highPct / 100).clamp(0.0, 1.0),
                        backgroundColor: const Color(0xFFF1F5F9),
                        valueColor: AlwaysStoppedAnimation<Color>(
                            highPct >= 20 ? _AA.red : _AA.green),
                      ),
                    ),
                    const SizedBox(height: 3),
                    Text('Z4–Z5 ${highPct.toStringAsFixed(0)}%',
                        style: TextStyle(
                            color: highPct >= 20 ? _AA.red : _AA.muted,
                            fontSize: 9.6,
                            fontWeight: FontWeight.w800)),
                  ])),
            ]),
          );
        },
      );
    });
  }
}

Color _analyticsZoneColor(String zone) {
  switch (zone) {
    case 'z5':
      return const Color(0xFFE11D48);
    case 'z4':
      return const Color(0xFFF97316);
    case 'z3':
      return const Color(0xFFFACC15);
    case 'z2':
      return const Color(0xFF84CC16);
    default:
      return const Color(0xFFA3E635);
  }
}

abstract class _BaseChartPainter extends CustomPainter {
  void drawGrid(Canvas canvas, Rect rect, {int lines = 5}) {
    final paint = Paint()
      ..color = _AA.line
      ..strokeWidth = 1;
    for (var i = 0; i <= lines; i++) {
      final y = rect.bottom - rect.height * i / lines;
      canvas.drawLine(Offset(rect.left, y), Offset(rect.right, y), paint);
    }
  }

  void text(
    Canvas canvas,
    String value,
    Offset offset, {
    double size = 10,
    Color color = _AA.text,
    FontWeight weight = FontWeight.w700,
    TextAlign align = TextAlign.left,
    double maxWidth = 120,
  }) {
    final tp = TextPainter(
      text: TextSpan(
          text: value,
          style: TextStyle(
              fontFamily: 'Inter',
              color: color,
              fontSize: size,
              fontWeight: weight)),
      textDirection: TextDirection.ltr,
      textAlign: align,
      maxLines: 2,
    )..layout(maxWidth: maxWidth);
    tp.paint(canvas, offset);
  }
}

