class _AnalyticsHrPlayerSummaryPainter extends _BaseChartPainter {
  _AnalyticsHrPlayerSummaryPainter({required this.players});
  final List<_AnalyticsHrPlayer> players;

  @override
  void paint(Canvas canvas, Size size) {
    if (players.isEmpty) return;
    final rect = Rect.fromLTWH(48, 26, math.max(10.0, size.width - 70),
        math.max(10.0, size.height - 86));
    canvas.save();
    canvas.clipRect(Rect.fromLTWH(0, 0, size.width, size.height));
    drawGrid(canvas, rect);
    final maxValue = math.max(
        130.0,
        players
                .map((p) => p.maxBpm > 0 ? p.maxBpm.toDouble() : p.avgBpm)
                .fold<double>(1, (a, b) => a > b ? a : b) +
            12);
    final minValue = math.max(
        40.0,
        players
                .map((p) => p.avgBpm > 0 ? p.avgBpm : p.maxBpm.toDouble())
                .fold<double>(999, (a, b) => a < b ? a : b) -
            8);
    final gap = rect.width / players.length;
    for (var i = 0; i < players.length; i++) {
      final p = players[i];
      final avg = p.avgBpm > 0 ? p.avgBpm : p.maxBpm.toDouble();
      final max = p.maxBpm > 0 ? p.maxBpm.toDouble() : avg;
      final x = rect.left + gap * i + gap / 2;
      final avgY = rect.bottom -
          rect.height *
              ((avg - minValue) / (maxValue - minValue))
                  .clamp(0.0, 1.0)
                  .toDouble();
      final maxY = rect.bottom -
          rect.height *
              ((max - minValue) / (maxValue - minValue))
                  .clamp(0.0, 1.0)
                  .toDouble();
      canvas.drawLine(
          Offset(x, avgY),
          Offset(x, maxY),
          Paint()
            ..color = _AA.red.withOpacity(.45)
            ..strokeWidth = 5
            ..strokeCap = StrokeCap.round);
      canvas.drawCircle(Offset(x, avgY), 5, Paint()..color = _AA.green);
      canvas.drawCircle(Offset(x, maxY), 5, Paint()..color = _AA.red);
      text(canvas, avg.toStringAsFixed(0), Offset(x - 14, avgY + 8),
          size: 8.5,
          color: _AA.green,
          weight: FontWeight.w700,
          maxWidth: 32,
          align: TextAlign.center);
      text(canvas, _shortAnalyticsName(p.playerName),
          Offset(x - gap * .42, rect.bottom + 8),
          size: 8,
          color: _AA.muted,
          maxWidth: gap * .86,
          align: TextAlign.center);
    }
    text(canvas, 'зелёная точка — средний bpm · красная — максимум',
        Offset(rect.left, 0),
        size: 10.2,
        color: _AA.text,
        weight: FontWeight.w700,
        maxWidth: rect.width);
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _AnalyticsHrPlayerSummaryPainter oldDelegate) =>
      oldDelegate.players != players;
}

String _shortAnalyticsName(String name) {
  final parts = name
      .trim()
      .split(RegExp(r'\s+'))
      .where((p) => p.isNotEmpty)
      .toList(growable: false);
  if (parts.isEmpty) return 'Игрок';
  if (parts.length == 1)
    return parts.first.length <= 10
        ? parts.first
        : '${parts.first.substring(0, 10)}…';
  return '${parts.first} ${parts[1].substring(0, 1)}.';
}

int _analyticsHrPointSortKey(_AnalyticsHrPoint p) =>
    p.timeMs > 0 ? p.timeMs : p.minute * 60000;

String _analyticsHrGroupKey(_AnalyticsHrPoint p) {
  final name = p.playerName.trim();
  final id = p.playerId;
  if (id != null && id > 0) return 'id:$id';
  return 'name:${name.isEmpty ? 'team' : name}';
}

List<List<_AnalyticsHrPoint>> _analyticsHrPointGroups(
    List<_AnalyticsHrPoint> points) {
  final map = <String, List<_AnalyticsHrPoint>>{};
  for (final p in points.where((p) => p.bpm > 0)) {
    map
        .putIfAbsent(_analyticsHrGroupKey(p), () => <_AnalyticsHrPoint>[])
        .add(p);
  }
  final groups = map.values.toList(growable: false);
  for (final g in groups) {
    g.sort((a, b) =>
        _analyticsHrPointSortKey(a).compareTo(_analyticsHrPointSortKey(b)));
  }
  groups.sort((a, b) => (a.first.playerName).compareTo(b.first.playerName));
  return groups;
}

Color _analyticsSeriesColor(int index) {
  const colors = <Color>[
    _AA.red,
    _AA.green,
    Color(0xFFF59E0B),
    Color(0xFF2563EB),
    Color(0xFF7C3AED),
    Color(0xFF0F766E),
  ];
  return colors[index % colors.length];
}

class _AnalyticsHrLoadMiniMapPainter extends CustomPainter {
  _AnalyticsHrLoadMiniMapPainter(
      {required this.points,
      required this.selectedPoint,
      required this.windowStart,
      required this.windowEnd});
  final List<_AnalyticsHrPoint> points;
  final _AnalyticsHrPoint? selectedPoint;
  final int windowStart;
  final int windowEnd;
  @override
  void paint(Canvas canvas, Size size) {
    if (points.isEmpty) return;
    final left = 8.0,
        right = math.max(9.0, size.width - 8),
        top = 8.0,
        bottom = math.max(9.0, size.height - 9);
    final minX = points.map(_analyticsHrPointSortKey).reduce(math.min);
    final maxX = math.max(
        minX + 60000, points.map(_analyticsHrPointSortKey).reduce(math.max));
    double xFor(int x) =>
        left + (right - left) * ((x - minX) / (maxX - minX)).clamp(0.0, 1.0);
    canvas.drawRRect(
        RRect.fromRectAndRadius(
            Rect.fromLTRB(left, top, right, bottom), const Radius.circular(7)),
        Paint()..color = const Color(0xFFEFF3F6));
    for (final p in points.where((p) => p.bpm >= 140)) {
      final x = xFor(_analyticsHrPointSortKey(p));
      final h = p.bpm >= 180
          ? bottom - top
          : p.bpm >= 160
              ? (bottom - top) * .75
              : (bottom - top) * .45;
      canvas.drawLine(
          Offset(x, bottom),
          Offset(x, bottom - h),
          Paint()
            ..color = _analyticsZoneColor(p.zone)
                .withOpacity(p.bpm >= 160 ? 0.85 : 0.45)
            ..strokeWidth = p.bpm >= 160 ? 2.2 : 1.2
            ..strokeCap = StrokeCap.round);
    }
    final w1 = xFor(windowStart), w2 = xFor(windowEnd);
    canvas.drawRRect(
        RRect.fromRectAndRadius(
            Rect.fromLTRB(w1, top, w2, bottom), const Radius.circular(6)),
        Paint()..color = _AA.green.withOpacity(.08));
    canvas.drawRRect(
        RRect.fromRectAndRadius(
            Rect.fromLTRB(w1, top, w2, bottom), const Radius.circular(6)),
        Paint()
          ..color = _AA.green
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.4);
    if (selectedPoint != null) {
      final x = xFor(_analyticsHrPointSortKey(selectedPoint!));
      canvas.drawLine(
          Offset(x, top - 2),
          Offset(x, bottom + 2),
          Paint()
            ..color = _AA.red
            ..strokeWidth = 2.5);
      canvas.drawCircle(Offset(x, top + 2), 4, Paint()..color = _AA.red);
    }
  }

  @override
  bool shouldRepaint(covariant _AnalyticsHrLoadMiniMapPainter old) =>
      old.points != points ||
      old.selectedPoint != selectedPoint ||
      old.windowStart != windowStart ||
      old.windowEnd != windowEnd;
}

class _AnalyticsHrLinePainter extends _BaseChartPainter {
  _AnalyticsHrLinePainter({required this.points, this.selectedPoint});
  final List<_AnalyticsHrPoint> points;
  final _AnalyticsHrPoint? selectedPoint;

  @override
  void paint(Canvas canvas, Size size) {
    final list = points.where((p) => p.bpm > 0).toList(growable: false);
    if (list.isEmpty) return;
    final rect = Rect.fromLTWH(46, 28, math.max(10.0, size.width - 76),
        math.max(10.0, size.height - 74));
    canvas.save();
    canvas.clipRect(Rect.fromLTWH(0, 0, size.width, size.height));
    drawGrid(canvas, rect);
    final minX = list
        .map(_analyticsHrPointSortKey)
        .fold<int>(
            _analyticsHrPointSortKey(list.first), (a, b) => a < b ? a : b)
        .toDouble();
    var maxX = list
        .map(_analyticsHrPointSortKey)
        .fold<int>(
            _analyticsHrPointSortKey(list.first), (a, b) => a > b ? a : b)
        .toDouble();
    if ((maxX - minX).abs() < 1) maxX = minX + 60000;
    final minBpm = math.max(
        40.0,
        list
                .map((p) => p.bpm)
                .fold<int>(list.first.bpm, (a, b) => a < b ? a : b)
                .toDouble() -
            10);
    final maxBpm = math.max(
        130.0,
        list
                .map((p) => p.bpm)
                .fold<int>(list.first.bpm, (a, b) => a > b ? a : b)
                .toDouble() +
            12);
    Offset map(_AnalyticsHrPoint p, double value) => Offset(
          rect.left +
              rect.width *
                  ((_analyticsHrPointSortKey(p) - minX) / (maxX - minX))
                      .clamp(0.0, 1.0)
                      .toDouble(),
          rect.bottom -
              rect.height *
                  ((value - minBpm) / (maxBpm - minBpm))
                      .clamp(0.0, 1.0)
                      .toDouble(),
        );
    if (maxBpm > 160) {
      final redTop = rect.top;
      final redBottom = rect.bottom -
          rect.height *
              ((160 - minBpm) / (maxBpm - minBpm)).clamp(0.0, 1.0).toDouble();
      canvas.drawRect(Rect.fromLTRB(rect.left, redTop, rect.right, redBottom),
          Paint()..color = const Color(0xFFE11D48).withOpacity(.075));
      text(canvas, 'ВЫСОКАЯ НАГРУЗКА', Offset(rect.left + 8, rect.top + 7),
          size: 9.6,
          color: const Color(0xFFE11D48),
          weight: FontWeight.w900,
          maxWidth: 120);
    }
    for (final z in [120, 140, 160, 180]) {
      if (z < minBpm || z > maxBpm) continue;
      final y = rect.bottom -
          rect.height *
              ((z - minBpm) / (maxBpm - minBpm)).clamp(0.0, 1.0).toDouble();
      final color = z >= 180
          ? const Color(0xFFE11D48)
          : (z >= 160
              ? const Color(0xFFF97316)
              : (z >= 140 ? const Color(0xFFFACC15) : const Color(0xFF84CC16)));
      canvas.drawLine(
          Offset(rect.left, y),
          Offset(rect.right, y),
          Paint()
            ..color = color.withOpacity(.45)
            ..strokeWidth = 1.1);
      text(
          canvas,
          'Z${z == 120 ? 2 : z == 140 ? 3 : z == 160 ? 4 : 5}',
          Offset(rect.right - 24, y - 14),
          size: 9.8,
          color: color,
          weight: FontWeight.w700,
          maxWidth: 24);
    }

    Path smoothPath(List<Offset> values) {
      final path = Path();
      if (values.isEmpty) return path;
      path.moveTo(values.first.dx, values.first.dy);
      for (var i = 1; i < values.length; i++) {
        final prev = values[i - 1];
        final current = values[i];
        final midX = (prev.dx + current.dx) / 2;
        path.cubicTo(midX, prev.dy, midX, current.dy, current.dx, current.dy);
      }
      return path;
    }

    final groups = _analyticsHrPointGroups(list);
    for (var gi = 0; gi < groups.length; gi++) {
      final group = groups[gi];
      if (group.isEmpty) continue;
      final lineColor =
          groups.length == 1 ? _AA.red : _analyticsSeriesColor(gi);
      final bpmOffsets = <Offset>[];
      final loadOffsets = <Offset>[];
      for (final p in group) {
        bpmOffsets.add(map(p, p.bpm.toDouble()));
        loadOffsets.add(map(
            p,
            minBpm +
                (maxBpm - minBpm) *
                    (p.hrLoad.clamp(0, 200).toDouble() / 200.0)));
      }
      final bpm = smoothPath(bpmOffsets);
      final load = smoothPath(loadOffsets);

      if (groups.length == 1 && bpmOffsets.length > 1) {
        final fill = Path.from(bpm)
          ..lineTo(bpmOffsets.last.dx, rect.bottom)
          ..lineTo(bpmOffsets.first.dx, rect.bottom)
          ..close();
        canvas.drawPath(
          fill,
          Paint()
            ..shader = const LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              colors: <Color>[Color(0x2EDC2626), Color(0x00DC2626)],
            ).createShader(rect),
        );
      }

      canvas.drawPath(
          load,
          Paint()
            ..color = const Color(0xFF7F1D1D)
                .withOpacity(groups.length == 1 ? .28 : .13)
            ..style = PaintingStyle.stroke
            ..strokeWidth = 1.6
            ..strokeCap = StrokeCap.round);
      canvas.drawPath(
          bpm,
          Paint()
            ..color = lineColor.withOpacity(.12)
            ..style = PaintingStyle.stroke
            ..strokeWidth = groups.length == 1 ? 9 : 6
            ..strokeCap = StrokeCap.round
            ..strokeJoin = StrokeJoin.round);
      canvas.drawPath(
          bpm,
          Paint()
            ..color = lineColor
            ..style = PaintingStyle.stroke
            ..strokeWidth = groups.length == 1 ? 3.2 : 2.4
            ..strokeCap = StrokeCap.round
            ..strokeJoin = StrokeJoin.round);

      final every =
          math.max(1, (group.length / (groups.length == 1 ? 8 : 4)).ceil());
      for (var i = 0; i < group.length; i += every) {
        final p = group[i];
        final o = map(p, p.bpm.toDouble());
        canvas.drawCircle(o, groups.length == 1 ? 4 : 3.2,
            Paint()..color = _analyticsZoneColor(p.zone));
        text(canvas, '${p.bpm}', o + const Offset(-9, -19),
            size: 9.4, color: lineColor, weight: FontWeight.w700, maxWidth: 30);
      }
      if (groups.length > 1) {
        final p = group.first;
        final o = map(p, p.bpm.toDouble());
        final name =
            _shortAnalyticsName(p.playerName.isEmpty ? 'Игрок' : p.playerName);
        text(canvas, name, o + const Offset(5, 7),
            size: 9.0, color: lineColor, weight: FontWeight.w700, maxWidth: 72);
      }
    }

    const timeTicks = 6;
    final durationMs = math.max(60000.0, maxX - minX);
    for (var i = 0; i <= timeTicks; i++) {
      final ratio = i / timeTicks;
      final x = rect.left + rect.width * ratio;
      final elapsedSec = durationMs * ratio / 1000.0;
      final elapsedMin = elapsedSec / 60.0;
      final label = durationMs < 300000
          ? '${elapsedSec.round()} с'
          : (elapsedMin >= 60
              ? '${(elapsedMin / 60).floor()}:${(elapsedMin % 60).round().toString().padLeft(2, '0')}'
              : '${elapsedMin.round()} мин');
      canvas.drawLine(
        Offset(x, rect.top),
        Offset(x, rect.bottom),
        Paint()
          ..color = _AA.line.withOpacity(i == 0 || i == timeTicks ? .75 : .42)
          ..strokeWidth = 1,
      );
      final labelWidth = i == 0 || i == timeTicks ? 58.0 : 52.0;
      text(
        canvas,
        label,
        Offset((x - labelWidth / 2).clamp(0.0, size.width - labelWidth),
            rect.bottom + 9),
        size: 11.2,
        color: _AA.muted,
        weight: FontWeight.w800,
        maxWidth: labelWidth,
        align: TextAlign.center,
      );
    }

    if (selectedPoint != null) {
      final selectedKey = _analyticsHrPointSortKey(selectedPoint!);
      final visibleSelected = list
          .where((p) =>
              _analyticsHrPointSortKey(p) == selectedKey &&
              _analyticsHrGroupKey(p) == _analyticsHrGroupKey(selectedPoint!))
          .toList();
      if (visibleSelected.isNotEmpty) {
        final point = visibleSelected.first;
        final o = map(point, point.bpm.toDouble());
        final tone = _analyticsZoneColor(point.zone);
        canvas.drawRect(
          Rect.fromLTRB(math.max(rect.left, o.dx - 8), rect.top,
              math.min(rect.right, o.dx + 8), rect.bottom),
          Paint()..color = tone.withOpacity(.08),
        );
        canvas.drawLine(
            Offset(o.dx, rect.top),
            Offset(o.dx, rect.bottom),
            Paint()
              ..color = tone
              ..strokeWidth = 2.4);
        canvas.drawCircle(o, 18, Paint()..color = tone.withOpacity(.07));
        canvas.drawCircle(o, 11, Paint()..color = Colors.white);
        canvas.drawCircle(o, 7, Paint()..color = tone);
        canvas.drawCircle(
            o,
            11,
            Paint()
              ..color = tone
              ..style = PaintingStyle.stroke
              ..strokeWidth = 2.4);
        final elapsed = math.max(0, ((selectedKey - minX) / 60000).round());
        final elapsedLabel = elapsed >= 60
            ? '${elapsed ~/ 60}:${(elapsed % 60).toString().padLeft(2, '0')}'
            : '$elapsed мин';
        final bubbleLeft = (o.dx + 12)
            .clamp(rect.left, math.max(rect.left, rect.right - 112))
            .toDouble();
        final bubbleTop =
            (o.dy - 38).clamp(rect.top + 3, rect.bottom - 43).toDouble();
        final bubbleRect = RRect.fromRectAndRadius(
          Rect.fromLTWH(bubbleLeft, bubbleTop, 108, 36),
          const Radius.circular(9),
        );
        canvas.drawRRect(bubbleRect, Paint()..color = Colors.white);
        canvas.drawRRect(
            bubbleRect,
            Paint()
              ..color = tone
              ..style = PaintingStyle.stroke
              ..strokeWidth = 1.5);
        text(canvas, '${point.bpm} bpm · ${point.zone.toUpperCase()}',
            Offset(bubbleLeft + 8, bubbleTop + 5),
            size: 10.5, color: tone, weight: FontWeight.w900, maxWidth: 94);
        text(canvas, elapsedLabel, Offset(bubbleLeft + 8, bubbleTop + 19),
            size: 9.4, color: _AA.text, weight: FontWeight.w800, maxWidth: 94);
      }
    }
    canvas.restore();
  }

  @override
  bool shouldRepaint(covariant _AnalyticsHrLinePainter oldDelegate) =>
      oldDelegate.points != points ||
      oldDelegate.selectedPoint != selectedPoint;
}

class _ValidatedTrackSegment {
  const _ValidatedTrackSegment({
    required this.fromIndex,
    required this.toIndex,
    required this.distanceM,
    required this.dtMs,
    required this.speedKmh,
    required this.accelMps2,
  });

  final int fromIndex;
  final int toIndex;
  final double distanceM;
  final int dtMs;
  final double speedKmh;
  final double accelMps2;
}

class _ValidatedTrackCache {
  const _ValidatedTrackCache({
    required this.length,
    required this.firstTimeMs,
    required this.lastTimeMs,
    required this.lastLatitude,
    required this.lastLongitude,
    required this.segments,
    required this.byToIndex,
    required this.turnPointIndexes,
    required this.turnSpeedByPointIndex,
  });

  final int length;
  final int firstTimeMs;
  final int lastTimeMs;
  final double lastLatitude;
  final double lastLongitude;
  final List<_ValidatedTrackSegment> segments;
  final Map<int, _ValidatedTrackSegment> byToIndex;
  final Set<int> turnPointIndexes;
  final Map<int, double> turnSpeedByPointIndex;
}

final Expando<_ValidatedTrackCache> _validatedTrackCache =
    Expando<_ValidatedTrackCache>('sportoteka_v87_validated_track');

_ValidatedTrackCache _validatedTrack(List<ActionTrackerGpsPoint> points) {
  if (points.isEmpty) {
    return const _ValidatedTrackCache(
      length: 0,
      firstTimeMs: 0,
      lastTimeMs: 0,
      lastLatitude: 0,
      lastLongitude: 0,
      segments: <_ValidatedTrackSegment>[],
      byToIndex: <int, _ValidatedTrackSegment>{},
      turnPointIndexes: <int>{},
      turnSpeedByPointIndex: <int, double>{},
    );
  }

  final cached = _validatedTrackCache[points];
  final last = points.last;
  if (cached != null &&
      cached.length == points.length &&
      cached.firstTimeMs == points.first.timeMs &&
      cached.lastTimeMs == last.timeMs &&
      (cached.lastLatitude - last.latitude).abs() < 1e-10 &&
      (cached.lastLongitude - last.longitude).abs() < 1e-10) {
    return cached;
  }

  final segments = <_ValidatedTrackSegment>[];
  final byToIndex = <int, _ValidatedTrackSegment>{};
  var anchorIndex = 0;
  var prevSpeed = 0.0;

  for (var i = 1; i < points.length; i++) {
    final anchor = points[anchorIndex];
    final b = points[i];

    if (_segmentBreaks(anchor, b)) {
      anchorIndex = i;
      prevSpeed = 0.0;
      continue;
    }

    final dtMs = b.timeMs - anchor.timeMs;
    if (dtMs <= 0) {
      // V87: duplicate/backwards tracker time is rejected and MUST NOT move
      // the anchor. This prevents dt≈0 from producing artificial speed.
      continue;
    }
    if (dtMs > 10000) {
      // Reconnect / long GPS pause. Start a new route section without adding
      // a teleport segment to distance or speed.
      anchorIndex = i;
      prevSpeed = 0.0;
      continue;
    }

    final distanceM = _LocalTrackAnalysis._distanceMeters(
        anchor.latitude, anchor.longitude, b.latitude, b.longitude);
    final speedKmh = (distanceM / (dtMs / 1000.0)) * 3.6;
    if (!speedKmh.isFinite) continue;

    if (distanceM <= 0.35 || speedKmh < 1.5) {
      // Stationary GPS jitter is a valid new anchor, but not movement.
      anchorIndex = i;
      prevSpeed = 0.0;
      continue;
    }

    final dtSec = dtMs / 1000.0;
    final accelMps2 = ((speedKmh - prevSpeed) / 3.6) / dtSec;
    final rejected = distanceM > 80 ||
        speedKmh > 36.0 ||
        (speedKmh >= 28.0 && accelMps2.abs() > 4.5) ||
        (speedKmh >= 16.0 && accelMps2.abs() > 7.0);
    if (rejected) {
      // Critical V85/V87 rule: a rejected coordinate does not become the next
      // anchor, otherwise the return from a GPS jump creates a false 34–35.x.
      continue;
    }

    final segment = _ValidatedTrackSegment(
      fromIndex: anchorIndex,
      toIndex: i,
      distanceM: distanceM,
      dtMs: dtMs,
      speedKmh: speedKmh,
      accelMps2: accelMps2.isFinite ? accelMps2 : 0.0,
    );
    segments.add(segment);
    byToIndex[i] = segment;
    anchorIndex = i;
    prevSpeed = speedKmh;
  }

  final turns = <int>{};
  final turnSpeed = <int, double>{};
  for (var i = 1; i < segments.length; i++) {
    final incoming = segments[i - 1];
    final outgoing = segments[i];
    if (incoming.toIndex != outgoing.fromIndex) continue;
    if (incoming.distanceM < 1.0 || outgoing.distanceM < 1.0) continue;

    final p0 = points[incoming.fromIndex];
    final p1 = points[incoming.toIndex];
    final p2 = points[outgoing.toIndex];
    final latRad = p1.latitude * math.pi / 180.0;
    final x1 = (p1.longitude - p0.longitude) * math.cos(latRad);
    final y1 = p1.latitude - p0.latitude;
    final x2 = (p2.longitude - p1.longitude) * math.cos(latRad);
    final y2 = p2.latitude - p1.latitude;
    final l1 = math.sqrt(x1 * x1 + y1 * y1);
    final l2 = math.sqrt(x2 * x2 + y2 * y2);
    if (l1 <= 1e-12 || l2 <= 1e-12) continue;
    final dot = ((x1 * x2 + y1 * y2) / (l1 * l2)).clamp(-1.0, 1.0);
    if (math.acos(dot) > .75) {
      final pointIndex = incoming.toIndex;
      turns.add(pointIndex);
      // Conservative speed at the change of direction: both incoming and
      // outgoing movement must support it, not just one isolated segment.
      turnSpeed[pointIndex] = math.min(incoming.speedKmh, outgoing.speedKmh);
    }
  }

  final result = _ValidatedTrackCache(
    length: points.length,
    firstTimeMs: points.first.timeMs,
    lastTimeMs: last.timeMs,
    lastLatitude: last.latitude,
    lastLongitude: last.longitude,
    segments: List<_ValidatedTrackSegment>.unmodifiable(segments),
    byToIndex: Map<int, _ValidatedTrackSegment>.unmodifiable(byToIndex),
    turnPointIndexes: Set<int>.unmodifiable(turns),
    turnSpeedByPointIndex: Map<int, double>.unmodifiable(turnSpeed),
  );
  _validatedTrackCache[points] = result;
  return result;
}

class _LocalTrackAnalysis {
  const _LocalTrackAnalysis({
    required this.distanceM,
    required this.durationSec,
    required this.maxSpeedKmh,
    required this.avgSpeedKmh,
    required this.sprintCount,
    required this.sprintDistanceM,
    required this.hsrDistanceM,
    required this.accelCount,
    required this.decelCount,
    required this.speedSamples,
  });

  final double distanceM;
  final int durationSec;
  final double maxSpeedKmh;
  final double avgSpeedKmh;
  final int sprintCount;
  final double sprintDistanceM;
  final double hsrDistanceM;
  final int accelCount;
  final int decelCount;
  final List<double> speedSamples;

  static _LocalTrackAnalysis fromPoints(List<ActionTrackerGpsPoint> points,
      {double sprintThresholdKmh = 18.0, double hsrThresholdKmh = 14.0}) {
    if (points.length < 2) {
      return const _LocalTrackAnalysis(
        distanceM: 0,
        durationSec: 0,
        maxSpeedKmh: 0,
        avgSpeedKmh: 0,
        sprintCount: 0,
        sprintDistanceM: 0,
        hsrDistanceM: 0,
        accelCount: 0,
        decelCount: 0,
        speedSamples: <double>[],
      );
    }

    final validated = _validatedTrack(points);
    double distance = 0.0;
    double maxSpeed = 0.0;
    double sprintDistance = 0.0;
    double hsrDistance = 0.0;
    int sprintCount = 0;
    int accelCount = 0;
    int decelCount = 0;
    int activeMs = 0;
    bool inSprint = false;
    int? previousToIndex;
    final samples = <double>[];

    for (final segment in validated.segments) {
      final continuous = previousToIndex == segment.fromIndex;
      if (!continuous) inSprint = false;

      distance += segment.distanceM;
      activeMs += segment.dtMs;
      maxSpeed = math.max(maxSpeed, segment.speedKmh);
      samples.add(segment.speedKmh);
      if (segment.speedKmh >= hsrThresholdKmh) {
        hsrDistance += segment.distanceM;
      }
      if (segment.speedKmh >= sprintThresholdKmh) {
        sprintDistance += segment.distanceM;
        if (!inSprint) sprintCount++;
        inSprint = true;
      } else if (segment.speedKmh < sprintThresholdKmh * .88) {
        inSprint = false;
      }
      if (segment.accelMps2 >= 1.0) accelCount++;
      if (segment.accelMps2 <= -1.0) decelCount++;
      previousToIndex = segment.toIndex;
    }

    final rawDurationSec =
        ((points.last.timeMs - points.first.timeMs).abs() / 1000).round();
    final activeDurationSec = (activeMs / 1000).round();
    final durationSec = activeDurationSec > 0
        ? activeDurationSec
        : (rawDurationSec <= 0
            ? math.max(1, points.length - 1)
            : rawDurationSec);
    final avg = durationSec <= 0 ? 0.0 : (distance / durationSec) * 3.6;

    return _LocalTrackAnalysis(
      distanceM: distance,
      durationSec: durationSec,
      maxSpeedKmh: maxSpeed,
      avgSpeedKmh: avg,
      sprintCount: sprintCount,
      sprintDistanceM: sprintDistance,
      hsrDistanceM: hsrDistance,
      accelCount: accelCount,
      decelCount: decelCount,
      speedSamples: List<double>.unmodifiable(samples),
    );
  }

  static double _distanceMeters(
      double lat1, double lon1, double lat2, double lon2) {
    const r = 6371000.0;
    final p1 = lat1 * math.pi / 180;
    final p2 = lat2 * math.pi / 180;
    final dp = (lat2 - lat1) * math.pi / 180;
    final dl = (lon2 - lon1) * math.pi / 180;
    final a = math.sin(dp / 2) * math.sin(dp / 2) +
        math.cos(p1) * math.cos(p2) * math.sin(dl / 2) * math.sin(dl / 2);
    return r * 2 * math.atan2(math.sqrt(a), math.sqrt(1 - a));
  }
}

