class _AA {
  // Строгая палитра CMR Trainers: белый/графитовый интерфейс,
  // зелёный используется только как акцент активного состояния.
  static const bg = Color(0xFFFFFFFF);
  static const card = Color(0xFFFFFFFF);
  static const soft = Color(0xFFF7F8F7);
  static const soft2 = Color(0xFFF2F4F2);
  static const greenSoft = Color(0xFFF3FAF6);
  static const greenSoft2 = Color(0xFFF8FEFA);
  static const greenLine = Color(0xFFD7F0E2);
  static const line = Color(0xFFE9ECEA);
  static const text = Color(0xFF0B0F14);
  static const graphite = Color(0xFF111827);
  static const graphite2 = Color(0xFF374151);
  static const muted = Color(0xFF5F6670);
  static const muted2 = Color(0xFF8A9099);
  // Навигация должна быть чуть контрастнее обычного вторичного текста:
  // на светлых планшетных экранах тонкие подписи иначе выглядят выцветшими.
  static const navMuted = Color(0xFF5D6861);
  static const green = Color(0xFF00A750);
  static const greenDark = Color(0xFF067A46);
  static const blue = Color(0xFF2563EB);
  static const orange = Color(0xFFF59E0B);
  static const red = Color(0xFFDC2626);

  // Единая геометрия для мобильной и планшетной аналитики трекера.
  static const double mobileCardRadius = 18.0;
  static const double mobileInnerRadius = 12.0;
  static const double mobileChipRadius = 10.0;
  static const double tabletCardRadius = 16.0;
  static const double tabletInnerRadius = 12.0;
  static const double sheetRadius = 18.0;

