class _CoachInsightScaffold extends StatelessWidget {
  const _CoachInsightScaffold(
      {required this.child, required this.insight, required this.onClose});
  final Widget child;
  final _CoachInsight? insight;
  final VoidCallback onClose;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(builder: (context, c) {
      final current = insight;
      final phone = c.maxWidth < 720;
      if (phone) {
        return Stack(children: [
          Positioned.fill(child: child),
          if (current != null)
            Positioned(
              left: 0,
              right: 0,
              bottom: 0,
              height: math.min(
                  math.max(320.0, c.maxHeight * .64), c.maxHeight - 12),
              child: _CoachInsightPanel(
                  insight: current, onClose: onClose, mobile: true),
            ),
        ]);
      }
      final panelWidth = current == null
          ? 0.0
          : math.min(390.0, math.max(330.0, c.maxWidth * .31));
      return Row(children: [
        Expanded(child: child),
        AnimatedContainer(
          duration: const Duration(milliseconds: 220),
          curve: Curves.easeOutCubic,
          width: panelWidth,
          child: current == null
              ? const SizedBox.shrink()
              : _CoachInsightPanel(insight: current, onClose: onClose),
        ),
      ]);
    });
  }
}

