class _YouthSpeedProfile {
  const _YouthSpeedProfile(
      {required this.label, required this.hsrKmh, required this.sprintKmh});

  final String label;
  final double hsrKmh;
  final double sprintKmh;

  static _YouthSpeedProfile fromLabel(String value) {
    final raw = value.toUpperCase();
    final age = int.tryParse(
        RegExp(r'U\s*([0-9]{1,2})').firstMatch(raw)?.group(1) ?? '');
    if (age == null || age <= 0) {
      return const _YouthSpeedProfile(
          label: 'ДЮФ', hsrKmh: 14.0, sprintKmh: 18.0);
    }
    if (age <= 8)
      return const _YouthSpeedProfile(
          label: 'U6–U8', hsrKmh: 11.5, sprintKmh: 14.5);
    if (age <= 10)
      return const _YouthSpeedProfile(
          label: 'U9–U10', hsrKmh: 12.5, sprintKmh: 15.5);
    if (age <= 12)
      return const _YouthSpeedProfile(
          label: 'U11–U12', hsrKmh: 13.5, sprintKmh: 17.0);
    if (age <= 13)
      return const _YouthSpeedProfile(
          label: 'U13', hsrKmh: 14.0, sprintKmh: 18.0);
    if (age <= 15)
      return const _YouthSpeedProfile(
          label: 'U14–U15', hsrKmh: 16.0, sprintKmh: 20.0);
    if (age <= 17)
      return const _YouthSpeedProfile(
          label: 'U16–U17', hsrKmh: 18.0, sprintKmh: 22.0);
    return const _YouthSpeedProfile(
        label: 'Профи', hsrKmh: 19.8, sprintKmh: 25.2);
  }
}

class _SessionPickerPlayerSummary {
  _SessionPickerPlayerSummary(
      {required this.id, required this.name, required this.player});
  final int id;
  final String name;
  final TrackerPlayerOption? player;
  int count = 0;
  double distanceM = 0;
  double maxSpeedKmh = 0;
  int sprints = 0;
  int accel = 0;
  int decel = 0;
  bool hasData = false;

  void add(TrackerSessionModel session) {
    count += 1;
    distanceM += session.distanceM;
    maxSpeedKmh =
        math.max<double>(maxSpeedKmh, _jsonDouble(session.maxSpeedKmh));
    sprints += session.sprintCount;
    accel += session.accelCount;
    decel += session.decelCount;
    hasData = hasData ||
        distanceM > 0 ||
        maxSpeedKmh > 0 ||
        sprints > 0 ||
        accel > 0 ||
        decel > 0 ||
        session.durationSec > 0;
  }
}

