class _TrackerInlineCalendarPaneState
    extends State<_TrackerInlineCalendarPane> {
  late DateTime _cursor;
  late DateTime _selected;
  final GlobalKey _selectedDayPanelKey = GlobalKey();

  @override
  void initState() {
    super.initState();
    _selected = DateTime(widget.initialDate.year, widget.initialDate.month,
        widget.initialDate.day);
    _cursor = DateTime(_selected.year, _selected.month, 1);
  }

  @override
  void didUpdateWidget(covariant _TrackerInlineCalendarPane oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!_trackerSameDay(oldWidget.initialDate, widget.initialDate)) {
      _selected = DateTime(widget.initialDate.year, widget.initialDate.month,
          widget.initialDate.day);
      _cursor = DateTime(_selected.year, _selected.month, 1);
    }
  }

  Map<String, _TrackerCalendarDayMark> get _marks {
    final map = <String, _TrackerCalendarDayMark>{};
    for (final group in _groupTrackerSessions(widget.sessions)) {
      final dt = group.anchor ?? _trackerSessionDate(group.representative);
      if (dt == null) continue;
      final key = _trackerCalendarKey(dt);
      final mark = map[key] ??
          _TrackerCalendarDayMark(day: DateTime(dt.year, dt.month, dt.day));
      mark.add(group);
      map[key] = mark;
    }
    return map;
  }

  List<_TrackerTrainingGroup> _sessionsFor(DateTime day) {
    final key = _trackerCalendarKey(day);
    final rows = _groupTrackerSessions(widget.sessions).where((group) {
      final dt = group.anchor ?? _trackerSessionDate(group.representative);
      return dt != null && _trackerCalendarKey(dt) == key;
    }).toList(growable: false);
    final sorted = [...rows]..sort((a, b) {
        final aDate = a.anchor;
        final bDate = b.anchor;
        if (aDate == null && bDate == null)
          return b.representative.id.compareTo(a.representative.id);
        if (aDate == null) return 1;
        if (bDate == null) return -1;
        return bDate.compareTo(aDate);
      });
    return sorted;
  }

  String _playerName(TrackerSessionModel session) {
    TrackerPlayerOption? player;
    final id = session.playerId;
    if (id != null) {
      for (final p in widget.players) {
        if (p.id == id) {
          player = p;
          break;
        }
      }
    }
    final raw = (session.playerName ?? '').trim();
    final fromRoster = player?.name.trim() ?? '';
    final name =
        raw.isNotEmpty && !_looksGenericPlayerName(raw) ? raw : fromRoster;
    return name.isEmpty ? 'Игрок ${session.playerId ?? ''}'.trim() : name;
  }

  void _setLocal(VoidCallback fn) {
    if (!mounted) return;
    setState(fn);
  }

  void _selectDate(DateTime d) {
    final normalized = DateTime(d.year, d.month, d.day);
    _setLocal(() {
      _selected = normalized;
      if (normalized.month != _cursor.month ||
          normalized.year != _cursor.year) {
        _cursor = DateTime(normalized.year, normalized.month, 1);
      }
    });
    widget.onSelected(normalized);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      final targetContext = _selectedDayPanelKey.currentContext;
      if (targetContext == null) return;
      Scrollable.ensureVisible(
        targetContext,
        duration: const Duration(milliseconds: 320),
        curve: Curves.easeOutCubic,
        alignment: .04,
      );
    });
  }

  void _shiftMonth(int delta) {
    _setLocal(() => _cursor = DateTime(_cursor.year, _cursor.month + delta, 1));
  }

  void _today() {
    final now = DateTime.now();
    _selectDate(DateTime(now.year, now.month, now.day));
  }

  @override
  Widget build(BuildContext context) {
    final width = MediaQuery.sizeOf(context).width;
    final mobile = width < 720;
    final selectedRows = _sessionsFor(_selected);
    final selectedMark = _marks[_trackerCalendarKey(_selected)];

    Widget calendarWindow({required bool phone}) {
      return Container(
        decoration: BoxDecoration(
          color: _AA.card,
          borderRadius: BorderRadius.circular(phone ? 20 : 22),
          boxShadow: const [
            BoxShadow(
                color: Color(0x07111827), blurRadius: 14, offset: Offset(0, 6))
          ],
        ),
        clipBehavior: Clip.antiAlias,
        child:
            Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Container(
            height: phone ? 58 : 60,
            padding:
                EdgeInsets.fromLTRB(phone ? 12 : 14, 8, phone ? 10 : 12, 8),
            decoration: const BoxDecoration(color: _AA.card),
            child: Row(children: [
              Container(
                width: phone ? 38 : 40,
                height: phone ? 38 : 40,
                decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(14)),
                child: const Icon(Icons.calendar_month_rounded,
                    color: _AA.green, size: 19),
              ),
