class _TrackerTrainingGroup {
  _TrackerTrainingGroup({
    required this.key,
    required this.sessions,
    required this.anchor,
    this.serverGroupKey = '',
  });

  final String key;
  final List<TrackerSessionModel> sessions;
  final DateTime? anchor;
  final String serverGroupKey;

  bool get personalSession =>
      sessions.every((session) => session.personalSession);
  List<int> get sessionIds => sessions
      .map((session) => session.id)
      .where((id) => id > 0)
      .toSet()
      .toList(growable: false);

  Set<int> get playerIds {
    final ids = <int>{};
    for (final session in sessions) {
      ids.addAll(session.participantIds.where((id) => id > 0));
      final direct = session.playerId;
      if (direct != null && direct > 0) ids.add(direct);
    }
    return ids;
  }

  List<String> get playerNames {
    final names = <String>[];
    void addName(String? value) {
      final name = (value ?? '').trim();
      if (name.isEmpty || _looksGenericPlayerName(name)) return;
      if (!names.any((item) => item.toLowerCase() == name.toLowerCase()))
        names.add(name);
    }

    for (final session in sessions) {
      for (final name in session.participantNames) {
        addName(name);
      }
      addName(session.playerName);
    }
    return names;
  }

  int get participantsCount {
    var declared = 0;
    for (final session in sessions) {
      declared = math.max(declared, session.participantsCount);
    }
    return math.max(declared, math.max(playerIds.length, playerNames.length));
  }

  double get distanceM =>
      sessions.fold<double>(0, (sum, session) => sum + session.distanceM);
  double get loadScore =>
      sessions.fold<double>(0, (sum, session) => sum + session.loadScore);
  double get maxSpeedKmh => sessions.fold<double>(
      0, (value, session) => math.max(value, session.maxSpeedKmh));
  int get sprintCount =>
      sessions.fold<int>(0, (sum, session) => sum + session.sprintCount);
  int get accelCount =>
      sessions.fold<int>(0, (sum, session) => sum + session.accelCount);
  int get decelCount =>
      sessions.fold<int>(0, (sum, session) => sum + session.decelCount);
  double get avgSpeedKmh {
    final rows = sessions.where((session) => session.avgSpeedKmh > 0).toList();
    if (rows.isEmpty) return 0;
    return rows.fold<double>(0, (sum, session) => sum + session.avgSpeedKmh) /
        rows.length;
  }
  int get gpsPlayersCount => sessions.where(_trackerSessionHasGps).length;
  int get polarPlayersCount => sessions.where(_trackerSessionHasPolar).length;
  int get durationSec => sessions.fold<int>(
      0, (value, session) => math.max(value, session.durationSec));
  int get heartRateSamplesCount => sessions.fold<int>(
      0, (sum, session) => sum + session.heartRateSamplesCount);
  bool get hasPolar => sessions.any(_trackerSessionHasPolar);
  bool get hasGps => sessions.any(_trackerSessionHasGps);

  TrackerSessionModel get representative {
    TrackerSessionModel best = sessions.first;
    double score(TrackerSessionModel session) =>
        session.participantsCount * 1000000 +
        session.heartRateSamplesCount * 100 +
        session.distanceM +
        session.durationSec +
        session.maxSpeedKmh;
    for (final session in sessions.skip(1)) {
      if (score(session) > score(best)) best = session;
    }
    return best;
  }
}

DateTime? _trackerEstimatedSessionStart(TrackerSessionModel session) {
  final created = _trackerSessionDate(session);
  if (created == null) return null;
  if (session.durationSec <= 0) return created;
  return created.subtract(Duration(seconds: session.durationSec));
}

List<_TrackerTrainingGroup> _groupTrackerSessions(
    Iterable<TrackerSessionModel> source) {
  final rows = source.toList(growable: false)
    ..sort((a, b) {
      final aDate = _trackerSessionDate(a);
      final bDate = _trackerSessionDate(b);
      if (aDate == null && bDate == null) return a.id.compareTo(b.id);
      if (aDate == null) return 1;
      if (bDate == null) return -1;
      final byDate = aDate.compareTo(bDate);
      return byDate != 0 ? byDate : a.id.compareTo(b.id);
    });
  final groups = <_TrackerTrainingGroup>[];
  final explicitGroups = <String, _TrackerTrainingGroup>{};

  for (final session in rows) {
    final created = _trackerSessionDate(session);
    if (session.personalSession) {
      groups.add(_TrackerTrainingGroup(
        key: 'personal:${session.id}',
        sessions: <TrackerSessionModel>[session],
        anchor: created,
      ));
      continue;
    }

    final serverKey = session.sessionGroupKey.trim();
    if (serverKey.isNotEmpty) {
      final dayKey = created == null ? 'unknown' : _trackerCalendarKey(created);
      final mapKey = 'team:$dayKey:$serverKey';
      final existing = explicitGroups[mapKey];
      if (existing != null) {
        existing.sessions.add(session);
      } else {
        final group = _TrackerTrainingGroup(
          key: mapKey,
          sessions: <TrackerSessionModel>[session],
          anchor: created,
          serverGroupKey: serverKey,
        );
        explicitGroups[mapKey] = group;
        groups.add(group);
      }
      continue;
    }

    _TrackerTrainingGroup? fallback;
    final estimatedStart = _trackerEstimatedSessionStart(session);
    for (final candidate in groups.reversed) {
      if (candidate.personalSession || candidate.serverGroupKey.isNotEmpty)
        continue;
      final candidateDate = candidate.anchor;
      if (created == null ||
          candidateDate == null ||
          !_trackerSameDay(created, candidateDate)) continue;
      final rawGap = created.difference(candidateDate).abs();
      final candidateStart =
          _trackerEstimatedSessionStart(candidate.sessions.first);
      final startGap = estimatedStart == null || candidateStart == null
          ? const Duration(days: 1)
          : estimatedStart.difference(candidateStart).abs();
      if (rawGap <= const Duration(minutes: 8) ||
          startGap <= const Duration(minutes: 8)) {
        fallback = candidate;
      }
      break;
    }
    if (fallback != null) {
      fallback.sessions.add(session);
    } else {
      groups.add(_TrackerTrainingGroup(
        key: 'team:time:${created?.millisecondsSinceEpoch ?? session.id}',
        sessions: <TrackerSessionModel>[session],
        anchor: created,
      ));
    }
  }

  groups.sort((a, b) {
    final aDate = a.anchor;
    final bDate = b.anchor;
    if (aDate == null && bDate == null)
      return b.representative.id.compareTo(a.representative.id);
    if (aDate == null) return 1;
    if (bDate == null) return -1;
    return bDate.compareTo(aDate);
  });
  return groups;
}

String _trackerTrainingWord(int value) {
  final mod100 = value % 100;
  final mod10 = value % 10;
  if (mod100 >= 11 && mod100 <= 14) return 'тренировок';
  if (mod10 == 1) return 'тренировка';
  if (mod10 >= 2 && mod10 <= 4) return 'тренировки';
  return 'тренировок';
}

class _TrackerCalendarDayMark {
  _TrackerCalendarDayMark({required this.day});
  final DateTime day;
  int trainingsCount = 0;
  int sessionRowsCount = 0;
  final Set<int> playerIds = <int>{};
  double distanceM = 0;
  double loadScore = 0;
  double maxSpeedKmh = 0;
  int sprintCount = 0;
  int declaredPlayersCount = 0;

  int get playersCount => math.max(playerIds.length, declaredPlayersCount);
  int get sessionsCount => trainingsCount;

  void add(_TrackerTrainingGroup group) {
    trainingsCount++;
    sessionRowsCount += group.sessions.length;
    playerIds.addAll(group.playerIds);
    if (group.participantsCount > declaredPlayersCount)
      declaredPlayersCount = group.participantsCount;
    distanceM += group.distanceM;
    loadScore += group.loadScore;
    sprintCount += group.sprintCount;
    if (group.maxSpeedKmh > maxSpeedKmh) maxSpeedKmh = group.maxSpeedKmh;
  }
}

class _TrackerInlineMonthCalendar extends StatelessWidget {
  const _TrackerInlineMonthCalendar({
    required this.cursor,
    required this.selected,
    required this.marks,
    required this.onSelect,
    this.roomy = false,
  });

  final DateTime cursor;
  final DateTime selected;
  final Map<String, _TrackerCalendarDayMark> marks;
  final ValueChanged<DateTime> onSelect;
  final bool roomy;

  @override
  Widget build(BuildContext context) {
    const weekdays = ['Пн', 'Вт', 'Ср', 'Чт', 'Пт', 'Сб', 'Вс'];
    final first = DateTime(cursor.year, cursor.month, 1);
    final daysInMonth = DateTime(cursor.year, cursor.month + 1, 0).day;
    final prevMonthDays = DateTime(cursor.year, cursor.month, 0).day;
    final leading = first.weekday - 1;
    final total = ((leading + daysInMonth + 6) ~/ 7) * 7;
    final rowsCount = total ~/ 7;

    Widget grid(double maxHeight, double maxWidth) {
      final gap = roomy ? 7.0 : 6.0;
      final cellWidth = (maxWidth - gap * 6) / 7;
      final heightIsBounded = maxHeight.isFinite && maxHeight > 0;
      final availableHeight = heightIsBounded
          ? math.max(
              0.0, (maxHeight - gap * (rowsCount - 1)) / rowsCount)
          : cellWidth / 1.18;
      final targetHeight = cellWidth / 1.18;
      final preferredHeight = roomy
          ? math.max(42.0, math.min(58.0, targetHeight))
          : math.max(34.0, math.min(44.0, targetHeight));
      // В широком desktop/tablet диалоге календарь иногда получает только
      // ~249 px высоты. Для месяца из шести строк прежний жёсткий минимум 42 px
      // давал 6 * 42 + 5 * 7 = 287 px и RenderFlex overflow ровно на 38 px.
      // При ограниченной высоте ячейка должна подчиняться LayoutBuilder, а
      // минимальный удобный размер сохраняется только в небounded/ListView виде.
      final cellHeight = heightIsBounded
          ? math.min(preferredHeight, availableHeight)
          : preferredHeight;
      final children = <Widget>[];
      for (var row = 0; row < rowsCount; row++) {
        final rowCells = <Widget>[];
        for (var col = 0; col < 7; col++) {
          final index = row * 7 + col;
          final dayNumber = index - leading + 1;
          late DateTime day;
          var inMonth = true;
          if (dayNumber < 1) {
            day = DateTime(
                cursor.year, cursor.month - 1, prevMonthDays + dayNumber);
            inMonth = false;
          } else if (dayNumber > daysInMonth) {
            day = DateTime(
                cursor.year, cursor.month + 1, dayNumber - daysInMonth);
            inMonth = false;
          } else {
            day = DateTime(cursor.year, cursor.month, dayNumber);
          }
          final mark = marks[_trackerCalendarKey(day)];
          final has = mark != null && mark.sessionsCount > 0;
          rowCells.add(Expanded(
            child: SizedBox(
              height: cellHeight,
              child: _TrackerCalendarDayCell(
                day: day,
                inMonth: inMonth,
                selected: _trackerSameDay(day, selected),
                today: _trackerSameDay(day, DateTime.now()),
                mark: mark,
                onTap: () => onSelect(DateTime(day.year, day.month, day.day)),
                dense: rowsCount > 5,
                has: has,
                roomy: roomy,
              ),
            ),
          ));
          if (col != 6) rowCells.add(SizedBox(width: gap));
        }
        children.add(Row(children: rowCells));
        if (row != rowsCount - 1) children.add(SizedBox(height: gap));
      }
      return Column(mainAxisSize: MainAxisSize.min, children: children);
    }

    return Container(
      decoration: BoxDecoration(
        color: _AA.card,
        borderRadius: BorderRadius.circular(12),
        border: Border.all(color: Colors.transparent, width: 0),
      ),
      padding: const EdgeInsets.fromLTRB(0, 0, 0, 0),
      child: LayoutBuilder(builder: (context, outer) {
        final header = Row(
          children: weekdays
              .map((d) => Expanded(
                  child: Center(
                      child: Text(d,
                          style: const TextStyle(
                              color: _AA.muted,
                              fontSize: 11.2,
                              fontWeight: FontWeight.w600,
                              height: 1.0)))))
              .toList(),
        );
        final gridWidget = LayoutBuilder(
            builder: (context, gridBox) =>
                grid(gridBox.maxHeight, gridBox.maxWidth));
        return Column(children: [
          header,
          const SizedBox(height: 8),
          if (outer.maxHeight.isFinite)
            Expanded(child: gridWidget)
          else
            gridWidget,
        ]);
      }),
    );
  }
}

class _TrackerCalendarDayCell extends StatelessWidget {
  const _TrackerCalendarDayCell({
    required this.day,
    required this.inMonth,
    required this.selected,
    required this.today,
    required this.mark,
    required this.onTap,
    required this.dense,
    required this.has,
    this.roomy = false,
  });

  final DateTime day;
  final bool inMonth;
  final bool selected;
  final bool today;
  final _TrackerCalendarDayMark? mark;
  final VoidCallback onTap;
  final bool dense;
  final bool has;
  final bool roomy;

  @override
  Widget build(BuildContext context) {
    final safeMark = mark;
    final safeHas = has && safeMark != null && safeMark.sessionsCount > 0;
    final bg = selected
        ? _AA.greenSoft
        : safeHas
            ? Colors.white
            : (inMonth ? _AA.bg : Colors.white);
    final textColor = selected
        ? const Color(0xFF067A46)
        : inMonth
            ? (today ? _AA.green : _AA.text)
            : _AA.muted.withOpacity(.72);
    final radius = roomy ? 12.0 : 11.0;
    final dayFont = roomy ? 12.0 : 11.0;
    final count = safeMark?.sessionsCount ?? 0;
    return _NoHoverTap(
      onTap: onTap,
      borderRadius: BorderRadius.circular(radius),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 160),
        padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 4),
        decoration: BoxDecoration(
          color: bg,
          borderRadius: BorderRadius.circular(radius),
          border: selected ? Border.all(color: _AA.greenLine, width: 1) : null,
          boxShadow: selected
              ? const [
                  BoxShadow(
                      color: Color(0x07111827),
                      blurRadius: 12,
                      offset: Offset(0, 5))
                ]
              : null,
        ),
        child: Stack(children: [
          Center(
            child: Text(
              '${day.day}',
              maxLines: 1,
              softWrap: false,
              style: TextStyle(
                  color: textColor,
                  fontSize: dayFont,
                  fontWeight: FontWeight.w600,
                  height: 1.0),
            ),
          ),
          if (safeHas)
            Positioned(
              top: -1,
              right: -1,
              child: Container(
                constraints: const BoxConstraints(minWidth: 14),
                height: 14,
                padding: const EdgeInsets.symmetric(horizontal: 3),
                decoration: BoxDecoration(
                    color: _AA.green,
                    borderRadius: BorderRadius.circular(99),
                    border: Border.all(color: Colors.white, width: 1.1)),
                child: Center(
                    child: Text('$count',
                        style: const TextStyle(
                            color: Colors.white,
                            fontSize: 9.6,
                            fontWeight: FontWeight.w700,
                            height: 1.0))),
              ),
            ),
          if (selected)
            Positioned(
              left: 0,
              right: 0,
              bottom: safeHas ? 4 : 5,
              child: Center(
                child: SizedBox(
                  width: safeHas ? 4 : 6,
                  height: safeHas ? 4 : 6,
                  child: const DecoratedBox(
                      decoration: BoxDecoration(
                          color: _AA.green, shape: BoxShape.circle)),
                ),
              ),
            ),
        ]),
      ),
    );
  }
}

