class _TrackerSessionPreview extends StatelessWidget {
  const _TrackerSessionPreview({
    required this.group,
    required this.players,
    required this.playerName,
    required this.compact,
    this.onSelect,
    this.onOpenReport,
  });

  final _TrackerTrainingGroup group;
  final List<TrackerPlayerOption> players;
  final String playerName;
  final bool compact;
  final VoidCallback? onSelect;
  final VoidCallback? onOpenReport;

  String _clock(DateTime? value) {
    if (value == null) return '—';
    return '${value.hour.toString().padLeft(2, '0')}:${value.minute.toString().padLeft(2, '0')}';
  }

  @override
  Widget build(BuildContext context) {
    final session = group.representative;
    final end = group.anchor ?? _trackerSessionDate(session);
    final start = end == null || group.durationSec <= 0
        ? null
        : end.subtract(Duration(seconds: group.durationSec));
    final participants = math.max(
        1, math.max(group.participantsCount, group.sessions.length));
    final gpsCount = math.min(group.gpsPlayersCount, participants);
    final polarCount = math.min(group.polarPlayersCount, participants);
    final rosterById = <int, TrackerPlayerOption>{};
    final rosterByName = <String, TrackerPlayerOption>{};
    for (final player in players) {
      if (player.id > 0) rosterById[player.id] = player;
      final normalizedName = player.name.trim().toLowerCase();
      if (normalizedName.isNotEmpty) rosterByName[normalizedName] = player;
      for (final identityId in player.identityIds) {
        if (identityId > 0) rosterById[identityId] = player;
      }
    }
    final participantRows = <_TrackerPreviewParticipant>[];
    final usedNames = <String>{};
    void addParticipant({int? id, String? fallbackName}) {
      final rawName = (fallbackName ?? '').trim();
      final roster = id == null
          ? rosterByName[rawName.toLowerCase()]
          : rosterById[id] ?? rosterByName[rawName.toLowerCase()];
      final rosterName = (roster?.name ?? '').trim();
      final resolvedName = rosterName.isNotEmpty
          ? rosterName
          : (rawName.isNotEmpty && !_looksGenericPlayerName(rawName)
              ? rawName
              : (id == null ? '' : 'Игрок #$id'));
      if (resolvedName.isEmpty ||
          !usedNames.add(resolvedName.toLowerCase())) return;
      final playerSessions = id == null
          ? const <TrackerSessionModel>[]
          : group.sessions
              .where((row) =>
                  row.playerId == id || row.participantIds.contains(id))
              .toList(growable: false);
      participantRows.add(_TrackerPreviewParticipant(
        id: id,
        name: resolvedName,
        number: (roster?.number ?? '').toString().trim(),
        position: (roster?.position ?? '').trim(),
        avatar: (roster?.avatar ?? '').trim(),
        hasGps: playerSessions.any(_trackerSessionHasGps),
        hasPolar: playerSessions.any(_trackerSessionHasPolar),
      ));
    }

    for (final row in group.sessions) {
      addParticipant(id: row.playerId, fallbackName: row.playerName);
    }
    for (final id in group.playerIds) {
      addParticipant(id: id);
    }
    for (final name in group.playerNames) {
      addParticipant(fallbackName: name);
    }
    if (participantRows.isEmpty) addParticipant(fallbackName: playerName);
    participantRows.sort((a, b) => a.name.compareTo(b.name));
    final unresolvedParticipants =
        math.max(0, participants - participantRows.length);
    final warnings = <String>[
      if (!group.hasGps) 'GPS-данные отсутствуют',
      if (group.hasGps && group.distanceM <= 0) 'GPS записан без дистанции',
      if (!group.hasPolar) 'Пульс не записан',
      if (group.durationSec > 0 && group.durationSec < 120)
        'Очень короткая запись',
      if (unresolvedParticipants > 0) 'Состав сессии ещё синхронизируется',
    ];
    final title = group.personalSession ? playerName : 'Командная тренировка';
    final qualityOk = group.hasGps && group.distanceM > 0 && group.durationSec > 0;

    final body = ListView(
      padding: const EdgeInsets.fromLTRB(10, 0, 10, 10),
      children: [
        Container(
          padding: const EdgeInsets.all(10),
          decoration: BoxDecoration(
            color: _AA.soft,
            borderRadius: BorderRadius.circular(12),
          ),
          child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Row(children: [
              Container(
                width: 32,
                height: 32,
                decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(11)),
                child: Icon(
                    group.personalSession
                        ? Icons.person_pin_circle_rounded
                        : Icons.groups_rounded,
                    size: 17,
                    color: _AA.green),
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Text(title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                              color: _AA.text,
                              fontSize: 13.4,
                              fontWeight: FontWeight.w800)),
                      const SizedBox(height: 2),
                      Text(
                        '${group.personalSession ? 'Личная' : 'Командная'} · #${session.id} · ${_trackerSessionSourceLabel(session)}',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: _AA.muted,
                            fontSize: 10.4,
                            fontWeight: FontWeight.w600),
                      ),
                    ]),
              ),
              Container(
                padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),
                decoration: BoxDecoration(
                    color: qualityOk
                        ? _AA.green.withOpacity(.10)
                        : const Color(0xFFFFF7ED),
                    borderRadius: BorderRadius.circular(999)),
                child: Text(qualityOk ? 'Данные готовы' : 'Проверьте данные',
                    style: TextStyle(
                        color: qualityOk
                            ? _AA.green
                            : const Color(0xFFEA580C),
                        fontSize: 9.4,
                        fontWeight: FontWeight.w800)),
              ),
            ]),
            const SizedBox(height: 9),
            Row(children: [
              Expanded(
                  child: _TrackerPreviewInfoLine(
                      icon: Icons.play_circle_outline_rounded,
                      label: 'Начало',
                      value: _clock(start))),
              Expanded(
                  child: _TrackerPreviewInfoLine(
                      icon: Icons.stop_circle_outlined,
                      label: 'Окончание',
                      value: _clock(end))),
              Expanded(
                  child: _TrackerPreviewInfoLine(
                      icon: Icons.timer_outlined,
                      label: 'Длительность',
                      value: _trackerSensorDuration(
                          group.durationSec, group.durationSec))),
            ]),
          ]),
        ),
        const SizedBox(height: 8),
        LayoutBuilder(builder: (context, c) {
          final gap = 6.0;
          final tileWidth = (c.maxWidth - gap) / 2;
          return Wrap(spacing: gap, runSpacing: gap, children: [
            SizedBox(
                width: tileWidth,
                child: _TrackerPreviewMetric(
                    icon: Icons.route_rounded,
                    label: 'Дистанция',
                    value: _meters(group.distanceM))),
            SizedBox(
                width: tileWidth,
                child: _TrackerPreviewMetric(
                    icon: Icons.person_pin_circle_outlined,
                    label: 'Сред. на игрока',
                    value: _meters(group.distanceM / participants))),
            SizedBox(
                width: tileWidth,
                child: _TrackerPreviewMetric(
                    icon: Icons.speed_rounded,
                    label: 'Скорость макс.',
                    value: '${group.maxSpeedKmh.toStringAsFixed(1)} км/ч')),
            SizedBox(
                width: tileWidth,
                child: _TrackerPreviewMetric(
                    icon: Icons.av_timer_rounded,
                    label: 'Скорость сред.',
                    value: group.avgSpeedKmh > 0
                        ? '${group.avgSpeedKmh.toStringAsFixed(1)} км/ч'
                        : '—')),
            SizedBox(
                width: tileWidth,
                child: _TrackerPreviewMetric(
                    icon: Icons.directions_run_rounded,
                    label: 'Спринты',
                    value: '${group.sprintCount}')),
            SizedBox(
                width: tileWidth,
                child: _TrackerPreviewMetric(
                    icon: Icons.trending_up_rounded,
                    label: 'Уск. / торм.',
                    value: '${group.accelCount} / ${group.decelCount}')),
            SizedBox(
                width: tileWidth,
                child: _TrackerPreviewMetric(
                    icon: Icons.local_fire_department_rounded,
                    label: 'Нагрузка',
                    value: group.loadScore.toStringAsFixed(0))),
            SizedBox(
                width: tileWidth,
                child: _TrackerPreviewMetric(
                    icon: Icons.groups_rounded,
                    label: 'Игроки',
                    value: '$participants')),
          ]);
        }),
        const SizedBox(height: 8),
        Container(
          padding: const EdgeInsets.all(9),
          decoration: BoxDecoration(
              color: _AA.soft, borderRadius: BorderRadius.circular(11)),
          child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            const Text('Покрытие датчиками',
                style: TextStyle(
                    color: _AA.text,
                    fontSize: 11.2,
                    fontWeight: FontWeight.w800)),
            const SizedBox(height: 7),
            _TrackerPreviewCoverage(
                icon: Icons.sensors_rounded,
                label: 'GPS',
                value: '$gpsCount из $participants игроков',
                color: _AA.green,
                complete: gpsCount >= participants),
            const SizedBox(height: 6),
            _TrackerPreviewCoverage(
                icon: Icons.favorite_rounded,
                label: 'Polar',
                value: '$polarCount из $participants игроков',
                color: const Color(0xFFDC2626),
                complete: polarCount >= participants),
          ]),
        ),
        const SizedBox(height: 8),
        Container(
          padding: const EdgeInsets.all(9),
          decoration: BoxDecoration(
              color: _AA.soft, borderRadius: BorderRadius.circular(11)),
          child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Row(children: [
              const Icon(Icons.groups_rounded, size: 16, color: _AA.graphite2),
              const SizedBox(width: 6),
              Expanded(
                  child: Text('Игроки сессии · $participants',
                      style: const TextStyle(
                          color: _AA.text,
                          fontSize: 11.2,
                          fontWeight: FontWeight.w800))),
              Text('${participantRows.length} показано',
                  style: const TextStyle(
                      color: _AA.muted,
                      fontSize: 9.6,
                      fontWeight: FontWeight.w700)),
            ]),
            const SizedBox(height: 8),
            LayoutBuilder(builder: (context, c) {
              final columns = c.maxWidth >= 390 ? 2 : 1;
              final gap = 6.0;
              final width = columns == 2 ? (c.maxWidth - gap) / 2 : c.maxWidth;
              return Wrap(spacing: gap, runSpacing: gap, children: [
                for (final row in participantRows)
                  SizedBox(
                    width: width,
                    child: _TrackerPreviewPlayerTile(participant: row),
                  ),
              ]);
            }),
          ]),
        ),
        if (warnings.isNotEmpty) ...[
          const SizedBox(height: 8),
          Container(
            padding: const EdgeInsets.all(9),
            decoration: BoxDecoration(
                color: const Color(0xFFFFF7ED),
                borderRadius: BorderRadius.circular(13)),
            child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              const Text('Качество данных',
                  style: TextStyle(
                      color: Color(0xFF9A3412),
                      fontSize: 11.2,
                      fontWeight: FontWeight.w800)),
              const SizedBox(height: 5),
              for (final warning in warnings)
                Padding(
                  padding: const EdgeInsets.only(bottom: 3),
                  child: Text('• $warning',
                      style: const TextStyle(
                          color: Color(0xFF9A3412),
                          fontSize: 10.2,
                          fontWeight: FontWeight.w600)),
                ),
            ]),
          ),
        ],
      ],
    );

    return Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
      Expanded(child: body),
      if (onSelect != null || onOpenReport != null)
        Container(
          padding: EdgeInsets.fromLTRB(10, 7, 10, compact ? 9 : 8),
          color: _AA.card,
          child: LayoutBuilder(builder: (context, c) {
            final narrow = c.maxWidth < 350;
            final select = _TrackerPreviewAction(
                icon: Icons.check_circle_outline_rounded,
                label: 'Выбрать эту сессию',
                subtitle: 'Использовать тренировку в аналитике',
                primary: true,
                onTap: onSelect);
            final report = _TrackerPreviewAction(
                icon: Icons.assignment_outlined,
                label: 'Полный отчёт',
                subtitle: 'Открыть карты, графики и показатели',
                primary: false,
                onTap: onOpenReport);
            if (narrow) {
              return Column(children: [select, const SizedBox(height: 6), report]);
            }
            return Row(children: [
              Expanded(child: select),
              const SizedBox(width: 7),
              Expanded(child: report),
            ]);
          }),
        ),
    ]);
  }
}

