class _TrackerPreviewPlayerTile extends StatelessWidget {
  const _TrackerPreviewPlayerTile({required this.participant});

  final _TrackerPreviewParticipant participant;

  @override
  Widget build(BuildContext context) {
    final parts = participant.name
        .trim()
        .split(RegExp(r'\s+'))
        .where((part) => part.isNotEmpty)
        .toList(growable: false);
    final initials = parts.isEmpty
        ? 'И'
        : parts.take(2).map((part) => part.substring(0, 1)).join().toUpperCase();
    final details = <String>[
      if (participant.number.isNotEmpty) '№ ${participant.number}',
      if (participant.position.isNotEmpty) participant.position,
      if (participant.id != null &&
          participant.number.isEmpty &&
          participant.position.isEmpty)
        'ID ${participant.id}',
    ];
    return Container(
      height: 48,
      padding: const EdgeInsets.symmetric(horizontal: 7),
      decoration: BoxDecoration(
        color: _AA.soft2,
        borderRadius: BorderRadius.circular(10),
      ),
      child: Row(children: [
        Container(
          width: 31,
          height: 31,
          clipBehavior: Clip.antiAlias,
          alignment: Alignment.center,
          decoration: BoxDecoration(
              color: _AA.greenSoft,
              borderRadius: BorderRadius.circular(10)),
          child: participant.avatar.isNotEmpty
              ? Image.network(
                  participant.avatar,
                  fit: BoxFit.cover,
                  errorBuilder: (_, __, ___) => Center(
                    child: Text(initials,
                        style: const TextStyle(
                            color: _AA.green,
                            fontSize: 10.2,
                            fontWeight: FontWeight.w900)),
                  ),
                )
              : Text(initials,
                  style: const TextStyle(
                      color: _AA.green,
                      fontSize: 10.2,
                      fontWeight: FontWeight.w900)),
        ),
        const SizedBox(width: 7),
        Expanded(
          child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(participant.name,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: _AA.text,
                        fontSize: 10.4,
                        fontWeight: FontWeight.w800)),
                if (details.isNotEmpty) ...[
                  const SizedBox(height: 2),
                  Text(details.join(' · '),
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: const TextStyle(
                          color: _AA.muted,
                          fontSize: 8.8,
                          fontWeight: FontWeight.w600)),
                ],
              ]),
        ),
        const SizedBox(width: 5),
        _TrackerPreviewSensorDot(
            label: 'G', active: participant.hasGps, color: _AA.green),
        const SizedBox(width: 3),
        _TrackerPreviewSensorDot(
            label: 'P',
            active: participant.hasPolar,
            color: const Color(0xFFDC2626)),
      ]),
    );
  }
}

