class _TrackerCalendarSessionCard extends StatelessWidget {
  const _TrackerCalendarSessionCard({
    required this.group,
    required this.playerName,
    this.onTap,
    this.selected = false,
  });

  final _TrackerTrainingGroup group;
  final String playerName;
  final VoidCallback? onTap;
  final bool selected;

  @override
  Widget build(BuildContext context) {
    final session = group.representative;
    final kindColor =
        group.personalSession ? _AA.greenDark : _AA.graphite2;
    final kindLabel = group.personalSession ? 'Личная' : 'Командная';
    final participantsCount = group.participantsCount;
    final sessionTitle = group.personalSession
        ? playerName
        : (session.title.trim().isNotEmpty &&
                session.title.trim().toLowerCase() != 'сессия'
            ? session.title.trim()
            : 'Командная тренировка');
    final card = AnimatedContainer(
      duration: const Duration(milliseconds: 220),
      curve: Curves.easeOutCubic,
      decoration: BoxDecoration(
        color: selected ? _AA.greenSoft2 : _AA.card,
        borderRadius: BorderRadius.circular(12),
        border: Border(
          bottom: BorderSide(
            color: selected ? _AA.green : _AA.line,
            width: selected ? 2 : .7,
          ),
        ),
      ),
      child: Padding(
        padding: const EdgeInsets.fromLTRB(9, 8, 8, 8),
        child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Row(children: [
            Container(
                width: 31,
                height: 31,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                    color: kindColor.withOpacity(.09),
                    borderRadius: BorderRadius.circular(10)),
                child: Icon(
                    group.personalSession
                        ? Icons.person_pin_circle_rounded
                        : Icons.groups_rounded,
                    color: kindColor,
                    size: 16)),
            const SizedBox(width: 8),
            Expanded(
              child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(sessionTitle,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: _AA.text,
                            fontSize: 11.7,
                            fontWeight: FontWeight.w800,
                            height: 1.0)),
                    const SizedBox(height: 4),
                    Text(
                        '$kindLabel · ${_trackerSessionTime(session)} · ${_trackerSessionSourceLabel(session)}',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: _AA.muted,
                            fontSize: 9.3,
                            fontWeight: FontWeight.w600,
                            height: 1.0)),
                  ]),
            ),
            if (onTap != null)
              Container(
                height: 27,
                padding: const EdgeInsets.symmetric(horizontal: 8),
                decoration: BoxDecoration(
                    color: selected ? _AA.greenSoft : _AA.soft2,
                    borderRadius: BorderRadius.circular(9)),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  Text(selected ? 'Выбрано' : 'Подробнее',
                      style: TextStyle(
                          color: selected ? _AA.greenDark : _AA.graphite2,
                          fontSize: 9.2,
                          fontWeight: FontWeight.w800)),
                  const SizedBox(width: 2),
                  Icon(
                      selected
                          ? Icons.check_rounded
                          : Icons.chevron_right_rounded,
                      color: selected ? _AA.greenDark : _AA.graphite2,
                      size: 15),
                ]),
              ),
          ]),
          const SizedBox(height: 7),
          Row(children: [
            Expanded(
              child: _TrackerSessionCompactMetric(
                  icon: Icons.groups_rounded,
                  value: '$participantsCount',
                  label: 'игроков'),
            ),
            const SizedBox(width: 5),
            Expanded(
              child: _TrackerSessionCompactMetric(
                  icon: Icons.route_rounded,
                  value: _meters(group.distanceM),
                  label: 'дистанция'),
            ),
            const SizedBox(width: 5),
            Expanded(
              child: _TrackerSessionCompactMetric(
                  icon: Icons.speed_rounded,
                  value: group.maxSpeedKmh > 0
                      ? group.maxSpeedKmh.toStringAsFixed(1)
                      : '—',
                  label: 'км/ч макс.'),
            ),
          ]),
          const SizedBox(height: 6),
          Row(children: [
            _TrackerSessionStatus(
                icon: Icons.sensors_rounded,
                label: 'GPS ${group.gpsPlayersCount}/$participantsCount',
                active: group.hasGps,
                color: _AA.green),
            const SizedBox(width: 5),
            _TrackerSessionStatus(
                icon: Icons.favorite_rounded,
                label: 'Polar ${group.polarPlayersCount}/$participantsCount',
                active: group.hasPolar,
                color: const Color(0xFFDC2626)),
            const Spacer(),
            Text('${group.sprintCount} спр.',
                style: const TextStyle(
                    color: _AA.muted,
                    fontSize: 9.1,
                    fontWeight: FontWeight.w700)),
          ]),
        ]),
      ),
    );
    if (onTap == null) return card;
    return TweenAnimationBuilder<double>(
      tween: Tween<double>(begin: 0, end: selected ? 1 : 0),
      duration: const Duration(milliseconds: 220),
      curve: Curves.easeOutBack,
      builder: (context, value, child) => Transform.scale(
        scale: 1 + value * .018,
        child: child,
      ),
      child: Material(
        color: Colors.transparent,
        child: InkWell(
          onTap: onTap,
          borderRadius: BorderRadius.circular(12),
          splashColor: _AA.green.withOpacity(.08),
          highlightColor: _AA.green.withOpacity(.07),
          child: card,
        ),
      ),
    );
  }
}

