String _shortPlayerName(String name) {
  final parts =
      name.trim().split(RegExp(r'\s+')).where((e) => e.isNotEmpty).toList();
  if (parts.isEmpty) return 'Игрок';
  if (parts.length == 1) return parts.first;
  final last = parts.first;
  final initial =
      parts.length > 1 && parts[1].isNotEmpty ? '${parts[1][0]}.' : '';
  return '$last $initial'.trim();
}

DateTime? _trackerInlineSessionDateTime(TrackerSessionModel session) =>
    _trackerMoscowDateTime(session.createdAt);

bool _trackerInlineSameDay(DateTime a, DateTime b) =>
    a.year == b.year && a.month == b.month && a.day == b.day;

String _trackerInlineNormalizeName(String value) =>
    value.trim().toLowerCase().replaceAll(RegExp(r'\s+'), ' ');

List<TrackerSessionModel> _trackerInlinePlayerDaySessions(
    TrackerPlayerOption player, List<TrackerSessionModel> daySessions) {
  final id = player.id;
  final name = _trackerInlineNormalizeName(player.name);
  return daySessions.where((session) {
    if (session.playerId != null && session.playerId == id) return true;
    final sessionName = _trackerInlineNormalizeName(session.playerName ?? '');
    return sessionName.isNotEmpty && name.isNotEmpty && sessionName == name;
  }).toList(growable: false);
}

String _trackerInlineSessionWord(int count) {
  final mod10 = count % 10;
  final mod100 = count % 100;
  final word = mod10 == 1 && mod100 != 11
      ? 'сессия'
      : (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)
          ? 'сессии'
          : 'сессий');
  return '$count $word';
}

class _InlinePlayerFilterPanel extends StatelessWidget {
  const _InlinePlayerFilterPanel(
      {required this.players,
      required this.sessions,
      required this.selectedDate,
      required this.selectedIds,
      required this.sessionKind,
      required this.onChanged});
  final List<TrackerPlayerOption> players;
  final List<TrackerSessionModel> sessions;
  final DateTime selectedDate;
  final Set<int> selectedIds;
  final PlayerTrainingCalendarMode sessionKind;
  final ValueChanged<Set<int>> onChanged;

  @override
  Widget build(BuildContext context) {
    final width = MediaQuery.sizeOf(context).width;
    final mobile = width < 720;

    return Container(
      color: _AA.bg,
      padding: EdgeInsets.fromLTRB(
          mobile ? 8 : 12, mobile ? 8 : 10, mobile ? 8 : 12, mobile ? 12 : 14),
      child: LayoutBuilder(builder: (context, c) {
        final columns =
            mobile ? 2 : (c.maxWidth >= 1320 ? 5 : (c.maxWidth >= 980 ? 4 : 3));
        final gap = mobile ? 8.0 : 10.0;
        final itemWidth = math.max(mobile ? 132.0 : 138.0,
            (c.maxWidth - gap * (columns - 1)) / columns);
        final daySessions = sessions.where((s) {
          final dt = _trackerInlineSessionDateTime(s);
          return dt != null && _trackerInlineSameDay(dt, selectedDate);
        }).toList(growable: false);
        // Для личных тренировок показываем только тех игроков, у которых
        // действительно есть личная сессия на выбранную дату. Иначе список
        // выглядел как полный командный состав, хотя найдено всего 1–2 сессии.
        final visible = (sessionKind == PlayerTrainingCalendarMode.personal
                ? players.where((p) =>
                    _trackerInlinePlayerDaySessions(p, daySessions).isNotEmpty)
                : players)
            .take(72)
            .toList(growable: false);
        final cards = <Widget>[
          SizedBox(
            width: itemWidth,
            child: _InlinePlayerPickCard.team(
              active: selectedIds.isEmpty,
              daySessionCount: daySessions.length,
              dayDistanceM:
                  daySessions.fold<double>(0, (sum, s) => sum + s.distanceM),
              personalMode: sessionKind == PlayerTrainingCalendarMode.personal,
              onTap: () => onChanged(<int>{}),
              mobile: mobile,
            ),
          ),
          for (final p in visible)
            SizedBox(
              width: itemWidth,
              child: _InlinePlayerPickCard(
                player: p,
                active: selectedIds.contains(p.id),
                mobile: mobile,
                daySessionCount:
                    _trackerInlinePlayerDaySessions(p, daySessions).length,
                dayDistanceM: _trackerInlinePlayerDaySessions(p, daySessions)
                    .fold<double>(0, (sum, s) => sum + s.distanceM),
                onTap: () {
                  final next = Set<int>.from(selectedIds);
                  if (next.contains(p.id)) {
                    next.remove(p.id);
                  } else {
                    next.add(p.id);
                  }
                  onChanged(next);
                },
              ),
            ),
        ];
        return SingleChildScrollView(
          physics: const BouncingScrollPhysics(),
          child: Wrap(spacing: gap, runSpacing: gap, children: cards),
        );
      }),
    );
  }
}

class _InlinePlayerPickCard extends StatelessWidget {
  const _InlinePlayerPickCard(
      {required this.player,
      required this.active,
      required this.onTap,
      required this.mobile,
      required this.daySessionCount,
      required this.dayDistanceM})
      : team = false,
        personalMode = false;
  const _InlinePlayerPickCard.team(
      {required this.active,
      required this.onTap,
      required this.mobile,
      required this.daySessionCount,
      required this.dayDistanceM,
      this.personalMode = false})
      : player = null,
        team = true;

  final TrackerPlayerOption? player;
  final bool team;
  final bool active;
  final bool mobile;
  final bool personalMode;
  final int daySessionCount;
  final double dayDistanceM;
  final VoidCallback onTap;

  @override
  Widget build(BuildContext context) {
    final name = team
        ? (personalMode ? 'Все личные' : 'Вся команда')
        : _shortPlayerName(player?.name ?? 'Игрок');
    final fullName = team
        ? (personalMode ? 'игроки с личными сессиями' : 'все игроки')
        : (player?.name ?? 'Игрок');
    final numberRaw = player?.number?.toString().trim() ?? '';
    final positionRaw = player?.position?.toString().trim() ?? '';
    final meta = team
        ? (personalMode ? 'личные тренировки' : 'командная аналитика')
        : [
            if (numberRaw.isNotEmpty) '№ $numberRaw',
            if (positionRaw.isNotEmpty) positionRaw,
          ].join(' · ');
    final sub = meta.isEmpty ? fullName : meta;
    final hasDaySession = daySessionCount > 0;
    final compactSessionValue = daySessionCount.toString();
    final compactDistanceValue =
        dayDistanceM > 0 ? _meters(dayDistanceM) : null;

    return _NoHoverTap(
      onTap: onTap,
      borderRadius: BorderRadius.circular(mobile ? 16 : 18),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 160),
        curve: Curves.easeOutCubic,
        height: mobile ? 92 : 86,
        padding: EdgeInsets.fromLTRB(
            mobile ? 8 : 10, mobile ? 8 : 8, mobile ? 8 : 10, mobile ? 8 : 8),
        decoration: BoxDecoration(
          color: active ? _AA.greenSoft : _AA.card,
          borderRadius: BorderRadius.circular(mobile ? 16 : 18),
          border: Border.all(
              color: active ? _AA.green.withOpacity(.44) : _AA.line,
              width: active ? 1.05 : .9),
          boxShadow: active
              ? const [
                  BoxShadow(
                      color: Color(0x07111827),
                      blurRadius: 12,
                      offset: Offset(0, 5))
                ]
              : null,
        ),
        child: Row(children: [
          _InlinePlayerAvatar(
              player: player,
              team: team,
              active: active,
              size: mobile ? 36 : 46),
          SizedBox(width: mobile ? 8 : 10),
          Expanded(
              child: Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  mainAxisAlignment: MainAxisAlignment.center,
                  children: [
                Text(name,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                        color: active ? _AA.green : _AA.text,
                        fontSize: mobile ? 11.6 : 12.2,
                        fontWeight: FontWeight.w700,
                        height: 1.0,
                        letterSpacing: -.08)),
                const SizedBox(height: 4),
                Text(sub,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                        color: _AA.muted,
                        fontSize: mobile ? 9.2 : 9.2,
                        fontWeight: FontWeight.w500,
                        height: 1.0)),
                const SizedBox(height: 5),
                Wrap(spacing: 4, runSpacing: 4, children: [
                  _InlinePlayerSessionPill(
                    icon: hasDaySession
                        ? Icons.event_available_rounded
                        : Icons.event_busy_rounded,
                    value: compactSessionValue,
                    active: active,
                    enabled: hasDaySession,
                    mobile: mobile,
                  ),
                  if (compactDistanceValue != null)
                    _InlinePlayerSessionPill(
                      icon: Icons.route_rounded,
                      value: compactDistanceValue,
                      active: active,
                      enabled: true,
                      mobile: mobile,
                    ),
                ]),
              ])),
          const SizedBox(width: 5),
          AnimatedContainer(
            duration: const Duration(milliseconds: 160),
            width: mobile ? 22 : 22,
            height: mobile ? 22 : 22,
            decoration: BoxDecoration(
              color: active ? _AA.green : Colors.white,
              shape: BoxShape.circle,
              border: Border.all(color: active ? _AA.green : _AA.line),
            ),
            child: Icon(active ? Icons.check_rounded : Icons.add_rounded,
                color: active ? Colors.white : _AA.muted,
                size: mobile ? 16 : 15),
          ),
        ]),
      ),
    );
  }
}

