class _InlinePlayerAvatar extends StatelessWidget {
  const _InlinePlayerAvatar(
      {required this.player,
      required this.team,
      required this.active,
      required this.size});

  final TrackerPlayerOption? player;
  final bool team;
  final bool active;
  final double size;

  @override
  Widget build(BuildContext context) {
    final avatar = player?.avatar;
    final initials = (player?.name ?? 'И')
        .trim()
        .split(RegExp(r'\s+'))
        .where((e) => e.isNotEmpty)
        .take(2)
        .map((e) => e.substring(0, 1))
        .join()
        .toUpperCase();
    return Container(
      width: size,
      height: size,
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: active ? Colors.white.withOpacity(.86) : _AA.soft,
        borderRadius: BorderRadius.circular(size * .36),
        border: Border.all(color: active ? _AA.greenLine : _AA.line, width: .9),
      ),
      child: team
          ? Icon(Icons.groups_rounded,
              color: active ? _AA.green : _AA.muted, size: size * .48)
          : (avatar != null && avatar.isNotEmpty
              ? Image.network(avatar,
                  fit: BoxFit.cover,
                  errorBuilder: (_, __, ___) => Center(
                      child: Text(initials.isEmpty ? 'И' : initials,
                          style: TextStyle(
                              color: _AA.text,
                              fontSize: size * .26,
                              fontWeight: FontWeight.w700))))
              : Center(
                  child: Text(initials.isEmpty ? 'И' : initials,
                      style: TextStyle(
                          color: _AA.text,
                          fontSize: size * .26,
                          fontWeight: FontWeight.w700)))),
    );
  }
}

