class _TabStrip extends StatelessWidget {
  const _TabStrip({
    required this.selected,
    required this.onSelect,
    this.visibleTabIndices,
    this.mobileAiCircle = false,
    required this.filterActive,
    required this.filterLabel,
    required this.onFilterTap,
  });

  final int selected;
  final ValueChanged<int> onSelect;
  final List<int>? visibleTabIndices;
  final bool mobileAiCircle;
  final bool filterActive;
  final String filterLabel;
  final VoidCallback onFilterTap;

  @override
  Widget build(BuildContext context) {
    final width = MediaQuery.sizeOf(context).width;
    final mobile = width < 720;
    final tablet = width >= 720 && width < 1280;
    final visibleTabs = (visibleTabIndices == null || visibleTabIndices!.isEmpty)
        ? (List<int>.generate(_tabs.length, (index) => index)
          ..remove(12)
          ..insert(1, 12))
        : visibleTabIndices!
            .where((index) => index >= 0 && index < _tabs.length)
            .toList(growable: false);

    Widget filterChip(
        {required bool mobileMode,
        required bool tabletMode,
        required bool desktopMode}) {
      const label = 'Выбор сессии';
      final height = mobileMode ? 34.0 : 36.0;
      return _NoHoverTap(
        borderRadius: BorderRadius.circular(9),
        onTap: onFilterTap,
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 180),
          curve: Curves.easeOutCubic,
          height: height,
          padding: EdgeInsets.symmetric(
            horizontal: mobileMode ? 9 : 11,
            vertical: mobileMode ? 7 : 8,
          ),
          decoration: BoxDecoration(
            color: filterActive ? _AA.greenSoft : Colors.transparent,
            borderRadius: BorderRadius.circular(9),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            Container(
              width: filterActive ? 6.5 : 5.0,
              height: filterActive ? 6.5 : 5.0,
              decoration: BoxDecoration(
                color: filterActive ? _AA.green : _AA.navMuted,
                shape: BoxShape.circle,
                boxShadow: filterActive
                    ? <BoxShadow>[
                        BoxShadow(
                          color: _AA.green.withOpacity(.16),
                          blurRadius: 8,
                          spreadRadius: 1,
                        ),
                      ]
                    : null,
              ),
            ),
            SizedBox(width: mobileMode ? 6 : 7),
            ConstrainedBox(
              constraints: BoxConstraints(maxWidth: mobileMode ? 90 : 220),
              child: Text(
                label,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: _AText.body(
                  mobileMode ? 10.2 : 10.6,
                  color: filterActive ? _AA.greenDark : _AA.navMuted,
                  weight: filterActive ? FontWeight.w600 : FontWeight.w500,
                ),
              ),
            ),
            if (filterActive) ...[
              const SizedBox(width: 6),
              Container(
                width: 5,
                height: 5,
                decoration: const BoxDecoration(
                  color: _AA.green,
                  shape: BoxShape.circle,
                ),
              ),
            ],
          ]),
        ),
      );
    }

    Widget tabItem(int tabIndex,
        {required bool mobileMode,
        required bool tabletMode,
        required bool desktopMode}) {
      final tab = _tabs[tabIndex];
      final active = selected == tabIndex;
      final height = mobileMode ? 34.0 : 36.0;

      return _NoHoverTap(
        borderRadius: BorderRadius.circular(9),
        onTap: () => onSelect(tabIndex),
        child: AnimatedContainer(
          duration: const Duration(milliseconds: 180),
          curve: Curves.easeOutCubic,
          height: height,
          padding: EdgeInsets.symmetric(
            horizontal: mobileMode ? 9 : 11,
            vertical: mobileMode ? 7 : 8,
          ),
          decoration: BoxDecoration(
            color: active ? _AA.greenSoft : Colors.transparent,
            borderRadius: BorderRadius.circular(9),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            Container(
              width: active ? 6.5 : 5.0,
              height: active ? 6.5 : 5.0,
              decoration: BoxDecoration(
                color: active ? _AA.green : _AA.navMuted,
                shape: BoxShape.circle,
                boxShadow: active
                    ? <BoxShadow>[
                        BoxShadow(
                          color: _AA.green.withOpacity(.16),
                          blurRadius: 8,
                          spreadRadius: 1,
                        ),
                      ]
                    : null,
              ),
            ),
            SizedBox(width: mobileMode ? 6 : 7),
            Text(
              tab.label,
              style: _AText.body(
                mobileMode ? 10.2 : 10.6,
                color: active ? _AA.greenDark : _AA.navMuted,
                weight: active ? FontWeight.w600 : FontWeight.w500,
              ),
            ),
            if (active) ...[
              const SizedBox(width: 6),
              Container(
                width: 5,
                height: 5,
                decoration: const BoxDecoration(
                  color: _AA.green,
                  shape: BoxShape.circle,
                ),
              ),
            ],
          ]),
        ),
      );
    }

    Widget itemAt(int index,
        {required bool mobileMode,
        required bool tabletMode,
        required bool desktopMode}) {
      // «Готовность» стоит непосредственно после «Обзора»; выбор сессии
      // остаётся рядом, но больше не разрывает эти два главных раздела.
      if (index == 2)
        return filterChip(
            mobileMode: mobileMode,
            tabletMode: tabletMode,
            desktopMode: desktopMode);
      final visibleIndex = index > 2 ? index - 1 : index;
      final tabIndex = visibleTabs[visibleIndex];
      return tabItem(tabIndex,
          mobileMode: mobileMode,
          tabletMode: tabletMode,
          desktopMode: desktopMode);
    }

    if (mobile) {
      final coreTabs = visibleTabs
          .where((index) => mobileAiCircle
              ? const <int>{0, 12, 1, 2}.contains(index)
              : const <int>{0, 12, 1, 2, 9}.contains(index))
          .toList(growable: false);
      final extraTabs = visibleTabs
          .where((index) =>
              !const <int>{0, 12, 1, 2, 9}.contains(index))
          .toList(growable: false);
      final hasAi = mobileAiCircle && visibleTabs.contains(9);
      final selectedInMore = extraTabs.contains(selected);

      Widget mobileNavButton({
        required String label,
        required IconData icon,
        required bool active,
        required VoidCallback onTap,
      }) {
        return Expanded(
          child: _NoHoverTap(
            onTap: onTap,
            borderRadius: BorderRadius.circular(9),
            child: AnimatedContainer(
              duration: const Duration(milliseconds: 150),
              height: 40,
              padding: const EdgeInsets.symmetric(horizontal: 2, vertical: 4),
              decoration: BoxDecoration(
                color: active ? _AA.greenSoft : Colors.transparent,
                borderRadius: BorderRadius.circular(9),
              ),
              child: Column(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  Icon(
                    icon,
                    size: 13,
                    color: active ? _AA.green : _AA.navMuted,
                  ),
                  const SizedBox(height: 2),
                  Text(
                    label,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    textAlign: TextAlign.center,
                    style: _AText.caption(
                      size: 9.5,
                      color: active ? _AA.greenDark : _AA.navMuted,
                    ),
                  ),
                ],
              ),
            ),
          ),
        );
      }

      void openMoreSections() {
        showModalBottomSheet<void>(
          context: context,
          useSafeArea: true,
          isScrollControlled: true,
          backgroundColor: Colors.transparent,
          builder: (sheetContext) {
            return Container(
              margin: const EdgeInsets.fromLTRB(8, 0, 8, 8),
              padding: const EdgeInsets.fromLTRB(12, 10, 12, 14),
              decoration: BoxDecoration(
                color: _AA.card,
                borderRadius: BorderRadius.circular(22),
                boxShadow: const [
                  BoxShadow(
                    color: Color(0x18101828),
                    blurRadius: 24,
                    offset: Offset(0, 10),
                  ),
                ],
              ),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Row(
                    children: [
                      const Expanded(
                        child: Text(
                          'Все разделы аналитики',
                          style: TextStyle(
                            color: _AA.text,
                            fontSize: 14.0,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ),
                      _NoHoverTap(
                        onTap: () => Navigator.of(sheetContext).pop(),
                        borderRadius: BorderRadius.circular(99),
                        child: Container(
                          width: 30,
                          height: 30,
                          alignment: Alignment.center,
                          decoration: const BoxDecoration(
                            color: _AA.soft,
                            shape: BoxShape.circle,
                          ),
                          child: const Icon(
                            Icons.close_rounded,
                            color: _AA.muted,
                            size: 17,
                          ),
                        ),
                      ),
                    ],
                  ),
                  const SizedBox(height: 5),
                  const Text(
                    'На телефоне основные вкладки закреплены в панели, остальные находятся здесь.',
                    style: TextStyle(
                      color: _AA.muted,
                      fontSize: 10.2,
                      fontWeight: FontWeight.w500,
                      height: 1.25,
                    ),
                  ),
                  const SizedBox(height: 10),
                  GridView.builder(
                    shrinkWrap: true,
                    physics: const NeverScrollableScrollPhysics(),
                    itemCount: extraTabs.length,
                    gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(
                      crossAxisCount: 2,
                      mainAxisSpacing: 7,
                      crossAxisSpacing: 7,
                      childAspectRatio: 2.65,
                    ),
                    itemBuilder: (_, index) {
                      final tabIndex = extraTabs[index];
                      final tab = _tabs[tabIndex];
                      final active = selected == tabIndex;
                      return _NoHoverTap(
                        onTap: () {
                          Navigator.of(sheetContext).pop();
                          Future<void>.delayed(
                            Duration.zero,
                            () => onSelect(tabIndex),
                          );
                        },
                        borderRadius: BorderRadius.circular(12),
                        child: Container(
                          padding: const EdgeInsets.symmetric(horizontal: 9),
                          decoration: BoxDecoration(
                            color: active ? _AA.greenSoft : _AA.soft,
                            borderRadius: BorderRadius.circular(12),
                            border: Border.all(
                              color: active ? _AA.greenLine : Colors.transparent,
                              width: .7,
                            ),
                          ),
                          child: Row(
                            children: [
                              Icon(
                                tab.icon,
                                size: 15,
                                color: active ? _AA.green : _AA.muted,
                              ),
                              const SizedBox(width: 7),
                              Expanded(
                                child: Text(
                                  tab.label,
                                  maxLines: 2,
                                  overflow: TextOverflow.ellipsis,
                                  style: TextStyle(
                                    color: active ? _AA.greenDark : _AA.text,
                                    fontSize: 10.2,
                                    fontWeight: active
                                        ? FontWeight.w700
                                        : FontWeight.w600,
                                    height: 1.05,
                                  ),
                                ),
                              ),
                            ],
                          ),
                        ),
                      );
                    },
                  ),
                ],
              ),
            );
          },
        );
      }

      final shortLabels = <int, String>{
        0: 'Обзор',
        12: 'Готов.',
        1: 'Карта',
        2: 'Скор.',
        3: 'Пульс',
        9: 'ИИ',
      };

      return Container(
        height: 50,
        color: _AA.bg,
        padding: const EdgeInsets.fromLTRB(6, 4, 6, 4),
        child: Container(
          padding: const EdgeInsets.all(2),
          decoration: BoxDecoration(
            color: _AA.card,
            borderRadius: BorderRadius.circular(_AA.mobileInnerRadius),
            boxShadow: const [
              BoxShadow(
                color: Color(0x08101828),
                blurRadius: 14,
                offset: Offset(0, 6),
              ),
            ],
          ),
          child: Row(
            children: [
              mobileNavButton(
                label: 'Сессия',
                icon: Icons.tune_rounded,
                active: filterActive,
                onTap: onFilterTap,
              ),
              for (final tabIndex in coreTabs)
                mobileNavButton(
                  label: shortLabels[tabIndex] ?? _tabs[tabIndex].label,
                  icon: _tabs[tabIndex].icon,
                  active: selected == tabIndex,
                  onTap: () => onSelect(tabIndex),
                ),
              if (hasAi)
                Expanded(
                  child: Center(
                    child: _NoHoverTap(
                      onTap: () => onSelect(9),
                      borderRadius: BorderRadius.circular(999),
                      child: Container(
                        width: 40,
                        height: 40,
                        decoration: const BoxDecoration(
                          color: _AA.greenSoft,
                          shape: BoxShape.circle,
                        ),
                        child: const Icon(
                          Icons.auto_awesome_rounded,
                          color: _AA.green,
                          size: 20,
                        ),
                      ),
                    ),
                  ),
                ),
              if (extraTabs.isNotEmpty)
                mobileNavButton(
                  label: 'Ещё',
                  icon: Icons.grid_view_rounded,
                  active: selectedInMore,
                  onTap: openMoreSections,
                ),
            ],
          ),
        ),
      );
    }

    // На планшете и ПК шапка аналитики повторяет геометрию Live:
    // одна плоская строка 46 px без второго белого контейнера и внешних
    // отступов. Раньше планшетная округлая обёртка выглядела как отдельное
    // «вылезающее» окно и частично перекрывалась системной белой областью.
    return Container(
      height: _AA.analyticsNavHeight,
      padding: EdgeInsets.symmetric(
        horizontal: tablet ? 8 : 12,
        vertical: 5,
      ),
      decoration: const BoxDecoration(
        color: _AA.card,
        border: Border(
            bottom: BorderSide(
                color: _AA.line, width: _AA.analyticsDividerWidth)),
      ),
      child: ListView.separated(
        // Внутри после внешних отступов остаётся ровно 36 px. Вертикальный
        // padding здесь раньше добавлял ещё 6 px и подрезал буквы/иконки.
        padding: const EdgeInsets.symmetric(horizontal: 4),
        scrollDirection: Axis.horizontal,
        itemCount: visibleTabs.length + 1,
        separatorBuilder: (_, __) => const SizedBox(width: 8),
        itemBuilder: (context, i) => itemAt(
          i,
          mobileMode: false,
          tabletMode: tablet,
          desktopMode: !tablet,
        ),
      ),
    );
  }
}

class _OverviewMetricsStrip extends StatelessWidget {
  const _OverviewMetricsStrip({required this.compact, required this.cards});
  final bool compact;
  final List<_Metric> cards;

  @override
  Widget build(BuildContext context) {
    // На узком планшете показатели не исчезают: полоса прокручивается,
    // как статусы GPS/Polar/BLE в Live.
    final visible = cards;
    return Container(
      height: _AA.analyticsContextRowHeight,
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
      decoration: const BoxDecoration(
        color: _AA.card,
      ),
      child: LayoutBuilder(
        builder: (context, constraints) {
          final spacing = visible.length <= 1 ? 0.0 : 5.0;
          final minItemWidth = compact ? 112.0 : 120.0;
          final available = math.max(
            minItemWidth,
            constraints.maxWidth - spacing * math.max(0, visible.length - 1),
          );
          final itemWidth = visible.isEmpty
              ? minItemWidth
              : (available / visible.length)
                  .clamp(minItemWidth, 154.0)
                  .toDouble();
          return ListView.separated(
            scrollDirection: Axis.horizontal,
            physics: const BouncingScrollPhysics(),
            itemCount: visible.length,
            separatorBuilder: (_, __) => SizedBox(width: spacing),
            itemBuilder: (_, index) => SizedBox(
              width: itemWidth,
              child: _OverviewMetricChip(metric: visible[index]),
            ),
          );
        },
      ),
    );
  }
}

/// Компактный KPI в стиле строки управления Live.
/// Все значения сохранены, но вместо высокой карточки используются две строки.
class _OverviewMetricChip extends StatelessWidget {
  const _OverviewMetricChip({required this.metric});

  final _Metric metric;

  @override
  Widget build(BuildContext context) {
    final child = Container(
      height: 42,
      padding: const EdgeInsets.symmetric(horizontal: 7),
      decoration: BoxDecoration(
        color: metric.onTap == null
            ? Colors.transparent
            : _AA.greenSoft.withOpacity(.36),
        borderRadius: BorderRadius.circular(9),
      ),
      child: Row(children: [
        Container(
          width: 27,
          height: 27,
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(8),
          ),
          child: Icon(metric.icon, color: _AA.green, size: 13),
        ),
        const SizedBox(width: 6),
        Expanded(
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                metric.title,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: _AText.caption(size: 9.5),
              ),
              const SizedBox(height: 2),
              Text(
                metric.note.isEmpty
                    ? metric.value
                    : '${metric.value}  ${metric.note}',
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: _AText.body(11, color: _AA.text, weight: FontWeight.w600),
              ),
            ],
          ),
        ),
      ]),
    );
    return metric.onTap == null
        ? child
        : _NoHoverTap(
            onTap: metric.onTap,
            borderRadius: BorderRadius.circular(9),
            child: child,
          );
  }
}

class _OverviewTab extends StatefulWidget {
  const _OverviewTab({
    required this.compact,
    required this.teamName,
    required this.clubName,
    required this.bundle,
    required this.local,
    required this.selectedPlayer,
    required this.playerFilterLabel,
    required this.selectedField,
    required this.selectedSession,
    required this.heatmap,
    required this.usingLatestFallback,
    required this.fallbackMessage,
    required this.onOpenCalibration,
    required this.onOpenSessions,
    required this.onOpenInsight,
    this.personalMode = false,
  });

  final bool compact;
  final String teamName;
  final String clubName;
  final _AnalyticsBundle bundle;
  final _LocalTrackAnalysis local;
  final TrackerPlayerOption? selectedPlayer;
  final String playerFilterLabel;
  final TrackerFieldModel? selectedField;
  final TrackerSessionModel? selectedSession;
  final List<TrackerHeatPoint> heatmap;
  final bool usingLatestFallback;
  final String fallbackMessage;
  final VoidCallback onOpenCalibration;
  final VoidCallback onOpenSessions;
  final ValueChanged<_CoachInsight> onOpenInsight;
  final bool personalMode;

  @override
  State<_OverviewTab> createState() => _OverviewTabState();
}

class _OverviewTabState extends State<_OverviewTab> {
  bool _showInlineRankings = false;

  @override
  Widget build(BuildContext context) {
    final compact = widget.compact;
    final teamName = widget.teamName;
    final clubName = widget.clubName;
    final bundle = widget.bundle;
    final local = widget.local;
    final selectedPlayer = widget.selectedPlayer;
    final playerFilterLabel = widget.playerFilterLabel;
    final selectedField = widget.selectedField;
    final selectedSession = widget.selectedSession;
    final heatmap = widget.heatmap;
    final usingLatestFallback = widget.usingLatestFallback;
    final fallbackMessage = widget.fallbackMessage;
    final onOpenCalibration = widget.onOpenCalibration;
    final onOpenSessions = widget.onOpenSessions;
    final onOpenInsight = widget.onOpenInsight;
    final personalMode = widget.personalMode;
    var rows =
        _rowsForAnalytics(bundle, selectedSession, local, selectedPlayer);
    if (personalMode && selectedPlayer != null) {
      final ids = <int>{selectedPlayer!.id, ...selectedPlayer!.identityIds};
      final name = selectedPlayer!.name.trim().toLowerCase();
      rows = rows.where((row) {
        final id = row.playerId;
        if (id != null && id > 0 && ids.contains(id)) return true;
        return name.isNotEmpty && row.playerName.trim().toLowerCase() == name;
      }).toList(growable: false);
    }
    final total = _DayTotal.fromRows(rows,
        sessionsCount: _groupTrackerSessions(bundle.sessions).length,
        fallbackSession: selectedSession,
        local: local);
    _CoachInsight overviewInsight(String title, IconData icon,
        List<_CoachInsightMetric> metrics, List<String> bullets,
        {Color accent = _AA.green}) {
      return _CoachInsight(
        title: title,
        subtitle:
            '${selectedPlayer?.name ?? selectedSession?.playerName ?? 'Команда'} · ${total.sessionsCount} ${_trackerTrainingWord(total.sessionsCount)}',
        icon: icon,
        accent: accent,
        metrics: metrics,
        bullets: bullets,
        footer:
            'Карточки сверху теперь кликабельные: тренер нажимает на нужный показатель и сразу получает расшифровку справа без отдельного модального окна.',
      );
    }

    final cards = <_Metric>[
      _Metric(
          icon: Icons.route_rounded,
          title: 'Объём дня',
          value: _meters(total.distanceM),
          note:
              '${total.sessionsCount} ${_trackerTrainingWord(total.sessionsCount)}',
          onTap: () => onOpenInsight(
                  overviewInsight('Объём работы', Icons.route_rounded, [
                _CoachInsightMetric(
                    'Дистанция', _meters(total.distanceM), 'за период'),
                _CoachInsightMetric(
                    'Тренировки', '${total.sessionsCount}', 'выбрано'),
                _CoachInsightMetric(
                    'Игроки', '${total.playersCount}', 'с данными'),
                _CoachInsightMetric(
                    'м/мин',
                    total.sessionsCount <= 0
                        ? '—'
                        : (total.distanceM / math.max(1, total.sessionsCount))
                            .toStringAsFixed(0),
                    'на тренировку'),
              ], [
                'Смотрите, кто дал основной объём, а кто выпал по дистанции.',
                'Если выбран период, рейтинг ниже агрегирует игроков по всем тренировкам.',
                'Для детских команд объём важнее оценивать вместе со скоростными зонами, а не отдельно.'
              ]))),
      _Metric(
          icon: Icons.groups_rounded,
          title: 'Игроков',
          value: '${total.playersCount}',
          note: 'с данными',
          onTap: () => onOpenInsight(
                  overviewInsight('Игроки с данными', Icons.groups_rounded, [
                _CoachInsightMetric(
                    'Игроки', '${total.playersCount}', 'активные'),
                _CoachInsightMetric(
                    'Тренировки', '${total.sessionsCount}', 'в фильтре'),
                _CoachInsightMetric(
                    'Фокус', selectedPlayer?.name ?? 'команда', 'выбор'),
                _CoachInsightMetric(
                    'Поле', selectedField?.title ?? '—', 'калибровка'),
              ], [
                'Если игроков меньше состава, проверьте выбранную дату, сессии и привязку устройств.',
                'По клику на игрока в командной таблице можно открыть персональный фокус.',
                'Пульсометрные данные также добавляются в общую картину нагрузки.'
              ]))),
      _Metric(
          icon: Icons.speed_rounded,
          title: 'Макс. скорость',
          value: '${total.maxSpeedKmh.toStringAsFixed(1)}',
          note: 'км/ч',
          onTap: () => onOpenInsight(overviewInsight(
              'Максимальная скорость',
              Icons.speed_rounded,
              [
                _CoachInsightMetric(
                    'Пик', '${total.maxSpeedKmh.toStringAsFixed(1)}', 'км/ч'),
                _CoachInsightMetric('SPR', '${local.sprintCount}', 'локально'),
                _CoachInsightMetric(
                    'HIR/VHIR', _meters(total.hirDistanceM), 'интенсивность'),
                _CoachInsightMetric(
                    'Игроки', '${total.playersCount}', 'сравнение'),
              ],
              [
                'Пик нужно смотреть вместе с графиком скорости: одиночный выброс GPS не должен ломать вывод.',
                'Вкладка «Скорость» показывает линию по времени и пороги HIR/SPR.',
                'Для U-команд пороги берутся из возрастного профиля команды.'
              ],
              accent: _AA.blue))),
      _Metric(
          icon: Icons.flash_on_rounded,
          title: 'Спринты',
          value: '${total.sprintCount}',
          note: _meters(total.sprintDistanceM),
          onTap: () => onOpenInsight(overviewInsight(
              'Спринты',
              Icons.flash_on_rounded,
              [
                _CoachInsightMetric(
                    'Спринты', '${total.sprintCount}', 'кол-во'),
                _CoachInsightMetric('SPR дистанция',
                    _meters(total.sprintDistanceM), 'суммарно'),
                _CoachInsightMetric(
                    'HIR/VHIR', _meters(total.hirDistanceM), 'подводка'),
                _CoachInsightMetric(
                    'Пик', '${total.maxSpeedKmh.toStringAsFixed(1)}', 'км/ч'),
              ],
              [
                'На карте включите фильтр «Спринт» — красным останутся участки выше порога.',
                'График масштабируется по устойчивым точкам, чтобы скорость около порога не выглядела слишком низко.',
                'Лидеры спринтов открываются справа по клику на игрока.'
              ],
              accent: _AA.red))),
      _Metric(
          icon: Icons.local_fire_department_rounded,
          title: 'HIR/VHIR',
          value: _meters(total.hirDistanceM),
          note: 'интенсивность',
          onTap: () => onOpenInsight(overviewInsight(
              'Высокая интенсивность',
              Icons.local_fire_department_rounded,
              [
                _CoachInsightMetric(
                    'HIR/VHIR', _meters(total.hirDistanceM), 'метры'),
                _CoachInsightMetric(
                    'Спринты', '${total.sprintCount}', 'выше SPR'),
                _CoachInsightMetric(
                    'SPR dist.', _meters(total.sprintDistanceM), 'метры'),
                _CoachInsightMetric(
                    'Пик', '${total.maxSpeedKmh.toStringAsFixed(1)}', 'км/ч'),
              ],
              [
                'HIR показывает подготовительную высокую интенсивность до чистого спринта.',
                'Если HIR много, а спринтов мало — команда работала интенсивно, но без максимальных рывков.',
                'Сравнивайте с пульсом, чтобы увидеть цену этой работы.'
              ],
              accent: _AA.orange))),
      _Metric(
          icon: Icons.compare_arrows_rounded,
          title: 'Уск./торм.',
          value: '${total.accelCount}/${total.decelCount}',
          note: 'механика',
          onTap: () => onOpenInsight(overviewInsight(
              'Локомоторная механика',
              Icons.compare_arrows_rounded,
              [
                _CoachInsightMetric(
                    'Ускорения', '${total.accelCount}', 'кол-во'),
                _CoachInsightMetric(
                    'Торможения', '${total.decelCount}', 'кол-во'),
                _CoachInsightMetric('Баланс',
                    '${total.accelCount - total.decelCount}', 'разница'),
                _CoachInsightMetric(
                    'Нагрузка', total.loadScore.toStringAsFixed(0), 'вклад'),
              ],
              [
                'Частые торможения повышают нагрузку даже при небольшой дистанции.',
                'Для тренера это подсказка по манёвренности, сменам направления и усталости.',
                'Смотрите вместе с картой: где именно игроки разгонялись и тормозили.'
              ],
              accent: _AA.blue))),
      _Metric(
          icon: Icons.bolt_rounded,
          title: 'Нагрузка',
          value: total.loadScore.toStringAsFixed(0),
          note: 'суммарная',
          onTap: () => onOpenInsight(overviewInsight(
              'Нагрузка команды',
              Icons.bolt_rounded,
              [
                _CoachInsightMetric(
                    'Нагрузка', total.loadScore.toStringAsFixed(0), 'сумма'),
                _CoachInsightMetric(
                    'Дистанция', _meters(total.distanceM), 'объём'),
                _CoachInsightMetric(
                    'HIR/VHIR', _meters(total.hirDistanceM), 'интенсивность'),
                _CoachInsightMetric('Уск/торм',
                    '${total.accelCount}/${total.decelCount}', 'механика'),
              ],
              [
                'Нагрузка собирается из объёма, интенсивности, спринтов и механики.',
                'Если подключён пульсометр, вкладка «Пульс» помогает понять внутреннюю нагрузку.',
                'Рейтинг нагрузки показывает, кого стоит разгрузить или проверить после тренировки.'
              ],
              accent: _AA.orange))),
    ];

    void openDayRankings() {
      if (MediaQuery.sizeOf(context).width < 720) {
        showGeneralDialog<void>(
          context: context,
          barrierDismissible: true,
          barrierLabel: 'Рейтинг дня',
          barrierColor: Colors.black.withOpacity(.10),
          transitionDuration: const Duration(milliseconds: 220),
          pageBuilder: (dialogContext, _, __) => Align(
            alignment: Alignment.centerRight,
            child: SafeArea(
              child: Material(
                color: Colors.transparent,
                child: ConstrainedBox(
                  constraints: const BoxConstraints(maxWidth: 390),
                  child: Container(
                    width: math.min(390.0, MediaQuery.sizeOf(context).width * .86),
                    height: double.infinity,
                    margin: const EdgeInsets.fromLTRB(0, 8, 8, 8),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(18),
                      boxShadow: const [
                        BoxShadow(
                          color: Color(0x1A0B0F14),
                          blurRadius: 28,
                          offset: Offset(-8, 8),
                        ),
                      ],
                    ),
                    child: _DayRankingDrawer(
                      rows: rows,
                      onClose: () => Navigator.of(dialogContext).pop(),
                    ),
                  ),
                ),
              ),
            ),
          ),
          transitionBuilder: (_, animation, __, child) => SlideTransition(
            position: Tween<Offset>(
              begin: const Offset(1.0, 0),
              end: Offset.zero,
            ).animate(CurvedAnimation(parent: animation, curve: Curves.easeOutCubic)),
            child: FadeTransition(opacity: animation, child: child),
          ),
        );
        return;
      }
      setState(() => _showInlineRankings = !_showInlineRankings);
    }

    final phone = MediaQuery.sizeOf(context).width < 720;
    if (phone) {
      return _MobileOverviewDashboard(
        teamName: teamName,
        clubName: clubName,
        total: total,
        cards: cards,
        rows: rows,
        selectedPlayer: selectedPlayer,
        selectedField: selectedField,
        selectedSession: selectedSession,
        local: local,
        heatmap: heatmap,
        usingLatestFallback: usingLatestFallback,
        fallbackMessage: fallbackMessage,
        onOpenSessions: onOpenSessions,
        personalMode: personalMode,
      );
    }

    final showInlineRankings = _showInlineRankings && rows.isNotEmpty;
    Widget rankingPanel() => Container(
          clipBehavior: Clip.antiAlias,
          decoration: BoxDecoration(
            color: const Color(0xFFF8FAF9),
            borderRadius: BorderRadius.circular(14),
          ),
          child: _DayRankingDrawer(
            rows: rows,
            onClose: () => setState(() => _showInlineRankings = false),
          ),
        );

    return Column(children: [
      if (usingLatestFallback) _InlineNotice(text: fallbackMessage),
      _OverviewMetricsStrip(compact: compact, cards: cards),
      Expanded(
        child: Padding(
          padding: const EdgeInsets.fromLTRB(7, 7, 7, 7),
          child: LayoutBuilder(
            builder: (context, c) {
              // Desktop/tablet: два основных блока всегда стоят рядом.
              // На телефон (<720 px) сюда код не попадает: выше используется
              // отдельный _MobileOverviewDashboard.
              final rankingWidth = showInlineRankings
                  ? math.min(350.0, math.max(280.0, c.maxWidth * .25))
                  : 0.0;
              return Row(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Expanded(
                    flex: 1,
                    child: _PlayerActivityProfilePanel(
                      selectedPlayer: selectedPlayer,
                      selectedSession: selectedSession,
                      local: local,
                      heatmap: heatmap,
                      rows: rows,
                      title: 'Радар выбранной сессии',
                    ),
                  ),
                  const SizedBox(width: 7),
                  Expanded(
                    flex: 1,
                    child: _DaySummaryPanel(
                      total: total,
                      selectedField: selectedField,
                      selectedPlayer: selectedPlayer,
                      selectedSession: selectedSession,
                      local: local,
                      rows: rows,
                      onOpenSessions: onOpenSessions,
                      onOpenRankings: openDayRankings,
                      rankingsOpen: showInlineRankings,
                    ),
                  ),
                  if (showInlineRankings) ...[
                    const SizedBox(width: 7),
                    SizedBox(
                      width: rankingWidth,
                      child: rankingPanel(),
                    ),
                  ],
                ],
              );
            },
          ),
        ),
      ),
    ]);
  }
}

class _MobileOverviewDashboard extends StatelessWidget {
  const _MobileOverviewDashboard({
    required this.teamName,
    required this.clubName,
    required this.total,
    required this.cards,
    required this.rows,
    required this.selectedPlayer,
    required this.selectedField,
    required this.selectedSession,
    required this.local,
    required this.heatmap,
    required this.usingLatestFallback,
    required this.fallbackMessage,
    required this.onOpenSessions,
    this.personalMode = false,
  });

  final String teamName;
  final String clubName;
  final _DayTotal total;
  final List<_Metric> cards;
  final List<TrackerPlayerLoadRow> rows;
  final TrackerPlayerOption? selectedPlayer;
  final TrackerFieldModel? selectedField;
  final TrackerSessionModel? selectedSession;
  final _LocalTrackAnalysis local;
  final List<TrackerHeatPoint> heatmap;
  final bool usingLatestFallback;
  final String fallbackMessage;
  final VoidCallback onOpenSessions;
  final bool personalMode;

  @override
  Widget build(BuildContext context) {
    final width = MediaQuery.sizeOf(context).width;
    // KPI в мобильной аналитике используют ту же responsive-сетку,
    // что и карточки «Показатели Live» в личной тренировке.
    final kpiColumns = width >= 520 ? 3 : 2;
    final visibleKpis = personalMode
        ? cards.where((metric) => metric.title != 'Игроков').take(6).toList(growable: false)
        : cards.take(6).toList(growable: false);
    final leaderRows = _mobileLeaderRows(rows);
    final content = <Widget>[
      if (usingLatestFallback) _MobileNoticeCard(text: fallbackMessage),
      GridView.count(
        shrinkWrap: true,
        physics: const NeverScrollableScrollPhysics(),
        crossAxisCount: kpiColumns,
        mainAxisSpacing: 7,
        crossAxisSpacing: 7,
        childAspectRatio: kpiColumns == 3 ? 2.48 : 2.72,
        children: [
          for (final metric in visibleKpis) _MobileKpiCard(metric: metric)
        ],
      ),
      if (personalMode) ...[
        const SizedBox(height: 8),
        _MobileCardShell(
          padding: const EdgeInsets.all(9),
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              const Text(
                'Все показатели сессии',
                style: TextStyle(
                  color: _AA.text,
                  fontSize: 12.4,
                  fontWeight: FontWeight.w800,
                ),
              ),
              const SizedBox(height: 7),
              Row(
                children: [
                  Expanded(
                    child: _MobileTinyStat(
                      title: 'Время',
                      value: _trackerSensorDuration(
                        local.durationSec,
                        selectedSession?.durationSec ?? 0,
                      ),
                      note: 'активность',
                    ),
                  ),
                  const SizedBox(width: 6),
                  Expanded(
                    child: _MobileTinyStat(
                      title: 'Средняя',
                      value: '${local.avgSpeedKmh.toStringAsFixed(1)} км/ч',
                      note: 'скорость',
                    ),
                  ),
                  const SizedBox(width: 6),
                  Expanded(
                    child: _MobileTinyStat(
                      title: 'SPR dist.',
                      value: _meters(local.sprintDistanceM),
                      note: 'спринт',
                    ),
                  ),
                ],
              ),
              const SizedBox(height: 6),
              Row(
                children: [
                  Expanded(
                    child: _MobileTinyStat(
                      title: 'Ускорения',
                      value: '${local.accelCount}',
                      note: 'события',
                    ),
                  ),
                  const SizedBox(width: 6),
                  Expanded(
                    child: _MobileTinyStat(
                      title: 'Торможения',
                      value: '${local.decelCount}',
                      note: 'события',
                    ),
                  ),
                  const SizedBox(width: 6),
                  Expanded(
                    child: _MobileTinyStat(
                      title: 'GPS',
                      value: '${local.speedSamples.length}',
                      note: 'отрезков',
                    ),
                  ),
                ],
              ),
            ],
          ),
        ),
      ],
      const SizedBox(height: 8),
      if (personalMode)
        _MobileLastSessionCard(
          selectedSession: selectedSession,
          selectedField: selectedField,
          sessionsCount: total.sessionsCount,
          onOpenSessions: onOpenSessions,
        )
      else ...[
        _MobileTeamSummaryCard(
            total: total,
            selectedField: selectedField,
            selectedPlayer: selectedPlayer,
            selectedSession: selectedSession,
            local: local,
            rows: rows,
            onOpenSessions: onOpenSessions),
        const SizedBox(height: 8),
        _MobileLeadersCard(rows: leaderRows),
      ],
      const SizedBox(height: 8),
      _MobileRadarCard(
          selectedPlayer: selectedPlayer,
          selectedSession: selectedSession,
          local: local,
          rows: rows),
      if (!personalMode) ...[
        const SizedBox(height: 8),
        _MobileLastSessionCard(
            selectedSession: selectedSession,
            selectedField: selectedField,
            sessionsCount: total.sessionsCount,
            onOpenSessions: onOpenSessions),
      ],
    ];

    final bottomSafe = MediaQuery.paddingOf(context).bottom;
    return SingleChildScrollView(
      physics: const BouncingScrollPhysics(),
      padding: EdgeInsets.fromLTRB(
          8, 8, 8, (personalMode ? 76 : 132) + bottomSafe),
      child: Column(
          crossAxisAlignment: CrossAxisAlignment.stretch, children: content),
    );
  }

  List<TrackerPlayerLoadRow> _mobileLeaderRows(
      List<TrackerPlayerLoadRow> source) {
    if (source.isEmpty) return const <TrackerPlayerLoadRow>[];
    final map = <int, TrackerPlayerLoadRow>{};
    void put(int key, TrackerPlayerLoadRow? row) {
      if (row == null) return;
      map.putIfAbsent(key, () => row);
    }

    final bySpeed = [...source]
      ..sort((a, b) => b.maxSpeedKmh.compareTo(a.maxSpeedKmh));
    final bySprint = [...source]
      ..sort((a, b) => b.sprintCount.compareTo(a.sprintCount));
    final byLoad = [...source]
      ..sort((a, b) => b.loadScore.compareTo(a.loadScore));
    final byDistance = [...source]
      ..sort((a, b) => b.distanceM.compareTo(a.distanceM));
    put(bySpeed.isNotEmpty ? 1 : 0, bySpeed.isNotEmpty ? bySpeed.first : null);
    put(bySprint.isNotEmpty ? 2 : 0,
        bySprint.isNotEmpty ? bySprint.first : null);
    put(byLoad.isNotEmpty ? 3 : 0, byLoad.isNotEmpty ? byLoad.first : null);
    put(byDistance.isNotEmpty ? 4 : 0,
        byDistance.isNotEmpty ? byDistance.first : null);
    return map.values.take(4).toList(growable: false);
  }
}

