class _MobileTeamSummaryCard extends StatelessWidget {
  const _MobileTeamSummaryCard(
      {required this.total,
      required this.selectedField,
      required this.selectedPlayer,
      required this.selectedSession,
      required this.local,
      required this.rows,
      required this.onOpenSessions});
  final _DayTotal total;
  final TrackerFieldModel? selectedField;
  final TrackerPlayerOption? selectedPlayer;
  final TrackerSessionModel? selectedSession;
  final _LocalTrackAnalysis local;
  final List<TrackerPlayerLoadRow> rows;
  final VoidCallback onOpenSessions;

  @override
  Widget build(BuildContext context) {
    final rowDistance = rows.fold<double>(0, (sum, row) => sum + row.distanceM);
    final rowMaxSpeed = rows.fold<double>(
        0, (value, row) => math.max(value, row.maxSpeedKmh));
    final rowSprintCount =
        rows.fold<int>(0, (sum, row) => sum + row.sprintCount);
    final distance = local.distanceM > 0
        ? local.distanceM
        : ((selectedSession?.distanceM ?? 0) > 0
            ? selectedSession!.distanceM
            : (rowDistance > 0 ? rowDistance : total.distanceM));
    final maxSpeed = local.maxSpeedKmh > 0
        ? local.maxSpeedKmh
        : ((selectedSession?.maxSpeedKmh ?? 0) > 0
            ? selectedSession!.maxSpeedKmh
            : (rowMaxSpeed > 0 ? rowMaxSpeed : total.maxSpeedKmh));
    final sprintCount = local.sprintCount > 0
        ? local.sprintCount
        : ((selectedSession?.sprintCount ?? 0) > 0
            ? selectedSession!.sprintCount
            : (rowSprintCount > 0 ? rowSprintCount : total.sprintCount));
    final duration = _trackerSensorDuration(
        local.durationSec, selectedSession?.durationSec ?? 0);

    return _MobileCardShell(
      onTap: onOpenSessions,
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        const Row(children: [
          Expanded(
              child: Text('Сводка сессии',
                  style: TextStyle(
                      fontFamily: 'Inter',
                      color: _AA.text,
                      fontSize: 14,
                      fontWeight: FontWeight.w600))),
          _CmrDotCluster(count: 3, size: 3.4),
        ]),
        const SizedBox(height: 8),
        Wrap(
          spacing: 8,
          runSpacing: 8,
          children: [
            SizedBox(
              width: (MediaQuery.sizeOf(context).width - 40) / 2,
              child: _MobileSummaryStat(
                  icon: Icons.timer_outlined,
                  title: 'Длительность',
                  value: duration,
                  note: 'сессия'),
            ),
            SizedBox(
              width: (MediaQuery.sizeOf(context).width - 40) / 2,
              child: _MobileSummaryStat(
                  icon: Icons.route_rounded,
                  title: 'Дистанция',
                  value: _meters(distance),
                  note: 'сессия'),
            ),
            SizedBox(
              width: (MediaQuery.sizeOf(context).width - 40) / 2,
              child: _MobileSummaryStat(
                  icon: Icons.speed_rounded,
                  title: 'Макс. скорость',
                  value: maxSpeed.toStringAsFixed(1),
                  note: 'км/ч'),
            ),
            SizedBox(
              width: (MediaQuery.sizeOf(context).width - 40) / 2,
              child: _MobileSummaryStat(
                  icon: Icons.flash_on_rounded,
                  title: 'Спринты',
                  value: '$sprintCount',
                  note: 'сессия'),
            ),
          ],
        ),
        const SizedBox(height: 10),
        Text(
            '${selectedPlayer?.name ?? selectedSession?.playerName ?? 'Команда'} · ${selectedField?.title ?? 'поле не выбрано'}',
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: _AText.body(10.2, weight: FontWeight.w500)),
      ]),
    );
  }
}

