class _MobileLeadersCard extends StatelessWidget {
  const _MobileLeadersCard({required this.rows});
  final List<TrackerPlayerLoadRow> rows;

  @override
  Widget build(BuildContext context) {
    return _MobileCardShell(
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: const [
          Expanded(
              child: Text('Лидеры дня',
                  style: TextStyle(
                      color: _AA.text,
                      fontSize: 13.2,
                      fontWeight: FontWeight.w700))),
          Icon(Icons.chevron_right_rounded, color: _AA.text, size: 24),
        ]),
        const SizedBox(height: 8),
        if (rows.isEmpty)
          const _Empty(
              icon: Icons.leaderboard_rounded,
              text:
                  'После сохранения сессий здесь появятся лидеры по дистанции, скорости, спринтам и нагрузке.')
        else
          SizedBox(
            height: 116,
            child: ListView.separated(
              scrollDirection: Axis.horizontal,
              itemCount: rows.length,
              separatorBuilder: (_, __) => const SizedBox(width: 7),
              itemBuilder: (context, i) {
                final r = rows[i];
                final metric = i == 0
                    ? 'Макс. скорость'
                    : (i == 1
                        ? 'Спринты'
                        : (i == 2 ? 'Нагрузка' : 'Дистанция'));
                final value = i == 0
                    ? '${r.maxSpeedKmh.toStringAsFixed(1)} км/ч'
                    : (i == 1
                        ? '${r.sprintCount} шт.'
                        : (i == 2
                            ? r.loadScore.toStringAsFixed(0)
                            : _meters(r.distanceM)));
                return _MobileLeaderTile(row: r, metric: metric, value: value);
              },
            ),
          ),
      ]),
    );
  }
}

