class _MobileLeaderAvatar extends StatelessWidget {
  const _MobileLeaderAvatar({required this.row});
  final TrackerPlayerLoadRow row;

  @override
  Widget build(BuildContext context) {
    final avatar = row.avatar;
    final initials = row.playerName
        .trim()
        .split(RegExp(r'\s+'))
        .where((e) => e.isNotEmpty)
        .take(2)
        .map((e) => e.substring(0, 1))
        .join()
        .toUpperCase();
    return Container(
      width: 36,
      height: 36,
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(_AA.mobileCardRadius)),
      child: avatar != null && avatar.isNotEmpty
          ? Image.network(avatar,
              fit: BoxFit.cover,
              errorBuilder: (_, __, ___) => Center(
                  child: Text(initials.isEmpty ? 'И' : initials,
                      style: const TextStyle(
                          color: _AA.text,
                          fontSize: 12,
                          fontWeight: FontWeight.w700))))
          : Center(
              child: Text(initials.isEmpty ? 'И' : initials,
                  style: const TextStyle(
                      color: _AA.text,
                      fontSize: 12,
                      fontWeight: FontWeight.w700))),
    );
  }
}

