class _MobileMapDashboardState extends State<_MobileMapDashboard> {
  String _filter = 'all';

  @override
  Widget build(BuildContext context) {
    final local = _LocalTrackAnalysis.fromPoints(widget.localPoints,
        sprintThresholdKmh: widget.sprintThresholdKmh,
        hsrThresholdKmh: widget.hsrThresholdKmh);
    final heatPoints = widget.points.isNotEmpty
        ? widget.points
        : _heatmapFromGpsStatic(widget.localPoints, widget.field);
    final filteredSamples = _filter == 'all'
        ? local.speedSamples
        : _activitySpeedSamples(
            widget.localPoints, _filter, widget.sprintThresholdKmh,
            hsrThresholdKmh: widget.hsrThresholdKmh);
    final maxSpeed =
        filteredSamples.fold<double>(0.0, (a, b) => math.max(a, b).toDouble());
    final timeRange = _movementRecordingSpanLabel(
      widget.localPoints,
      fallbackDurationSec: widget.selectedSession?.durationSec ?? 0,
    );
    final activityLabel = _activityFilterLabel(_filter);
    final bottomSafe = MediaQuery.paddingOf(context).bottom;
    return SingleChildScrollView(
      physics: const BouncingScrollPhysics(),
      padding: EdgeInsets.fromLTRB(
          8, 8, 8, (widget.personalMode ? 76 : 132) + bottomSafe),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        _MobileCardShell(
          child:
              Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Row(children: [
              _MobileIconBox(
                  icon: widget.heatMode
                      ? Icons.local_fire_department_rounded
                      : Icons.timeline_rounded,
                  color: widget.heatMode ? _AA.orange : _AA.green),
              const SizedBox(width: 7),
              Expanded(
                  child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                    Text(
                        widget.heatMode ? 'Тепловая карта' : 'Карта активности',
                        style: const TextStyle(
                            color: _AA.text,
                            fontSize: 14,
                            fontWeight: FontWeight.w700)),
                    Text(
                        widget.localPoints.isEmpty
                            ? 'нет точек выбранной сессии'
                            : '${widget.localPoints.length} GPS · $activityLabel · $timeRange',
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: _AA.muted,
                            fontSize: 11.2,
                            fontWeight: FontWeight.w600)),
                  ])),
              _NoHoverTap(
                onTap: widget.personalMode
                    ? () => _openFullscreenMap(context, heatPoints)
                    : widget.onOpenCalibration,
                borderRadius: BorderRadius.circular(_AA.mobileInnerRadius),
                child: Container(
                    width: 34,
                    height: 34,
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                        color: _AA.card,
                        borderRadius:
                            BorderRadius.circular(_AA.mobileInnerRadius)),
                    child: const Icon(Icons.open_in_full_rounded,
                        color: _AA.text, size: 17)),
              ),
            ]),
            const SizedBox(height: 8),
            Row(children: [
              Expanded(
                  child: _MobileModeChip(
                      label: 'Активность',
                      icon: Icons.timeline_rounded,
                      active: !widget.heatMode,
                      onTap: () => widget.onHeatModeChanged(false))),
              const SizedBox(width: 8),
              Expanded(
                  child: _MobileModeChip(
                      label: 'Тепло',
                      icon: Icons.local_fire_department_rounded,
                      active: widget.heatMode,
                      onTap: () => widget.onHeatModeChanged(true))),
            ]),
            if (!widget.heatMode) ...[
              const SizedBox(height: 10),
              SizedBox(
                height: 34,
                child: ListView(scrollDirection: Axis.horizontal, children: [
                  _MobileFilterPill(
                      label: 'Все',
                      value: 'all',
                      current: _filter,
                      onTap: _setFilter),
                  _MobileFilterPill(
                      label: 'Ходьба',
                      value: 'walk',
                      current: _filter,
                      onTap: _setFilter),
                  _MobileFilterPill(
                      label: 'Бег',
                      value: 'run',
                      current: _filter,
                      onTap: _setFilter),
                  _MobileFilterPill(
                      label: 'Высокая',
                      value: 'hir',
                      current: _filter,
                      onTap: _setFilter),
                  _MobileFilterPill(
                      label: 'Спринт',
                      value: 'sprint',
                      current: _filter,
                      onTap: _setFilter),
                  _MobileFilterPill(
                      label: 'Ускорения',
                      value: 'accel',
                      current: _filter,
                      onTap: _setFilter),
                  _MobileFilterPill(
                      label: 'Торможения',
                      value: 'decel',
                      current: _filter,
                      onTap: _setFilter),
                  _MobileFilterPill(
                      label: 'Повороты',
                      value: 'turn',
                      current: _filter,
                      onTap: _setFilter),
                  _MobileFilterPill(
                      label: 'Остановки',
                      value: 'stop',
                      current: _filter,
                      onTap: _setFilter),
                ]),
              ),
            ],
            const SizedBox(height: 8),
            GestureDetector(
              onTap: widget.personalMode
                  ? () => _openFullscreenMap(context, heatPoints)
                  : null,
              child: ClipRRect(
                borderRadius: BorderRadius.circular(_AA.mobileCardRadius),
                child: AspectRatio(
                  aspectRatio: 1.72,
                  child: CustomPaint(
                    painter: _ActionPitchPainter(
                      heat: widget.heatMode
                          ? heatPoints
                          : const <TrackerHeatPoint>[],
                      local: widget.heatMode
                          ? const <ActionTrackerGpsPoint>[]
                          : widget.localPoints,
                      field: widget.field,
                      sprintThresholdKmh: widget.sprintThresholdKmh,
                      hsrThresholdKmh: widget.hsrThresholdKmh,
                      activityFilter: _filter,
                      showSprintArrows: widget.showSprintArrows,
                      mapRotationDeg: widget.mapRotationDeg,
                    ),
                    child: Center(
                        child: widget.localPoints.isEmpty && !widget.heatMode
                            ? const Text('Ждём GPS-точки',
                                style: TextStyle(
                                    color: Colors.white,
                                    fontSize: 15,
                                    fontWeight: FontWeight.w700))
                            : null),
                  ),
                ),
              ),
            ),
          ]),
        ),
        const SizedBox(height: 8),
        _MobileCardShell(
          child:
              Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            Row(children: [
              const _MobileIconBox(icon: Icons.speed_rounded, color: _AA.green),
              const SizedBox(width: 7),
              Expanded(
                  child: Text('Скорость по фильтру',
                      style: const TextStyle(
                          color: _AA.text,
                          fontSize: 14,
                          fontWeight: FontWeight.w700))),
              Text(
                  maxSpeed > 0
                      ? 'max ${maxSpeed.toStringAsFixed(1)}'
                      : 'нет скорости',
                  style: const TextStyle(
                      color: _AA.muted,
                      fontSize: 11.2,
                      fontWeight: FontWeight.w700)),
            ]),
            const SizedBox(height: 8),
            SizedBox(
                height: 210,
                child: CustomPaint(
                    painter: _SpeedPainter(
                        samples: filteredSamples,
                        hsrThresholdKmh: widget.hsrThresholdKmh,
                        sprintThresholdKmh: widget.sprintThresholdKmh,
                        maxSpeedKmh: maxSpeed),
                    child: const SizedBox.expand())),
            const SizedBox(height: 8),
            Row(children: [
              Expanded(
                  child: _MobileTinyStat(
                      title: 'Дистанция',
                      value: _meters(local.distanceM),
                      note: 'выбранный фильтр')),
              const SizedBox(width: 8),
              Expanded(
                  child: _MobileTinyStat(
                      title: 'GPS',
                      value: '${widget.localPoints.length}',
                      note: 'точек')),
              const SizedBox(width: 8),
              Expanded(
                  child: _MobileTinyStat(
                      title: 'Спринты',
                      value: '${local.sprintCount}',
                      note: 'рывки')),
            ]),
          ]),
        ),
      ]),
    );
  }

  void _openFullscreenMap(
      BuildContext sourceContext, List<TrackerHeatPoint> heatPoints) {
    showGeneralDialog<void>(
      context: sourceContext,
      barrierDismissible: true,
      barrierLabel: 'Закрыть карту',
      barrierColor: Colors.black.withOpacity(.72),
      pageBuilder: (dialogContext, _, __) {
        return Material(
          color: const Color(0xFFF6F7F6),
          child: SafeArea(
            child: Column(
              children: [
                Container(
                  height: 52,
                  padding: const EdgeInsets.symmetric(horizontal: 12),
                  color: Colors.white,
                  child: Row(
                    children: [
                      IconButton(
                        onPressed: () => Navigator.pop(dialogContext),
                        icon: const Icon(Icons.close_rounded, color: _AA.text),
                      ),
                      const SizedBox(width: 4),
                      Expanded(
                        child: Text(
                          widget.heatMode ? 'Тепловая карта' : 'Карта тренировки',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                            color: _AA.text,
                            fontSize: 15,
                            fontWeight: FontWeight.w800,
                          ),
                        ),
                      ),
                      Text(
                        widget.selectedSession == null
                            ? ''
                            : '#${widget.selectedSession!.id}',
                        style: const TextStyle(
                          color: _AA.muted,
                          fontSize: 11,
                          fontWeight: FontWeight.w700,
                        ),
                      ),
                    ],
                  ),
                ),
                Expanded(
                  child: Padding(
                    padding: const EdgeInsets.all(10),
                    child: Center(
                      child: AspectRatio(
                        aspectRatio: 1.72,
                        child: ClipRRect(
                          borderRadius: BorderRadius.circular(16),
                          child: CustomPaint(
                            painter: _ActionPitchPainter(
                              heat: widget.heatMode
                                  ? heatPoints
                                  : const <TrackerHeatPoint>[],
                              local: widget.heatMode
                                  ? const <ActionTrackerGpsPoint>[]
                                  : widget.localPoints,
                              field: widget.field,
                              sprintThresholdKmh: widget.sprintThresholdKmh,
                              hsrThresholdKmh: widget.hsrThresholdKmh,
                              activityFilter: _filter,
                              showSprintArrows: widget.showSprintArrows,
                              mapRotationDeg: widget.mapRotationDeg,
                            ),
                            child: const SizedBox.expand(),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }

  void _setFilter(String value) => setState(() => _filter = value);
}

class _MobileSpeedDashboard extends StatelessWidget {
  const _MobileSpeedDashboard(
      {required this.bundle,
      required this.local,
      required this.selectedSession,
      required this.hsrThresholdKmh,
      required this.sprintThresholdKmh,
      this.personalMode = false});
  final _AnalyticsBundle bundle;
  final _LocalTrackAnalysis local;
  final TrackerSessionModel? selectedSession;
  final double hsrThresholdKmh;
  final double sprintThresholdKmh;
  final bool personalMode;

  @override
  Widget build(BuildContext context) {
    final maxSpeed = local.maxSpeedKmh > 0
        ? local.maxSpeedKmh
        : (selectedSession?.maxSpeedKmh ?? 0);
    final avgSpeed = local.avgSpeedKmh > 0
        ? local.avgSpeedKmh
        : (selectedSession?.avgSpeedKmh ?? 0);
    final duration = local.durationSec > 0
        ? local.durationSec
        : (selectedSession?.durationSec ?? 0);
    final metersPerMin = selectedSession?.metersPerMinute ??
        (duration <= 0 ? 0 : local.distanceM / (duration / 60.0));
    final rows = [..._rowsForAnalytics(bundle, selectedSession, local, null)]
      ..sort((a, b) => b.maxSpeedKmh.compareTo(a.maxSpeedKmh));
    final bottomSafe = MediaQuery.paddingOf(context).bottom;
    return SingleChildScrollView(
      physics: const BouncingScrollPhysics(),
      padding: EdgeInsets.fromLTRB(
          8, 8, 8, (personalMode ? 76 : 132) + bottomSafe),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        GridView.count(
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          crossAxisCount: MediaQuery.sizeOf(context).width >= 520 ? 3 : 2,
          mainAxisSpacing: 7,
          crossAxisSpacing: 7,
          childAspectRatio:
              MediaQuery.sizeOf(context).width >= 520 ? 2.48 : 2.72,
          children: [
            _MobileSimpleKpi(
                icon: Icons.speed_rounded,
                title: 'Средняя',
                value: avgSpeed.toStringAsFixed(1),
                note: 'км/ч'),
            _MobileSimpleKpi(
                icon: Icons.trending_up_rounded,
                title: 'Максимум',
                value: maxSpeed.toStringAsFixed(1),
                note: 'км/ч'),
            _MobileSimpleKpi(
                icon: Icons.timer_rounded,
                title: 'Темп',
                value: metersPerMin.toStringAsFixed(1),
                note: 'м/мин'),
            _MobileSimpleKpi(
                icon: Icons.gps_fixed_rounded,
                title: 'Точек',
                value: '${local.speedSamples.length}',
                note: 'GPS скорость'),
          ],
        ),
        const SizedBox(height: 8),
        _MobileCardShell(
          child:
              Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('График скорости',
                style: TextStyle(
                    color: _AA.text,
                    fontSize: 14,
                    fontWeight: FontWeight.w700)),
            const SizedBox(height: 2),
            Text(
                'пороги HIR ${hsrThresholdKmh.toStringAsFixed(1)} / SPR ${sprintThresholdKmh.toStringAsFixed(1)} км/ч',
                style: const TextStyle(
                    color: _AA.muted,
                    fontSize: 11.2,
                    fontWeight: FontWeight.w600)),
            const SizedBox(height: 10),
            SizedBox(
                height: 280,
                child: CustomPaint(
                    painter: _SpeedPainter(
                        samples: local.speedSamples,
                        hsrThresholdKmh: hsrThresholdKmh,
                        sprintThresholdKmh: sprintThresholdKmh,
                        maxSpeedKmh: maxSpeed),
                    child: const SizedBox.expand())),
          ]),
        ),
        if (!personalMode) ...[
          const SizedBox(height: 8),
          _MobileCardShell(
              child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
            const Text('Лидеры скорости',
                style: TextStyle(color: _AA.text, fontSize: 14, fontWeight: FontWeight.w700)),
            const SizedBox(height: 10),
            if (rows.isEmpty)
              const _Empty(icon: Icons.speed_rounded, text: 'После сохранения сессии появятся игроки с максимальной скоростью.')
            else
              for (final r in rows.take(6))
                _MobilePlayerRow(row: r, metric: 'Макс. скорость', value: '${r.maxSpeedKmh.toStringAsFixed(1)} км/ч'),
          ])),
        ],
      ]),
    );
  }
}

class _MobileHeartDashboard extends StatelessWidget {
  const _MobileHeartDashboard(
      {required this.heartRate,
      required this.selectedPlayer,
      required this.scopeLabel,
      this.personalMode = false});
  final _AnalyticsHeartRate heartRate;
  final TrackerPlayerOption? selectedPlayer;
  final String scopeLabel;
  final bool personalMode;

  @override
  Widget build(BuildContext context) {
    if (heartRate.effectiveSamplesCount <= 0 &&
        heartRate.timelineForChart.isEmpty &&
        heartRate.players.isEmpty) {
      return Padding(
        padding: const EdgeInsets.fromLTRB(8, 8, 8, 8),
        child: Column(children: [
          _MobileCardShell(
            child: Row(children: [
              const Icon(Icons.event_available_rounded,
                  color: _AA.green, size: 18),
              const SizedBox(width: 8),
              Expanded(
                  child: Text(scopeLabel,
                      style: const TextStyle(
                          color: _AA.text,
                          fontSize: 12,
                          fontWeight: FontWeight.w700))),
            ]),
          ),
          const SizedBox(height: 8),
          const _MobileCardShell(
              child: _Empty(
                  icon: Icons.favorite_border_rounded,
                  text:
                      'По выбранной тренировке нет данных Polar H10. Проверьте привязку датчика и время сессии.')),
        ]),
      );
    }
    final bottomSafe = MediaQuery.paddingOf(context).bottom;
    return SingleChildScrollView(
      physics: const BouncingScrollPhysics(),
      padding: EdgeInsets.fromLTRB(
          8, 8, 8, (personalMode ? 76 : 132) + bottomSafe),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        _MobileCardShell(
          child: Row(children: [
            const Icon(Icons.event_available_rounded,
                color: _AA.green, size: 18),
            const SizedBox(width: 8),
            Expanded(
                child: Text(scopeLabel,
                    maxLines: 2,
                    overflow: TextOverflow.ellipsis,
                    style: const TextStyle(
                        color: _AA.text,
                        fontSize: 12,
                        fontWeight: FontWeight.w700,
                        height: 1.25))),
          ]),
        ),
        const SizedBox(height: 8),
        SizedBox(
          height: 52,
          child: ListView(scrollDirection: Axis.horizontal, children: [
            if (personalMode)
              _MobileHrChip(
                  label: selectedPlayer?.name ?? 'Мой пульс',
                  note: '${heartRate.effectiveSamplesCount} HR',
                  active: true)
            else ...[
              _MobileHrChip(
                  label: 'Все',
                  note: '${heartRate.effectiveSamplesCount} HR',
                  active: true),
              for (final p in heartRate.players.take(8))
                _MobileHrChip(
                    label: p.playerName,
                    note: '${p.avgBpm.toStringAsFixed(0)} bpm · ${p.samplesCount}',
                    active: false),
            ],
          ]),
        ),
        const SizedBox(height: 10),
        GridView.count(
          shrinkWrap: true,
          physics: const NeverScrollableScrollPhysics(),
          crossAxisCount: MediaQuery.sizeOf(context).width >= 520 ? 3 : 2,
          mainAxisSpacing: 7,
          crossAxisSpacing: 7,
          childAspectRatio:
              MediaQuery.sizeOf(context).width >= 520 ? 2.48 : 2.72,
          children: [
            _MobileSimpleKpi(
                icon: Icons.favorite_rounded,
                title: 'Средний',
                value: heartRate.effectiveAvgBpm > 0
                    ? heartRate.effectiveAvgBpm.toStringAsFixed(0)
                    : '—',
                note: 'bpm'),
            _MobileSimpleKpi(
                icon: Icons.local_fire_department_rounded,
                title: 'Максимум',
                value: heartRate.effectiveMaxBpm > 0
                    ? '${heartRate.effectiveMaxBpm}'
                    : '—',
                note: 'bpm'),
            _MobileSimpleKpi(
                icon: Icons.monitor_heart_rounded,
                title: 'HR-записи',
                value: '${heartRate.effectiveSamplesCount}',
                note: 'точек'),
            _MobileSimpleKpi(
                icon: personalMode ? Icons.person_rounded : Icons.groups_rounded,
                title: personalMode ? 'Профиль' : 'Игроки',
                value: personalMode ? '1' : '${heartRate.effectivePlayersCount}',
                note: personalMode ? 'личный' : 'Polar'),
          ],
        ),
        const SizedBox(height: 8),
        _MobileCardShell(
            child:
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          const Text('Пульс по времени',
              style: TextStyle(
                  color: _AA.text, fontSize: 14, fontWeight: FontWeight.w700)),
          const SizedBox(height: 2),
          Text(personalMode ? 'личная линия Polar H10' : 'командные линии Polar H10',
              style: TextStyle(
                  color: _AA.muted,
                  fontSize: 11.2,
                  fontWeight: FontWeight.w600)),
          const SizedBox(height: 10),
          SizedBox(
              height: 500, child: _AnalyticsHrLineChart(heartRate: heartRate)),
