        const SizedBox(height: 8),
        _MobileCardShell(
            child:
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          const Text('Зоны ЧСС',
              style: TextStyle(
                  color: _AA.text, fontSize: 14, fontWeight: FontWeight.w700)),
          const SizedBox(height: 10),
          SizedBox(
              height: 180, child: _AnalyticsHrZonesPanel(heartRate: heartRate)),
        ])),
      ]),
    );
  }
}

class _MobileTeamDashboard extends StatelessWidget {
  const _MobileTeamDashboard(
      {required this.bundle,
      required this.selectedSession,
      required this.local,
      required this.players,
      required this.selectedPlayer,
      required this.onSelectPlayer});
  final _AnalyticsBundle bundle;
  final TrackerSessionModel? selectedSession;
  final _LocalTrackAnalysis local;
  final List<TrackerPlayerOption> players;
  final TrackerPlayerOption? selectedPlayer;
  final ValueChanged<int> onSelectPlayer;

  @override
  Widget build(BuildContext context) {
    final rows =
        _rowsForAnalytics(bundle, selectedSession, local, selectedPlayer);
    final total = _DayTotal.fromRows(rows,
        sessionsCount: _groupTrackerSessions(bundle.sessions).length,
        fallbackSession: selectedSession,
        local: local);
    final bottomSafe = MediaQuery.paddingOf(context).bottom;
    return SingleChildScrollView(
      physics: const BouncingScrollPhysics(),
      padding: EdgeInsets.fromLTRB(8, 8, 8, 132 + bottomSafe),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        _MobileTeamSummaryCard(
            total: total,
            selectedField: null,
            selectedPlayer: selectedPlayer,
            selectedSession: selectedSession,
            local: local,
            rows: rows,
            onOpenSessions: () {}),
        const SizedBox(height: 8),
        _MobileCardShell(
            child:
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
          const Text('Игроки команды',
              style: TextStyle(
                  color: _AA.text, fontSize: 14, fontWeight: FontWeight.w700)),
          const SizedBox(height: 10),
          if (rows.isEmpty)
            const _Empty(
                icon: Icons.groups_rounded,
                text: 'По выбранному периоду нет игроков с данными.')
          else
            for (final r in rows.take(12))
              _NoHoverTap(
                  onTap: r.playerId == null
                      ? null
                      : () => onSelectPlayer(r.playerId!),
                  child: _MobilePlayerRow(
                      row: r,
                      metric:
                          'дистанция ${_dashIfZero(r.distanceM, suffix: ' м')}',
                      value: 'Нагрузка ${r.loadScore.toStringAsFixed(0)}')),
        ])),
      ]),
    );
  }
}

class _MobileRatingsDashboard extends StatelessWidget {
  const _MobileRatingsDashboard(
      {required this.bundle,
      required this.local,
      required this.teamName,
      required this.selectedPlayer,
      required this.selectedSession});
  final _AnalyticsBundle bundle;
  final _LocalTrackAnalysis local;
  final String teamName;
  final TrackerPlayerOption? selectedPlayer;
  final TrackerSessionModel? selectedSession;

  @override
  Widget build(BuildContext context) {
    final rows =
        _rowsForAnalytics(bundle, selectedSession, local, selectedPlayer);
    final bySpeed = [...rows]
      ..sort((a, b) => b.maxSpeedKmh.compareTo(a.maxSpeedKmh));
    final byLoad = [...rows]
      ..sort((a, b) => b.loadScore.compareTo(a.loadScore));
    final byDistance = [...rows]
      ..sort((a, b) => b.distanceM.compareTo(a.distanceM));
    final bottomSafe = MediaQuery.paddingOf(context).bottom;
    return SingleChildScrollView(
      physics: const BouncingScrollPhysics(),
      padding: EdgeInsets.fromLTRB(8, 8, 8, 132 + bottomSafe),
      child: Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
        _MobileRatingBlock(
          title: 'Скорость',
          icon: Icons.speed_rounded,
          rows: bySpeed,
          valueBuilder: (r) => '${r.maxSpeedKmh.toStringAsFixed(1)} км/ч',
          numericBuilder: (r) => r.maxSpeedKmh,
          detailNote: 'максимальная скорость по выбранным сессиям',
        ),
        const SizedBox(height: 8),
        _MobileRatingBlock(
          title: 'Нагрузка',
          icon: Icons.bolt_rounded,
          rows: byLoad,
          valueBuilder: (r) => r.loadScore.toStringAsFixed(0),
          numericBuilder: (r) => r.loadScore,
          detailNote: 'суммарная нагрузка игроков',
        ),
        const SizedBox(height: 8),
        _MobileRatingBlock(
          title: 'Дистанция',
          icon: Icons.route_rounded,
          rows: byDistance,
          valueBuilder: (r) => _meters(r.distanceM),
          numericBuilder: (r) => r.distanceM,
          detailNote: 'общий объём перемещений',
        ),
      ]),
    );
  }
}

class _MobileRatingBlock extends StatelessWidget {
  const _MobileRatingBlock({
    required this.title,
    required this.icon,
    required this.rows,
    required this.valueBuilder,
    required this.numericBuilder,
    required this.detailNote,
  });

  final String title;
  final IconData icon;
  final List<TrackerPlayerLoadRow> rows;
  final String Function(TrackerPlayerLoadRow row) valueBuilder;
  final double Function(TrackerPlayerLoadRow row) numericBuilder;
  final String detailNote;

  void _openDetails(BuildContext context) {
    if (rows.isEmpty) return;
    showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Colors.transparent,
      builder: (sheetContext) => _MobileRatingDetailSheet(
        title: title,
        icon: icon,
        rows: rows,
        valueBuilder: valueBuilder,
        numericBuilder: numericBuilder,
        detailNote: detailNote,
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    return _MobileCardShell(
      onTap: rows.isEmpty ? null : () => _openDetails(context),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        Row(children: [
          _MobileIconBox(icon: icon),
          const SizedBox(width: 6),
          Expanded(
              child: Text(title,
                  style: const TextStyle(
                      color: _AA.text,
                      fontSize: 14,
                      fontWeight: FontWeight.w700))),
          if (rows.isNotEmpty)
            const Icon(Icons.chevron_right_rounded, color: _AA.text, size: 22),
        ]),
        const SizedBox(height: 10),
        if (rows.isEmpty)
          const _Empty(
              icon: Icons.leaderboard_rounded,
              text: 'После сохранения сессии здесь появятся лидеры.')
        else
          for (final r in rows.take(5))
            _MobilePlayerRow(row: r, metric: title, value: valueBuilder(r)),
      ]),
    );
  }
}

class _MobileRatingDetailSheet extends StatelessWidget {
  const _MobileRatingDetailSheet({
    required this.title,
    required this.icon,
    required this.rows,
    required this.valueBuilder,
    required this.numericBuilder,
    required this.detailNote,
  });

  final String title;
  final IconData icon;
  final List<TrackerPlayerLoadRow> rows;
  final String Function(TrackerPlayerLoadRow row) valueBuilder;
  final double Function(TrackerPlayerLoadRow row) numericBuilder;
  final String detailNote;

  @override
  Widget build(BuildContext context) {
    final height = MediaQuery.sizeOf(context).height;
    final visibleRows = rows
        .where((r) => numericBuilder(r) > 0)
        .take(12)
        .toList(growable: false);
    final sourceRows = visibleRows.isNotEmpty
        ? visibleRows
        : rows.take(12).toList(growable: false);
    final maxValue =
        sourceRows.fold<double>(0, (m, r) => math.max(m, numericBuilder(r)));
    return SafeArea(
      top: false,
      child: Align(
        alignment: Alignment.bottomCenter,
        child: Container(
          constraints: BoxConstraints(maxHeight: math.min(height * .82, 680)),
          decoration: const BoxDecoration(
            color: _AA.bg,
            borderRadius:
                BorderRadius.vertical(top: Radius.circular(_AA.sheetRadius)),
          ),
          child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.stretch,
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 12, 12, 10),
                  child: Row(children: [
                    _MobileIconBox(icon: icon),
                    const SizedBox(width: 7),
                    Expanded(
                        child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                          Text(title,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: _AA.text,
                                  fontSize: 16,
                                  fontWeight: FontWeight.w700)),
                          const SizedBox(height: 2),
                          Text(detailNote,
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: _AA.muted,
                                  fontSize: 11,
                                  fontWeight: FontWeight.w600)),
                        ])),
                    _NoHoverTap(
                      onTap: () => Navigator.pop(context),
                      borderRadius:
                          BorderRadius.circular(_AA.mobileInnerRadius),
                      child: Container(
                        width: 42,
                        height: 42,
                        alignment: Alignment.center,
                        decoration: BoxDecoration(
                            color: _AA.card,
                            borderRadius:
                                BorderRadius.circular(_AA.mobileInnerRadius)),
                        child: const Icon(Icons.close_rounded,
                            color: _AA.text, size: 22),
                      ),
                    ),
                  ]),
                ),
                Flexible(
                  child: ListView(
                    padding: const EdgeInsets.fromLTRB(12, 0, 12, 12),
                    children: [
                      _MobileCardShell(
                        child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              const Text('График лидеров',
                                  style: TextStyle(
                                      color: _AA.text,
                                      fontSize: 13,
                                      fontWeight: FontWeight.w700)),
                              const SizedBox(height: 10),
                              if (sourceRows.isEmpty)
                                const _Empty(
                                    icon: Icons.leaderboard_rounded,
                                    text: 'Нет данных для графика.')
                              else
                                for (final r in sourceRows) ...[
                                  _MobileRatingBarRow(
                                    row: r,
                                    valueText: valueBuilder(r),
                                    value: numericBuilder(r),
                                    maxValue: maxValue,
                                  ),
                                  if (r != sourceRows.last)
                                    const SizedBox(height: 10),
                                ],
                            ]),
                      ),
                      const SizedBox(height: 8),
                      _MobileCardShell(
                        child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              const Text('Список игроков',
                                  style: TextStyle(
                                      color: _AA.text,
                                      fontSize: 13,
                                      fontWeight: FontWeight.w700)),
                              const SizedBox(height: 8),
                              if (rows.isEmpty)
                                const _Empty(
                                    icon: Icons.groups_rounded,
                                    text: 'Нет игроков с данными.')
                              else
                                for (final r in rows.take(20))
                                  _MobilePlayerRow(
                                      row: r,
                                      metric: title,
                                      value: valueBuilder(r)),
                            ]),
                      ),
                    ],
                  ),
                ),
              ]),
        ),
      ),
    );
  }
}

class _MobileRatingBarRow extends StatelessWidget {
  const _MobileRatingBarRow(
      {required this.row,
      required this.valueText,
      required this.value,
      required this.maxValue});

  final TrackerPlayerLoadRow row;
  final String valueText;
  final double value;
  final double maxValue;

  @override
  Widget build(BuildContext context) {
    final ratio =
        maxValue <= 0 ? 0.0 : (value / maxValue).clamp(0.0, 1.0).toDouble();
    return Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
      Row(children: [
        _MobileLeaderAvatar(row: row),
        const SizedBox(width: 7),
        Expanded(
            child: Text(_leaderShortName(row.playerName),
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: const TextStyle(
                    color: _AA.text,
                    fontSize: 11.6,
                    fontWeight: FontWeight.w700))),
        Text(valueText,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
                color: _AA.green, fontSize: 11.8, fontWeight: FontWeight.w700)),
      ]),
      const SizedBox(height: 7),
      ClipRRect(
        borderRadius: BorderRadius.circular(999),
        child: Container(
          height: 8,
          color: _AA.line.withOpacity(.72),
          alignment: Alignment.centerLeft,
          child: FractionallySizedBox(
            widthFactor: ratio <= 0 ? 0.02 : math.max(.06, ratio),
            child: Container(
                decoration: BoxDecoration(
                    color: _AA.green,
                    borderRadius: BorderRadius.circular(999))),
          ),
        ),
      ),
    ]);
  }
}

