class _MapTabState extends State<_MapTab> {
  String _activityFilter = 'all';
  String _detailPanelMode = 'chart';
  _MapPointInfo? _selectedPoint;
  RangeValues _range = const RangeValues(0, 1);
  double _cursor = 0;
  bool _compareMode = false;
  bool _personalGhostEnabled = false;
  Timer? _playTimer;
  bool _playing = false;
  double _playbackRate = 1.0;
  bool _autoExpandedScheduled = false;
  TrackerGeoBaseLayer _geoBaseLayer = TrackerGeoBaseLayer.pitch;

  @override
  void initState() {
    super.initState();
    if (widget.initialCursorTimeMs > 0 && _playerPoints.isNotEmpty) {
      _cursor = _movementProgressForTime(
        _playerPoints,
        widget.initialCursorTimeMs,
      ).clamp(0.0, 1.0).toDouble();
    }
    _scheduleAutoExpandedMap();
  }

  void _scheduleAutoExpandedMap() {
    if (!widget.autoOpenExpanded || _autoExpandedScheduled) return;
    _autoExpandedScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      if (!mounted) return;
      widget.onAutoOpenHandled?.call();
      await _openExpandedMap(
        matchMode: widget.autoOpenExpandedMatch,
        returnToSessionsOnClose: true,
      );
    });
  }

  @override
  void dispose() {
    _playTimer?.cancel();
    super.dispose();
  }

  void _deferMouseSafe(FutureOr<void> Function() action,
      {int milliseconds = 120}) {
    Timer(Duration(milliseconds: milliseconds), () async {
      if (!mounted) return;
      await WidgetsBinding.instance.endOfFrame;
      if (!mounted) return;
      FocusManager.instance.primaryFocus?.unfocus();
      await action();
    });
  }

  Set<int> get _effectivePlayerIds {
    if (widget.personalMode && widget.selectedPlayer != null) {
      return <int>{
        widget.selectedPlayer!.id,
        ...widget.selectedPlayer!.identityIds,
      }..removeWhere((id) => id <= 0);
    }
    return _movementExpandedPlayerIds(widget.players, widget.selectedPlayerIds);
  }

  List<ActionTrackerGpsPoint> get _playerPoints =>
      _movementPointsForPlayers(widget.localPoints, _effectivePlayerIds);

  List<ActionTrackerGpsPoint> get _rangePoints =>
      _movementPointsForRange(_playerPoints, _range);

  List<ActionTrackerGpsPoint> get _visiblePoints {
    if (widget.heatMode) return const <ActionTrackerGpsPoint>[];
    return _rangePoints;
  }

  ActionTrackerGpsPoint? get _cursorPoint =>
      _movementPointAtProgress(_playerPoints, _cursor, range: _range);

  ActionTrackerGpsPoint? get _personalGhostPoint =>
      widget.personalMode &&
              _personalGhostEnabled &&
              widget.personalGhostPoints.isNotEmpty
          ? _movementPointAtProgress(
              widget.personalGhostPoints,
              _cursor,
              range: _range,
            )
          : null;

  @override
  void didUpdateWidget(covariant _MapTab oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (!oldWidget.autoOpenExpanded && widget.autoOpenExpanded) {
      _autoExpandedScheduled = false;
      _scheduleAutoExpandedMap();
    }
    if (oldWidget.selectedSession?.id != widget.selectedSession?.id ||
        oldWidget.localPoints != widget.localPoints) {
      _range = const RangeValues(0, 1);
      _cursor = 0;
      _selectedPoint = null;
      _personalGhostEnabled = false;
      _stopPlayback();
    }
  }

  @override
  Widget build(BuildContext context) {
    final playerPoints = _playerPoints;
    final rangedPoints = _rangePoints;
    final visiblePoints = _visiblePoints;
    final local = _LocalTrackAnalysis.fromPoints(rangedPoints,
        sprintThresholdKmh: widget.sprintThresholdKmh,
        hsrThresholdKmh: widget.hsrThresholdKmh);
    final useServerHeat = !widget.personalMode &&
        widget.selectedPlayerIds.isEmpty &&
        _range.start <= .0001 &&
        _range.end >= .9999;
    final heatPoints = useServerHeat && widget.points.isNotEmpty
        ? widget.points
        : _heatmapFromGpsStatic(rangedPoints, widget.field);
    final activityLabel = _activityFilterLabel(_activityFilter);
    final chartSpeedSamples = _activityFilter == 'all'
        ? local.speedSamples
        : _activitySpeedSamples(
            rangedPoints, _activityFilter, widget.sprintThresholdKmh,
            hsrThresholdKmh: widget.hsrThresholdKmh);
    final chartMaxSpeed = chartSpeedSamples.fold<double>(
        0.0, (value, sample) => math.max(value, sample).toDouble());
    final timeRange = _movementRecordingSpanLabel(
      rangedPoints,
      fallbackDurationSec: widget.selectedSession?.durationSec ?? 0,
    );
    final comparisonRows =
        _movementRowsForSelection(widget.comparisonRows, _effectivePlayerIds);
    final comparisonMode = widget.selectedPlayerIds.length > 1 &&
        comparisonRows.length > 1;
    final events = _movementEvents(
      rangedPoints,
      hsrThresholdKmh: widget.hsrThresholdKmh,
      sprintThresholdKmh: widget.sprintThresholdKmh,
    );
    final filteredEvents = events
        .where((event) => _movementEventMatchesFilter(event, _activityFilter))
        .toList(growable: false);
    final fatigue = _MovementFatigue.fromPoints(rangedPoints,
        sprintThresholdKmh: widget.sprintThresholdKmh);
    final mediaWidth = MediaQuery.sizeOf(context).width;
    final phone = mediaWidth < 720;
    final desktopSidebarMode =
        widget.showDesktopSidebar && mediaWidth >= 1012;

    final mapModeControls = <Widget>[
      _MapModeButton(
        label: 'Маршрут',
        icon: Icons.timeline_rounded,
        active: !widget.heatMode,
        onTap: () => widget.onHeatModeChanged(false),
      ),
      _MapModeButton(
        label: 'Тепло',
        icon: Icons.local_fire_department_rounded,
        active: widget.heatMode,
        onTap: () {
          if (_geoBaseLayer != TrackerGeoBaseLayer.pitch) {
            setState(() => _geoBaseLayer = TrackerGeoBaseLayer.pitch);
          }
          widget.onHeatModeChanged(true);
        },
      ),
      _MapModeButton(
        label: widget.personalMode ? 'Запись' : 'Матч',
        icon: widget.personalMode
            ? Icons.play_circle_outline_rounded
            : Icons.sports_soccer_rounded,
        active: false,
        // V187: «Матч» в карте больше не является промежуточным режимом —
        // сразу открываем полноценный экран повтора/разбора матча.
        onTap: () => unawaited(_openExpandedMap(matchMode: true)),
      ),
      if (widget.personalMode && widget.personalGhostPoints.isNotEmpty)
        _MapModeButton(
          label: 'Ghost',
          icon: Icons.blur_on_rounded,
          active: _personalGhostEnabled,
          onTap: () => setState(
            () => _personalGhostEnabled = !_personalGhostEnabled,
          ),
        ),
      _MapModeButton(
        label: 'Пит-уолл',
        icon: Icons.monitor_heart_rounded,
        active: false,
        emphasis: true,
        onTap: () => unawaited(_openExpandedMap(pitWallMode: true)),
      ),
      _MovementPointsMenu(
        current: _activityFilter,
        onChanged: (value) {
          widget.onHeatModeChanged(false);
          _setFilter(value);
        },
      ),
    ];

    Widget mapToolbarContent() {
      final detailsButton = _SmallButton(
        icon: Icons.open_in_full_rounded,
        label: 'Подробнее',
        onTap: () => unawaited(_openExpandedMap()),
      );

      final layerSwitch = TrackerGeoLayerStrip(
        value: _geoBaseLayer,
        compact: true,
        onChanged: (layer) {
          setState(() => _geoBaseLayer = layer);
          if (layer != TrackerGeoBaseLayer.pitch && widget.heatMode) {
            widget.onHeatModeChanged(false);
          }
        },
      );

      if (phone) {
        return SingleChildScrollView(
          scrollDirection: Axis.horizontal,
          physics: const BouncingScrollPhysics(),
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              ...mapModeControls,
              const SizedBox(width: 5),
              layerSwitch,
              const SizedBox(width: 5),
              detailsButton,
            ],
          ),
        );
      }

      return SingleChildScrollView(
        scrollDirection: Axis.horizontal,
        physics: const BouncingScrollPhysics(),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            ...mapModeControls,
            const SizedBox(width: 10),
            layerSwitch,
            const SizedBox(width: 6),
            detailsButton,
          ],
        ),
      );
    }

    final inlineGeoTracks = _geoBaseLayer == TrackerGeoBaseLayer.pitch
        ? const <TrackerGeoTrack>[]
        : _analyticsGeoTracks(
            points: rangedPoints,
            players: widget.players,
            selectedIds: _effectivePlayerIds,
          );


    final mapPanel = _Panel(
      title: widget.heatMode ? 'Тепловая карта' : 'Карта движения',
      subtitle: rangedPoints.isEmpty
          ? 'нет GPS-точек выбранной сессии'
          : '${rangedPoints.length} GPS · $activityLabel · $timeRange · ${local.sprintCount} спринтов',
      hideHeader: true,
      flat: true,
      child: Column(children: [
        SizedBox(
          // V186: в desktop-режиме с левым CMR-меню карточки игроков
          // размещаются в два ряда; в остальных режимах сохраняем один ряд.
          height: !widget.personalMode && desktopSidebarMode ? 110 : 58,
          child: widget.personalMode
              ? _PersonalMapPlayerStrip(
                  player: widget.selectedPlayer,
                  row: comparisonRows.isNotEmpty ? comparisonRows.first : null,
                  currentSession: widget.selectedSession,
                  ghostSession: widget.personalGhostSession,
                  ghostAvailable: widget.personalGhostPoints.isNotEmpty,
                  ghostEnabled: _personalGhostEnabled,
                  onToggleGhost: widget.personalGhostPoints.isEmpty
                      ? null
                      : () => setState(
                            () => _personalGhostEnabled =
                                !_personalGhostEnabled,
                          ),
                )
              : _MapPlayerStrip(
                  players: widget.players,
                  rows: widget.comparisonRows,
                  session: widget.selectedSession,
                  selectedIds: widget.selectedPlayerIds,
                  compareMode: _compareMode,
                  twoRows: desktopSidebarMode,
                  onCompareModeChanged: (value) => setState(() {
                    _compareMode = value;
                    if (!value && widget.selectedPlayerIds.length > 1) {
                      widget.onPlayerSelectionChanged(<int>{});
                    }
                  }),
                  onChanged: widget.onPlayerSelectionChanged,
                ),
        ),
        if (!desktopSidebarMode)
          Container(
            height: 36,
            padding: const EdgeInsets.symmetric(horizontal: 2),
            decoration: BoxDecoration(
              color: _AA.soft,
              borderRadius: BorderRadius.circular(10),
            ),
            child: mapToolbarContent(),
          ),
        Expanded(
          child: _geoBaseLayer == TrackerGeoBaseLayer.pitch
              ? _PitchViewport(
                  painter: _ActionPitchPainter(
                    heat: widget.heatMode
                        ? heatPoints
                        : const <TrackerHeatPoint>[],
                    local: widget.heatMode
                        ? const <ActionTrackerGpsPoint>[]
                        : visiblePoints,
                    field: widget.field,
                    sprintThresholdKmh: widget.sprintThresholdKmh,
                    hsrThresholdKmh: widget.hsrThresholdKmh,
                    activityFilter: _activityFilter,
                    showSprintArrows: widget.showSprintArrows,
                    mapRotationDeg: widget.mapRotationDeg,
                    cursorPoint: _cursorPoint,
                    ghostPoint: _personalGhostPoint,
                  ),
                  onTapDown: widget.heatMode
                      ? null
                      : (localPosition, mapSize) {
                          final tappablePoints = _filterActivityPoints(
                            visiblePoints,
                            _activityFilter,
                            widget.sprintThresholdKmh,
                            hsrThresholdKmh: widget.hsrThresholdKmh,
                          );
                          final info = _nearestPointInfo(
                            localPosition,
                            mapSize,
                            tappablePoints,
                            widget.field,
                            widget.hsrThresholdKmh,
                            widget.sprintThresholdKmh,
                            heartRate: widget.heartRate,
                            allTrackPoints: playerPoints,
                            projectionPoints: visiblePoints,
                          );
                          if (info != null) {
                            _deferMouseSafe(() {
                              if (!mounted) return;
                              setState(() {
                                _selectedPoint = info;
                                _detailPanelMode = 'info';
                                _cursor = _movementProgressForTime(
                                  playerPoints,
                                  info.timeMs,
                                );
                              });
                            }, milliseconds: 50);
                          }
                        },
                )
              : Tracker2GisMapLayer(
                  layer: _geoBaseLayer,
                  tracks: inlineGeoTracks,
                  cursorTimeMs: _cursorPoint?.timeMs,
                  live: false,
                  followLatest: false,
                  interactive: true,
                  perspective3d: false,
                  field: widget.field,
                  rotationDeg: widget.mapRotationDeg,
                  showPlayers: true,
                  showLabels: true,
                  showTrace: true,
                ),
        ),
        if (!widget.heatMode)
          _MovementTransportStrip(
            points: playerPoints,
            range: _range,
            cursor: _cursor,
            playing: _playing,
            playbackRate: _playbackRate,
            onPlaybackRateChanged: (value) =>
                setState(() => _playbackRate = value),
            onTogglePlay: _togglePlayback,
            onCursorChanged: (value) => setState(() => _cursor = value),
            onRangeChanged: _setRange,
            dense: true,
          ),
      ]),
    );

    Widget chartContent() => Column(children: [
          Container(
            height: 30,
            padding: const EdgeInsets.symmetric(horizontal: 8),
            decoration: const BoxDecoration(
                border: Border(bottom: BorderSide(color: _AA.line))),
            child: Row(children: [
              Icon(_activityFilterIcon(_activityFilter),
                  color: _AA.green, size: 15),
              const SizedBox(width: 6),
              Expanded(
                  child: Text(
                      'Фильтр: $activityLabel · ${chartSpeedSamples.length} отрезков · $timeRange',
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: _AText.body(10.2, color: _AA.text, weight: FontWeight.w600))),
              Text(
                  chartMaxSpeed > 0
                      ? 'max ${chartMaxSpeed.toStringAsFixed(1)} км/ч'
                      : 'нет скорости',
                  style: const TextStyle(
                      color: _AA.muted,
                      fontSize: 10.4,
                      fontWeight: FontWeight.w700)),
            ]),
          ),
          Expanded(
            flex: 7,
            child: _MovementTimeline(
              points: rangedPoints,
              hsrThresholdKmh: widget.hsrThresholdKmh,
              sprintThresholdKmh: widget.sprintThresholdKmh,
              cursor: _movementCursorInsideRange(_cursor, _range),
              onCursorChanged: (localProgress) => setState(() {
                _cursor = _movementGlobalProgress(localProgress, _range);
              }),
            ),
          ),
          Container(height: 1, color: _AA.line),
          Expanded(
            flex: comparisonMode ? 5 : 4,
            child: comparisonMode
                ? _PlayerComparisonPanel(rows: comparisonRows)
                : _MovementMiniSummary(
                    local: local,
                    fatigue: fatigue,
                    eventCount: events.length,
                    hsrThresholdKmh: widget.hsrThresholdKmh,
                    sprintThresholdKmh: widget.sprintThresholdKmh,
                  ),
          ),
        ]);

    Widget eventsContent() => _MovementEventList(
          events: filteredEvents,
          points: rangedPoints,
          field: widget.field,
          heartRate: widget.heartRate,
          onSelect: _jumpToEvent,
        );

    Widget infoContent() => _selectedPoint == null
        ? _MovementSessionInfo(
            local: local,
            fatigue: fatigue,
            events: events,
            selectedIds: widget.selectedPlayerIds,
            selectedPlayer: widget.selectedPlayer,
            selectedSession: widget.selectedSession,
            field: widget.field,
            pointsCount: rangedPoints.length,
            timeRange: timeRange,
            activityLabel: activityLabel,
            onOpenCalibration: widget.onOpenCalibration,
          )
        : _SelectedMapPointCard(
            info: _selectedPoint!,
            onClear: () => setState(() => _selectedPoint = null),
            onPrevious: () => _stepSelectedPoint(-1),
            onNext: () => _stepSelectedPoint(1),
          );

    final detailPanel = _Panel(
      title: '',
      subtitle: '',
      hideHeader: true,
      flat: true,
      surfaceColor: const Color(0xFFF7FAF7),
      child: Column(children: [
        Container(
          height: 36,
          padding: const EdgeInsets.symmetric(horizontal: 2),
          decoration: BoxDecoration(
            color: _AA.soft,
            borderRadius: BorderRadius.circular(10),
          ),
          child: Row(children: [
            Expanded(
              child: FittedBox(
                fit: BoxFit.scaleDown,
                child: _MapModeButton(
                    label: 'График',
                    icon: Icons.show_chart_rounded,
                    active: _detailPanelMode == 'chart',
                    onTap: () => setState(() => _detailPanelMode = 'chart')),
              ),
            ),
            Expanded(
              child: FittedBox(
                fit: BoxFit.scaleDown,
                child: _MapModeButton(
                    label: 'События',
                    icon: Icons.bolt_rounded,
                    active: _detailPanelMode == 'events',
                    onTap: () => setState(() => _detailPanelMode = 'events')),
              ),
            ),
            Expanded(
              child: FittedBox(
                fit: BoxFit.scaleDown,
                child: _MapModeButton(
                    label: _selectedPoint == null ? 'Сессия' : 'Точка',
                    icon: Icons.info_outline_rounded,
                    active: _detailPanelMode == 'info',
                    onTap: () => setState(() => _detailPanelMode = 'info')),
              ),
            ),
          ]),
        ),
        const SizedBox(height: 5),
        _MapQuickMetricsStrip(
          distance: _meters(local.distanceM),
          maxSpeed: '${local.maxSpeedKmh.toStringAsFixed(1)} км/ч',
          sprints: '${local.sprintCount}',
          events: '${events.length}',
        ),
        const SizedBox(height: 5),
        Expanded(
          child: _detailPanelMode == 'chart'
              ? chartContent()
              : _detailPanelMode == 'events'
                  ? eventsContent()
                  : infoContent(),
        ),
      ]),
    );

    void openPhoneInspector(String mode) {
      final title = switch (mode) {
        'chart' => 'График скорости',
        'events' => 'События тренировки',
        'sprints' => 'Спринты',
        _ => _selectedPoint == null ? 'Данные сессии' : 'Выбранная точка',
      };
      final icon = switch (mode) {
        'chart' => Icons.show_chart_rounded,
        'events' => Icons.bolt_rounded,
        'sprints' => Icons.flash_on_rounded,
        _ => Icons.info_outline_rounded,
      };
      showModalBottomSheet<void>(
        context: context,
        useSafeArea: true,
        isScrollControlled: true,
        backgroundColor: Colors.transparent,
        builder: (sheetContext) {
          Widget body;
          if (mode == 'chart') {
            body = chartContent();
          } else if (mode == 'events') {
            body = _MovementEventList(
              events: filteredEvents,
              points: rangedPoints,
              field: widget.field,
              heartRate: widget.heartRate,
              onSelect: (event) {
                Navigator.of(sheetContext).pop();
                _jumpToEvent(event);
              },
            );
          } else if (mode == 'sprints') {
            body = _MovementEventList(
              events: events
                  .where((event) => event.kind == 'sprint')
                  .toList(growable: false),
              points: rangedPoints,
              field: widget.field,
              heartRate: widget.heartRate,
              onSelect: (event) {
                Navigator.of(sheetContext).pop();
                _jumpToEvent(event);
              },
            );
          } else {
            body = infoContent();
          }
          return FractionallySizedBox(
            heightFactor: .90,
            child: Container(
              margin: const EdgeInsets.fromLTRB(8, 0, 8, 8),
              decoration: BoxDecoration(
                color: _AA.card,
                borderRadius: BorderRadius.circular(24),
                boxShadow: const [
                  BoxShadow(
                    color: Color(0x20101828),
                    blurRadius: 28,
                    offset: Offset(0, 12),
                  ),
                ],
              ),
              clipBehavior: Clip.antiAlias,
              child: Column(
                children: [
                  Container(
                    height: 54,
                    padding: const EdgeInsets.symmetric(horizontal: 12),
                    decoration: const BoxDecoration(
                      color: _AA.card,
                      border: Border(bottom: BorderSide(color: _AA.line)),
                    ),
                    child: Row(
                      children: [
                        Container(
                          width: 36,
                          height: 36,
                          decoration: BoxDecoration(
                            color: _AA.greenSoft,
                            borderRadius: BorderRadius.circular(12),
                          ),
                          child: Icon(icon, color: _AA.green, size: 18),
                        ),
                        const SizedBox(width: 9),
                        Expanded(
                          child: Text(
                            title,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: const TextStyle(
                              color: _AA.text,
                              fontSize: 14.0,
                              fontWeight: FontWeight.w800,
                            ),
                          ),
                        ),
                        _NoHoverTap(
                          onTap: () => Navigator.of(sheetContext).pop(),
                          borderRadius: BorderRadius.circular(12),
                          child: Container(
                            width: 34,
                            height: 34,
                            alignment: Alignment.center,
                            decoration: BoxDecoration(
                              color: _AA.soft,
                              borderRadius: BorderRadius.circular(12),
                            ),
                            child: const Icon(
                              Icons.close_rounded,
                              color: _AA.muted,
                              size: 19,
                            ),
                          ),
                        ),
                      ],
                    ),
                  ),
                  Expanded(
                    child: Padding(
                      padding: const EdgeInsets.all(8),
                      child: body,
                    ),
                  ),
                ],
              ),
            ),
          );
        },
      );
    }

    Widget desktopMapSidebar(double workspaceWidth) {
      final sidebarWidth = workspaceWidth >= 1700
          ? 306.0
          : (workspaceWidth >= 1440
              ? 286.0
              : (workspaceWidth >= 1180 ? 262.0 : 232.0));

      void setLayer(TrackerGeoBaseLayer layer) {
        setState(() => _geoBaseLayer = layer);
        if (layer != TrackerGeoBaseLayer.pitch && widget.heatMode) {
          widget.onHeatModeChanged(false);
        }
      }

      return SizedBox(
        width: sidebarWidth,
        child: ColoredBox(
          color: Colors.white,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Expanded(
                child: ListView(
                  padding: const EdgeInsets.fromLTRB(10, 10, 10, 12),
                  children: [
                    _MapSidebarItem(
                      label: 'Маршрут',
                      subtitle: 'трек движения и воспроизведение',
                      icon: Icons.timeline_rounded,
                      active: !widget.heatMode,
                      onTap: () => widget.onHeatModeChanged(false),
                    ),
                    const SizedBox(height: 4),
                    _MapSidebarItem(
                      label: 'Тепло',
                      subtitle: 'тепловая карта активности',
                      icon: Icons.local_fire_department_rounded,
                      active: widget.heatMode,
                      onTap: () {
                        if (_geoBaseLayer != TrackerGeoBaseLayer.pitch) {
                          setState(() =>
                              _geoBaseLayer = TrackerGeoBaseLayer.pitch);
                        }
                        widget.onHeatModeChanged(true);
                      },
                    ),
                    const SizedBox(height: 4),
                    _MapSidebarItem(
                      label: widget.personalMode ? 'Запись' : 'Матч',
                      subtitle: widget.personalMode
                          ? 'открыть полный повтор тренировки'
                          : 'открыть полный разбор матча',
                      icon: widget.personalMode
                          ? Icons.play_circle_outline_rounded
                          : Icons.sports_soccer_rounded,
                      onTap: () =>
                          unawaited(_openExpandedMap(matchMode: true)),
                    ),
                    if (widget.personalMode &&
                        widget.personalGhostPoints.isNotEmpty) ...[
                      const SizedBox(height: 4),
                      _MapSidebarItem(
                        label: 'Ghost',
                        subtitle: 'сравнение с другой тренировкой',
                        icon: Icons.blur_on_rounded,
                        active: _personalGhostEnabled,
                        onTap: () => setState(() =>
                            _personalGhostEnabled = !_personalGhostEnabled),
                      ),
                    ],
                    const SizedBox(height: 4),
                    _MapSidebarItem(
                      label: 'Пит-уолл',
                      subtitle: 'телеметрия и сигналы нагрузки',
                      icon: Icons.monitor_heart_rounded,
                      emphasis: true,
                      onTap: () =>
                          unawaited(_openExpandedMap(pitWallMode: true)),
                    ),
                    const SizedBox(height: 4),
                    _MapSidebarPointsItem(
                      current: _activityFilter,
                      onChanged: (value) {
                        widget.onHeatModeChanged(false);
                        _setFilter(value);
                      },
                    ),
                    const Padding(
                      padding: EdgeInsets.fromLTRB(10, 15, 10, 7),
                      child: Text(
                        'ПОДЛОЖКА',
                        style: TextStyle(
                          color: _AA.muted2,
                          fontSize: 8.8,
                          fontWeight: FontWeight.w700,
                          letterSpacing: .45,
                        ),
                      ),
                    ),
                    _MapSidebarItem(
                      label: 'Поле',
                      subtitle: 'откалиброванное футбольное поле',
                      icon: Icons.sports_soccer_rounded,
                      active: _geoBaseLayer == TrackerGeoBaseLayer.pitch,
                      onTap: () => setLayer(TrackerGeoBaseLayer.pitch),
                    ),
                    const SizedBox(height: 4),
                    _MapSidebarItem(
                      label: 'Карта',
                      subtitle: 'обычная географическая подложка',
                      icon: Icons.map_rounded,
                      active: _geoBaseLayer == TrackerGeoBaseLayer.dgis,
                      onTap: () => setLayer(TrackerGeoBaseLayer.dgis),
                    ),
                    const SizedBox(height: 4),
                    _MapSidebarItem(
                      label: 'Спутник',
                      subtitle: 'спутниковая географическая подложка',
                      icon: Icons.satellite_alt_rounded,
                      active: _geoBaseLayer == TrackerGeoBaseLayer.satellite,
                      onTap: () => setLayer(TrackerGeoBaseLayer.satellite),
                    ),
                    const SizedBox(height: 12),
                    _MapSidebarItem(
                      label: 'Подробнее',
                      subtitle: 'развернуть карту и инструменты',
                      icon: Icons.open_in_full_rounded,
                      onTap: () => unawaited(_openExpandedMap()),
                    ),
                  ],
                ),
              ),
              Container(height: 1, color: _AA.line),
              Padding(
                padding: const EdgeInsets.fromLTRB(10, 10, 10, 13),
                child: _MapSidebarBackItem(
                  title: 'К списку меню аналитики',
                  subtitle: '${widget.teamName} · Аналитика',
                  onTap: widget.onBackToAnalyticsMenu,
                ),
              ),
            ],
          ),
        ),
      );
    }

    return LayoutBuilder(builder: (context, constraints) {
      final width = constraints.maxWidth;
      // V117.3: на desktop карта снова является главным левым рабочим блоком,
      // а графики/события находятся справа. Ничего важного не складываем
      // вертикально под полем, поэтому карта остаётся высокой и читаемой.
      if (width >= 960) {
        final workspace = Padding(
          padding: const EdgeInsets.all(4),
          child: Row(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Expanded(flex: 12, child: mapPanel),
            const SizedBox(width: 6),
            Expanded(
              // V186: с левым меню правый инспектор больше не зажимается.
              // На компактном desktop он занимает примерно треть workspace.
              flex: desktopSidebarMode ? (width < 1350 ? 6 : 5) : 4,
              child: detailPanel,
            ),
          ]),
        );
        if (!desktopSidebarMode) return workspace;
        return Row(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            desktopMapSidebar(width),
            Container(width: 1, color: _AA.line),
            Expanded(child: workspace),
          ],
        );
      }
      if (width >= 720) {
        return Padding(
          padding: const EdgeInsets.all(4),
          child: Row(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
            Expanded(flex: 9, child: mapPanel),
            const SizedBox(width: 6),
            Expanded(flex: 4, child: detailPanel),
          ]),
        );
      }
      if (widget.personalMode) {
        final bottomSafe = MediaQuery.paddingOf(context).bottom;
        return ListView(
          primary: false,
          physics: const BouncingScrollPhysics(
            parent: AlwaysScrollableScrollPhysics(),
          ),
          padding: EdgeInsets.fromLTRB(8, 6, 8, 92 + bottomSafe),
          children: [
            SizedBox(height: 520, child: mapPanel),
            const SizedBox(height: 6),
            Container(
              height: 44,
              padding: const EdgeInsets.symmetric(horizontal: 3),
              decoration: BoxDecoration(
                color: _AA.soft,
                borderRadius: BorderRadius.circular(12),
              ),
              child: SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                physics: const BouncingScrollPhysics(),
                child: Row(
                  children: [
                    _MapModeButton(
                      label: 'График',
                      icon: Icons.show_chart_rounded,
                      active: false,
                      onTap: () => openPhoneInspector('chart'),
                    ),
                    _MapModeButton(
                      label: 'События',
                      icon: Icons.bolt_rounded,
                      active: false,
                      onTap: () => openPhoneInspector('events'),
                    ),
                    _MapModeButton(
                      label: 'Спринты',
                      icon: Icons.flash_on_rounded,
                      active: false,
                      onTap: () => openPhoneInspector('sprints'),
                    ),
                    _MapModeButton(
                      label: _selectedPoint == null ? 'Сессия' : 'Точка',
                      icon: Icons.info_outline_rounded,
                      active: false,
                      onTap: () => openPhoneInspector('info'),
                    ),
                  ],
                ),
              ),
            ),
          ],
        );
      }
      final bottomSafe = MediaQuery.paddingOf(context).bottom;
      return ListView(
        primary: false,
        physics: const BouncingScrollPhysics(),
        padding: EdgeInsets.fromLTRB(10, 10, 10, 112 + bottomSafe),
        children: [
          SizedBox(height: 590, child: mapPanel),
          const SizedBox(height: 8),
          SizedBox(height: 360, child: detailPanel),
        ],
      );
    });
  }

  void _setFilter(String value) {
    setState(() {
      _activityFilter = value;
      _selectedPoint = null;
    });
  }

  void _setRange(RangeValues value) {
    final start = value.start.clamp(0.0, 1.0).toDouble();
    final end = value.end.clamp(0.0, 1.0).toDouble();
    final safeEnd = math.max(end, math.min(1.0, start + .01)).toDouble();
    setState(() {
      _range = RangeValues(start, safeEnd);
      _cursor = _cursor.clamp(start, safeEnd).toDouble();
      _selectedPoint = null;
    });
  }

  void _togglePlayback() {
    if (_playing) {
      _stopPlayback();
      return;
    }
    if (_playerPoints.length < 2) return;
    setState(() {
      _playing = true;
      if (_cursor < _range.start || _cursor >= _range.end) {
        _cursor = _range.start;
      }
    });
    _playTimer?.cancel();
    _playTimer = Timer.periodic(const Duration(milliseconds: 200), (_) {
      if (!mounted) return;
      final minTime = _movementMinTime(_playerPoints);
      final maxTime = _movementMaxTime(_playerPoints);
      final durationMs = math.max(1, maxTime - minTime);
      final step = (200.0 * _playbackRate) / durationMs;
      final next = _cursor + step;
      if (next >= _range.end) {
        setState(() => _cursor = _range.end);
        _stopPlayback();
      } else {
        setState(() => _cursor = next);
      }
    });
  }

  void _stopPlayback() {
    _playTimer?.cancel();
    _playTimer = null;
    if (_playing && mounted) setState(() => _playing = false);
    _playing = false;
  }

  void _jumpToEvent(_MovementEvent event) {
    final progress = _movementProgressForTime(_playerPoints, event.startTimeMs);
    setState(() {
      _cursor = progress.clamp(_range.start, _range.end).toDouble();
      _detailPanelMode = 'events';
      _selectedPoint = _mapPointInfoFromIndex(
        _rangePoints,
        event.startIndex.clamp(0, math.max(0, _rangePoints.length - 1)).toInt(),
        widget.field,
        widget.hsrThresholdKmh,
        widget.sprintThresholdKmh,
        heartRate: widget.heartRate,
        allTrackPoints: _playerPoints,
      );
    });
  }

  void _stepSelectedPoint(int direction) {
    final points = _rangePoints;
    if (_selectedPoint == null || points.isEmpty) return;
    var currentIndex = points.indexWhere((p) =>
        p.timeMs == _selectedPoint!.timeMs &&
        (p.playerId == _selectedPoint!.playerId || _selectedPoint!.playerId == null));
    if (currentIndex < 0) currentIndex = _selectedPoint!.index.clamp(0, points.length - 1).toInt();
    final nextIndex = (currentIndex + direction).clamp(0, points.length - 1).toInt();
    final info = _mapPointInfoFromIndex(
      points,
      nextIndex,
      widget.field,
      widget.hsrThresholdKmh,
      widget.sprintThresholdKmh,
      heartRate: widget.heartRate,
      allTrackPoints: _playerPoints,
    );
    if (info == null) return;
    setState(() {
      _selectedPoint = info;
      _cursor = _movementProgressForTime(_playerPoints, info.timeMs);
    });
  }

  Future<void> _openExpandedMap({
    bool matchMode = false,
    bool pitWallMode = false,
    bool returnToSessionsOnClose = false,
  }) async {
    _stopPlayback();
    var closeToSessions = false;
    final media = MediaQuery.sizeOf(context);
    final desktopWindow = media.width >= 1180;

    await showGeneralDialog<void>(
      context: context,
      useRootNavigator: true,
      barrierDismissible: false,
      barrierLabel: 'Карта аналитики',
      barrierColor: desktopWindow ? Colors.black.withOpacity(.16) : Colors.white,
      transitionDuration: const Duration(milliseconds: 140),
      transitionBuilder: (context, animation, secondaryAnimation, child) {
        return FadeTransition(
          opacity: CurvedAnimation(parent: animation, curve: Curves.easeOutCubic),
          child: child,
        );
      },
      pageBuilder: (dialogContext, _, __) {
        final inspector = _ExpandedMovementInspector(
          api: widget.api,
          clubId: widget.clubId,
          userId: widget.userId,
          teamId: widget.teamId,
          teamName: widget.teamName,
          clubName: widget.clubName,
          points: widget.points,
          localPoints: widget.localPoints,
          field: widget.field,
          selectedPlayer: widget.selectedPlayer,
          selectedSession: widget.selectedSession,
          players: widget.players,
          heartRate: widget.heartRate,
          comparisonRows: widget.comparisonRows,
          selectedPlayerIds: widget.selectedPlayerIds,
          initialRange: _range,
          initialCursor: _cursor,
          initialFilter: _activityFilter,
          heatMode: widget.heatMode,
          initialMatchMode: matchMode,
          initialPitWallMode: pitWallMode,
          initialGhostMode:
              widget.personalMode ? _personalGhostEnabled : false,
          personalGhostSession: widget.personalGhostSession,
          personalGhostPoints: widget.personalGhostPoints,
          sprintThresholdKmh: widget.sprintThresholdKmh,
          hsrThresholdKmh: widget.hsrThresholdKmh,
          showSprintArrows: widget.showSprintArrows,
          mapRotationDeg: widget.mapRotationDeg,
          onOpenCalibration: widget.onOpenCalibration,
          onPlayerSelectionChanged: widget.onPlayerSelectionChanged,
          onOpenTelemetryVideo: widget.onOpenTelemetryVideo,
          onOpenTelemetryAi: widget.onOpenTelemetryAi,
          onClose: () {
            // V119.3: крестик полноэкранной карты всегда возвращает
            // пользователя к выбору сессии. ИИ/Видео используют отдельный
            // onDismissForAction и поэтому не затрагивают этот переход.
            closeToSessions = true;
            Navigator.of(dialogContext, rootNavigator: true).pop();
          },
          onDismissForAction: () {
            Navigator.of(dialogContext, rootNavigator: true).pop();
          },
          // V187: из полного разбора матча нижняя кнопка возвращает не в
          // промежуточную карту, а сразу в «Обзор» основного меню аналитики.
          onBackToAnalyticsOverview: widget.onBackToAnalyticsMenu,
          personalMode: widget.personalMode,
        );

        if (!desktopWindow) {
          return Material(
            color: Colors.white,
            child: SafeArea(
              minimum: EdgeInsets.zero,
              child: SizedBox.expand(child: inspector),
            ),
          );
        }

        return Material(
          color: Colors.transparent,
          child: SafeArea(
            minimum: const EdgeInsets.all(8),
            child: Center(
              child: Container(
                width: math.min(1510.0, media.width - 16),
                height: math.min(930.0, media.height - 16),
                clipBehavior: Clip.antiAlias,
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(18),
                  boxShadow: [
                    BoxShadow(
                      color: Colors.black.withOpacity(.14),
                      blurRadius: 34,
                      spreadRadius: -18,
                      offset: const Offset(0, 18),
                    ),
                  ],
                ),
                child: inspector,
              ),
            ),
          ),
        );
      },
    );

    if (mounted && closeToSessions) {
      widget.onExpandedClosedToSessions?.call();
    }
  }
}

