class _ExpandedMovementInspectorState extends State<_ExpandedMovementInspector> {
  late Set<int> _selectedIds;
  late RangeValues _range;
  late double _cursor;
  late String _filter;
  bool _compareMode = false;
  bool _individualThresholds = false;
  bool _heatMode = false;
  bool _matchMode = false;
  bool _reviewMode = false;
  late final TgAnalyticsOverlayController _tacticalReviewController;
  final TrackerTacticalReviewApi _tacticalReviewApi = TrackerTacticalReviewApi();
  Timer? _tacticalReviewSaveTimer;
  _TacticalReviewPendingSave? _tacticalReviewPendingSave;
  final Set<String> _tacticalReviewDirtyKeys = <String>{};
  final Map<String, int> _tacticalReviewRevisionByKey = <String, int>{};
  int _tacticalReviewLoadToken = 0;
  bool _tacticalReviewSaving = false;
  bool _tacticalReviewServerLoaded = false;
  bool _pitWallMode = false;
  bool _sectorOverlay = false;
  bool _ghostEnabled = false;
  bool _teamShapeEnabled = true;
  // V145: завершённая сессия получает те же визуальные режимы, что Live+:
  // 3D-перспективу и точки ключевых моментов прямо на поле.
  bool _perspective3d = true;
  TrackerGeoBaseLayer _geoBaseLayer = TrackerGeoBaseLayer.pitch;
  bool _geoShowTracks = false;
  double? _geoRotationDeg;
  // V151 PERFORMANCE: состояние 3D-камеры живёт внутри
  // _AnalyticsPitchPerspective. Движение джойстика больше НЕ вызывает
  // setState всего Expanded inspector и не пересчитывает 9k+ GPS-точек.
  // V149: точки журнала не перегружают карту при первом открытии.
  // Пользователь включает их отдельно кнопкой «Журнал» или через меню «Точки».
  bool _showJournalMarkers = false;
  // V185: в полном разборе HUD выключен по умолчанию, чтобы подписи игроков
  // не накладывались друг на друга; включается из нового левого меню.
  bool _showReplayHud = false;
  // V192: правая колонка в повторе матча теперь работает как инспектор.
  // Списки игроков и журнал открываются по требованию и не съедают место
  // у графика постоянно.
  // V203: в повторе матча журнал является правой панелью по умолчанию.
  // Внутри журнала сразу идут карточки игроков/событий без дублирующих
  // служебных шапок. Игроки / Скорость / Кардио переключают тот же блок.
  bool _matchJournalMode = true;
  bool _matchPlayersMode = false; // legacy mobile fallback; desktop roster is above the pitch
  bool _matchCardioMode = false;
  // V196: compare opens as a dedicated right inspector. Player roster itself stays above.
  bool _matchCompareMode = false;
  // V196: Match is the base layout. Route/Heat only change the data painted on the same pitch.
  String _mapPresentation = 'match'; // match | route | heat
  // V195: Маршрут/Тепло используют тот же принцип правого инспектора,
  // что и повтор матча. Событийные разделы открываются целиком в
  // зарезервированном правом блоке, а не ужимаются под графиком.
  // null = базовая панель «Скорость + кардио».
  String? _analysisDrawerMode;
  double _playbackRate = 1.0;
  String _sideMode = 'events';
  _MapPointInfo? _selectedPoint;
  String? _selectedReplayEventId;
  List<Map<String, dynamic>> _archivedLiveRawEvents =
      const <Map<String, dynamic>>[];
  bool _archivedLiveLoading = false;
  int _archivedLiveLoadToken = 0;
  String _replayJournalCacheKey = '';
  List<_ReplayJournalEvent> _replayCachedReconstructed =
      const <_ReplayJournalEvent>[];
  List<_ReplayJournalEvent> _replayCachedArchived =
      const <_ReplayJournalEvent>[];
  List<_ReplayJournalEvent> _replayCachedMerged =
      const <_ReplayJournalEvent>[];
  List<_MovementMapMarker> _replayCachedMarkers =
      const <_MovementMapMarker>[];
  List<Map<String, dynamic>> _replayCachedGpsHr =
      const <Map<String, dynamic>>[];
  Timer? _playTimer;
  bool _playing = false;
  String _telemetryCacheKey = '';
  List<_TelemetrySectorMetric> _telemetryCachedSectors = const <_TelemetrySectorMetric>[];
  _TelemetryConfidence _telemetryCachedConfidence = const _TelemetryConfidence(
    score: 0, gaps: 0, breaks: 0, impossibleSegments: 0, outsideFieldRatio: 0, avgIntervalMs: 0);
  _TelemetryDelta _telemetryCachedDelta = const _TelemetryDelta(
    firstScore: 0, secondScore: 0, deltaPct: 0, firstMaxSpeed: 0, secondMaxSpeed: 0);
  _TelemetryDegradation _telemetryCachedDegradation = const _TelemetryDegradation(
    quarterMaxSpeeds: <double>[], quarterHsrPerMin: <double>[], deltaPct: 0);
  List<_TelemetryKeyMoment> _telemetryCachedMoments = const <_TelemetryKeyMoment>[];
  _TelemetryWeatherSnapshot? _telemetryWeather;
  bool _inlineAiExpanded = false;
  int _inlineAiRevision = 0;
  Map<String, dynamic> _inlineAiPayload = const <String, dynamic>{};
  String _inlineAiPrompt = '';

  @override
  void initState() {
    super.initState();
    _selectedIds = widget.personalMode && widget.selectedPlayer != null
        ? <int>{widget.selectedPlayer!.id}
        : Set<int>.from(widget.selectedPlayerIds);
    _range = widget.initialRange;
    _cursor = widget.initialCursor;
    _filter = widget.initialFilter;
    _heatMode = widget.personalMode ? widget.heatMode : false;
    _matchMode = widget.personalMode ? widget.initialMatchMode : true;
    _mapPresentation = widget.personalMode
        ? (_matchMode ? 'match' : (_heatMode ? 'heat' : 'route'))
        : 'match';
    // Географическая подложка имеет собственный север/проекцию. Угол
    // виртуального поля сюда переносить нельзя — при первом открытии она
    // сама выравнивается по реальной длинной стороне поля или GPS-треку.
    _geoRotationDeg = null;
    _tacticalReviewController = TgAnalyticsOverlayController(
      sessionKey: _tacticalReviewSessionKey(),
      onMutation: _queueTacticalReviewSave,
    );
    _pitWallMode = widget.initialPitWallMode;
    _ghostEnabled = widget.initialGhostMode;
    if (widget.personalMode && widget.personalGhostPoints.isEmpty) {
      _ghostEnabled = false;
    }
    if (_pitWallMode) _sideMode = 'pit';
    if (_matchMode) _heatMode = false;
    _compareMode = _selectedIds.length > 1;
    unawaited(_loadArchivedLiveReplayEvents());
    unawaited(_loadTacticalReviewForKey(_tacticalReviewSessionKey()));
  }

  @override
  void didUpdateWidget(covariant _ExpandedMovementInspector oldWidget) {
    super.didUpdateWidget(oldWidget);
    final oldStart = _movementMinTime(oldWidget.localPoints);
    final newStart = _movementMinTime(widget.localPoints);
    final oldEnd = _movementMaxTime(oldWidget.localPoints);
    final newEnd = _movementMaxTime(widget.localPoints);
    final sessionChanged =
        oldWidget.selectedSession?.id != widget.selectedSession?.id ||
        oldStart != newStart ||
        oldEnd != newEnd;
    if (oldWidget.teamId != widget.teamId || sessionChanged) {
      // Сначала дожимаем отложенное сохранение предыдущего разбора.
      unawaited(_flushTacticalReviewSave());
      // V150: журнал-маркеры всегда стартуют выключенными для новой сессии.
      // Состояние «Все точки» / фильтра карты на это не влияет.
      if (mounted) {
        final key = _tacticalReviewSessionKey();
        _tacticalReviewController.switchSession(key);
        _tacticalReviewServerLoaded = false;
        setState(() {
          if (sessionChanged) {
            _showJournalMarkers = false;
            _selectedReplayEventId = null;
            _analysisDrawerMode = null;
            _matchCompareMode = false;
            if (!widget.personalMode) {
              _matchMode = true;
              _heatMode = false;
              _mapPresentation = 'match';
              _matchJournalMode = true;
              _matchPlayersMode = false;
              _matchCardioMode = false;
            }
          }
          _reviewMode = false;
        });
        unawaited(_loadTacticalReviewForKey(key));
      }
      unawaited(_loadArchivedLiveReplayEvents());
    }
  }

  void _queueTacticalReviewSave(
    String scopeKey,
    List<Map<String, dynamic>> annotations,
  ) {
    final revision = (_tacticalReviewRevisionByKey[scopeKey] ?? 0) + 1;
    _tacticalReviewRevisionByKey[scopeKey] = revision;
    _tacticalReviewDirtyKeys.add(scopeKey);
    _tacticalReviewPendingSave = _TacticalReviewPendingSave(
      scopeKey: scopeKey,
      clubId: widget.clubId,
      teamId: widget.teamId,
      sessionId: widget.selectedSession?.id ?? 0,
      createdBy: widget.userId,
      startMs: _movementMinTime(widget.localPoints),
      endMs: _movementMaxTime(widget.localPoints),
      playerId: widget.personalMode
          ? widget.selectedPlayer?.id
          : (_selectedIds.length == 1 ? _selectedIds.first : null),
      title: widget.selectedSession?.title ?? widget.teamName,
      annotations: annotations
          .map((item) => Map<String, dynamic>.from(item))
          .toList(growable: false),
      revision: revision,
    );
    _tacticalReviewSaveTimer?.cancel();
    _tacticalReviewSaveTimer = Timer(
      const Duration(milliseconds: 850),
      () => unawaited(_flushTacticalReviewSave()),
    );
  }

  Future<void> _flushTacticalReviewSave() async {
    _tacticalReviewSaveTimer?.cancel();
    _tacticalReviewSaveTimer = null;
    final pending = _tacticalReviewPendingSave;
    if (pending == null) return;
    _tacticalReviewPendingSave = null;
    _tacticalReviewSaving = true;
    try {
      await _tacticalReviewApi.save(
        scopeKey: pending.scopeKey,
        clubId: pending.clubId,
        teamId: pending.teamId,
        sessionId: pending.sessionId,
        createdBy: pending.createdBy,
        startMs: pending.startMs,
        endMs: pending.endMs,
        playerId: pending.playerId,
        title: pending.title,
        annotations: pending.annotations,
      );
      if (_tacticalReviewRevisionByKey[pending.scopeKey] == pending.revision) {
        _tacticalReviewDirtyKeys.remove(pending.scopeKey);
      }
    } catch (error) {
      // Серверное сохранение не должно ломать сам экран разбора. Runtime cache
      // остаётся доступным, а следующая мутация снова поставит документ в очередь.
      // ignore: avoid_print
      print('[TACTICAL_REVIEW] save fallback: $error');
    } finally {
      _tacticalReviewSaving = false;
    }
  }

  Future<void> _loadTacticalReviewForKey(String scopeKey) async {
    final token = ++_tacticalReviewLoadToken;
    try {
      var document = await _tacticalReviewApi.load(scopeKey: scopeKey);
      // Разбор, начатый прямо во время Live, хранится по live_session_id.
      // Для старых документов оставляем прозрачный fallback на прежний ключ.
      if (document == null) {
        final legacyKey = _legacyTacticalReviewSessionKey();
        if (legacyKey != scopeKey) {
          document = await _tacticalReviewApi.load(scopeKey: legacyKey);
        }
      }
      if (!mounted || token != _tacticalReviewLoadToken) return;
      if (_tacticalReviewController.sessionKey != scopeKey) return;
      // Если пользователь уже начал рисовать до ответа сервера, его локальная
      // работа важнее и не должна быть перезаписана поздним HTTP-ответом.
      if (_tacticalReviewDirtyKeys.contains(scopeKey)) return;
      if (document != null) {
        _tacticalReviewController.replaceFromJson(document.annotations);
      }
      _tacticalReviewServerLoaded = true;
    } catch (error) {
      // Endpoint может быть ещё не загружен на сервер. В этом случае UI работает
      // как раньше, используя runtime cache.
      // ignore: avoid_print
      print('[TACTICAL_REVIEW] load fallback: $error');
    }
  }

  Future<void> _loadArchivedLiveReplayEvents() async {
    final token = ++_archivedLiveLoadToken;
    if (widget.teamId <= 0 || widget.localPoints.isEmpty) {
      if (mounted) {
        setState(() {
          _archivedLiveRawEvents = const <Map<String, dynamic>>[];
          _archivedLiveLoading = false;
        });
      }
      return;
    }
    if (mounted) setState(() => _archivedLiveLoading = true);
    final rows = await widget.api.loadLiveReplayEvents(
      teamId: widget.teamId,
      limit: 1200,
    );
    if (!mounted || token != _archivedLiveLoadToken) return;
    setState(() {
      _archivedLiveRawEvents = rows;
      _archivedLiveLoading = false;
      _replayJournalCacheKey = '';
    });
  }

  String _tacticalReviewSessionKey() {
    ActionTrackerGpsPoint? firstLivePoint;
    for (final point in widget.localPoints) {
      final liveId = point.liveSessionId ?? 0;
      if (liveId <= 0 || liveId >= 700000000) continue;
      if (firstLivePoint == null || point.timeMs < firstLivePoint.timeMs) {
        firstLivePoint = point;
      }
    }
    if (firstLivePoint != null && firstLivePoint.timeMs > 0) {
      return 'tracker:${widget.teamId}:live-window:'
          '${firstLivePoint.timeMs ~/ 300000}';
    }
    return _legacyTacticalReviewSessionKey();
  }

  String _legacyTacticalReviewSessionKey() {
    final sessionId = widget.selectedSession?.id ?? 0;
    final startMs = _movementMinTime(widget.localPoints);
    return 'tracker:${widget.teamId}:session:$sessionId:start:$startMs';
  }

  @override
  void dispose() {
    _playTimer?.cancel();
    _tacticalReviewSaveTimer?.cancel();
    unawaited(_flushTacticalReviewSave());
    _tacticalReviewController.dispose();
    super.dispose();
  }

  Set<int> get _dataPlayerIds {
    if (widget.personalMode && widget.selectedPlayer != null) {
      return <int>{
        widget.selectedPlayer!.id,
        ...widget.selectedPlayer!.identityIds,
      }..removeWhere((id) => id <= 0);
    }
    return _movementExpandedPlayerIds(widget.players, _selectedIds);
  }

  List<ActionTrackerGpsPoint> get _playerPoints =>
      _movementPointsForPlayers(widget.localPoints, _dataPlayerIds);
  List<ActionTrackerGpsPoint> get _rangePoints =>
      _movementPointsForRange(_playerPoints, _range);

  TrackerPlayerLoadRow? get _focusedRow {
    if (_selectedIds.length != 1) return null;
    final ids = _dataPlayerIds;
    for (final row in widget.comparisonRows) {
      if (row.playerId != null && ids.contains(row.playerId)) return row;
    }
    return null;
  }

  double get _hsrThreshold {
    final maxSpeed = _focusedRow?.maxSpeedKmh ?? 0;
    if (_individualThresholds && maxSpeed > 0) {
      return math.max(7.0, maxSpeed * .75).toDouble();
    }
    return widget.hsrThresholdKmh;
  }

  double get _sprintThreshold {
    final maxSpeed = _focusedRow?.maxSpeedKmh ?? 0;
    if (_individualThresholds && maxSpeed > 0) {
      return math.max(_hsrThreshold + 1.0, maxSpeed * .90).toDouble();
    }
    return widget.sprintThresholdKmh;
  }

  void _ensureTelemetryCache(
    List<ActionTrackerGpsPoint> points,
    List<_MovementEvent> events,
  ) {
    final selected = _selectedIds.toList()..sort();
    final key = <Object?>[
      points.length,
      points.isEmpty ? 0 : points.first.timeMs,
      points.isEmpty ? 0 : points.last.timeMs,
      _range.start.toStringAsFixed(4),
      _range.end.toStringAsFixed(4),
      selected.join('-'),
      _hsrThreshold.toStringAsFixed(2),
      _sprintThreshold.toStringAsFixed(2),
      widget.field?.id ?? 0,
      widget.heartRate.effectiveSamplesCount,
      widget.heartRate.effectiveMaxBpm,
    ].join('|');
    if (_telemetryCacheKey == key) return;
    _telemetryCacheKey = key;
    _telemetryCachedSectors = _telemetrySectors(
      points,
      widget.field,
      hsrThresholdKmh: _hsrThreshold,
      sprintThresholdKmh: _sprintThreshold,
    );
    _telemetryCachedConfidence =
        _TelemetryConfidence.fromPoints(points, widget.field);
    _telemetryCachedDelta = _TelemetryDelta.fromPoints(
      points,
      hsrThresholdKmh: _hsrThreshold,
      sprintThresholdKmh: _sprintThreshold,
    );
    _telemetryCachedDegradation = _TelemetryDegradation.fromPoints(
      points,
      hsrThresholdKmh: _hsrThreshold,
      sprintThresholdKmh: _sprintThreshold,
    );
    _telemetryCachedMoments =
        _telemetryKeyMoments(points, events, widget.heartRate);
  }


  void _ensureReplayJournalCache(
    List<ActionTrackerGpsPoint> points,
    List<_MovementEvent> movementEvents,
  ) {
    final selected = _dataPlayerIds.toList()..sort();
    final firstRaw = _archivedLiveRawEvents.isEmpty
        ? const <String, dynamic>{}
        : _archivedLiveRawEvents.first;
    final lastRaw = _archivedLiveRawEvents.isEmpty
        ? const <String, dynamic>{}
        : _archivedLiveRawEvents.last;
    final key = <Object?>[
      points.length,
      points.isEmpty ? 0 : points.first.timeMs,
      points.isEmpty ? 0 : points.last.timeMs,
      movementEvents.length,
      _range.start.toStringAsFixed(4),
      _range.end.toStringAsFixed(4),
      selected.join('-'),
      _hsrThreshold.toStringAsFixed(2),
      _sprintThreshold.toStringAsFixed(2),
      widget.field?.id ?? 0,
      widget.heartRate.effectiveSamplesCount,
      widget.heartRate.effectiveMaxBpm,
      _archivedLiveRawEvents.length,
      firstRaw['event_id'] ?? firstRaw['id'] ?? firstRaw['time_ms'] ?? '',
      lastRaw['event_id'] ?? lastRaw['id'] ?? lastRaw['time_ms'] ?? '',
    ].join('|');
    if (_replayJournalCacheKey == key) return;
    _replayJournalCacheKey = key;
    _replayCachedReconstructed = _replayJournalFromMovement(
      points,
      movementEvents,
      widget.heartRate,
      widget.players,
      widget.field,
    );
    _replayCachedArchived = _replayJournalFromArchivedLive(
      _archivedLiveRawEvents,
      points,
      widget.players,
      widget.heartRate,
      selectedPlayerIds: _dataPlayerIds,
    );
    _replayCachedMerged = _mergeReplayJournalEvents(
      _replayCachedArchived,
      _replayCachedReconstructed,
    );
    _replayCachedMarkers = _replayJournalMapMarkers(
      points,
      _replayCachedMerged,
      widget.heartRate,
    );
    _replayCachedGpsHr = _movementGpsHrCorrelations(
      points,
      movementEvents,
      widget.heartRate,
      widget.field,
    );
  }

  @override
  Widget build(BuildContext context) {
    final screenWidth = MediaQuery.sizeOf(context).width;
    final phone = screenWidth < 720;
    // На планшете набор Live-подобных кнопок шире. До 1180 px убираем
    // KPI из этой строки и разрешаем горизонтальный скролл без overflow.
    final compactToolbar = screenWidth < 1180;
    // V191: левое CMR-меню сохраняем на ВСЕХ планшетах и desktop.
    // Скрываем его только на телефоне (<720 px); на компактном планшете
    // колонка становится уже, но пункты и кнопка возврата остаются на месте.
    final desktopInspectorSidebar = screenWidth >= 720;
    final playbackPoints = _matchMode
        ? _movementPointsForPlayers(widget.localPoints, const <int>{})
        : _playerPoints;
    final points = _movementPointsForRange(playbackPoints, _range);
    final local = _LocalTrackAnalysis.fromPoints(points,
        sprintThresholdKmh: _sprintThreshold,
        hsrThresholdKmh: _hsrThreshold);
    final events = _movementEvents(points,
        hsrThresholdKmh: _hsrThreshold,
        sprintThresholdKmh: _sprintThreshold);
    // V146: справа и на поле показывается Replay именно в стиле Live.
    // Реальные сохранённые Live-события имеют приоритет; недостающие моменты
    // восстанавливаются по GPS + Polar, поэтому старые тренировки тоже не пустые.
    final movementJournalEvents = _movementJournalEvents(events);
    _ensureReplayJournalCache(points, movementJournalEvents);
    final reconstructedJournal = _replayCachedReconstructed;
    final archivedJournal = _replayCachedArchived;
    final replayJournal = _replayCachedMerged;
    final journalMarkers = _replayCachedMarkers;
    final replayRedCount = replayJournal.where((event) => event.isRed).length;
    final cardioLinkedMoments =
        journalMarkers.where((marker) => marker.hasHeartRate).length;
    final gpsHrCorrelations = _replayCachedGpsHr;
    final fatigue = _MovementFatigue.fromPoints(points,
        sprintThresholdKmh: _sprintThreshold);
    final useServerHeat = !widget.personalMode &&
        _selectedIds.isEmpty &&
        _range.start <= .0001 &&
        _range.end >= .9999;
    final heat = useServerHeat && widget.points.isNotEmpty
        ? widget.points
        : _heatmapFromGpsStatic(_rangePoints, widget.field);
    final cursorPoint = _matchMode
        ? null
        : _movementPointAtProgress(playbackPoints, _cursor, range: _range);
    final comparisonRows =
        _movementRowsForSelection(widget.comparisonRows, _dataPlayerIds);

    // V192: верхние KPI в режиме Матч считаются ДО текущего положения
    // таймлайна. Для 2-4 выбранных игроков аддитивные показатели суммируются,
    // максимальная скорость берётся максимальной, а для «Вся команда» считаются
    // все треки. Так цифры растут синхронно с повтором, как в Live.
    // V195: один источник истины для KPI во всех режимах карты.
    // Маршрут/Тепло/Матч теперь считают показатели по выбранным игрокам
    // до текущего положения таймлайна одинаковым алгоритмом. Это убирает
    // расхождение «верхние KPI vs правая карточка/режим».
    final cursorMetrics = _replayCursorMetrics(
      allPoints: widget.localPoints,
      playerIds: _dataPlayerIds,
      range: _range,
      cursor: _cursor,
      sprintThresholdKmh: _sprintThreshold,
      hsrThresholdKmh: _hsrThreshold,
      fallbackDurationSec: widget.selectedSession?.durationSec ?? 0,
    );

    final inspectorDistance = cursorMetrics.distanceM;
    final inspectorMaxSpeed = cursorMetrics.maxSpeedKmh;
    final inspectorSprintCount = cursorMetrics.sprintCount;
    final inspectorHir = cursorMetrics.hirDistanceM;
    final inspectorAccel = cursorMetrics.accelCount;
    final inspectorDecel = cursorMetrics.decelCount;
    final inspectorTurns = cursorMetrics.turnCount;
    final inspectorLoad = cursorMetrics.loadScore;
    final inspectorExplosive = cursorMetrics.explosiveActions;
    final inspectorDurationSec = cursorMetrics.durationSec;
    final inspectorAvgSpeed = cursorMetrics.avgSpeedKmh;
    final inspectorFatigueLabel = cursorMetrics.fatigueLabel;
    final inspectorChartPoints = _matchMode
        ? _movementPointsForRange(
            _movementPointsForPlayers(widget.localPoints, _dataPlayerIds),
            _range,
          )
        : points;

    final selectedUiPlayers = widget.players.where((player) {
      if (_selectedIds.isEmpty) return false;
      final identities = <int>{player.id, ...player.identityIds};
      return identities.any(_selectedIds.contains);
    }).toList(growable: false);
    final replaySelectionLabel = widget.personalMode
        ? _shortPlayerName(
            widget.selectedPlayer?.displayName ??
                widget.selectedPlayer?.name ??
                'Игрок',
          )
        : (_selectedIds.isEmpty
            ? 'Вся команда'
            : (selectedUiPlayers.length == 1
                ? _shortPlayerName(
                    selectedUiPlayers.first.displayName ??
                        selectedUiPlayers.first.name,
                  )
                : '${selectedUiPlayers.isEmpty ? _selectedIds.length : selectedUiPlayers.length} игрока'));
    final replaySelectionCount = widget.personalMode
        ? 1
        : (_selectedIds.isEmpty
            ? _movementVisiblePlayers(
                widget.players, widget.comparisonRows, widget.selectedSession)
                .length
            : (selectedUiPlayers.isEmpty
                ? _selectedIds.length
                : selectedUiPlayers.length));

    final matchTargetTime = _matchMode
        ? _movementTimeAtProgress(
            playbackPoints, _cursor.clamp(_range.start, _range.end).toDouble())
        : 0;
    final matchFrames = _matchMode
        ? _matchPlaybackFrames(
            playbackPoints, widget.players, widget.comparisonRows, matchTargetTime)
        : const <_MatchPlaybackFrame>[];

    // V195: карточки игроков сверху во всех desktop/tablet режимах и список
    // «Игроки» справа используют ОДНУ карту накопительных метрик к таймлайну.
    // Это устраняет расхождение 634 м / 1.44 км и 26.7 / 19.7 км/ч.
    final playerCursorMetrics = <int, _ReplayCursorMetrics>{};
    if (desktopInspectorSidebar) {
      final visiblePlayers = _movementVisiblePlayers(
        widget.players,
        widget.comparisonRows,
        widget.selectedSession,
      );
      for (final player in visiblePlayers) {
        final ids = <int>{player.id, ...player.identityIds}
          ..removeWhere((id) => id <= 0);
        playerCursorMetrics[player.id] = _replayCursorMetrics(
          allPoints: widget.localPoints,
          playerIds: ids,
          range: _range,
          cursor: _cursor,
          sprintThresholdKmh: _sprintThreshold,
          hsrThresholdKmh: _hsrThreshold,
          fallbackDurationSec: widget.selectedSession?.durationSec ?? 0,
        );
      }
    }
    _ensureTelemetryCache(points, events);
    final telemetrySectors = _telemetryCachedSectors;
    final telemetryConfidence = _telemetryCachedConfidence;
    final telemetryDelta = _telemetryCachedDelta;
    final telemetryDegradation = _telemetryCachedDegradation;
    final telemetryMoments = _telemetryCachedMoments;
    final telemetryTeamShape =
        _TelemetryTeamShape.fromFrames(matchFrames, widget.field);
    final telemetryAlerts = <_TelemetryAlert>[
      ..._telemetryAlerts(
        confidence: telemetryConfidence,
        delta: telemetryDelta,
        degradation: telemetryDegradation,
        teamShape: telemetryTeamShape,
        heartRate: widget.heartRate,
        frames: matchFrames,
      ),
      ..._telemetryWeatherAlerts(
        _telemetryWeather,
        delta: telemetryDelta,
        degradation: telemetryDegradation,
      ),
    ]..sort((a, b) => b.level.compareTo(a.level));
    final telemetryGhost = _ghostEnabled
        ? (widget.personalMode
            ? _movementPointAtProgress(
                widget.personalGhostPoints,
                _cursor,
                range: _range,
              )
            : _telemetryGhostPoint(
                widget.localPoints,
                _selectedIds,
                widget.players,
                _cursor,
                _range))
        : null;
    // V119.1: статичные P1/P2/... убраны. Pit Wall остаётся живым:
    // форма команды, HUD, сигналы, события и общий курсор телеметрии.
    const telemetryPitMarkers = <ActionTrackerGpsPoint>[];
    final telemetryStartMs = _movementMinTime(points);
    final telemetryCursorMs = _movementTimeAtProgress(
      playbackPoints,
      _cursor.clamp(_range.start, _range.end).toDouble(),
    );
    final geoTracks = _geoBaseLayer == TrackerGeoBaseLayer.pitch ||
            !Tracker2GisMapLayer.hasMapKey
        ? const <TrackerGeoTrack>[]
        : _analyticsGeoTracks(
            points: playbackPoints,
            players: widget.players,
            selectedIds: _selectedIds,
          );
    final telemetryPlayerNames = widget.players
        .where((player) => _selectedIds.isEmpty ||
            _selectedIds.contains(player.id) ||
            player.identityIds.any(_selectedIds.contains))
        .map((player) => player.name)
        .where((name) => name.trim().isNotEmpty)
        .toList(growable: false);
    final telemetryPayload = <String, dynamic>{
      'source': 'tracker_f1_telemetry',
      'session_id': widget.selectedSession?.id,
      'session_title': widget.selectedSession?.title ?? 'Тренировка',
      'player_ids': _selectedIds.toList()..sort(),
      'player_names': telemetryPlayerNames,
      'selection_mode': widget.personalMode
          ? 'single_player'
          : (_selectedIds.isEmpty
              ? 'team'
              : (_selectedIds.length == 1 ? 'single_player' : 'players')),
      'cursor_time_ms': telemetryCursorMs,
      'elapsed_ms': math.max(0, telemetryCursorMs - telemetryStartMs),
      'recording_duration_ms': math.max(0, _movementMaxTime(points) - telemetryStartMs),
      'gps_confidence': telemetryConfidence.score,
      'gps_gaps': telemetryConfidence.gaps,
      'delta_pace_pct': telemetryDelta.deltaPct,
      'degradation_pct': telemetryDegradation.deltaPct,
      'team_compactness_pct': telemetryTeamShape.compactness,
      'team_shape_length_m': telemetryTeamShape.lengthM,
      'team_shape_width_m': telemetryTeamShape.widthM,
      'key_moments': telemetryMoments
          .map((moment) => moment.toJson(telemetryStartMs))
          .toList(growable: false),
      // V145: ИИ получает не отдельные GPS и Polar, а синхронизированные
      // пары «движение + внутренняя реакция» по времени события.
      'heart_rate_avg_bpm': widget.heartRate.effectiveAvgBpm,
      'heart_rate_max_bpm': widget.heartRate.effectiveMaxBpm,
      'heart_rate_samples_count': widget.heartRate.effectiveSamplesCount,
      'gps_hr_linked_moments': gpsHrCorrelations,
      'replay_journal_source': archivedJournal.isNotEmpty
          ? 'archived_live_plus_reconstructed'
          : 'reconstructed_from_gps_hr',
      'replay_journal_events': replayJournal
          .take(80)
          .map((event) => <String, dynamic>{
                'source': event.source,
                'kind': event.kind,
                'severity': event.severity,
                'title': event.title,
                'detail': event.detail,
                'time_ms': event.timeMs,
                if (event.elapsedMs != null) 'elapsed_ms': event.elapsedMs,
                if (event.playerId != null) 'player_id': event.playerId,
                'player_name': event.playerName,
                'speed_kmh': event.speedKmh,
                'acceleration_mps2': event.accelerationMps2,
                if (event.hrProfile?.startBpm != null)
                  'hr_start_bpm': event.hrProfile!.startBpm,
                if (event.hrProfile?.peakBpm != null)
                  'hr_peak_bpm': event.hrProfile!.peakBpm,
                if (event.hrProfile?.after30Bpm != null)
                  'hr_after_30s_bpm': event.hrProfile!.after30Bpm,
              })
          .toList(growable: false),
      'pit_wall_alerts': telemetryAlerts
          .map((alert) => <String, dynamic>{
                'level': alert.level,
                'title': alert.title,
                'detail': alert.detail,
              })
          .toList(growable: false),
      if (_telemetryWeather != null) ..._telemetryWeather!.toJson(),
      if (points.isNotEmpty) 'latitude': points.first.latitude,
      if (points.isNotEmpty) 'longitude': points.first.longitude,
      if ((widget.field?.title ?? '').trim().isNotEmpty)
        'location_name': widget.field!.title.trim(),
      'tactical_review_count': _tacticalReviewController.count,
      'tactical_review_annotations': _tacticalReviewController.exportJson(),
      'telemetry_sync': true,
    };

    final focusedAiPlayerId = _selectedIds.length == 1
        ? _selectedIds.first
        : 0;
    final focusedAiNames = focusedAiPlayerId <= 0
        ? const <String>[]
        : widget.players
            .where((player) => player.id == focusedAiPlayerId ||
                player.identityIds.contains(focusedAiPlayerId))
            .map((player) => player.name.trim())
            .where((name) => name.isNotEmpty)
            .toList(growable: false);
    final String? focusedAiPlayerName =
        focusedAiNames.isEmpty ? null : focusedAiNames.first;
    final aiPayload = _inlineAiPayload.isEmpty
        ? <String, dynamic>{...telemetryPayload, 'telemetry_engineer': true}
        : _inlineAiPayload;
    final aiPrompt = _inlineAiPrompt.isNotEmpty
        ? _inlineAiPrompt
        : 'Работай как инженер футбольной телеметрии. Анализируй только переданный контекст сессии и не выдумывай отсутствующие данные.';


    Widget inspectorToolbarRow() => Row(
        mainAxisSize:
            compactToolbar ? MainAxisSize.min : MainAxisSize.max,
        children: [
          _MapModeButton(
              label: widget.personalMode ? 'Запись' : 'Матч',
              icon: widget.personalMode
                  ? Icons.play_circle_outline_rounded
                  : Icons.sports_soccer_rounded,
              active: widget.personalMode ? _matchMode : _mapPresentation == 'match',
              onTap: () => setState(() {
                    _matchMode = true;
                    _heatMode = false;
                    _mapPresentation = 'match';
                    _matchJournalMode = true;
                    _matchPlayersMode = false;
                    _matchCardioMode = false;
                    _matchCompareMode = false;
                    _analysisDrawerMode = null;
                    _sideMode = 'events';
                    _pitWallMode = false;
                    _selectedPoint = null;
                  })),
          _MapModeButton(
              label: 'Маршрут',
              icon: Icons.timeline_rounded,
              active: widget.personalMode
                  ? (!_heatMode && !_matchMode)
                  : _mapPresentation == 'route',
              onTap: () => setState(() {
                    // V197: повторное нажатие отжимает слой и возвращает
                    // базовый вид «Матч/Запись», не меняя правый инспектор.
                    if (widget.personalMode) {
                      final wasActive = !_heatMode && !_matchMode;
                      _heatMode = false;
                      _matchMode = wasActive;
                    } else {
                      final wasActive = _mapPresentation == 'route';
                      _matchMode = true;
                      _heatMode = false;
                      _mapPresentation = wasActive ? 'match' : 'route';
                    }
                  })),
          _MapModeButton(
              label: 'Тепло',
              icon: Icons.local_fire_department_rounded,
              active: widget.personalMode
                  ? (_heatMode && !_matchMode)
                  : _mapPresentation == 'heat',
              onTap: () => setState(() {
                    // V197: heatmap тоже работает как переключаемый слой.
                    if (widget.personalMode) {
                      final wasActive = _heatMode && !_matchMode;
                      _heatMode = !wasActive;
                      _matchMode = wasActive;
                    } else {
                      final wasActive = _mapPresentation == 'heat';
                      _matchMode = true;
                      _heatMode = !wasActive;
                      _mapPresentation = wasActive ? 'match' : 'heat';
                    }
                  })),
          _MapModeButton(
              label: _perspective3d ? '3D PRO' : '2D',
              icon: _perspective3d
                  ? Icons.view_in_ar_rounded
                  : Icons.grid_view_rounded,
              active: _perspective3d,
              onTap: () => setState(() {
                    _perspective3d = !_perspective3d;
                  })),
          _MapModeButton(
              label: 'Метки',
              icon: Icons.place_rounded,
              active: _showJournalMarkers,
              onTap: () => setState(() {
                    _showJournalMarkers = !_showJournalMarkers;
                  })),
          _MapModeButton(
              label: 'Разбор',
              icon: Icons.draw_rounded,
              active: _reviewMode,
              emphasis: _reviewMode,
              onTap: () {
                if (!_reviewMode) {
                  _playTimer?.cancel();
                }
                setState(() {
                  _reviewMode = !_reviewMode;
                  if (_reviewMode) {
                    _playing = false;
                    _selectedPoint = null;
                    _tacticalReviewController.setTool(TgAnalyticsTool.select);
                  }
                });
              }),
          _MapModeButton(
              label: 'HUD',
              icon: Icons.dashboard_customize_rounded,
              active: _showReplayHud,
              onTap: () => setState(() {
                    _showReplayHud = !_showReplayHud;
                  })),
          if (widget.personalMode && widget.personalGhostPoints.isNotEmpty)
            _MapModeButton(
                label: 'Ghost',
                icon: Icons.blur_on_rounded,
                active: _ghostEnabled,
                onTap: () => setState(() {
                      _ghostEnabled = !_ghostEnabled;
                      _selectedPoint = null;
                    })),
          _MapModeButton(
              label: 'Пит-уолл',
              icon: Icons.monitor_heart_rounded,
