    Widget inspectorToolbar() {
      if (!compactToolbar) return inspectorToolbarRow();
      return SingleChildScrollView(
        scrollDirection: Axis.horizontal,
        physics: const BouncingScrollPhysics(),
        child: inspectorToolbarRow(),
      );
    }

    Widget inspectorKpiRow() {
      // V196: пороги убраны из рабочей шапки — KPI начинаются сразу слева.
      return _ReplayTopMetricsStrip(
        label: replaySelectionLabel,
        playerCount: replaySelectionCount,
        metrics: cursorMetrics,
      );
    }

    Widget inspectorDesktopSidebar() {
      final sidebarWidth = screenWidth >= 1500
          ? 236.0
          : (screenWidth >= 1180
              ? 220.0
              : (screenWidth >= 980
                  ? 200.0
                  : (screenWidth >= 820 ? 184.0 : 168.0)));

      void setGeoLayer(TrackerGeoBaseLayer layer) {
        setState(() {
          _geoBaseLayer = layer;
          if (layer != TrackerGeoBaseLayer.pitch) {
            _heatMode = false;
            _perspective3d = false;
          }
          _selectedPoint = null;
        });
      }

      void toggleReview() {
        if (!_reviewMode) {
          _playTimer?.cancel();
        }
        setState(() {
          _reviewMode = !_reviewMode;
          if (_reviewMode) {
            _playing = false;
            _selectedPoint = null;
            _tacticalReviewController.setTool(TgAnalyticsTool.select);
          }
        });
      }

      void togglePitWall() {
        setState(() {
          final closingPitWall = _sideMode == 'pit';
          _analysisDrawerMode = null;
          _pitWallMode = !closingPitWall;
          _sideMode = closingPitWall ? 'events' : 'pit';
          if (!closingPitWall) {
            _matchJournalMode = false;
            _matchPlayersMode = false;
            _matchCardioMode = false;
            _matchCompareMode = false;
          } else if (_matchMode) {
            _matchJournalMode = true;
          }
          _selectedPoint = null;
        });
      }

      void openInlineAi() {
        final playerFilter = telemetryPlayerNames.isEmpty
            ? 'команда'
            : telemetryPlayerNames.join(', ');
        final sessionTitle = widget.selectedSession?.title ?? 'Тренировка';
        setState(() {
          _inlineAiPayload = <String, dynamic>{
            ...telemetryPayload,
            'telemetry_engineer': true,
            'player_filter': playerFilter,
          };
          _inlineAiPrompt =
              'Работай как инженер футбольной телеметрии по тренировке «$sessionTitle». '
              'Фильтр игроков: $playerFilter. Используй Pit Wall-контекст: качество GPS, delta темпа, деградацию HSR, форму команды, мини-сектора, ключевые моменты, скорость, ускорения/торможения, Polar, погоду и местоположение. '
              'Обязательно анализируй GPS и Polar совместно по gps_hr_linked_moments: для интенсивных эпизодов сопоставляй скорость/ускорение/зону поля с HR стартом, пиком и восстановлением через 30 секунд. Не делай медицинских выводов и не используй универсальные возрастные пороги, если они не переданы в контексте. '
              'Сначала назови 3 главных сигнала, затем объясни каждый по времени и данным, выдели сомнительные GPS-участки, предложи 3 действия тренеру и моменты для видеоразбора. Не выдумывай отсутствующие каналы.';
          _inlineAiExpanded = true;
          _inlineAiRevision++;
        });
      }

