        return Padding(
          padding: const EdgeInsets.fromLTRB(10, 14, 10, 7),
          child: Text(
            label,
            style: AppTypography.custom(
              size: 9.5,
              weight: FontWeight.w600,
              color: _AA.muted2,
              height: 1.22,
              letterSpacing: 0,
            ),
          ),
        );
      }

