                        if (widget.personalMode) {
                          final wasActive = !_heatMode && !_matchMode;
                          _heatMode = false;
                          _matchMode = wasActive;
                        } else {
                          final wasActive = _mapPresentation == 'route';
                          _matchMode = true;
                          _heatMode = false;
