                    const SizedBox(height: 4),
                    _MapSidebarItem(
                      label: 'Тепло',
                      subtitle: 'heatmap поверх того же поля матча',
                      icon: Icons.local_fire_department_rounded,
                      active: widget.personalMode
                          ? (_heatMode && !_matchMode)
                          : _mapPresentation == 'heat',
                      onTap: () => setState(() {
                        _geoBaseLayer = TrackerGeoBaseLayer.pitch;
