                        icon: Icons.my_location_rounded,
                        active: _analysisDrawerMode == 'point',
                        emphasis: _analysisDrawerMode == 'point',
                        onTap: () => setState(() {
                          _analysisDrawerMode = 'point';
                          _matchJournalMode = false;
