            active: _matchJournalMode && !_matchCompareMode,
            badge: replayJournal.length,
            dangerBadge: replayRedCount > 0,
            onTap: () => setState(() {
              _matchJournalMode = true;
              _matchPlayersMode = false;
              _matchCardioMode = false;
              _matchCompareMode = false;
              _analysisDrawerMode = null;
              _sideMode = 'events';
              _pitWallMode = false;
            }),
          ),
        ),
        const SizedBox(width: 3),
        Expanded(
          child: _CompactInspectorTab(
            label: 'Скорость',
            icon: Icons.speed_rounded,
            active: speedActive,
            onTap: () => setState(() {
              _matchJournalMode = false;
              _matchPlayersMode = false;
              _matchCardioMode = false;
              _matchCompareMode = false;
              _analysisDrawerMode = null;
              _sideMode = 'events';
              _pitWallMode = false;
            }),
          ),
        ),
        const SizedBox(width: 3),
        Expanded(
