    void selectMatchRosterPlayer(TrackerPlayerOption player) {
      final identityIds = <int>{player.id, ...player.identityIds};
      final alreadyFocused = _selectedIds.any(identityIds.contains);
      final next = Set<int>.from(_selectedIds);
      if (_compareMode) {
        if (alreadyFocused) {
          next.removeWhere(identityIds.contains);
        } else if (next.length < 4) {
          next.add(player.id);
        }
      } else {
        next
          ..clear()
          ..addAll(alreadyFocused && _selectedIds.length == 1
              ? const <int>{}
              : <int>{player.id});
      }
      setState(() {
        _selectedIds = next;
        _selectedPoint = null;
        if (_selectedIds.length >= 2) _compareMode = true;
      });
      widget.onPlayerSelectionChanged(Set<int>.from(next));
    }

