    Widget analysisDetailDrawer() {
      final mode = _analysisDrawerMode ?? 'events';
      late final String title;
      late final String subtitle;
      late final IconData icon;
      late final Widget body;

      if (mode == 'sprints') {
        final sprintEvents = events
            .where((event) => event.kind == 'sprint')
            .toList(growable: false);
        title = 'Спринты';
        subtitle = '${sprintEvents.length} эпизодов · клик → момент на поле';
        icon = Icons.flash_on_rounded;
        body = _MovementEventList(
          events: sprintEvents,
          points: points,
          field: widget.field,
          heartRate: widget.heartRate,
          onSelect: _selectEvent,
        );
      } else if (mode == 'turns') {
        final turnEvents = events
            .where((event) => event.kind == 'turn')
            .toList(growable: false);
        title = 'Повороты';
        subtitle = '${turnEvents.length} эпизодов · клик → момент на поле';
        icon = Icons.change_circle_rounded;
        body = _MovementEventList(
          events: turnEvents,
          points: points,
          field: widget.field,
          heartRate: widget.heartRate,
          onSelect: _selectEvent,
        );
      } else if (mode == 'point') {
        title = _selectedPoint == null ? 'Данные сессии' : 'Точка GPS';
        subtitle = _selectedPoint == null
            ? 'выберите точку на поле для подробностей'
            : '#${_selectedPoint!.index + 1} · ${_movementMatchClockLabel(math.max(0, _selectedPoint!.timeMs - _movementMinTime(_playerPoints)))}';
        icon = Icons.my_location_rounded;
        body = _selectedPoint == null
            ? _MovementSessionInfo(
                local: local,
                fatigue: fatigue,
                events: events,
                selectedIds: _selectedIds,
                selectedPlayer: widget.selectedPlayer,
                selectedSession: widget.selectedSession,
                field: widget.field,
                pointsCount: points.length,
                timeRange: _movementRecordingSpanLabel(
                  points,
                  fallbackDurationSec: widget.selectedSession?.durationSec ?? 0,
                ),
                activityLabel: _activityFilterLabel(_filter),
                onOpenCalibration: widget.onOpenCalibration,
              )
            : _SelectedMapPointCard(
                info: _selectedPoint!,
                onClear: () => setState(() => _selectedPoint = null),
                onPrevious: () => _stepPoint(-1),
                onNext: () => _stepPoint(1),
              );
      } else {
        title = 'Журнал';
        subtitle = '${replayJournal.length} событий · красных $replayRedCount';
        icon = Icons.timeline_rounded;
        body = _ReplayJournalPanel(
          events: replayJournal,
          selectedId: _selectedReplayEventId,
          loadingArchived: _archivedLiveLoading,
          archivedCount: archivedJournal.length,
          reconstructedCount: reconstructedJournal.length,
          trackStartMs: _movementMinTime(points),
          players: widget.players,
          onSelect: _selectReplayEvent,
        );
      }

      return Container(
        decoration: BoxDecoration(
          color: Colors.white,
          borderRadius: BorderRadius.circular(15),
          border: Border.all(color: _AA.line),
        ),
        child: Column(children: [
          Container(
            height: 54,
            padding: const EdgeInsets.symmetric(horizontal: 12),
            decoration: const BoxDecoration(
              border: Border(bottom: BorderSide(color: _AA.line)),
            ),
            child: Row(children: [
              Icon(icon, color: _AA.green, size: 17),
              const SizedBox(width: 7),
              Expanded(
                child: Column(
                  mainAxisAlignment: MainAxisAlignment.center,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      title,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: _AText.body(
                        11.2,
                        color: _AA.text,
                        weight: FontWeight.w700,
                      ),
                    ),
                    const SizedBox(height: 2),
                    Text(
                      subtitle,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: _AText.caption(size: 8.8, color: _AA.muted),
                    ),
                  ],
                ),
              ),
              _NoHoverTap(
                onTap: () => setState(() {
                  _analysisDrawerMode = null;
                  if (_matchMode) _matchJournalMode = true;
                }),
                borderRadius: BorderRadius.circular(99),
                child: Container(
                  width: 28,
                  height: 28,
                  alignment: Alignment.center,
                  decoration: const BoxDecoration(
                    color: _AA.soft,
                    shape: BoxShape.circle,
                  ),
                  child: const Icon(
                    Icons.close_rounded,
                    color: _AA.muted,
                    size: 16,
                  ),
                ),
              ),
            ]),
          ),
          Expanded(
            child: Padding(
              padding: const EdgeInsets.all(7),
              child: body,
            ),
          ),
        ]),
      );
    }

