      child: inspectorContent,
      expanded: _inlineAiExpanded,
      onToggle: () => setState(() {
        _inlineAiExpanded = !_inlineAiExpanded;
        if (_inlineAiExpanded) _inlineAiRevision++;
      }),
      clubId: widget.clubId,
      userId: widget.userId,
      teamId: widget.teamId,
      clubName: widget.clubName,
      teamName: widget.teamName,
      contextTitle: 'СПОРТОТЕКА ИИ',
      contextSubtitle: 'ИИ-инженер телеметрии · ${widget.selectedSession?.title ?? 'Сессия'}',
      initialPrompt: aiPrompt,
      initialPayload: aiPayload,
      panelKey: ValueKey<String>(
        'tracker_map_inline_ai_${widget.selectedSession?.id ?? 0}_${_inlineAiRevision}',
      ),
      bottomInset: 8,
      playerOnlyMode: focusedAiPlayerId > 0,
      playerId: focusedAiPlayerId > 0 ? focusedAiPlayerId : null,
      playerName: focusedAiPlayerName,
      onNavigate: (target, payload) {},
    );
  }

  void _selectEvent(_MovementEvent event) {
    final keepJournalVisible =
        _sideMode == 'events' || _sideMode == 'sprints' || _sideMode == 'turns';
    setState(() {
      _cursor = _movementProgressForTime(_playerPoints, event.startTimeMs)
          .clamp(_range.start, _range.end)
          .toDouble();
      _selectedPoint = _mapPointInfoFromTime(
        _rangePoints,
        event.startTimeMs,
        widget.field,
        _hsrThreshold,
        _sprintThreshold,
        heartRate: widget.heartRate,
        allTrackPoints: _playerPoints,
      );
      if (_selectedPoint != null && !keepJournalVisible) _sideMode = 'point';
    });
  }


  void _selectReplayEvent(_ReplayJournalEvent event) {
    final playbackPoints = _matchMode
        ? _movementPointsForPlayers(widget.localPoints, const <int>{})
        : _playerPoints;
    final rangedPoints = _movementPointsForRange(playbackPoints, _range);
    setState(() {
      _selectedReplayEventId = event.id;
      _cursor = _movementProgressForTime(playbackPoints, event.timeMs)
          .clamp(_range.start, _range.end)
          .toDouble();
      _selectedPoint = _mapPointInfoFromTime(
        rangedPoints,
        event.timeMs,
        widget.field,
        _hsrThreshold,
        _sprintThreshold,
        heartRate: widget.heartRate,
        allTrackPoints: playbackPoints,
      );
      // Как в Live: нажатие на событие фиксирует карту на моменте, но журнал
      // справа не исчезает и не заменяется карточкой отдельной GPS-точки.
      _sideMode = 'events';
      if (_matchMode) {
        _matchJournalMode = true;
        _matchPlayersMode = false;
        _matchCardioMode = false;
        _matchCompareMode = false;
      } else {
        _analysisDrawerMode = 'events';
      }
    });
  }

  void _stepPoint(int direction) {
    final points = _rangePoints;
    if (_selectedPoint == null || points.isEmpty) return;
    var currentIndex = points.indexWhere((p) =>
        p.timeMs == _selectedPoint!.timeMs &&
        (p.playerId == _selectedPoint!.playerId || _selectedPoint!.playerId == null));
    if (currentIndex < 0) currentIndex = _selectedPoint!.index.clamp(0, points.length - 1).toInt();
    final next = (currentIndex + direction).clamp(0, points.length - 1).toInt();
    final info = _mapPointInfoFromIndex(points, next, widget.field,
        _hsrThreshold, _sprintThreshold,
        heartRate: widget.heartRate, allTrackPoints: _playerPoints);
    if (info == null) return;
    setState(() {
      _selectedPoint = info;
      _cursor = _movementProgressForTime(_playerPoints, info.timeMs);
    });
  }

  void _togglePlayback() {
    if (_playing) {
      _playTimer?.cancel();
      setState(() => _playing = false);
      return;
    }
    final playbackPoints = _matchMode
        ? _movementPointsForPlayers(widget.localPoints, const <int>{})
        : _playerPoints;
    if (playbackPoints.length < 2) return;
    setState(() {
      _playing = true;
      if (_cursor < _range.start || _cursor >= _range.end) _cursor = _range.start;
    });
    _playTimer = Timer.periodic(const Duration(milliseconds: 200), (_) {
      if (!mounted) return;
      final durationMs = math.max(
          1, _movementMaxTime(playbackPoints) - _movementMinTime(playbackPoints));
      final sessionAdvanceMs = 200.0 * _playbackRate;
      final next = _cursor + sessionAdvanceMs / durationMs;
      if (next >= _range.end) {
        _playTimer?.cancel();
        setState(() {
          _cursor = _range.end;
          _playing = false;
        });
      } else {
        setState(() => _cursor = next);
      }
    });
  }
}

