class _MapPlayerStrip extends StatelessWidget {
  const _MapPlayerStrip({
    required this.players,
    required this.rows,
    required this.session,
    required this.selectedIds,
    required this.compareMode,
    required this.onCompareModeChanged,
    required this.onChanged,
    this.cursorMetricsByPlayer = const <int, _ReplayCursorMetrics>{},
    this.twoRows = false,
  });

  final List<TrackerPlayerOption> players;
  final List<TrackerPlayerLoadRow> rows;
  final TrackerSessionModel? session;
  final Set<int> selectedIds;
  final bool compareMode;
  final ValueChanged<bool> onCompareModeChanged;
  final ValueChanged<Set<int>> onChanged;
  final Map<int, _ReplayCursorMetrics> cursorMetricsByPlayer;
  final bool twoRows;

  @override
  Widget build(BuildContext context) {
    final visiblePlayers = _movementVisiblePlayers(players, rows, session);

    Widget compareButton({double width = 64, double height = 48}) {
      return _NoHoverTap(
        onTap: () => onCompareModeChanged(true),
        borderRadius: BorderRadius.circular(12),
        child: Container(
          width: width,
          height: height,
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: compareMode ? _AA.greenSoft : _AA.card,
            borderRadius: BorderRadius.circular(12),
            border: Border.all(
              color: compareMode ? _AA.greenLine : _AA.line,
            ),
          ),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            mainAxisSize: MainAxisSize.min,
            children: [
              Icon(
                Icons.compare_arrows_rounded,
                color: compareMode ? _AA.green : _AA.muted,
                size: 18,
              ),
              const SizedBox(height: 3),
              Text(
                'Сравнить',
                style: _AText.body(
                  10.2,
                  color: compareMode ? _AA.green : _AA.text,
                  weight: FontWeight.w600,
                ),
              ),
              if (compareMode) ...[
                const SizedBox(height: 2),
                Text(
                  '${selectedIds.length}/4',
                  style: _AText.caption(size: 9.5, color: _AA.muted),
                ),
              ],
            ],
          ),
        ),
      );
    }

    if (twoRows) {
      return Container(
        color: Colors.white,
        padding: const EdgeInsets.fromLTRB(5, 4, 5, 4),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.stretch,
          children: [
            _MapPlayerCard.team(
              active: selectedIds.isEmpty,
              rowCount: visiblePlayers.length,
              timelineAware: cursorMetricsByPlayer.isNotEmpty,
              cardWidth: 126,
              cardHeight: 102,
              onTap: () {
                onChanged(<int>{});
                if (compareMode) onCompareModeChanged(false);
              },
            ),
            const SizedBox(width: 6),
            Expanded(
              child: SingleChildScrollView(
                scrollDirection: Axis.horizontal,
                physics: const BouncingScrollPhysics(),
                child: SizedBox(
                  height: 102,
                  child: Wrap(
                    direction: Axis.vertical,
                    spacing: 6,
                    runSpacing: 6,
                    children: [
                      for (final player in visiblePlayers)
                        _MapPlayerCard(
                          player: player,
                          row: _movementRowForPlayer(rows, player),
                          cursorMetrics: cursorMetricsByPlayer[player.id],
                          active: selectedIds.contains(player.id),
                          compareMode: compareMode,
                          cardWidth: 154,
                          cardHeight: 48,
                          onTap: () {
                            if (!compareMode) {
                              onChanged(<int>{player.id});
                              return;
                            }
                            final next = Set<int>.from(selectedIds);
                            if (next.contains(player.id)) {
                              next.remove(player.id);
                            } else if (next.length < 4) {
                              next.add(player.id);
                            }
                            onChanged(next);
                          },
                        ),
                    ],
                  ),
                ),
              ),
            ),
            const SizedBox(width: 6),
            compareButton(width: 72, height: 102),
          ],
        ),
      );
    }

    return Container(
      color: Colors.white,
      padding: const EdgeInsets.fromLTRB(5, 4, 5, 4),
      child: Row(children: [
        _MapPlayerCard.team(
          active: selectedIds.isEmpty,
          rowCount: visiblePlayers.length,
          timelineAware: cursorMetricsByPlayer.isNotEmpty,
          onTap: () {
            onChanged(<int>{});
            if (compareMode) onCompareModeChanged(false);
          },
        ),
        const SizedBox(width: 6),
        Expanded(
          child: ListView.separated(
            scrollDirection: Axis.horizontal,
            itemCount: visiblePlayers.length,
            separatorBuilder: (_, __) => const SizedBox(width: 6),
            itemBuilder: (context, index) {
              final player = visiblePlayers[index];
              final row = _movementRowForPlayer(rows, player);
              final active = selectedIds.contains(player.id);
              return _MapPlayerCard(
                player: player,
                row: row,
                cursorMetrics: cursorMetricsByPlayer[player.id],
                active: active,
                compareMode: compareMode,
                onTap: () {
                  if (!compareMode) {
                    onChanged(<int>{player.id});
                    return;
                  }
                  final next = Set<int>.from(selectedIds);
                  if (next.contains(player.id)) {
                    next.remove(player.id);
                  } else if (next.length < 4) {
                    next.add(player.id);
                  }
                  onChanged(next);
                },
              );
            },
          ),
        ),
        const SizedBox(width: 6),
        compareButton(),
      ]),
    );
  }
}

class _MapPlayerCard extends StatelessWidget {
  const _MapPlayerCard({
    required this.player,
    required this.row,
    required this.active,
    required this.compareMode,
    required this.onTap,
    this.cursorMetrics,
    this.cardWidth,
    this.cardHeight = 48,
  })  : team = false,
        rowCount = 0,
        timelineAware = false;

  const _MapPlayerCard.team({
    required this.active,
    required this.rowCount,
    required this.onTap,
    this.timelineAware = false,
    this.cardWidth,
    this.cardHeight = 48,
  })  : player = null,
        row = null,
        cursorMetrics = null,
        compareMode = false,
        team = true;

  final TrackerPlayerOption? player;
  final TrackerPlayerLoadRow? row;
  final _ReplayCursorMetrics? cursorMetrics;
  final bool active;
  final bool compareMode;
  final VoidCallback onTap;
  final bool team;
  final int rowCount;
  final bool timelineAware;
  final double? cardWidth;
  final double cardHeight;

  @override
  Widget build(BuildContext context) {
    final playerDisplayName =
        (player?.displayName ?? player?.name ?? row?.playerName ?? 'Игрок').trim();
    final name = team ? 'Вся команда' : _shortPlayerName(playerDisplayName);
    final avatar = player?.avatar ?? row?.avatar;
    final initials = team
        ? 'КОМ'
        : playerDisplayName
            .trim()
            .split(RegExp(r'\s+'))
            .where((e) => e.isNotEmpty)
            .take(2)
            .map((e) => e.substring(0, 1))
            .join()
            .toUpperCase();
    final number = (player?.number ?? '').trim();
    final distance = cursorMetrics?.distanceM ?? row?.distanceM ?? 0.0;
    final maxSpeed = cursorMetrics?.maxSpeedKmh ?? row?.maxSpeedKmh ?? 0.0;
    final sprints = cursorMetrics?.sprintCount ?? row?.sprintCount ?? 0;

    return _NoHoverTap(
      onTap: onTap,
      borderRadius: BorderRadius.circular(12),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 150),
        width: cardWidth ?? (team ? 126 : 166),
        height: cardHeight,
        padding: const EdgeInsets.fromLTRB(6, 4, 6, 4),
        decoration: BoxDecoration(
          color: active ? _AA.greenSoft : _AA.soft,
          borderRadius: BorderRadius.circular(12),
          // V117.2: как в Live — без тяжёлой рамки вокруг каждой карточки.
          border: active ? Border.all(color: _AA.greenLine, width: 1) : null,
        ),
        child: Row(children: [
          Stack(
            clipBehavior: Clip.none,
            children: [
              Container(
                width: 32,
                height: 32,
                clipBehavior: Clip.antiAlias,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  shape: BoxShape.circle,
                  color: Colors.white,
                  border: Border.all(
                    color: active ? _AA.greenLine : _AA.line,
                    width: active ? 2 : 1,
                  ),
                ),
                child: team
                    ? const Icon(Icons.groups_rounded, color: _AA.green, size: 20)
                    : (avatar != null && avatar.trim().isNotEmpty
                        ? Image.network(
                            avatar,
                            fit: BoxFit.cover,
                            width: 28,
                            height: 28,
                            errorBuilder: (_, __, ___) => Text(
                              initials,
                              style: const TextStyle(
                                color: _AA.text,
                                fontSize: 8.8,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          )
                        : Text(
                            initials,
                            style: const TextStyle(
                              color: _AA.text,
                              fontSize: 8.8,
                              fontWeight: FontWeight.w900,
                            ),
                          )),
              ),
              if (!team && number.isNotEmpty)
                Positioned(
                  right: -4,
                  bottom: -4,
                  child: Container(
                    constraints: const BoxConstraints(minWidth: 16),
                    height: 16,
                    padding: const EdgeInsets.symmetric(horizontal: 3),
                    alignment: Alignment.center,
                    decoration: BoxDecoration(
                      color: active ? _AA.green : _AA.soft2,
                      shape: BoxShape.circle,
                    ),
                    child: Text(
                      number,
                      style: TextStyle(
                        color: active ? Colors.white : _AA.graphite,
                        fontSize: 7.4,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  ),
                ),
            ],
          ),
          const SizedBox(width: 7),
          Expanded(
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                Row(children: [
                  Expanded(
                    child: Text(
                      name,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: _AText.body(
                        10.6,
                        color: active ? _AA.greenDark : _AA.text,
                        weight: active ? FontWeight.w700 : FontWeight.w600,
                      ),
                    ),
                  ),
                  if (compareMode && active)
                    const Icon(Icons.check_circle_rounded,
                        color: _AA.green, size: 12),
                ]),
                const SizedBox(height: 4),
                Text(
                  team
                      ? '$rowCount игроков · ${timelineAware ? 'к текущему моменту' : 'вся сессия'}'
                      : 'GPS · ${_meters(distance)} · ${maxSpeed > 0 ? '${maxSpeed.toStringAsFixed(1)} км/ч' : '—'} · $sprints спр.',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: _AText.body(
                    9.5,
                    color: active ? _AA.greenDark : _AA.muted,
                    weight: FontWeight.w500,
                  ),
                ),
              ],
            ),
          ),
        ]),
      ),
    );
  }

  Widget _mapCardMetric(String label, String value) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(label,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
                color: _AA.muted, fontSize: 6.9, fontWeight: FontWeight.w700)),
        Text(value,
            maxLines: 1,
            overflow: TextOverflow.ellipsis,
            style: const TextStyle(
                color: _AA.text, fontSize: 8.3, fontWeight: FontWeight.w900)),
      ],
    );
  }
}


class _MatchLiveRosterPanel extends StatelessWidget {
  const _MatchLiveRosterPanel({
    required this.frames,
    required this.selectedIds,
    required this.rows,
    required this.cursorMetricsByPlayer,
    required this.onPlayerTap,
  });

  final List<_MatchPlaybackFrame> frames;
  final Set<int> selectedIds;
  final List<TrackerPlayerLoadRow> rows;
  final Map<int, _ReplayCursorMetrics> cursorMetricsByPlayer;
  final ValueChanged<TrackerPlayerOption> onPlayerTap;

  @override
  Widget build(BuildContext context) {
    if (frames.isEmpty) {
      return Center(
        child: Text(
          'До этого момента GPS игроков ещё не поступал',
          textAlign: TextAlign.center,
          style: _AText.body(
            10.6,
            color: _AA.muted,
            weight: FontWeight.w500,
          ),
        ),
      );
    }

    return ListView.separated(
      padding: const EdgeInsets.fromLTRB(2, 3, 2, 4),
      itemCount: frames.length,
      separatorBuilder: (_, __) => const SizedBox(height: 6),
      itemBuilder: (context, index) {
        final frame = frames[index];
        final focused = selectedIds.length == 1 &&
            (selectedIds.contains(frame.player.id) ||
                frame.player.identityIds.any(selectedIds.contains));
        final dimmed = selectedIds.isNotEmpty && !focused;
        final stale = frame.lastSampleDeltaMs > 3000;
        final frameDisplayName =
            (frame.player.displayName ?? frame.player.name).trim();
        final initials = frameDisplayName
            .trim()
            .split(RegExp(r'\s+'))
            .where((part) => part.isNotEmpty)
            .take(2)
            .map((part) => part.substring(0, 1))
            .join()
            .toUpperCase();
        final avatar = frame.player.avatar;
        final row = _movementRowForPlayer(rows, frame.player);
        final cursorMetric = cursorMetricsByPlayer[frame.player.id];
        final number = (frame.player.number ?? '').trim();
        final gpsAgeSec = frame.lastSampleDeltaMs / 1000.0;

        return Opacity(
          opacity: dimmed ? .58 : 1,
          child: _NoHoverTap(
            onTap: () => onPlayerTap(frame.player),
            borderRadius: BorderRadius.circular(12),
            child: AnimatedContainer(
              duration: const Duration(milliseconds: 160),
              constraints: const BoxConstraints(minHeight: 78),
              padding: const EdgeInsets.fromLTRB(9, 8, 9, 7),
              decoration: BoxDecoration(
                color: focused
                    ? _AA.greenSoft
                    : stale
                        ? const Color(0xFFFFF9ED)
                        : _AA.soft,
                borderRadius: BorderRadius.circular(12),
                border: focused
                    ? Border.all(color: _AA.greenLine, width: 1)
                    : null,
              ),
              child: Column(children: [
                Row(children: [
                  Stack(
                    clipBehavior: Clip.none,
                    children: [
                      Container(
                        width: 38,
                        height: 38,
                        clipBehavior: Clip.antiAlias,
                        alignment: Alignment.center,
                        decoration: BoxDecoration(
                          shape: BoxShape.circle,
                          color: Colors.white,
                          border: Border.all(
                            color: stale
                                ? _AA.orange.withOpacity(.55)
                                : focused
                                    ? _AA.greenLine
                                    : _AA.line,
                            width: stale || focused ? 2 : 1,
                          ),
                        ),
                        child: avatar != null && avatar.trim().isNotEmpty
                            ? Image.network(
                                avatar,
                                width: 38,
                                height: 38,
                                fit: BoxFit.cover,
                                errorBuilder: (_, __, ___) => Text(
                                  initials,
                                  style: const TextStyle(
                                    color: _AA.text,
                                    fontSize: 9,
                                    fontWeight: FontWeight.w900,
                                  ),
                                ),
                              )
                            : Text(
                                initials,
                                style: const TextStyle(
                                  color: _AA.text,
                                  fontSize: 9,
                                  fontWeight: FontWeight.w900,
                                ),
                              ),
                      ),
                      if (number.isNotEmpty)
                        Positioned(
                          right: -4,
                          bottom: -4,
                          child: Container(
                            constraints: const BoxConstraints(minWidth: 18),
                            height: 18,
                            padding: const EdgeInsets.symmetric(horizontal: 3),
                            alignment: Alignment.center,
                            decoration: BoxDecoration(
                              color: stale ? _AA.orange : _AA.green,
                              shape: BoxShape.circle,
                            ),
                            child: Text(number,
                                style: const TextStyle(
                                    color: Colors.white,
                                    fontSize: 8,
                                    fontWeight: FontWeight.w900)),
                          ),
                        ),
                    ],
                  ),
                  const SizedBox(width: 9),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          _shortPlayerName(frameDisplayName),
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: _AText.body(
                            10.6,
                            color: focused ? _AA.green : _AA.text,
                            weight: FontWeight.w700,
                          ),
                        ),
                        const SizedBox(height: 2),
                        Text(
                          stale
                              ? 'GPS потерян · ${gpsAgeSec < 60 ? '${gpsAgeSec.toStringAsFixed(0)} сек' : '${(gpsAgeSec / 60).toStringAsFixed(1)} мин'} назад'
                              : 'GPS синхронно · повтор матча',
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: _AText.body(
                            9.5,
                            color: stale ? _AA.orange : _AA.greenDark,
                            weight: FontWeight.w500,
                          ),
                        ),
                      ],
                    ),
                  ),
                  const SizedBox(width: 6),
                  Container(
                    padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 4),
                    decoration: BoxDecoration(
                      color: stale ? Colors.white.withOpacity(.8) : Colors.white,
                      borderRadius: BorderRadius.circular(8),
                    ),
                    child: Text(
                      stale ? '—' : '${frame.speedKmh.toStringAsFixed(1)} км/ч',
                      style: _AText.body(
                        10.2,
                        color: stale ? _AA.muted : _AA.text,
                        weight: FontWeight.w700,
                      ),
                    ),
                  ),
                ]),
                const SizedBox(height: 7),
                Row(children: [
                  Expanded(child: _matchRosterMetric(
                    'Дист.',
                    _meters(cursorMetric?.distanceM ?? row?.distanceM ?? 0),
                  )),
                  Expanded(child: _matchRosterMetric(
                    'Макс',
                    (cursorMetric?.maxSpeedKmh ?? row?.maxSpeedKmh ?? 0) > 0
                        ? '${(cursorMetric?.maxSpeedKmh ?? row?.maxSpeedKmh ?? 0).toStringAsFixed(1)}'
                        : '—',
                  )),
                  Expanded(child: _matchRosterMetric(
                    'Спр.',
                    '${cursorMetric?.sprintCount ?? row?.sprintCount ?? 0}',
                  )),
                ]),
              ]),
            ),
          ),
        );
      },
    );
  }

  Widget _matchRosterMetric(String label, String value) {
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      mainAxisSize: MainAxisSize.min,
      children: [
        Text(
          label,
          style: _AText.caption(size: 9.5, color: _AA.muted),
        ),
        const SizedBox(height: 1),
        Text(
          value,
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          style: _AText.body(
            10.2,
            color: _AA.text,
            weight: FontWeight.w600,
          ),
        ),
      ],
    );
  }
}

class _MatchPlaybackRatePicker extends StatelessWidget {
  const _MatchPlaybackRatePicker({
    required this.value,
    required this.onChanged,
  });

  final double value;
  final ValueChanged<double> onChanged;

  @override
  Widget build(BuildContext context) {
    const rates = <double>[1, 2, 5, 10, 20];
    return Container(
      height: 32,
      padding: const EdgeInsets.all(2),
      decoration: BoxDecoration(
        color: _AA.card,
        borderRadius: BorderRadius.circular(11),
        border: Border.all(color: _AA.line),
      ),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: rates.map((rate) {
          final active = (value - rate).abs() < .01;
          return _NoHoverTap(
            onTap: () => onChanged(rate),
            borderRadius: BorderRadius.circular(8),
            child: AnimatedContainer(
              duration: const Duration(milliseconds: 120),
              height: 26,
              padding: const EdgeInsets.symmetric(horizontal: 9),
              alignment: Alignment.center,
              decoration: BoxDecoration(
                color: active ? _AA.greenSoft : Colors.transparent,
                borderRadius: BorderRadius.circular(8),
              ),
              child: Text(
                '${rate.toInt()}×',
                style: TextStyle(
                  color: active ? _AA.green : _AA.muted,
                  fontSize: 9.6,
                  fontWeight: FontWeight.w800,
                ),
              ),
            ),
          );
        }).toList(growable: false),
      ),
    );
  }
}

List<TrackerGeoTrack> _analyticsGeoTracks({
  required List<ActionTrackerGpsPoint> points,
  required List<TrackerPlayerOption> players,
  required Set<int> selectedIds,
}) {
  int canonicalPlayerId(int? sourceId) {
    if (sourceId != null && sourceId > 0) {
      for (final player in players) {
        if (player.id == sourceId || player.identityIds.contains(sourceId)) {
          return player.id;
        }
      }
      return sourceId;
    }
    if (selectedIds.length == 1) return selectedIds.first;
    return 0;
  }

  final grouped = <int, List<ActionTrackerGpsPoint>>{};
  for (final point in points) {
    final id = canonicalPlayerId(point.playerId);
    grouped.putIfAbsent(id, () => <ActionTrackerGpsPoint>[]).add(point);
  }

  const colors = <Color>[
    Color(0xFF16794B),
    Color(0xFF2879D0),
    Color(0xFFF08A24),
    Color(0xFF8B5CC7),
    Color(0xFFD84C5A),
    Color(0xFF078F95),
  ];
  final result = <TrackerGeoTrack>[];
  var colorIndex = 0;
  for (final entry in grouped.entries) {
    final source = entry.value..sort((a, b) => a.timeMs.compareTo(b.timeMs));
    TrackerPlayerOption? player;
    for (final candidate in players) {
      if (candidate.id == entry.key ||
          candidate.identityIds.contains(entry.key)) {
        player = candidate;
        break;
      }
    }
    final selected = selectedIds.contains(entry.key) ||
        (player != null &&
            (selectedIds.contains(player.id) ||
                player.identityIds.any(selectedIds.contains)));
    result.add(
      TrackerGeoTrack(
        id: 'analytics-${entry.key}-$colorIndex',
        name: player?.name ?? (entry.key > 0 ? 'Игрок ${entry.key}' : 'Маршрут'),
        avatar: player?.avatar,
        color: colors[colorIndex % colors.length],
        selected: selected,
        points: source
            .map(
              (point) => TrackerGeoPoint(
                latitude: point.latitude,
                longitude: point.longitude,
                timeMs: point.timeMs,
                speedKmh: point.speedKmh ?? 0,
                breakBefore: point.breakBefore,
              ),
            )
            .toList(growable: false),
      ),
    );
    colorIndex++;
  }
  return result;
}

class _MatchPlaybackFrame {
  const _MatchPlaybackFrame({
    required this.player,
    required this.point,
    required this.speedKmh,
    required this.lastSampleDeltaMs,
  });

  final TrackerPlayerOption player;
  final ActionTrackerGpsPoint point;
  final double speedKmh;
  final int lastSampleDeltaMs;
}

class _MatchPlaybackField extends StatelessWidget {
  const _MatchPlaybackField({
    required this.points,
    required this.players,
    required this.rows,
    required this.field,
    required this.cursor,
    required this.range,
    required this.mapRotationDeg,
    required this.selectedIds,
    required this.heartRate,
    this.modeLabel = 'Матч',
    this.routeOverlay = const <ActionTrackerGpsPoint>[],
    this.heatOverlay = const <TrackerHeatPoint>[],
    this.sprintThresholdKmh = 18.0,
    this.hsrThresholdKmh = 14.0,
    this.activityFilter = 'all',
    this.showSprintArrows = true,
    this.showTrackDots = false,
    this.onGpsPointTap,
    this.showHudMetrics = true,
    this.mapMarkers = const <_MovementMapMarker>[],
    this.onMarkerTap,
    this.showTeamShape = false,
    this.sectorMetrics = const <_TelemetrySectorMetric>[],
    this.pitWallActive = false,
    this.pitWallPoints = const <ActionTrackerGpsPoint>[],
    this.pitWallAlertCount = 0,
    this.pitWallConfidence = 0,
  });

  final List<ActionTrackerGpsPoint> points;
  final List<TrackerPlayerOption> players;
  final List<TrackerPlayerLoadRow> rows;
  final TrackerFieldModel? field;
  final double cursor;
  final RangeValues range;
  final double mapRotationDeg;
  final Set<int> selectedIds;
  final _AnalyticsHeartRate heartRate;
  final String modeLabel;
  final List<ActionTrackerGpsPoint> routeOverlay;
  final List<TrackerHeatPoint> heatOverlay;
  final double sprintThresholdKmh;
  final double hsrThresholdKmh;
  final String activityFilter;
  final bool showSprintArrows;
  final bool showTrackDots;
  final ValueChanged<ActionTrackerGpsPoint>? onGpsPointTap;
  final bool showHudMetrics;
  final List<_MovementMapMarker> mapMarkers;
  final ValueChanged<_MovementMapMarker>? onMarkerTap;
  final bool showTeamShape;
  final List<_TelemetrySectorMetric> sectorMetrics;
  final bool pitWallActive;
  final List<ActionTrackerGpsPoint> pitWallPoints;
  final int pitWallAlertCount;
  final double pitWallConfidence;

  @override
  Widget build(BuildContext context) {
    if (points.isEmpty) {
      return Container(
        color: const Color(0xFFF7F9F8),
        alignment: Alignment.center,
        child: const Text(
          'Для режима матча нет GPS-точек',
          style: TextStyle(
            color: _AA.muted,
            fontSize: 12,
            fontWeight: FontWeight.w700,
          ),
        ),
      );
    }

    final targetTime = _movementTimeAtProgress(
      points,
      cursor.clamp(range.start, range.end).toDouble(),
    );
    final frames = _matchPlaybackFrames(points, players, rows, targetTime);
    final freshCount = frames.where((frame) => frame.lastSampleDeltaMs <= 3000).length;
    final staleCount = math.max(0, frames.length - freshCount);
    final minTime = _movementMinTime(points);
    final elapsed = math.max(0, targetTime - minTime);

    return LayoutBuilder(builder: (context, constraints) {
      final size = Size(
        math.max(1.0, constraints.maxWidth),
        math.max(1.0, constraints.maxHeight),
      );
      final bounds = _Bounds.fromGps(points);
      final useFieldProjection = _shouldUseFieldProjection(points, field);

      final content = Stack(
        clipBehavior: Clip.hardEdge,
        children: [
          Positioned.fill(
            child: CustomPaint(
              painter: _ActionPitchPainter(
                heat: heatOverlay,
                local: routeOverlay,
                field: field,
                sprintThresholdKmh: sprintThresholdKmh,
                hsrThresholdKmh: hsrThresholdKmh,
                activityFilter: activityFilter,
                mapRotationDeg: mapRotationDeg,
                showSprintArrows: showSprintArrows,
                showTrackDots: showTrackDots,
                pitWallActive: pitWallActive,
                pitWallPoints: pitWallPoints,
                pitWallProjectionPoints: points,
                projectionPoints: points,
                mapMarkers: mapMarkers,
                selectedMarkerTimeMs: targetTime,
              ),
            ),
          ),
          if (sectorMetrics.isNotEmpty)
            Positioned.fill(
              child: IgnorePointer(
                child: CustomPaint(
                  painter: _TelemetrySectorOverlayPainter(sectors: sectorMetrics),
                ),
              ),
            ),
          if (showTeamShape && frames.length >= 3)
            Positioned.fill(
              child: IgnorePointer(
                child: CustomPaint(
                  painter: _TelemetryTeamShapeOverlayPainter(
                    frames: frames,
                    field: field,
                    allPoints: points,
                    mapRotationDeg: mapRotationDeg,
                  ),
                ),
              ),
            ),
          Positioned(
            left: 12,
            top: 12,
            child: Container(
              padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
              decoration: BoxDecoration(
                color: Colors.white.withOpacity(.94),
                borderRadius: BorderRadius.circular(12),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withOpacity(.06),
                    blurRadius: 10,
                    offset: const Offset(0, 3),
                  ),
                ],
              ),
              child: Row(mainAxisSize: MainAxisSize.min, children: [
                const Icon(Icons.sports_soccer_rounded,
                    color: _AA.green, size: 16),
                const SizedBox(width: 6),
                Text(
                  '$modeLabel · ${_movementMatchClockLabel(elapsed)}',
                  style: const TextStyle(
                    color: _AA.text,
                    fontSize: 10.5,
                    fontWeight: FontWeight.w800,
                  ),
                ),
                const SizedBox(width: 8),
                Text(
                  staleCount > 0
                      ? '$freshCount GPS · $staleCount без связи'
                      : '$freshCount GPS синхронно',
                  style: TextStyle(
                    color: staleCount > 0 ? _AA.orange : _AA.muted,
                    fontSize: 9.4,
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ]),
            ),
          ),
          if (pitWallActive)
            Positioned(
              right: 12,
              top: 12,
              child: Container(
                padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 7),
                decoration: BoxDecoration(
                  color: const Color(0xFF00A750),
                  borderRadius: BorderRadius.circular(12),
                  boxShadow: [
                    BoxShadow(
                      color: const Color(0xFF00A750).withOpacity(.28),
                      blurRadius: 14,
                      spreadRadius: -5,
                      offset: const Offset(0, 5),
                    ),
                  ],
                ),
                child: Row(mainAxisSize: MainAxisSize.min, children: [
                  const Icon(Icons.monitor_heart_rounded,
                      color: Colors.white, size: 15),
                  const SizedBox(width: 6),
                  const Text('ПИТ-УОЛЛ · АКТИВЕН',
                      style: TextStyle(
                          color: Colors.white,
                          fontSize: 9.4,
                          fontWeight: FontWeight.w900,
                          letterSpacing: .35)),
                  const SizedBox(width: 8),
                  Text('${pitWallConfidence.toStringAsFixed(0)}% GPS',
                      style: const TextStyle(
                          color: Colors.white,
                          fontSize: 8.6,
                          fontWeight: FontWeight.w700)),
                  if (pitWallAlertCount > 0) ...[
                    const SizedBox(width: 7),
                    Container(
                      constraints: const BoxConstraints(minWidth: 18),
                      height: 18,
                      padding: const EdgeInsets.symmetric(horizontal: 5),
                      alignment: Alignment.center,
                      decoration: BoxDecoration(
                        color: Colors.white.withOpacity(.18),
                        borderRadius: BorderRadius.circular(99),
                      ),
                      child: Text('$pitWallAlertCount',
                          style: const TextStyle(
                              color: Colors.white,
                              fontSize: 8.2,
                              fontWeight: FontWeight.w900)),
                    ),
                  ],
                ]),
              ),
            ),
          for (final frame in frames)
            _buildMarker(
              frame,
              size,
              bounds,
              useFieldProjection,
              minTime,
            ),
        ],
      );

      final canTapMarkers = onMarkerTap != null && mapMarkers.isNotEmpty;
      final canTapRoute = onGpsPointTap != null && routeOverlay.isNotEmpty;
      if (!canTapMarkers && !canTapRoute) return content;
      return GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTapDown: (details) {
          final tap = details.localPosition;
          if (canTapMarkers) {
            _MovementMapMarker? nearest;
            var nearestDistance = double.infinity;
            for (final marker in mapMarkers.take(64)) {
              var markerPosition = _matchProjectPoint(
                marker.point,
                size,
                bounds,
                field,
                useFieldProjection,
              );
              if (mapRotationDeg.abs() > .1) {
                markerPosition =
                    _rotateMatchPoint(markerPosition, size, mapRotationDeg);
              }
              final distance = (tap - markerPosition).distance;
              if (distance < nearestDistance) {
                nearestDistance = distance;
                nearest = marker;
              }
            }
            // Replay-маркеры имеют приоритет над GPS-треком.
            if (nearest != null && nearestDistance <= 24.0) {
              onMarkerTap!(nearest);
              return;
            }
          }

          if (canTapRoute) {
            ActionTrackerGpsPoint? nearestPoint;
            var nearestDistance = double.infinity;
            // Для hit-test достаточно проредить очень плотный трек.
            final stride = math.max(1, (routeOverlay.length / 900).ceil());
            for (var i = 0; i < routeOverlay.length; i += stride) {
              final point = routeOverlay[i];
              var pointPosition = _matchProjectPoint(
                point,
                size,
                bounds,
                field,
                useFieldProjection,
              );
              if (mapRotationDeg.abs() > .1) {
                pointPosition =
                    _rotateMatchPoint(pointPosition, size, mapRotationDeg);
              }
              final distance = (tap - pointPosition).distance;
              if (distance < nearestDistance) {
                nearestDistance = distance;
                nearestPoint = point;
              }
            }
            if (nearestPoint != null && nearestDistance <= 22.0) {
              onGpsPointTap!(nearestPoint);
            }
          }
        },
        child: content,
      );
    });
  }

  Widget _buildMarker(
    _MatchPlaybackFrame frame,
    Size size,
    _Bounds bounds,
    bool useFieldProjection,
    int sessionStartMs,
  ) {
    var position = _matchProjectPoint(
      frame.point,
      size,
      bounds,
      field,
      useFieldProjection,
    );
    if (mapRotationDeg.abs() > .1) {
      position = _rotateMatchPoint(position, size, mapRotationDeg);
    }

    final highlighted = selectedIds.isNotEmpty &&
        (selectedIds.contains(frame.player.id) ||
            frame.player.identityIds.any(selectedIds.contains));
    final dimmed = selectedIds.isNotEmpty && !highlighted;
    final stale = frame.lastSampleDeltaMs > 3000;
    final avatar = frame.player.avatar ??
        _movementRowForPlayer(rows, frame.player)?.avatar;
    final shortName = _shortPlayerName(frame.player.name);
    _AnalyticsHrPoint? hrSample;
    if (showHudMetrics) {
      hrSample = _nearestHrForGps(
        heartRate,
        frame.player.id,
        frame.point.timeMs,
        sessionStartMs,
      );
      if (hrSample == null) {
        for (final identityId in frame.player.identityIds) {
          hrSample = _nearestHrForGps(
            heartRate,
            identityId,
            frame.point.timeMs,
            sessionStartMs,
          );
          if (hrSample != null) break;
        }
      }
    }
    final hrBpm = hrSample?.bpm ?? 0;
    final initials = frame.player.name
        .trim()
        .split(RegExp(r'\s+'))
        .where((part) => part.isNotEmpty)
        .take(2)
        .map((part) => part.substring(0, 1))
        .join()
        .toUpperCase();
    final markerWidth = showHudMetrics
        ? 118.0
        : (highlighted || stale ? 94.0 : 54.0);
    final avatarSize = highlighted ? 42.0 : 36.0;
    final left = (position.dx - markerWidth / 2)
        .clamp(0.0, math.max(0.0, size.width - markerWidth))
        .toDouble();
    final top = (position.dy - (highlighted ? 31 : 25))
        .clamp(0.0, math.max(0.0, size.height - 66))
        .toDouble();

    return Positioned(
      left: left,
      top: top,
      width: markerWidth,
      child: IgnorePointer(
        child: AnimatedOpacity(
          duration: const Duration(milliseconds: 160),
          opacity: stale
              ? .56
              : dimmed
                  ? .32
                  : 1.0,
          child: Column(mainAxisSize: MainAxisSize.min, children: [
            Stack(
              clipBehavior: Clip.none,
              alignment: Alignment.center,
              children: [
                AnimatedContainer(
                  duration: const Duration(milliseconds: 160),
                  width: avatarSize + 7,
                  height: avatarSize + 7,
                  decoration: BoxDecoration(
                    shape: BoxShape.circle,
                    color: Colors.white,
                    border: Border.all(
                      color: stale
                          ? _AA.orange
                          : highlighted
                              ? _AA.green
                              : Colors.white,
                      width: stale || highlighted ? 2.5 : 1.5,
                    ),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black.withOpacity(highlighted ? .18 : .10),
                        blurRadius: highlighted ? 10 : 6,
                        offset: const Offset(0, 3),
                      ),
                    ],
                  ),
                ),
                ClipOval(
                  child: Container(
                    width: avatarSize,
                    height: avatarSize,
                    color: _AA.card,
                    alignment: Alignment.center,
                    child: avatar != null && avatar.trim().isNotEmpty
                        ? Image.network(
                            avatar,
                            width: avatarSize,
                            height: avatarSize,
                            fit: BoxFit.cover,
                            errorBuilder: (_, __, ___) => Text(
                              initials,
                              style: const TextStyle(
                                color: _AA.text,
                                fontSize: 9.5,
                                fontWeight: FontWeight.w900,
                              ),
                            ),
                          )
                        : Text(
                            initials,
                            style: const TextStyle(
                              color: _AA.text,
                              fontSize: 9.5,
                              fontWeight: FontWeight.w900,
                            ),
                          ),
                  ),
                ),
                if ((frame.player.number ?? '').trim().isNotEmpty)
                  Positioned(
                    right: 1,
                    bottom: 0,
                    child: Container(
                      constraints: const BoxConstraints(minWidth: 17),
                      height: 17,
                      padding: const EdgeInsets.symmetric(horizontal: 3),
                      alignment: Alignment.center,
                      decoration: BoxDecoration(
                        color: stale ? _AA.orange : _AA.green,
                        shape: BoxShape.circle,
                      ),
                      child: Text(
                        frame.player.number!,
                        style: const TextStyle(
                          color: Colors.white,
                          fontSize: 7.5,
                          fontWeight: FontWeight.w900,
                        ),
                      ),
                    ),
                  ),
                if (stale)
                  Positioned(
                    left: 0,
                    top: -1,
                    child: Container(
                      width: 17,
                      height: 17,
                      alignment: Alignment.center,
                      decoration: const BoxDecoration(
                        color: Colors.white,
                        shape: BoxShape.circle,
                      ),
                      child: const Icon(Icons.gps_off_rounded,
                          color: _AA.orange, size: 11),
                    ),
                  ),
              ],
            ),
            if (showHudMetrics || highlighted || stale) ...[
              const SizedBox(height: 2),
              Container(
                constraints: BoxConstraints(
                    maxWidth: showHudMetrics ? 118 : 94),
                padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
                decoration: BoxDecoration(
                  color: Colors.white.withOpacity(.94),
                  borderRadius: BorderRadius.circular(7),
                ),
                child: Text(
                  stale
                      ? '$shortName · GPS ${(frame.lastSampleDeltaMs / 1000).toStringAsFixed(0)}с'
                      : showHudMetrics && hrBpm > 0
                          ? '$shortName · ${frame.speedKmh.toStringAsFixed(1)} · ♥ $hrBpm'
                          : '$shortName · ${frame.speedKmh.toStringAsFixed(1)}',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  textAlign: TextAlign.center,
                  style: TextStyle(
                    color: stale ? _AA.orange : _AA.text,
                    fontSize: 7.8,
                    fontWeight: FontWeight.w800,
                  ),
                ),
              ),
            ],
          ]),
        ),
      ),
    );
  }
}

List<_MatchPlaybackFrame> _matchPlaybackFrames(
  List<ActionTrackerGpsPoint> points,
  List<TrackerPlayerOption> players,
  List<TrackerPlayerLoadRow> rows,
  int targetTime,
) {
  final grouped = <int, List<ActionTrackerGpsPoint>>{};
  for (final point in points) {
    final id = point.playerId;
    if (id == null || id <= 0 || point.timeMs <= 0) continue;
    grouped.putIfAbsent(id, () => <ActionTrackerGpsPoint>[]).add(point);
  }

  // Старые личные записи могли сохраниться без player_id у каждой GPS-точки.
  // В личном кабинете roster всегда состоит из одного владельца, поэтому такую
  // запись безопасно привязываем к нему для режима «Запись»: аватар продолжает
  // двигаться по полю даже у старых сессий, а чужие данные сюда не попадают.
  if (grouped.isEmpty && players.length == 1) {
    final fallback = points.where((point) => point.timeMs > 0).toList();
    if (fallback.isNotEmpty) grouped[players.first.id] = fallback;
  }

  TrackerPlayerOption? playerForId(int id) {
    for (final player in players) {
      if (player.id == id || player.identityIds.contains(id)) return player;
    }
    for (final row in rows) {
      if (row.playerId == id) {
        return TrackerPlayerOption(
          id: id,
          name: row.playerName,
          avatar: row.avatar,
          identityIds: <int>{id},
        );
      }
    }
    return null;
  }

  final frames = <_MatchPlaybackFrame>[];
  final usedPlayers = <int>{};
  for (final entry in grouped.entries) {
    final player = playerForId(entry.key);
    if (player == null || usedPlayers.contains(player.id)) continue;
    final series = entry.value..sort((a, b) => a.timeMs.compareTo(b.timeMs));
    final sample = _matchInterpolatedPoint(series, targetTime);
    if (sample == null) continue;
    usedPlayers.add(player.id);
    frames.add(_MatchPlaybackFrame(
      player: player,
      point: sample.point,
      speedKmh: sample.speedKmh,
      lastSampleDeltaMs: sample.deltaMs,
    ));
  }
  frames.sort((a, b) => a.player.name.compareTo(b.player.name));
  return frames;
}

class _MatchInterpolatedSample {
  const _MatchInterpolatedSample({
    required this.point,
    required this.speedKmh,
    required this.deltaMs,
  });

  final ActionTrackerGpsPoint point;
  final double speedKmh;
  final int deltaMs;
}

_MatchInterpolatedSample? _matchInterpolatedPoint(
    List<ActionTrackerGpsPoint> series, int targetTime) {
  if (series.isEmpty || targetTime <= 0) return null;
  if (series.length == 1) {
    final delta = (series.first.timeMs - targetTime).abs();
    // V117.2: после первой полученной GPS-точки игрок больше не исчезает
    // из повтора при потере связи — остаётся на последней позиции.
    if (targetTime < series.first.timeMs && delta > 2000) return null;
    return _MatchInterpolatedSample(
      point: series.first,
      speedKmh: targetTime > series.first.timeMs + 3000
          ? 0.0
          : (series.first.speedKmh ?? 0).clamp(0.0, 36.0).toDouble(),
      deltaMs: delta,
    );
  }

  var low = 0;
  var high = series.length - 1;
  while (low <= high) {
    final mid = (low + high) >> 1;
    if (series[mid].timeMs < targetTime) {
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  final nextIndex = low.clamp(0, series.length - 1).toInt();
  final prevIndex = (nextIndex - 1).clamp(0, series.length - 1).toInt();
  final prev = series[prevIndex];
  final next = series[nextIndex];

  if (prevIndex == nextIndex) {
    final delta = (prev.timeMs - targetTime).abs();
    if (targetTime < prev.timeMs && delta > 2000) return null;
    return _MatchInterpolatedSample(
      point: prev,
      speedKmh: targetTime > prev.timeMs + 3000
          ? 0.0
          : (prev.speedKmh ?? 0).clamp(0.0, 36.0).toDouble(),
      deltaMs: delta,
    );
  }

  final gapMs = next.timeMs - prev.timeMs;
  if (gapMs <= 0 || gapMs > 15000) {
    final prevDelta = (targetTime - prev.timeMs).abs();
    final nextDelta = (next.timeMs - targetTime).abs();
    // Большой разрыв связи: до появления новой точки держим футболиста в
    // последней подтверждённой позиции. Не прыгаем в будущую GPS-точку и
    // не удаляем аватар с поля.
    if (targetTime >= prev.timeMs && targetTime <= next.timeMs) {
      return _MatchInterpolatedSample(
        point: prev,
        speedKmh: 0.0,
        deltaMs: prevDelta,
      );
    }
    final nearest = prevDelta <= nextDelta ? prev : next;
    final delta = math.min(prevDelta, nextDelta);
    if (targetTime < series.first.timeMs && delta > 2000) return null;
    return _MatchInterpolatedSample(
      point: nearest,
      speedKmh: delta > 3000
          ? 0.0
          : (nearest.speedKmh ?? 0).clamp(0.0, 36.0).toDouble(),
      deltaMs: delta,
    );
  }

  final ratio =
      ((targetTime - prev.timeMs) / gapMs).clamp(0.0, 1.0).toDouble();
  final latitude = prev.latitude + (next.latitude - prev.latitude) * ratio;
  final longitude = prev.longitude + (next.longitude - prev.longitude) * ratio;
  final distanceM = _LocalTrackAnalysis._distanceMeters(
      prev.latitude, prev.longitude, next.latitude, next.longitude);
  var speedKmh = (distanceM / (gapMs / 1000.0)) * 3.6;
  if (!speedKmh.isFinite || speedKmh < 0 || speedKmh > 36.0) {
    speedKmh = 0;
  }

  return _MatchInterpolatedSample(
    point: ActionTrackerGpsPoint(
      timeMs: targetTime,
      latitude: latitude,
      longitude: longitude,
      speedKmh: speedKmh,
      liveSessionId: prev.liveSessionId ?? next.liveSessionId,
      sessionId: prev.sessionId ?? next.sessionId,
      playerId: prev.playerId ?? next.playerId,
    ),
    speedKmh: speedKmh,
    deltaMs: math.min(
      (targetTime - prev.timeMs).abs(),
      (next.timeMs - targetTime).abs(),
    ),
  );
}

Offset _matchProjectPoint(
  ActionTrackerGpsPoint point,
  Size size,
  _Bounds bounds,
  TrackerFieldModel? field,
  bool useFieldProjection,
) {
  if (useFieldProjection) {
    final projected = TrackerPitchProjector.projectGps(
      field,
      latitude: point.latitude,
      longitude: point.longitude,
    );
    if (projected != null) {
      return _fitPointToPitch(
        Offset(projected.clampedNx * size.width,
            projected.clampedNy * size.height),
        size,
      );
    }
  }
  return _fitPointToPitch(bounds.project(point, size), size);
}

Offset _rotateMatchPoint(Offset point, Size size, double degrees) {
  final radians = degrees * math.pi / 180.0;
  final center = Offset(size.width / 2, size.height / 2);
  final dx = point.dx - center.dx;
  final dy = point.dy - center.dy;
  final cosA = math.cos(radians);
  final sinA = math.sin(radians);
  return Offset(
    center.dx + dx * cosA - dy * sinA,
    center.dy + dx * sinA + dy * cosA,
  );
}

class _MovementTransportStrip extends StatelessWidget {
  const _MovementTransportStrip({
    required this.points,
    required this.range,
    required this.cursor,
    required this.playing,
    required this.onTogglePlay,
    required this.onCursorChanged,
    required this.onRangeChanged,
    this.playbackRate = 1.0,
    this.onPlaybackRateChanged,
    this.dense = false,
  });
  final List<ActionTrackerGpsPoint> points;
  final RangeValues range;
  final double cursor;
  final bool playing;
  final VoidCallback onTogglePlay;
  final ValueChanged<double> onCursorChanged;
  final ValueChanged<RangeValues> onRangeChanged;
  final double playbackRate;
  final ValueChanged<double>? onPlaybackRateChanged;
  final bool dense;

  @override
  Widget build(BuildContext context) {
    final durationMs = _movementRecordingSpanMs(points);
    final elapsedMs = math.max(
      0,
      (durationMs * cursor.clamp(0.0, 1.0)).round(),
    );
    final hasCustomRange = range.start > .0005 || range.end < .9995;

    final sliderTheme = SliderTheme.of(context).copyWith(
      trackHeight: 2.4,
      activeTrackColor: _AA.green,
      inactiveTrackColor: _AA.greenLine.withOpacity(.72),
      thumbColor: _AA.green,
      overlayColor: _AA.green.withOpacity(.08),
      thumbShape: const RoundSliderThumbShape(enabledThumbRadius: 5.2),
      overlayShape: const RoundSliderOverlayShape(overlayRadius: 9),
    );

    Widget rateControl() {
      final label =
          '${playbackRate.toStringAsFixed(playbackRate % 1 == 0 ? 0 : 1)}×';
      if (onPlaybackRateChanged == null) {
        return Text(
          label,
          style: _AText.caption(size: 9.5, color: _AA.muted),
        );
      }
      return PopupMenuButton<double>(
        tooltip: 'Скорость воспроизведения',
        initialValue: playbackRate,
        onSelected: onPlaybackRateChanged,
        color: Colors.white,
        elevation: 8,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
        itemBuilder: (_) => const <PopupMenuEntry<double>>[
          PopupMenuItem(value: 1, child: Text('1× · реальное время')),
          PopupMenuItem(value: 2, child: Text('2×')),
          PopupMenuItem(value: 5, child: Text('5×')),
          PopupMenuItem(value: 10, child: Text('10×')),
          PopupMenuItem(value: 20, child: Text('20×')),
        ],
        child: Container(
          height: 24,
          padding: const EdgeInsets.symmetric(horizontal: 7),
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: _AA.soft,
            borderRadius: BorderRadius.circular(8),
          ),
          child: Row(mainAxisSize: MainAxisSize.min, children: [
            Text(
              label,
              style: _AText.body(
                9.5,
                color: _AA.text,
                weight: FontWeight.w600,
              ),
            ),
            const SizedBox(width: 2),
            const Icon(Icons.expand_more_rounded, size: 13, color: _AA.muted),
          ]),
        ),
      );
    }

    Widget rangeControl() {
      return PopupMenuButton<String>(
        tooltip: 'Диапазон анализа',
        onSelected: (value) {
          if (value == 'all') {
            onRangeChanged(const RangeValues(0, 1));
            return;
          }
          final safeCursor = cursor.clamp(0.0, 1.0).toDouble();
          if (value == 'start') {
            final start = math.min(safeCursor, range.end - .001).toDouble();
            onRangeChanged(RangeValues(start.clamp(0.0, 1.0).toDouble(), range.end));
          } else if (value == 'end') {
            final end = math.max(safeCursor, range.start + .001).toDouble();
            onRangeChanged(RangeValues(range.start, end.clamp(0.0, 1.0).toDouble()));
          }
        },
        color: Colors.white,
        elevation: 8,
        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
        itemBuilder: (_) => const <PopupMenuEntry<String>>[
          PopupMenuItem(value: 'all', child: Text('Вся запись')),
          PopupMenuItem(value: 'start', child: Text('Начало диапазона = текущая точка')),
          PopupMenuItem(value: 'end', child: Text('Конец диапазона = текущая точка')),
        ],
        child: Container(
          width: 28,
          height: 24,
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: hasCustomRange ? _AA.greenSoft : _AA.soft,
            borderRadius: BorderRadius.circular(8),
          ),
          child: Icon(
            Icons.filter_alt_outlined,
            size: 14,
            color: hasCustomRange ? _AA.greenDark : _AA.muted,
          ),
        ),
      );
    }

    return Container(
      height: dense ? 34 : 38,
      padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 3),
      decoration: BoxDecoration(
        color: _AA.card,
        borderRadius: BorderRadius.circular(10),
        border: Border.all(color: _AA.line.withOpacity(.72), width: .7),
      ),
      child: Row(children: [
        _NoHoverTap(
          onTap: onTogglePlay,
          borderRadius: BorderRadius.circular(8),
          child: Container(
            width: 30,
            height: 26,
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: _AA.greenSoft,
              borderRadius: BorderRadius.circular(8),
            ),
            child: Icon(
              playing ? Icons.pause_rounded : Icons.play_arrow_rounded,
              color: _AA.green,
              size: 16,
            ),
          ),
        ),
        const SizedBox(width: 7),
        Text(
          '${_movementMatchClockLabel(elapsedMs)} / ${_movementMatchClockLabel(durationMs)}',
          style: _AText.body(
            10.2,
            color: _AA.text,
            weight: FontWeight.w600,
          ),
        ),
        const SizedBox(width: 6),
        rateControl(),
        const SizedBox(width: 4),
        rangeControl(),
        const SizedBox(width: 5),
        Expanded(
          child: SliderTheme(
            data: sliderTheme,
            child: Slider(
              value: cursor.clamp(range.start, range.end).toDouble(),
              min: range.start,
              max: math.max(range.end, range.start + .0001).toDouble(),
              onChanged: onCursorChanged,
            ),
          ),
        ),
      ]),
    );
  }
}

class _MovementTimeline extends StatelessWidget {
  const _MovementTimeline({
    required this.points,
    required this.hsrThresholdKmh,
    required this.sprintThresholdKmh,
    required this.cursor,
    required this.onCursorChanged,
  });
  final List<ActionTrackerGpsPoint> points;
  final double hsrThresholdKmh;
  final double sprintThresholdKmh;
  final double cursor;
  final ValueChanged<double> onCursorChanged;

  @override
  Widget build(BuildContext context) {
    return LayoutBuilder(builder: (context, constraints) {
      void select(Offset position) {
        if (constraints.maxWidth <= 0) return;
        onCursorChanged(
            (position.dx / constraints.maxWidth).clamp(0.0, 1.0).toDouble());
      }

      return GestureDetector(
        behavior: HitTestBehavior.opaque,
        onTapDown: (details) => select(details.localPosition),
        onHorizontalDragUpdate: (details) => select(details.localPosition),
        child: CustomPaint(
          painter: _MovementTimelinePainter(
            points: points,
            hsrThresholdKmh: hsrThresholdKmh,
            sprintThresholdKmh: sprintThresholdKmh,
            cursor: cursor,
          ),
          child: const SizedBox.expand(),
        ),
      );
    });
  }
}

class _MovementTimelinePainter extends CustomPainter {
  const _MovementTimelinePainter({
    required this.points,
    required this.hsrThresholdKmh,
    required this.sprintThresholdKmh,
    required this.cursor,
  });

  final List<ActionTrackerGpsPoint> points;
  final double hsrThresholdKmh;
  final double sprintThresholdKmh;
  final double cursor;

  @override
  void paint(Canvas canvas, Size size) {
    final rect = Offset.zero & size;
    canvas.drawRRect(
      RRect.fromRectAndRadius(rect, const Radius.circular(12)),
      Paint()..color = Colors.white,
    );

    // V203 MAP SPEED:
    // Team sessions can contain several technical GPS tracks and, after
    // recovery, an isolated timestamp with a different clock base. Using the
    // absolute min/max of every raw point compressed the real speed trace into
    // the far-right edge. Draw every validated player track on the same
    // 0..100% session-progress axis instead. Only real movement segments define
    // the visible X range, so stationary/recovery outliers cannot shrink it.
    final series = <({List<ActionTrackerGpsPoint> points, _ValidatedTrackCache track})>[];
    for (final rows in _movementTrackSeries(points)) {
      final track = _validatedTrack(rows);
      if (track.segments.isEmpty) continue;
      series.add((points: rows, track: track));
    }

    if (series.isEmpty) {
      _paintChartText(
        canvas,
        'Нет GPS скорости',
        Offset(size.width / 2, size.height / 2),
        10,
        _AA.muted,
      );
      return;
    }

    var observedMax = 0.0;
    for (final item in series) {
      for (final segment in item.track.segments) {
        observedMax = math.max(observedMax, segment.speedKmh).toDouble();
      }
    }

    // The chart scale follows the actual session, not the sprint threshold.
    // Example: max 9.4 km/h now occupies most of the chart instead of living
    // in the bottom quarter under an 18 km/h threshold.
    final maxSpeed = math
        .max(12.0, observedMax * 1.18)
        .clamp(12.0, 38.0)
        .toDouble();

    double yFor(double speed) => size.height -
        10 -
        (speed / maxSpeed).clamp(0.0, 1.0) * (size.height - 20);

    for (var i = 1; i <= 3; i++) {
      final y = size.height * i / 4;
      canvas.drawLine(
        Offset(0, y),
        Offset(size.width, y),
        Paint()..color = _AA.line.withOpacity(.55),
      );
    }

    void threshold(double speed, Color color) {
      // Do not clamp an unreachable threshold onto the top edge. If the
      // current session never approached HSR/SPR, the speed curve gets the
      // vertical space instead.
      if (speed <= 0 || speed > maxSpeed) return;
      final y = yFor(speed);
      canvas.drawLine(
        Offset(0, y),
        Offset(size.width, y),
        Paint()
          ..color = color.withOpacity(.55)
          ..strokeWidth = 1,
      );
    }

    threshold(hsrThresholdKmh, _AA.orange);
    threshold(sprintThresholdKmh, _AA.red);

    for (final item in series) {
      final rows = item.points;
      final track = item.track;

      var minTime = 0;
      var maxTime = 0;
      for (final segment in track.segments) {
        final from = rows[segment.fromIndex].timeMs;
        final to = rows[segment.toIndex].timeMs;
        if (from > 0 && (minTime == 0 || from < minTime)) minTime = from;
        if (to > maxTime) maxTime = to;
      }
      final span = math.max(1, maxTime - minTime);

      double xFor(int timeMs) =>
          ((timeMs - minTime) / span).clamp(0.0, 1.0) * size.width;

      final path = Path();
      var started = false;
      int? previousToIndex;

      for (final segment in track.segments) {
        final x = xFor(rows[segment.toIndex].timeMs);
        final y = yFor(segment.speedKmh);
        if (!started || previousToIndex != segment.fromIndex) {
          path.moveTo(x, y);
          started = true;
        } else {
          path.lineTo(x, y);
        }
        previousToIndex = segment.toIndex;
      }

      canvas.drawPath(
        path,
        Paint()
          ..color = _AA.green.withOpacity(.11)
          ..strokeWidth = 6
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round,
      );
      canvas.drawPath(
        path,
        Paint()
          ..color = _AA.green
          ..strokeWidth = 2
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round,
      );
    }

    final cursorX = cursor.clamp(0.0, 1.0) * size.width;
    canvas.drawLine(
      Offset(cursorX, 0),
      Offset(cursorX, size.height),
      Paint()
        ..color = _AA.text.withOpacity(.72)
        ..strokeWidth = 1.2,
    );
    canvas.drawCircle(
      Offset(cursorX, 8),
      3.5,
      Paint()..color = _AA.green,
    );
  }

  @override
  bool shouldRepaint(covariant _MovementTimelinePainter oldDelegate) =>
      oldDelegate.points != points ||
      oldDelegate.hsrThresholdKmh != hsrThresholdKmh ||
      oldDelegate.sprintThresholdKmh != sprintThresholdKmh ||
      oldDelegate.cursor != cursor;
}

class _MovementLiveMetricsGrid extends StatelessWidget {
  const _MovementLiveMetricsGrid({
    required this.distanceM,
    required this.avgSpeedKmh,
    required this.maxSpeedKmh,
    required this.durationSec,
    required this.sprintCount,
    required this.hirDistanceM,
    required this.accelCount,
    required this.decelCount,
    required this.turnCount,
    required this.loadScore,
    required this.explosiveActions,
    required this.fatigueLabel,
  });

  final double distanceM;
  final double avgSpeedKmh;
  final double maxSpeedKmh;
  final int durationSec;
  final int sprintCount;
  final double hirDistanceM;
  final int accelCount;
  final int decelCount;
  final int turnCount;
  final double loadScore;
  final int explosiveActions;
  final String fatigueLabel;

  @override
  Widget build(BuildContext context) {
    final values = <({String label, String value, IconData icon})>[
      (label: 'Дистанция', value: _meters(distanceM), icon: Icons.route_rounded),
      (label: 'Ср. скорость', value: '${avgSpeedKmh.toStringAsFixed(1)} км/ч', icon: Icons.speed_rounded),
      (label: 'Макс. скорость', value: '${maxSpeedKmh.toStringAsFixed(1)} км/ч', icon: Icons.bolt_rounded),
      (label: 'Время', value: _time(durationSec), icon: Icons.timer_outlined),
      (label: 'Спринты', value: '$sprintCount', icon: Icons.directions_run_rounded),
      (label: 'HIR', value: _meters(hirDistanceM), icon: Icons.trending_up_rounded),
      (label: 'Ускорения', value: '$accelCount', icon: Icons.north_east_rounded),
      (label: 'Торможения', value: '$decelCount', icon: Icons.south_east_rounded),
      (label: 'Повороты', value: '$turnCount', icon: Icons.change_circle_rounded),
      (label: 'Нагрузка', value: loadScore <= 0 ? '—' : loadScore.toStringAsFixed(0), icon: Icons.stacked_line_chart_rounded),
      (label: 'Взрывные', value: '$explosiveActions', icon: Icons.flash_on_rounded),
      (label: 'Усталость', value: fatigueLabel, icon: Icons.battery_3_bar_rounded),
    ];

    return LayoutBuilder(
      builder: (context, constraints) {
        final columns = constraints.maxWidth < 315 ? 3 : 4;
        final rows = (values.length / columns).ceil();
        final height = rows * 34.0 + (rows - 1) * 4.0;
        return SizedBox(
          height: height,
          child: GridView.builder(
            padding: EdgeInsets.zero,
            physics: const NeverScrollableScrollPhysics(),
            gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
              crossAxisCount: columns,
              crossAxisSpacing: 4,
              mainAxisSpacing: 4,
              mainAxisExtent: 34,
            ),
            itemCount: values.length,
            itemBuilder: (_, index) {
              final item = values[index];
              return Container(
                padding: const EdgeInsets.symmetric(horizontal: 6, vertical: 4),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(9),
                ),
                child: Row(
                  children: [
                    Icon(item.icon, size: 10.5, color: _AA.green),
                    const SizedBox(width: 4),
                    Expanded(
                      child: Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            item.label,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: _AText.caption(size: 7.1, color: _AA.muted),
                          ),
                          const SizedBox(height: 1),
                          Text(
                            item.value,
                            maxLines: 1,
                            overflow: TextOverflow.ellipsis,
                            style: _AText.body(
                              8.8,
                              color: _AA.text,
                              weight: FontWeight.w600,
                            ),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              );
            },
          ),
        );
      },
    );
  }
}


class _ReplayCursorMetrics {
  const _ReplayCursorMetrics({
    required this.distanceM,
    required this.avgSpeedKmh,
    required this.maxSpeedKmh,
    required this.durationSec,
    required this.sprintCount,
    required this.hirDistanceM,
    required this.accelCount,
    required this.decelCount,
    required this.turnCount,
    required this.loadScore,
    required this.explosiveActions,
    required this.fatigueLabel,
  });

  final double distanceM;
  final double avgSpeedKmh;
  final double maxSpeedKmh;
  final int durationSec;
  final int sprintCount;
  final double hirDistanceM;
  final int accelCount;
  final int decelCount;
  final int turnCount;
  final double loadScore;
  final int explosiveActions;
  final String fatigueLabel;

  factory _ReplayCursorMetrics.fromLocal(
    _LocalTrackAnalysis local, {
    required int turnCount,
    required String fatigueLabel,
    double loadScore = 0,
  }) {
    final resolvedLoad = loadScore > 0
        ? loadScore
        : local.distanceM / 10.0 +
            local.hsrDistanceM * .18 +
            (local.accelCount + local.decelCount) * 2.5 +
            local.sprintCount * 8.0;
    return _ReplayCursorMetrics(
      distanceM: local.distanceM,
      avgSpeedKmh: local.avgSpeedKmh,
      maxSpeedKmh: local.maxSpeedKmh,
      durationSec: local.durationSec,
      sprintCount: local.sprintCount,
      hirDistanceM: local.hsrDistanceM,
      accelCount: local.accelCount,
      decelCount: local.decelCount,
      turnCount: turnCount,
      loadScore: resolvedLoad,
      explosiveActions: local.accelCount + local.decelCount + local.sprintCount,
      fatigueLabel: fatigueLabel,
    );
  }
}

_ReplayCursorMetrics _replayCursorMetrics({
  required List<ActionTrackerGpsPoint> allPoints,
  required Set<int> playerIds,
  required RangeValues range,
  required double cursor,
  required double sprintThresholdKmh,
  required double hsrThresholdKmh,
  int fallbackDurationSec = 0,
}) {
  final selected = _movementPointsForPlayers(allPoints, playerIds);
  final ranged = _movementPointsForRange(selected, range);
  final inside = _movementCursorInsideRange(cursor, range);

  double distanceM = 0;
  double maxSpeedKmh = 0;
  double hirDistanceM = 0;
  double loadScore = 0;
  int activeDurationSec = 0;
  int sprintCount = 0;
  int accelCount = 0;
  int decelCount = 0;
  int turnCount = 0;
  final fatigueValues = <double>[];

  for (final track in _movementTrackSeries(ranged)) {
    if (track.length < 2) continue;
    final minTime = _movementMinTime(track);
    final maxTime = _movementMaxTime(track);
    if (minTime <= 0 || maxTime <= minTime) continue;
    final targetTime = minTime + ((maxTime - minTime) * inside).round();
    final cumulative = track
        .where((point) => point.timeMs <= targetTime)
        .toList(growable: false);
    if (cumulative.length < 2) continue;

    final analysis = _LocalTrackAnalysis.fromPoints(
      cumulative,
      sprintThresholdKmh: sprintThresholdKmh,
      hsrThresholdKmh: hsrThresholdKmh,
    );
    distanceM += analysis.distanceM;
    activeDurationSec += analysis.durationSec;
    maxSpeedKmh = math.max(maxSpeedKmh, analysis.maxSpeedKmh).toDouble();
    hirDistanceM += analysis.hsrDistanceM;
    sprintCount += analysis.sprintCount;
    accelCount += analysis.accelCount;
    decelCount += analysis.decelCount;
    turnCount += _validatedTrack(cumulative).turnPointIndexes.length;
    loadScore += analysis.distanceM / 10.0 +
        analysis.hsrDistanceM * .18 +
        (analysis.accelCount + analysis.decelCount) * 2.5 +
        analysis.sprintCount * 8.0;

    final fatigue = _MovementFatigue.fromPoints(
      cumulative,
      sprintThresholdKmh: sprintThresholdKmh,
    );
    if (fatigue.earlyMax > 0 && fatigue.deltaPct.isFinite) {
      fatigueValues.add(fatigue.deltaPct);
    }
  }

  final recordingSpanMs = _movementRecordingSpanMs(
    allPoints,
    fallbackDurationSec: fallbackDurationSec,
  );
  final durationSec = recordingSpanMs <= 0
      ? 0
      : ((recordingSpanMs * cursor.clamp(0.0, 1.0)) / 1000).round();
  final avgSpeedKmh = activeDurationSec <= 0
      ? 0.0
      : (distanceM / activeDurationSec) * 3.6;
  final fatiguePct = fatigueValues.isEmpty
      ? null
      : fatigueValues.reduce((a, b) => a + b) / fatigueValues.length;
  final fatigueLabel = fatiguePct == null
      ? '—'
      : '${fatiguePct >= 0 ? '+' : ''}${fatiguePct.toStringAsFixed(1)}%';

  return _ReplayCursorMetrics(
    distanceM: distanceM,
    avgSpeedKmh: avgSpeedKmh,
    maxSpeedKmh: maxSpeedKmh,
    durationSec: durationSec,
    sprintCount: sprintCount,
    hirDistanceM: hirDistanceM,
    accelCount: accelCount,
    decelCount: decelCount,
    turnCount: turnCount,
    loadScore: loadScore,
    explosiveActions: accelCount + decelCount + sprintCount,
    fatigueLabel: fatigueLabel,
  );
}

