    required this.maxSpeedKmh,
    required this.avgSpeedKmh,
    required this.peakAccelMps2,
    this.turnAngleDeg = 0,
    this.entrySpeedKmh = 0,
    this.exitSpeedKmh = 0,
  });
  final String kind;
  final int startIndex;
  final int endIndex;
  final int startTimeMs;
  final int endTimeMs;
  final double distanceM;
  final double maxSpeedKmh;
  final double avgSpeedKmh;
  final double peakAccelMps2;
  final double turnAngleDeg;
  final double entrySpeedKmh;
  final double exitSpeedKmh;

  int get durationMs => math.max(0, endTimeMs - startTimeMs);
}


// V145: журнал завершённой сессии повторяет Live-журнал, но строится
// из сохранённых GPS-точек. Обычная ходьба/бег остаются на треке, а в журнал
// попадают только моменты, которые действительно полезно пересматривать.
List<_MovementEvent> _movementJournalEvents(List<_MovementEvent> events) {
  const kinds = <String>{
    'sprint',
    'hir',
    'accel',
    'decel',
    'turn',
    'stop',
  };
  final out = events
      .where((event) => kinds.contains(event.kind))
      .toList(growable: false);
  return out.isEmpty ? events : out;
}

class _MovementMapMarker {
  const _MovementMapMarker({
    required this.point,
    required this.kind,
    required this.timeMs,
    required this.hasHeartRate,
    this.isRed = false,
    this.source = 'reconstructed',
  });

  final ActionTrackerGpsPoint point;
  final String kind;
  final int timeMs;
  final bool hasHeartRate;
  final bool isRed;
  final String source;
}

_ReplayJournalEvent? _replayEventForMapMarker(
  List<_ReplayJournalEvent> events,
  _MovementMapMarker marker,
) {
  _ReplayJournalEvent? best;
  var bestDelta = 1 << 62;
  for (final event in events) {
    final delta = (event.timeMs - marker.timeMs).abs();
    if (delta > 5000) continue;
    final sameKind = _replayKindsEquivalent(event.kind, marker.kind);
    // Событие того же типа всегда предпочтительнее соседнего события,
    // даже если соседнее стоит на несколько сотен миллисекунд ближе.
    final score = delta + (sameKind ? 0 : 3000);
    if (score < bestDelta) {
      bestDelta = score;
      best = event;
    }
  }
  return best;
}

List<_MovementEvent> _movementMarkerEventSample(
  List<_MovementEvent> events, {
  int limit = 160,
}) {
  if (events.length <= limit) return events;
  final chosen = <_MovementEvent>[];
  final seen = <int>{};

  // Спринты/HIR не теряем даже в очень длинной сессии.
  for (final event in events) {
    if (event.kind != 'sprint' && event.kind != 'hir') continue;
    if (seen.add(event.startTimeMs)) chosen.add(event);
    if (chosen.length >= limit) break;
  }
  if (chosen.length < limit) {
    final slots = limit - chosen.length;
    final step = math.max(1.0, events.length / slots);
    for (var i = 0; i < slots; i++) {
      final index = math.min(events.length - 1, (i * step).floor()).toInt();
      final event = events[index];
      if (seen.add(event.startTimeMs)) chosen.add(event);
    }
  }
  chosen.sort((a, b) => a.startTimeMs.compareTo(b.startTimeMs));
  return chosen.take(limit).toList(growable: false);
}

List<_MovementMapMarker> _movementMapMarkers(
  List<ActionTrackerGpsPoint> points,
  List<_MovementEvent> events,
  _AnalyticsHeartRate heartRate,
) {
  if (points.isEmpty || events.isEmpty) {
    return const <_MovementMapMarker>[];
  }
  final trackStartMs = _movementMinTime(points);
  final out = <_MovementMapMarker>[];
  for (final event in _movementMarkerEventSample(events)) {
    if (event.startIndex < 0 || event.startIndex >= points.length) continue;
    final point = points[event.startIndex];
    final hrProfile = _movementHrProfileForEvent(
      heartRate,
      event,
      point.playerId,
      trackStartMs,
    );
    out.add(_MovementMapMarker(
      point: point,
      kind: event.kind,
      timeMs: event.startTimeMs,
      hasHeartRate: hrProfile != null && hrProfile.hasData,
    ));
  }
  return out;
}

List<Map<String, dynamic>> _movementGpsHrCorrelations(
  List<ActionTrackerGpsPoint> points,
  List<_MovementEvent> events,
  _AnalyticsHeartRate heartRate,
  TrackerFieldModel? field,
) {
  if (points.isEmpty || events.isEmpty || heartRate.effectiveSamplesCount <= 0) {
    return const <Map<String, dynamic>>[];
  }
  final trackStartMs = _movementMinTime(points);
  final out = <Map<String, dynamic>>[];
  for (final event in events) {
    if (event.startIndex < 0 || event.startIndex >= points.length) continue;
    final point = points[event.startIndex];
    final profile = _movementHrProfileForEvent(
      heartRate,
      event,
      point.playerId,
      trackStartMs,
    );
    if (profile == null || !profile.hasData) continue;
    out.add(<String, dynamic>{
      'event': event.kind,
      'time_ms': event.startTimeMs,
      'elapsed_ms': math.max(0, event.startTimeMs - trackStartMs),
      'duration_ms': event.durationMs,
      'max_speed_kmh': event.maxSpeedKmh,
      'distance_m': event.distanceM,
      'peak_accel_mps2': event.peakAccelMps2,
      if (event.turnAngleDeg > 0) 'turn_angle_deg': event.turnAngleDeg,
      if (profile.startBpm != null) 'hr_start_bpm': profile.startBpm,
      if (profile.peakBpm != null) 'hr_peak_bpm': profile.peakBpm,
      if (profile.after30Bpm != null) 'hr_after_30s_bpm': profile.after30Bpm,
      if (profile.recoveryBpm != null)
        'hr_recovery_delta_bpm': profile.recoveryBpm,
      'field_zone': _movementFieldZone(point, points, field),
    });
    if (out.length >= 64) break;
  }
  return out;
}


// V146: единый журнал завершённой тренировки. Если сервер сохранил реальные
// Live-события — показываем их. Если нет, воспроизводим тот же смысл из GPS,
// Polar и качества потока. Это даёт Replay-журнал даже для старых тренировок.
class _ReplayJournalEvent {
  const _ReplayJournalEvent({
    required this.id,
    required this.source,
    required this.kind,
    required this.title,
    required this.detail,
    required this.timeMs,
    required this.playerId,
    required this.playerName,
    required this.severity,
    required this.speedKmh,
    this.elapsedMs,
    this.accelerationMps2 = 0,
    this.loadScore = 0,
    this.latitude,
    this.longitude,
    this.movementEvent,
    this.hrProfile,
  });

  final String id;
  final String source; // live | reconstructed
  final String kind;
  final String title;
  final String detail;
  final int timeMs;
  final int? playerId;
  final String playerName;
  final String severity;
  final double speedKmh;
  final int? elapsedMs;
  final double accelerationMps2;
  final double loadScore;
  final double? latitude;
  final double? longitude;
  final _MovementEvent? movementEvent;
  final _MovementHrProfile? hrProfile;

  bool get isRed => severity.toLowerCase() == 'red';
  bool get isArchivedLive => source == 'live';
  bool get hasCoordinates =>
      latitude != null && longitude != null &&
      latitude!.isFinite && longitude!.isFinite &&
      latitude!.abs() <= 90 && longitude!.abs() <= 180;
}

int _replayInt(dynamic value) {
  if (value is num) return value.toInt();
  return int.tryParse('${value ?? ''}'.trim()) ?? 0;
}

double _replayDouble(dynamic value) {
  if (value is num) return value.toDouble();
  return double.tryParse('${value ?? ''}'.trim()) ?? 0.0;
}

double? _replayNullableDouble(dynamic value) {
  final text = '${value ?? ''}'.trim();
  if (text.isEmpty || text == 'null') return null;
  final parsed = value is num ? value.toDouble() : double.tryParse(text);
  return parsed != null && parsed.isFinite ? parsed : null;
}

String _replayPlayerName(
  int? playerId,
  List<TrackerPlayerOption> players, {
  String fallback = 'Игрок',
}) {
  if (playerId != null && playerId > 0) {
    for (final player in players) {
      if (player.id == playerId || player.identityIds.contains(playerId)) {
        final name = player.name.trim();
        if (name.isNotEmpty) return name;
      }
    }
  }
  return fallback.trim().isEmpty ? 'Игрок' : fallback.trim();
}

String _replayNormalizeKind(String raw) {
  final value = raw.trim().toLowerCase();
  if (value.contains('sprint')) return 'sprint';
  if (value == 'hir' || value.contains('high_intensity') || value.contains('high intensity')) return 'hir';
  if (value.contains('decel') || value.contains('brak')) return 'decel';
  if (value.contains('accel')) return 'accel';
  if (value.contains('turn') || value.contains('direction')) return 'turn';
  if (value.contains('stop') || value.contains('stationary')) return 'stop';
  if (value.contains('gps') && (value.contains('gap') || value.contains('lost') || value.contains('offline'))) return 'gps_gap';
  if (value.contains('gps')) return 'gps';
  if (value.contains('heart') || value.contains('hr')) return 'hr';
  return value.isEmpty ? 'moment' : value;
}

bool _replayKindsEquivalent(String a, String b) {
  final left = _replayNormalizeKind(a);
  final right = _replayNormalizeKind(b);
  if (left == right) return true;
  const intensity = <String>{'sprint', 'hir'};
  return intensity.contains(left) && intensity.contains(right);
}

int _replayTrackStartForPlayer(
  List<ActionTrackerGpsPoint> points,
  int? playerId,
) {
  var minTime = 0;
  for (final point in points) {
    if (playerId != null && playerId > 0 &&
        point.playerId != null && point.playerId! > 0 && point.playerId != playerId) {
      continue;
    }
    if (point.timeMs <= 0) continue;
    if (minTime == 0 || point.timeMs < minTime) minTime = point.timeMs;
  }
  return minTime > 0 ? minTime : _movementMinTime(points);
}

bool _replayMovementSignificant(_MovementEvent event) {
  switch (event.kind) {
    case 'sprint':
    case 'hir':
      return true;
    case 'accel':
      return event.peakAccelMps2 >= 1.35;
    case 'decel':
      return event.peakAccelMps2 <= -1.35;
    case 'turn':
      return event.turnAngleDeg >= 30 && event.maxSpeedKmh >= 3.0;
    case 'stop':
      return event.durationMs >= 3000;
    default:
      return false;
  }
}

String _replayMovementDetail(_MovementEvent event) {
  if (event.kind == 'turn') {
    final delta = event.exitSpeedKmh - event.entrySpeedKmh;
    return '${event.turnAngleDeg.toStringAsFixed(0)}° · вход ${event.entrySpeedKmh.toStringAsFixed(1)} → выход ${event.exitSpeedKmh.toStringAsFixed(1)} км/ч · ${delta <= 0 ? 'потеря' : 'набор'} ${delta.abs().toStringAsFixed(1)}';
  }
  if (event.kind == 'accel' || event.kind == 'decel') {
    return '${event.peakAccelMps2.toStringAsFixed(2)} м/с² · до ${event.maxSpeedKmh.toStringAsFixed(1)} км/ч';
  }
  if (event.kind == 'stop') {
    return 'остановка ${(event.durationMs / 1000).toStringAsFixed(1)} с';
  }
  return 'макс. ${event.maxSpeedKmh.toStringAsFixed(1)} км/ч · ${event.distanceM.toStringAsFixed(0)} м · ${(event.durationMs / 1000).toStringAsFixed(1)} с';
}

List<_ReplayJournalEvent> _replayJournalFromMovement(
  List<ActionTrackerGpsPoint> points,
  List<_MovementEvent> events,
  _AnalyticsHeartRate heartRate,
  List<TrackerPlayerOption> players,
  TrackerFieldModel? field,
) {
  if (points.isEmpty || events.isEmpty) return const <_ReplayJournalEvent>[];
  final trackStartMs = _movementMinTime(points);
  final ordered = events.where(_replayMovementSignificant).toList(growable: false)
    ..sort((a, b) => a.startTimeMs.compareTo(b.startTimeMs));
  final lastByPlayerKind = <String, int>{};
  final out = <_ReplayJournalEvent>[];

  for (final event in ordered) {
    if (event.startIndex < 0 || event.startIndex >= points.length) continue;
    final point = points[event.startIndex];
    final playerId = point.playerId;
    final key = '${playerId ?? 0}:${event.kind}';
    final previous = lastByPlayerKind[key] ?? 0;
    final minGapMs = event.kind == 'sprint' || event.kind == 'hir'
        ? 1500
        : event.kind == 'stop'
            ? 5000
            : 3000;
    if (previous > 0 && event.startTimeMs - previous < minGapMs) continue;
    lastByPlayerKind[key] = event.startTimeMs;

    final hrProfile = _movementHrProfileForEvent(
      heartRate,
      event,
      playerId,
      trackStartMs,
    );
    final sessionMaxHr = heartRate.effectiveMaxBpm;
    final hrNearSessionPeak = sessionMaxHr > 0 &&
        (hrProfile?.peakBpm ?? 0) >= math.max(1, sessionMaxHr - 4);
    final red = event.kind == 'sprint' ||
        event.peakAccelMps2.abs() >= 2.6 ||
        (event.kind == 'turn' && event.turnAngleDeg >= 100 && event.maxSpeedKmh >= 10) ||
        ((event.kind == 'sprint' || event.kind == 'hir') && hrNearSessionPeak);
    final zone = _movementFieldZone(point, points, field);
    final details = <String>[_replayMovementDetail(event)];
    if (zone.isNotEmpty) details.add(zone);
    out.add(_ReplayJournalEvent(
      id: 'replay:${playerId ?? 0}:${event.kind}:${event.startTimeMs}',
      source: 'reconstructed',
      kind: event.kind,
      title: _movementEventLabel(event.kind),
      detail: details.join(' · '),
      timeMs: event.startTimeMs,
      playerId: playerId,
      playerName: _replayPlayerName(playerId, players, fallback: 'Игрок'),
      severity: red ? 'red' : 'orange',
      speedKmh: event.maxSpeedKmh,
      elapsedMs: math.max(0, event.startTimeMs - _replayTrackStartForPlayer(points, playerId)),
      accelerationMps2: event.peakAccelMps2,
      latitude: point.latitude,
      longitude: point.longitude,
      movementEvent: event,
      hrProfile: hrProfile,
    ));
    if (out.length >= 260) break;
  }

  // GPS-разрывы — часть Live-журнала. Для старых сессий их можно достоверно
  // восстановить по отсутствию точек внутри одного player stream.
  final grouped = <int, List<ActionTrackerGpsPoint>>{};
  for (final point in points) {
    final key = point.playerId ?? 0;
    (grouped[key] ??= <ActionTrackerGpsPoint>[]).add(point);
  }
  for (final entry in grouped.entries) {
    final rows = entry.value;
    if (rows.length < 2) continue;
    for (var i = 1; i < rows.length; i++) {
      final a = rows[i - 1];
      final b = rows[i];
      final gap = b.timeMs - a.timeMs;
      if (gap < 6000 || gap > 10 * 60 * 1000) continue;
      final red = gap >= 15000 || b.breakBefore;
      final playerId = b.playerId;
      out.add(_ReplayJournalEvent(
        id: 'replay:${playerId ?? 0}:gps_gap:${b.timeMs}',
        source: 'reconstructed',
        kind: 'gps_gap',
        title: red ? 'Разрыв GPS / связи' : 'Пауза GPS',
        detail: 'без новой GPS-точки ${(gap / 1000).toStringAsFixed(1)} с · ${_movementFieldZone(b, points, field)}',
        timeMs: b.timeMs,
        playerId: playerId,
        playerName: _replayPlayerName(playerId, players, fallback: 'Игрок'),
        severity: red ? 'red' : 'orange',
        speedKmh: b.speedKmh ?? 0,
        elapsedMs: math.max(0, b.timeMs - _replayTrackStartForPlayer(points, playerId)),
        latitude: b.latitude,
        longitude: b.longitude,
      ));
      if (out.length >= 300) break;
    }
    if (out.length >= 300) break;
  }

  out.sort((a, b) => b.timeMs.compareTo(a.timeMs));
  return out;
}

List<_ReplayJournalEvent> _replayJournalFromArchivedLive(
  List<Map<String, dynamic>> rawEvents,
  List<ActionTrackerGpsPoint> points,
  List<TrackerPlayerOption> players,
  _AnalyticsHeartRate heartRate, {
  Set<int> selectedPlayerIds = const <int>{},
}) {
  if (rawEvents.isEmpty || points.isEmpty) return const <_ReplayJournalEvent>[];
  final minTime = _movementMinTime(points);
  final maxTime = _movementMaxTime(points);
  if (minTime <= 0 || maxTime <= 0) return const <_ReplayJournalEvent>[];
  final liveIds = points
      .map((point) => point.liveSessionId ?? 0)
      .where((id) => id > 0)
      .toSet();
  final trackStartMs = minTime;
  final out = <_ReplayJournalEvent>[];

  for (final raw in rawEvents) {
    final timeMs = _replayInt(raw['time_ms']);
    if (timeMs <= 0) continue;
    final eventLiveId = _replayInt(raw['live_session_id']);
    final exactLiveMatch =
        liveIds.isNotEmpty && eventLiveId > 0 && liveIds.contains(eventLiveId);
    if (liveIds.isNotEmpty && eventLiveId > 0 && !exactLiveMatch) continue;
    if (!exactLiveMatch &&
        (timeMs < minTime - 90000 || timeMs > maxTime + 90000)) {
      continue;
    }
    final playerIdRaw = _replayInt(raw['player_id']);
    final playerId = playerIdRaw > 0 ? playerIdRaw : null;
    if (selectedPlayerIds.isNotEmpty &&
        playerId != null &&
        !selectedPlayerIds.contains(playerId)) {
      continue;
    }
    final rawName = '${raw['player_name'] ?? raw['name'] ?? ''}'.trim();
    final playerName = _replayPlayerName(
      playerId,
      players,
      fallback: rawName.isEmpty ? 'Игрок' : rawName,
    );
    final kind = _replayNormalizeKind('${raw['type'] ?? raw['event_type'] ?? 'moment'}');
    final severityRaw = '${raw['severity'] ?? ''}'.trim().toLowerCase();
    final speed = _replayDouble(raw['speed_kmh']);
    final accel = _replayDouble(raw['acceleration_mps2'] ?? raw['accel_mps2']);
    final severity = severityRaw == 'red' || severityRaw == 'critical'
        ? 'red'
        : (severityRaw == 'orange' || severityRaw == 'warning'
            ? 'orange'
            : ((kind == 'sprint' || accel.abs() >= 2.6) ? 'red' : 'orange'));
    final titleRaw = '${raw['title'] ?? ''}'.trim();
    final title = titleRaw.isEmpty
        ? (kind == 'gps_gap' ? 'Разрыв GPS / связи' : _movementEventLabel(kind))
        : titleRaw;
    final detailRaw = '${raw['detail'] ?? raw['message'] ?? ''}'.trim();
    final lat = _replayNullableDouble(raw['latitude'] ?? raw['lat']);
    final lng = _replayNullableDouble(raw['longitude'] ?? raw['lng'] ?? raw['lon']);
    final nearestHr = _nearestHrForGps(heartRate, playerId, timeMs, trackStartMs);
    final details = <String>[];
    if (detailRaw.isNotEmpty) details.add(detailRaw);
    if (detailRaw.isEmpty && speed > 0) details.add('${speed.toStringAsFixed(1)} км/ч');
    if (nearestHr != null) details.add('HR ${nearestHr.bpm} bpm');
    out.add(_ReplayJournalEvent(
      id: '${raw['event_id'] ?? raw['id'] ?? 'live:$eventLiveId:${playerId ?? 0}:$kind:$timeMs'}',
      source: 'live',
      kind: kind,
      title: title,
      detail: details.isEmpty ? 'сохранённый Live-момент' : details.join(' · '),
      timeMs: timeMs,
      playerId: playerId,
      playerName: playerName,
      severity: severity,
      speedKmh: speed,
      elapsedMs: math.max(0, timeMs - _replayTrackStartForPlayer(points, playerId)),
      accelerationMps2: accel,
      loadScore: _replayDouble(raw['load_score']),
      latitude: lat,
      longitude: lng,
    ));
  }
  out.sort((a, b) => b.timeMs.compareTo(a.timeMs));
  return out;
}

List<_ReplayJournalEvent> _mergeReplayJournalEvents(
  List<_ReplayJournalEvent> live,
  List<_ReplayJournalEvent> reconstructed,
) {
  if (live.isEmpty) return reconstructed;
  final out = <_ReplayJournalEvent>[...live];
  for (final replay in reconstructed) {
    final duplicate = live.any((real) {
      final samePlayer = real.playerId == null || replay.playerId == null ||
          real.playerId == replay.playerId;
      if (!samePlayer) return false;
      if ((real.timeMs - replay.timeMs).abs() > 3500) return false;
      return _replayKindsEquivalent(real.kind, replay.kind) ||
          real.kind == 'moment';
    });
    if (!duplicate) out.add(replay);
  }
  out.sort((a, b) => b.timeMs.compareTo(a.timeMs));
  return out.take(320).toList(growable: false);
}

ActionTrackerGpsPoint? _nearestReplayPoint(
  List<ActionTrackerGpsPoint> points,
  int timeMs,
  int? playerId,
) {
  if (points.isEmpty || timeMs <= 0) return null;
  ActionTrackerGpsPoint? best;
  var bestDelta = 1 << 62;
  for (final point in points) {
    if (playerId != null && playerId > 0 &&
        point.playerId != null && point.playerId! > 0 && point.playerId != playerId) {
      continue;
    }
    final delta = (point.timeMs - timeMs).abs();
    if (delta < bestDelta) {
      bestDelta = delta;
      best = point;
    }
  }
  return bestDelta <= 60000 ? best : null;
}

List<_ReplayJournalEvent> _replayMarkerSample(
  List<_ReplayJournalEvent> events, {
  // V150: на поле одновременно не больше 40 ключевых Replay-моментов.
  // Полный журнал справа при этом остаётся без обрезки.
  int limit = 40,
}) {
  if (events.length <= limit) return events;
  final chosen = <_ReplayJournalEvent>[];
  final ids = <String>{};
  void addWhere(bool Function(_ReplayJournalEvent) test) {
    for (final event in events) {
      if (!test(event) || !ids.add(event.id)) continue;
      chosen.add(event);
      if (chosen.length >= limit) return;
    }
  }
  addWhere((e) => e.isRed);
  if (chosen.length < limit) addWhere((e) => e.isArchivedLive);
  if (chosen.length < limit) {
    addWhere((e) => const <String>{'sprint', 'hir', 'gps_gap'}.contains(e.kind));
  }
  if (chosen.length < limit) {
    final remaining = events.where((e) => !ids.contains(e.id)).toList(growable: false);
    final slots = limit - chosen.length;
    final step = math.max(1.0, remaining.length / math.max(1, slots));
    for (var i = 0; i < slots && remaining.isNotEmpty; i++) {
      final index = math.min(remaining.length - 1, (i * step).floor()).toInt();
      final event = remaining[index];
      if (ids.add(event.id)) chosen.add(event);
    }
  }
  chosen.sort((a, b) => a.timeMs.compareTo(b.timeMs));
  return chosen.take(limit).toList(growable: false);
}

List<_MovementMapMarker> _replayJournalMapMarkers(
  List<ActionTrackerGpsPoint> points,
  List<_ReplayJournalEvent> events,
  _AnalyticsHeartRate heartRate,
) {
  if (points.isEmpty || events.isEmpty) return const <_MovementMapMarker>[];
  final startMs = _movementMinTime(points);
  final out = <_MovementMapMarker>[];
  for (final event in _replayMarkerSample(events)) {
    ActionTrackerGpsPoint? point;
    if (event.hasCoordinates) {
      point = ActionTrackerGpsPoint(
        timeMs: event.timeMs,
        latitude: event.latitude!,
        longitude: event.longitude!,
        speedKmh: event.speedKmh,
        playerId: event.playerId,
      );
    } else {
      point = _nearestReplayPoint(points, event.timeMs, event.playerId);
    }
    if (point == null) continue;
    final hasHr = event.hrProfile?.hasData == true ||
        _nearestHrForGps(heartRate, event.playerId, event.timeMs, startMs) != null;
    out.add(_MovementMapMarker(
      point: point,
      kind: event.kind,
      timeMs: event.timeMs,
      hasHeartRate: hasHr,
      isRed: event.isRed,
      source: event.source,
    ));
  }
  return out;
}


class _TelemetrySectorMetric {
  const _TelemetrySectorMetric({
    required this.index,
    required this.column,
    required this.row,
    required this.distanceM,
    required this.durationMs,
    required this.maxSpeedKmh,
    required this.avgSpeedKmh,
    required this.sprints,
    required this.turns,
  });

  final int index;
  final int column;
  final int row;
  final double distanceM;
  final int durationMs;
  final double maxSpeedKmh;
  final double avgSpeedKmh;
  final int sprints;
  final int turns;

  double get intensityScore =>
      distanceM + sprints * 38.0 + turns * 3.5 + maxSpeedKmh * 2.2;

  String get label => '${String.fromCharCode(65 + row)}${column + 1}';
}

Offset _telemetryNormalizedPoint(
  ActionTrackerGpsPoint point,
  TrackerFieldModel? field,
  _Bounds bounds,
) {
  final projected = TrackerPitchProjector.projectGps(
    field,
    latitude: point.latitude,
    longitude: point.longitude,
  );
  if (projected != null) {
    return Offset(projected.clampedNx, projected.clampedNy);
  }
  final x = ((point.longitude - bounds.minLng) / (bounds.maxLng - bounds.minLng))
      .clamp(0.0, 1.0)
      .toDouble();
  final y = (1 -
          ((point.latitude - bounds.minLat) / (bounds.maxLat - bounds.minLat))
              .clamp(0.0, 1.0))
      .toDouble();
  return Offset(x, y);
}

List<_TelemetrySectorMetric> _telemetrySectors(
  List<ActionTrackerGpsPoint> points,
  TrackerFieldModel? field, {
  required double hsrThresholdKmh,
  required double sprintThresholdKmh,
  int columns = 6,
  int rows = 3,
}) {
  if (points.length < 2) return const <_TelemetrySectorMetric>[];
  final bounds = _Bounds.fromGps(points);
  final validated = _validatedTrack(points);
  final distance = List<double>.filled(columns * rows, 0);
  final duration = List<int>.filled(columns * rows, 0);
  final maxSpeed = List<double>.filled(columns * rows, 0);
  final weightedSpeed = List<double>.filled(columns * rows, 0);
  final sprintCount = List<int>.filled(columns * rows, 0);
  final turnCount = List<int>.filled(columns * rows, 0);
  final sprintActive = List<bool>.filled(columns * rows, false);

  for (final segment in validated.segments) {
    if (segment.toIndex < 0 || segment.toIndex >= points.length) continue;
    final point = points[segment.toIndex];
    final n = _telemetryNormalizedPoint(point, field, bounds);
    final col = math.min(columns - 1, math.max(0, (n.dx * columns).floor()));
    final row = math.min(rows - 1, math.max(0, (n.dy * rows).floor()));
    final index = row * columns + col;
    distance[index] += segment.distanceM;
    duration[index] += segment.dtMs;
    maxSpeed[index] = math.max(maxSpeed[index], segment.speedKmh).toDouble();
    weightedSpeed[index] += segment.speedKmh * math.max(1, segment.dtMs);
    if (segment.speedKmh >= sprintThresholdKmh) {
      if (!sprintActive[index]) sprintCount[index]++;
      sprintActive[index] = true;
    } else if (segment.speedKmh < sprintThresholdKmh * .88) {
      sprintActive[index] = false;
    }
    if (validated.turnPointIndexes.contains(segment.toIndex)) {
      turnCount[index]++;
    }
  }

  final result = <_TelemetrySectorMetric>[];
  for (var row = 0; row < rows; row++) {
    for (var col = 0; col < columns; col++) {
      final index = row * columns + col;
      final dt = duration[index];
      final avg = dt <= 0 ? 0.0 : weightedSpeed[index] / dt;
      result.add(_TelemetrySectorMetric(
        index: index,
        column: col,
        row: row,
        distanceM: distance[index],
        durationMs: dt,
        maxSpeedKmh: maxSpeed[index],
        avgSpeedKmh: avg,
        sprints: sprintCount[index],
        turns: turnCount[index],
      ));
    }
  }
  return result;
}

class _TelemetryConfidence {
  const _TelemetryConfidence({
    required this.score,
    required this.gaps,
    required this.breaks,
    required this.impossibleSegments,
    required this.outsideFieldRatio,
    required this.avgIntervalMs,
  });

  final double score;
  final int gaps;
  final int breaks;
  final int impossibleSegments;
  final double outsideFieldRatio;
  final double avgIntervalMs;

  String get label {
    if (score >= 94) return 'Отлично';
    if (score >= 86) return 'Надёжно';
    if (score >= 74) return 'Средне';
    return 'Проверить GPS';
  }

  factory _TelemetryConfidence.fromPoints(
    List<ActionTrackerGpsPoint> points,
    TrackerFieldModel? field,
  ) {
    if (points.length < 2) {
      return const _TelemetryConfidence(
        score: 0,
        gaps: 0,
        breaks: 0,
        impossibleSegments: 0,
        outsideFieldRatio: 0,
        avgIntervalMs: 0,
      );
    }
    var gaps = 0;
    var breaks = 0;
    var impossible = 0;
    var totalDt = 0;
    var validDtCount = 0;
    var outside = 0;
    var projected = 0;
    for (var i = 1; i < points.length; i++) {
      final a = points[i - 1];
      final b = points[i];
      final dt = b.timeMs - a.timeMs;
      if (dt > 0) {
        totalDt += dt;
        validDtCount++;
      }
      if (dt > 3200) gaps++;
      if (b.breakBefore) breaks++;
      if (dt > 0 && dt <= 10000) {
        final d = _LocalTrackAnalysis._distanceMeters(
          a.latitude,
          a.longitude,
          b.latitude,
          b.longitude,
        );
        final speed = d / (dt / 1000.0) * 3.6;
        if (speed > 36.0) impossible++;
      }
      final q = TrackerPitchProjector.projectGps(
        field,
        latitude: b.latitude,
        longitude: b.longitude,
      );
      if (q != null) {
        projected++;
        if (!q.isInside) outside++;
      }
    }
    final denom = math.max(1, points.length - 1);
    final gapRatio = gaps / denom;
    final breakRatio = breaks / denom;
    final impossibleRatio = impossible / denom;
    final outsideRatio = projected <= 0 ? 0.0 : outside / projected;
    final avgInterval = validDtCount <= 0 ? 0.0 : totalDt / validDtCount;
    final sparsePenalty = avgInterval <= 1500
        ? 0.0
        : ((avgInterval - 1500) / 1500 * 9).clamp(0.0, 18.0).toDouble();
    final penalty = gapRatio * 52 +
        breakRatio * 34 +
        impossibleRatio * 85 +
        outsideRatio * 18 +
        sparsePenalty;
    return _TelemetryConfidence(
      score: (100 - penalty).clamp(0.0, 100.0).toDouble(),
      gaps: gaps,
      breaks: breaks,
      impossibleSegments: impossible,
      outsideFieldRatio: outsideRatio,
      avgIntervalMs: avgInterval,
    );
  }
}

class _TelemetryDelta {
  const _TelemetryDelta({
    required this.firstScore,
    required this.secondScore,
    required this.deltaPct,
    required this.firstMaxSpeed,
    required this.secondMaxSpeed,
  });

  final double firstScore;
  final double secondScore;
  final double deltaPct;
  final double firstMaxSpeed;
  final double secondMaxSpeed;

  String get label =>
      '${deltaPct >= 0 ? '+' : ''}${deltaPct.toStringAsFixed(1)}%';

  factory _TelemetryDelta.fromPoints(
    List<ActionTrackerGpsPoint> points, {
    required double hsrThresholdKmh,
    required double sprintThresholdKmh,
  }) {
    if (points.length < 4) {
      return const _TelemetryDelta(
        firstScore: 0,
        secondScore: 0,
        deltaPct: 0,
        firstMaxSpeed: 0,
        secondMaxSpeed: 0,
      );
    }
    final minT = _movementMinTime(points);
    final maxT = _movementMaxTime(points);
    final mid = minT + ((maxT - minT) / 2).round();
    final first = points.where((p) => p.timeMs <= mid).toList(growable: false);
    final second = points.where((p) => p.timeMs >= mid).toList(growable: false);

    double score(List<ActionTrackerGpsPoint> list) {
      final a = _LocalTrackAnalysis.fromPoints(
        list,
        hsrThresholdKmh: hsrThresholdKmh,
        sprintThresholdKmh: sprintThresholdKmh,
      );
      final minutes = math.max(1.0, a.durationSec / 60.0);
      return a.avgSpeedKmh * 3.0 +
          (a.hsrDistanceM / minutes) * .20 +
          (a.sprintCount / minutes) * 8.0;
    }

    final firstAnalysis = _LocalTrackAnalysis.fromPoints(
      first,
      hsrThresholdKmh: hsrThresholdKmh,
      sprintThresholdKmh: sprintThresholdKmh,
    );
    final secondAnalysis = _LocalTrackAnalysis.fromPoints(
      second,
      hsrThresholdKmh: hsrThresholdKmh,
      sprintThresholdKmh: sprintThresholdKmh,
    );
    final a = score(first);
    final b = score(second);
    final delta = a <= 0 ? 0.0 : ((b - a) / a * 100.0);
    return _TelemetryDelta(
      firstScore: a,
      secondScore: b,
      deltaPct: delta.clamp(-99.0, 99.0).toDouble(),
      firstMaxSpeed: firstAnalysis.maxSpeedKmh,
      secondMaxSpeed: secondAnalysis.maxSpeedKmh,
    );
  }
}

class _TelemetryDegradation {
  const _TelemetryDegradation({
    required this.quarterMaxSpeeds,
    required this.quarterHsrPerMin,
    required this.deltaPct,
  });

  final List<double> quarterMaxSpeeds;
  final List<double> quarterHsrPerMin;
  final double deltaPct;

  String get label =>
      '${deltaPct >= 0 ? '+' : ''}${deltaPct.toStringAsFixed(1)}%';

  factory _TelemetryDegradation.fromPoints(
    List<ActionTrackerGpsPoint> points, {
    required double hsrThresholdKmh,
    required double sprintThresholdKmh,
  }) {
    if (points.length < 5) {
      return const _TelemetryDegradation(
        quarterMaxSpeeds: <double>[],
        quarterHsrPerMin: <double>[],
        deltaPct: 0,
      );
    }
    final minT = _movementMinTime(points);
    final maxT = _movementMaxTime(points);
    final span = math.max(1, maxT - minT);
    final maxes = <double>[];
    final hsr = <double>[];
    for (var q = 0; q < 4; q++) {
      final start = minT + (span * q / 4).round();
      final end = minT + (span * (q + 1) / 4).round();
      final list = points
          .where((p) => p.timeMs >= start && p.timeMs <= end)
          .toList(growable: false);
      final a = _LocalTrackAnalysis.fromPoints(
        list,
        hsrThresholdKmh: hsrThresholdKmh,
        sprintThresholdKmh: sprintThresholdKmh,
      );
      maxes.add(a.maxSpeedKmh);
      final minutes = math.max(1.0, a.durationSec / 60.0);
      hsr.add(a.hsrDistanceM / minutes);
    }
    final first = hsr.isEmpty ? 0.0 : hsr.first;
    final last = hsr.isEmpty ? 0.0 : hsr.last;
    final delta = first <= 0 ? 0.0 : ((last - first) / first * 100.0);
    return _TelemetryDegradation(
      quarterMaxSpeeds: maxes,
      quarterHsrPerMin: hsr,
      deltaPct: delta.clamp(-99.0, 99.0).toDouble(),
    );
  }
}

class _TelemetryTeamShape {
  const _TelemetryTeamShape({
    required this.players,
    required this.widthM,
    required this.lengthM,
    required this.areaM2,
    required this.compactness,
  });

  final int players;
  final double widthM;
  final double lengthM;
  final double areaM2;
  final double compactness;

  factory _TelemetryTeamShape.fromFrames(
    List<_MatchPlaybackFrame> frames,
    TrackerFieldModel? field,
  ) {
    final usable = frames.where((f) => f.lastSampleDeltaMs <= 10000).toList();
    if (usable.length < 2) {
      return _TelemetryTeamShape(
        players: usable.length,
        widthM: 0,
        lengthM: 0,
        areaM2: 0,
        compactness: 0,
      );
    }
    final xs = <double>[];
    final ys = <double>[];
    final projected = <TrackerPitchProjection>[];
    for (final frame in usable) {
      final q = TrackerPitchProjector.projectGps(
        field,
        latitude: frame.point.latitude,
        longitude: frame.point.longitude,
      );
      if (q != null) projected.add(q);
    }
    if (projected.length == usable.length) {
      xs.addAll(projected.map((e) => e.xM));
      ys.addAll(projected.map((e) => e.yM));
    } else {
      final baseLat = usable.first.point.latitude;
      final baseLon = usable.first.point.longitude;
      for (final frame in usable) {
        final p = frame.point;
        final dx = _LocalTrackAnalysis._distanceMeters(
          baseLat,
          baseLon,
          baseLat,
          p.longitude,
        ) * (p.longitude < baseLon ? -1 : 1);
        final dy = _LocalTrackAnalysis._distanceMeters(
          baseLat,
          baseLon,
          p.latitude,
          baseLon,
        ) * (p.latitude < baseLat ? -1 : 1);
        xs.add(dx);
        ys.add(dy);
      }
    }
    final spanX = xs.reduce((a, b) => a > b ? a : b) -
        xs.reduce((a, b) => a < b ? a : b);
    final spanY = ys.reduce((a, b) => a > b ? a : b) -
        ys.reduce((a, b) => a < b ? a : b);
    final length = math.max(spanX, spanY).toDouble();
    final width = math.min(spanX, spanY).toDouble();
    final area = math.max(0.0, width * length).toDouble();
    final referenceArea = math.max(1.0, (field?.lengthM ?? 105) * (field?.widthM ?? 68)).toDouble();
    final compact = (100.0 * (1 - area / referenceArea))
        .clamp(0.0, 100.0)
        .toDouble();
    return _TelemetryTeamShape(
      players: usable.length,
      widthM: width,
      lengthM: length,
      areaM2: area,
      compactness: compact,
    );
  }
}

class _TelemetryAlert {
  const _TelemetryAlert({
    required this.level,
    required this.title,
    required this.detail,
    required this.icon,
  });

  final int level;
  final String title;
  final String detail;
  final IconData icon;
}

List<_TelemetryAlert> _telemetryAlerts({
  required _TelemetryConfidence confidence,
  required _TelemetryDelta delta,
  required _TelemetryDegradation degradation,
  required _TelemetryTeamShape teamShape,
  required _AnalyticsHeartRate heartRate,
  required List<_MatchPlaybackFrame> frames,
}) {
  final alerts = <_TelemetryAlert>[];
  if (confidence.score < 86) {
    alerts.add(_TelemetryAlert(
      level: confidence.score < 74 ? 3 : 2,
      title: 'Качество GPS ${confidence.score.toStringAsFixed(0)}%',
      detail: '${confidence.gaps} разрывов · ${confidence.impossibleSegments} отброшенных скачков',
      icon: Icons.gps_off_rounded,
    ));
  }
  if (delta.deltaPct <= -8) {
    alerts.add(_TelemetryAlert(
      level: delta.deltaPct <= -15 ? 3 : 2,
      title: 'Падение темпа ${delta.label}',
      detail: 'Вторая половина слабее первой по скоростной и HSR-телеметрии',
      icon: Icons.trending_down_rounded,
    ));
  }
  if (degradation.deltaPct <= -10) {
    alerts.add(_TelemetryAlert(
      level: degradation.deltaPct <= -20 ? 3 : 2,
      title: 'Деградация HSR ${degradation.label}',
      detail: 'Последний сектор сессии теряет высокоинтенсивную работу',
      icon: Icons.battery_std_rounded,
    ));
  }
  final stale = frames.where((f) => f.lastSampleDeltaMs > 3000).length;
  if (stale > 0) {
    alerts.add(_TelemetryAlert(
      level: stale >= 3 ? 3 : 2,
      title: '$stale игроков без свежего GPS',
      detail: 'Игроки остаются на последней достоверной позиции',
      icon: Icons.wifi_off_rounded,
    ));
  }
  if (teamShape.players >= 4 && teamShape.compactness < 55) {
    alerts.add(_TelemetryAlert(
      level: 1,
      title: 'Команда растянута',
      detail: 'Компактность ${teamShape.compactness.toStringAsFixed(0)}% · ${teamShape.lengthM.toStringAsFixed(0)}×${teamShape.widthM.toStringAsFixed(0)} м',
      icon: Icons.open_in_full_rounded,
    ));
  }
  if (heartRate.effectiveMaxBpm > 0 && heartRate.effectiveSamplesCount > 0) {
    alerts.add(_TelemetryAlert(
      level: 0,
      title: 'Polar синхронизирован',
      detail: 'HR max ${heartRate.effectiveMaxBpm} · ${heartRate.effectiveSamplesCount} замеров',
      icon: Icons.favorite_rounded,
    ));
  }
  if (alerts.isEmpty) {
    alerts.add(const _TelemetryAlert(
      level: 0,
      title: 'Телеметрия стабильна',
      detail: 'Критических отклонений в выбранном диапазоне не найдено',
      icon: Icons.verified_rounded,
    ));
  }
  alerts.sort((a, b) => b.level.compareTo(a.level));
  return alerts;
}

List<_TelemetryAlert> _telemetryWeatherAlerts(
  _TelemetryWeatherSnapshot? weather, {
  required _TelemetryDelta delta,
  required _TelemetryDegradation degradation,
}) {
  if (weather == null) return const <_TelemetryAlert>[];
  final alerts = <_TelemetryAlert>[];
  if (weather.temperatureC >= 28 || weather.apparentTemperatureC >= 30) {
    alerts.add(_TelemetryAlert(
      level: weather.temperatureC >= 32 ? 3 : 2,
      title: 'Погодная нагрузка · ${weather.temperatureC.toStringAsFixed(0)}°C',
      detail: 'Учитывайте жару при интерпретации темпа и восстановления; чаще контролируйте воду и паузы',
      icon: Icons.wb_sunny_rounded,
    ));
  }
  if (weather.humidityPct >= 75) {
    alerts.add(_TelemetryAlert(
      level: 2,
      title: 'Влажность ${weather.humidityPct.toStringAsFixed(0)}%',
      detail: 'Сопоставляйте повторные спринты с HR-восстановлением, а не только с внешней скоростью',
      icon: Icons.water_drop_outlined,
    ));
  }
  if (weather.windSpeedMps >= 8) {
    alerts.add(_TelemetryAlert(
      level: 1,
      title: 'Ветер ${weather.windSpeedMps.toStringAsFixed(1)} м/с',
      detail: 'Скорость по направлениям может отличаться — сравнивайте сектора и Ghost в одинаковых направлениях',
      icon: Icons.air_rounded,
    ));
  }
  if (weather.precipitationMm >= .2) {
    alerts.add(_TelemetryAlert(
      level: 1,
      title: 'Осадки ${weather.precipitationMm.toStringAsFixed(1)} мм',
      detail: 'Учитывайте сцепление покрытия при резких торможениях и поворотах',
      icon: Icons.grain_rounded,
    ));
  }
  if ((delta.deltaPct <= -10 || degradation.deltaPct <= -15) &&
      (weather.temperatureC >= 25 || weather.humidityPct >= 70)) {
    alerts.add(_TelemetryAlert(
      level: 2,
      title: 'Темп падает на фоне погодной нагрузки',
      detail: 'Это не доказывает причинность, но погоду стоит учитывать вместе с HSR и Polar при решении о паузе/замене',
      icon: Icons.thermostat_rounded,
    ));
  }
  return alerts;
}

class _TelemetryKeyMoment {
  const _TelemetryKeyMoment({
    required this.timeMs,
    required this.title,
    required this.detail,
    required this.icon,
    required this.score,
  });

  final int timeMs;
  final String title;
  final String detail;
  final IconData icon;
  final double score;

  Map<String, dynamic> toJson(int sessionStartMs) => <String, dynamic>{
        'time_ms': timeMs,
        'elapsed_ms': math.max(0, timeMs - sessionStartMs),
        'title': title,
        'detail': detail,
        'score': score,
      };
}

List<_TelemetryKeyMoment> _telemetryKeyMoments(
  List<ActionTrackerGpsPoint> points,
  List<_MovementEvent> events,
  _AnalyticsHeartRate heartRate,
) {
  final moments = <_TelemetryKeyMoment>[];
  final trackStartMs = _movementMinTime(points);
  for (final event in events) {
    final point = event.startIndex >= 0 && event.startIndex < points.length
        ? points[event.startIndex]
        : null;
    final hrProfile = point == null
        ? null
        : _movementHrProfileForEvent(
            heartRate,
            event,
            point.playerId,
            trackStartMs,
          );
    final cardioDetail = hrProfile == null || !hrProfile.hasData
        ? ''
        : ' · ${hrProfile.label}';
    if (event.kind == 'sprint') {
      moments.add(_TelemetryKeyMoment(
        timeMs: event.startTimeMs,
        title: 'Спринт ${event.maxSpeedKmh.toStringAsFixed(1)} км/ч',
        detail: '${event.distanceM.toStringAsFixed(0)} м · ${(event.durationMs / 1000).toStringAsFixed(1)} с$cardioDetail',
        icon: Icons.flash_on_rounded,
        score: 60 + event.maxSpeedKmh,
      ));
    } else if (event.kind == 'accel') {
      moments.add(_TelemetryKeyMoment(
        timeMs: event.startTimeMs,
        title: 'Ускорение ${event.peakAccelMps2.toStringAsFixed(2)} м/с²',
        detail: 'пик ${event.maxSpeedKmh.toStringAsFixed(1)} км/ч$cardioDetail',
        icon: Icons.trending_up_rounded,
        score: 45 + event.peakAccelMps2.abs() * 8,
      ));
    } else if (event.kind == 'decel') {
      moments.add(_TelemetryKeyMoment(
        timeMs: event.startTimeMs,
        title: 'Торможение ${event.peakAccelMps2.toStringAsFixed(2)} м/с²',
        detail: 'смена темпа до ${event.maxSpeedKmh.toStringAsFixed(1)} км/ч$cardioDetail',
        icon: Icons.trending_down_rounded,
        score: 42 + event.peakAccelMps2.abs() * 7,
      ));
    } else if (event.kind == 'turn' && event.turnAngleDeg >= 65) {
      moments.add(_TelemetryKeyMoment(
        timeMs: event.startTimeMs,
        title: 'Резкий поворот ${event.turnAngleDeg.toStringAsFixed(0)}°',
        detail: '${event.entrySpeedKmh.toStringAsFixed(1)} → ${event.exitSpeedKmh.toStringAsFixed(1)} км/ч$cardioDetail',
        icon: Icons.change_circle_rounded,
        score: 35 + event.turnAngleDeg / 4,
      ));
    }
  }
  final adaptiveHrThreshold = (heartRate.effectiveMaxBpm <= 0
          ? double.infinity
          : math.max(
              heartRate.effectiveAvgBpm > 0
                  ? heartRate.effectiveAvgBpm + 18.0
                  : 0.0,
              heartRate.effectiveMaxBpm * .90,
            ))
      .toDouble();
  for (final p in heartRate.timelineForChart) {
    if (p.timeMs > 0 && p.bpm >= adaptiveHrThreshold) {
      moments.add(_TelemetryKeyMoment(
        timeMs: p.timeMs,
        title: 'HR ${p.bpm} bpm · ${p.zone.toUpperCase()}',
        detail: p.playerName.trim().isEmpty
            ? 'пиковая внутренняя реакция относительно этой сессии'
            : p.playerName,
        icon: Icons.favorite_rounded,
        score: 40.0 +
            math.max(0.0, p.bpm.toDouble() - adaptiveHrThreshold).toDouble() *
                .8,
      ));
    }
  }
  moments.sort((a, b) => b.score.compareTo(a.score));
  final unique = <_TelemetryKeyMoment>[];
  for (final m in moments) {
    if (unique.any((e) => (e.timeMs - m.timeMs).abs() < 3000)) continue;
    unique.add(m);
    if (unique.length >= 16) break;
  }
  unique.sort((a, b) => a.timeMs.compareTo(b.timeMs));
  return unique;
}

ActionTrackerGpsPoint? _telemetryGhostPoint(
  List<ActionTrackerGpsPoint> allPoints,
  Set<int> selectedIds,
  List<TrackerPlayerOption> players,
  double cursor,
  RangeValues range,
) {
  if (selectedIds.length < 2) return null;
  final ordered = selectedIds.toList()..sort();
  final ghostId = ordered[1];
  final ghostIds = <int>{ghostId};
  for (final p in players) {
    if (p.id == ghostId || p.identityIds.contains(ghostId)) {
      ghostIds.add(p.id);
      ghostIds.addAll(p.identityIds);
      break;
    }
  }
  final series = _movementPointsForPlayers(allPoints, ghostIds);
  if (series.isEmpty) return null;
  return _movementPointAtProgress(series, cursor, range: range);
}


List<ActionTrackerGpsPoint> _telemetryPitMarkerPoints(
  List<ActionTrackerGpsPoint> points,
  List<_TelemetryKeyMoment> moments,
) {
  if (points.isEmpty || moments.isEmpty) return const <ActionTrackerGpsPoint>[];
  final source = points.where((p) => p.timeMs > 0).toList(growable: false);
  if (source.isEmpty) return const <ActionTrackerGpsPoint>[];
  final out = <ActionTrackerGpsPoint>[];
  for (final moment in moments.take(6)) {
    ActionTrackerGpsPoint? best;
    var bestDelta = 1 << 62;
    for (final point in source) {
      final delta = (point.timeMs - moment.timeMs).abs();
      if (delta < bestDelta) {
        bestDelta = delta;
        best = point;
      }
    }
    if (best != null && bestDelta <= 12000) out.add(best);
  }
  return out;
}


