class _TelemetryWeatherCard extends StatefulWidget {
  const _TelemetryWeatherCard({
    required this.points,
    required this.fieldTitle,
    required this.sessionCreatedAt,
    required this.playerLabel,
    required this.deltaPct,
    required this.degradationPct,
    required this.onChanged,
  });

  final List<ActionTrackerGpsPoint> points;
  final String fieldTitle;
  final String sessionCreatedAt;
  final String playerLabel;
  final double deltaPct;
  final double degradationPct;
  final ValueChanged<_TelemetryWeatherSnapshot> onChanged;

  @override
  State<_TelemetryWeatherCard> createState() => _TelemetryWeatherCardState();
}

class _TelemetryWeatherCardState extends State<_TelemetryWeatherCard> {
  _TelemetryWeatherSnapshot? _data;
  bool _loading = false;
  String _error = '';
  String _requestKey = '';

  @override
  void initState() {
    super.initState();
    unawaited(_load());
  }

  @override
  void didUpdateWidget(covariant _TelemetryWeatherCard oldWidget) {
    super.didUpdateWidget(oldWidget);
    final nextKey = _keyFor(widget);
    if (nextKey != _requestKey) unawaited(_load());
  }

  String _keyFor(_TelemetryWeatherCard value) {
    if (value.points.isEmpty) return 'empty';
    final p = value.points[value.points.length ~/ 2];
    return '${p.latitude.toStringAsFixed(4)}|${p.longitude.toStringAsFixed(4)}|${value.sessionCreatedAt}';
  }

  Future<void> _load() async {
    final key = _keyFor(widget);
    _requestKey = key;
    if (widget.points.isEmpty) {
      if (mounted) setState(() => _error = 'Нет GPS для погоды');
      return;
    }
    final point = widget.points[widget.points.length ~/ 2];
    if (!point.latitude.isFinite || !point.longitude.isFinite) return;
    if (mounted) setState(() {
      _loading = true;
      _error = '';
    });

    try {
      final sessionTime = _trackerMoscowDateTime(widget.sessionCreatedAt) ??
          DateTime.now();
      final date = '${sessionTime.year.toString().padLeft(4, '0')}-${sessionTime.month.toString().padLeft(2, '0')}-${sessionTime.day.toString().padLeft(2, '0')}';
      final hour = sessionTime.hour;

      Map<String, dynamic>? weather;
      String source = 'Open-Meteo';

      Future<Map<String, dynamic>?> fetchArchive() async {
        final uri = Uri.parse('https://archive-api.open-meteo.com/v1/archive')
            .replace(queryParameters: <String, String>{
          'latitude': '${point.latitude}',
          'longitude': '${point.longitude}',
          'start_date': date,
          'end_date': date,
          'hourly':
              'temperature_2m,apparent_temperature,relative_humidity_2m,precipitation,wind_speed_10m',
          'timezone': 'auto',
        });
        final response = await http.get(uri).timeout(const Duration(seconds: 7));
        if (response.statusCode != 200) return null;
        final decoded = jsonDecode(response.body);
        if (decoded is! Map) return null;
        final hourly = decoded['hourly'];
        if (hourly is! Map) return null;
        final times = hourly['time'];
        if (times is! List || times.isEmpty) return null;
        var index = hour.clamp(0, times.length - 1).toInt();
        double read(String name) {
          final values = hourly[name];
          if (values is! List || values.isEmpty) return 0;
          index = index.clamp(0, values.length - 1).toInt();
          final raw = values[index];
          return raw is num ? raw.toDouble() : double.tryParse('$raw') ?? 0;
        }
        return <String, dynamic>{
          'temperature': read('temperature_2m'),
          'apparent': read('apparent_temperature'),
          'humidity': read('relative_humidity_2m'),
          'precipitation': read('precipitation'),
          'wind_kmh': read('wind_speed_10m'),
        };
      }

      Future<Map<String, dynamic>?> fetchCurrent() async {
        final uri = Uri.parse('https://api.open-meteo.com/v1/forecast')
            .replace(queryParameters: <String, String>{
          'latitude': '${point.latitude}',
          'longitude': '${point.longitude}',
          'current':
              'temperature_2m,apparent_temperature,relative_humidity_2m,precipitation,wind_speed_10m',
          'timezone': 'auto',
        });
        final response = await http.get(uri).timeout(const Duration(seconds: 7));
        if (response.statusCode != 200) return null;
        final decoded = jsonDecode(response.body);
        if (decoded is! Map) return null;
        final current = decoded['current'];
        if (current is! Map) return null;
        double read(String name) {
          final raw = current[name];
          return raw is num ? raw.toDouble() : double.tryParse('$raw') ?? 0;
        }
        source = 'Open-Meteo · сейчас';
        return <String, dynamic>{
          'temperature': read('temperature_2m'),
          'apparent': read('apparent_temperature'),
          'humidity': read('relative_humidity_2m'),
          'precipitation': read('precipitation'),
          'wind_kmh': read('wind_speed_10m'),
        };
      }

      weather = await fetchArchive();
      weather ??= await fetchCurrent();
      if (weather == null) throw StateError('weather unavailable');

      final coordinates =
          '${point.latitude.toStringAsFixed(4)}, ${point.longitude.toStringAsFixed(4)}';
      final location = widget.fieldTitle.trim().isNotEmpty
          ? '${widget.fieldTitle.trim()} · $coordinates'
          : coordinates;
      final snapshot = _TelemetryWeatherSnapshot(
        temperatureC: (weather['temperature'] as num?)?.toDouble() ?? 0,
        apparentTemperatureC: (weather['apparent'] as num?)?.toDouble() ?? 0,
        humidityPct: (weather['humidity'] as num?)?.toDouble() ?? 0,
        windSpeedMps: ((weather['wind_kmh'] as num?)?.toDouble() ?? 0) / 3.6,
        precipitationMm:
            (weather['precipitation'] as num?)?.toDouble() ?? 0,
        latitude: point.latitude,
        longitude: point.longitude,
        locationLabel: location,
        sourceLabel: source,
      );
      if (!mounted || key != _requestKey) return;
      setState(() {
        _data = snapshot;
        _loading = false;
      });
      widget.onChanged(snapshot);
    } catch (_) {
      if (!mounted || key != _requestKey) return;
      setState(() {
        _loading = false;
        _error = 'Погода временно недоступна';
      });
    }
  }

  String _advice(_TelemetryWeatherSnapshot data) {
    final parts = <String>[];
    if (data.temperatureC >= 28 || data.apparentTemperatureC >= 30) {
      parts.add('жара — чаще вода и длиннее восстановление');
    }
    if (data.humidityPct >= 75) {
      parts.add('высокая влажность — следить за HR-восстановлением');
    }
    if (data.windSpeedMps >= 8) {
      parts.add('сильный ветер — сравнивать скорость по направлениям');
    }
    if (data.precipitationMm >= .2) {
      parts.add('осадки — учитывать сцепление при торможениях и поворотах');
    }
    if ((widget.deltaPct <= -10 || widget.degradationPct <= -15) &&
        (data.temperatureC >= 25 || data.humidityPct >= 70)) {
      parts.add('падение темпа лучше оценивать вместе с погодной нагрузкой');
    }
    if (parts.isEmpty) return 'условия нейтральные · используйте погоду как контекст нагрузки';
    return parts.take(2).join(' · ');
  }

  @override
  Widget build(BuildContext context) {
    final data = _data;
    return Container(
      padding: const EdgeInsets.symmetric(horizontal: 9, vertical: 8),
      decoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(12),
      ),
      child: Row(children: [
        Container(
          width: 30,
          height: 30,
          alignment: Alignment.center,
          decoration: BoxDecoration(
            color: _AA.greenSoft,
            borderRadius: BorderRadius.circular(10),
          ),
          child: Icon(
            data == null
                ? Icons.cloud_outlined
                : (data.precipitationMm > .2
                    ? Icons.water_drop_outlined
                    : Icons.wb_sunny_outlined),
            color: _AA.green,
            size: 17,
          ),
        ),
        const SizedBox(width: 8),
        Expanded(
          child: _loading
              ? const Text('Погода · загружаю условия сессии…',
                  style: TextStyle(
                      color: _AA.muted,
                      fontSize: 8.9,
                      fontWeight: FontWeight.w700))
              : data == null
                  ? Text(
                      _error.isEmpty ? 'Погода · нет данных' : _error,
                      style: const TextStyle(
                          color: _AA.muted,
                          fontSize: 8.9,
                          fontWeight: FontWeight.w700),
                    )
                  : Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Row(children: [
                          Expanded(
                            child: Text(
                              '${data.locationLabel} · ${data.temperatureC.toStringAsFixed(0)}°C · ${data.humidityPct.toStringAsFixed(0)}% · ветер ${data.windSpeedMps.toStringAsFixed(1)} м/с',
                              maxLines: 1,
                              overflow: TextOverflow.ellipsis,
                              style: const TextStyle(
                                  color: _AA.text,
                                  fontSize: 9.0,
                                  fontWeight: FontWeight.w800),
                            ),
                          ),
                        ]),
                        const SizedBox(height: 2),
                        Text(
                          'Совет: ${_advice(data)}',
                          maxLines: 2,
                          overflow: TextOverflow.ellipsis,
                          style: const TextStyle(
                              color: _AA.muted,
                              fontSize: 7.7,
                              fontWeight: FontWeight.w600,
                              height: 1.18),
                        ),
                      ],
                    ),
        ),
      ]),
    );
  }
}

