class _TelemetryStackPainter extends CustomPainter {
  _TelemetryStackPainter({
    required this.points,
    required this.heartRate,
    required this.cursor,
    required this.range,
    required this.hsrThresholdKmh,
    required this.sprintThresholdKmh,
  });
  final List<ActionTrackerGpsPoint> points;
  final _AnalyticsHeartRate heartRate;
  final double cursor;
  final RangeValues range;
  final double hsrThresholdKmh;
  final double sprintThresholdKmh;

  @override
  void paint(Canvas canvas, Size size) {
    final rect = Rect.fromLTWH(32, 0, math.max(1.0, size.width - 32).toDouble(), size.height);
    final laneH = size.height / 4;
    final grid = Paint()..color = _AA.line.withOpacity(.75)..strokeWidth = .6;
    for (var i = 1; i < 4; i++) {
      canvas.drawLine(Offset(0, laneH * i), Offset(size.width, laneH * i), grid);
    }
    void label(String text, double y) => _paintChartText(canvas, text, Offset(2, y + 8), 6.8, _AA.muted, alignLeft: true);
    label('SPD', 0);
    label('ACC', laneH);
    label('HR', laneH * 2);
    label('GPS', laneH * 3);
    if (points.length < 2) return;
    final validated = _validatedTrack(points);
    final minT = _movementMinTime(points);
    final maxT = math.max(minT + 1, _movementMaxTime(points)).toInt();
    double xFor(int t) => rect.left + ((t - minT) / (maxT - minT)).clamp(0.0, 1.0).toDouble() * rect.width;
    final maxSpeed = math.max(
      10.0,
      validated.segments.fold<double>(
        0,
        (v, e) => math.max(v, e.speedKmh).toDouble(),
      ),
    ).toDouble();
    final speedPath = Path();
    final accelPath = Path();
    var firstS = true;
    var firstA = true;
    for (final s in validated.segments) {
      final x = xFor(points[s.toIndex].timeMs);
      final sy = laneH - 2 - (s.speedKmh / maxSpeed).clamp(0.0, 1.0).toDouble() * (laneH - 5);
      if (firstS) { speedPath.moveTo(x, sy); firstS = false; } else { speedPath.lineTo(x, sy); }
      final normalizedA = ((s.accelMps2 + 4) / 8).clamp(0.0, 1.0).toDouble();
      final ay = laneH * 2 - 2 - normalizedA * (laneH - 5);
      if (firstA) { accelPath.moveTo(x, ay); firstA = false; } else { accelPath.lineTo(x, ay); }
    }
    canvas.drawPath(speedPath, Paint()..color = _AA.green..strokeWidth = 1.2..style = PaintingStyle.stroke);
    canvas.drawPath(accelPath, Paint()..color = _AA.blue..strokeWidth = 1.0..style = PaintingStyle.stroke);
    final hr = heartRate.timelineForChart.where((p) => p.timeMs > 0).toList();
    if (hr.length > 1) {
      final maxHr = math.max(
        180,
        hr.map((e) => e.bpm).reduce((a, b) => a > b ? a : b),
      ).toInt();
      final hp = Path();
      for (var i = 0; i < hr.length; i++) {
        final x = xFor(hr[i].timeMs);
        final y = laneH * 3 - 2 - (hr[i].bpm / maxHr).clamp(0.0, 1.0).toDouble() * (laneH - 5);
        if (i == 0) hp.moveTo(x, y); else hp.lineTo(x, y);
      }
      canvas.drawPath(hp, Paint()..color = _AA.red..strokeWidth = 1.1..style = PaintingStyle.stroke);
    }
    for (var i = 1; i < points.length; i++) {
      final dt = points[i].timeMs - points[i - 1].timeMs;
      if (dt > 3200 || points[i].breakBefore) {
        final x = xFor(points[i].timeMs);
        canvas.drawRect(Rect.fromLTWH(x - 1.2, laneH * 3 + 2, 2.4, laneH - 4), Paint()..color = _AA.orange.withOpacity(.75));
      }
    }
    final cx = rect.left + cursor.clamp(0.0, 1.0).toDouble() * rect.width;
    canvas.drawLine(Offset(cx, 0), Offset(cx, size.height), Paint()..color = _AA.text.withOpacity(.65)..strokeWidth = 1.0);
  }

  @override
  bool shouldRepaint(covariant _TelemetryStackPainter oldDelegate) =>
      oldDelegate.points != points || oldDelegate.heartRate != heartRate || oldDelegate.cursor != cursor || oldDelegate.range != range;
}

class _TelemetrySectorOverlayPainter extends CustomPainter {
  _TelemetrySectorOverlayPainter({required this.sectors});
  final List<_TelemetrySectorMetric> sectors;
  @override
  void paint(Canvas canvas, Size size) {
    if (sectors.isEmpty) return;
    final maxScore = sectors.fold<double>(
      1,
      (v, e) => math.max(v, e.intensityScore).toDouble(),
    );
    const columns = 6;
    const rows = 3;
    final inner = _pitchInnerRect(size);
    for (final s in sectors) {
      final ratio = (s.intensityScore / maxScore).clamp(0.0, 1.0).toDouble();
      final rect = Rect.fromLTWH(
        inner.left + s.column * inner.width / columns,
        inner.top + s.row * inner.height / rows,
        inner.width / columns,
        inner.height / rows,
      );
      canvas.drawRect(rect, Paint()..color = _AA.green.withOpacity(.025 + ratio * .11));
      canvas.drawRect(rect, Paint()..color = Colors.white.withOpacity(.30)..style = PaintingStyle.stroke..strokeWidth = .55);
      if (ratio > .30) {
        _paintChartText(canvas, s.label, rect.topLeft + const Offset(5, 10), 7.2, Colors.white.withOpacity(.86), alignLeft: true);
      }
    }
  }
  @override
  bool shouldRepaint(covariant _TelemetrySectorOverlayPainter oldDelegate) => oldDelegate.sectors != sectors;
}

class _TelemetryTeamShapeOverlayPainter extends CustomPainter {
  _TelemetryTeamShapeOverlayPainter({
    required this.frames,
    required this.field,
    required this.allPoints,
    required this.mapRotationDeg,
  });
  final List<_MatchPlaybackFrame> frames;
  final TrackerFieldModel? field;
  final List<ActionTrackerGpsPoint> allPoints;
  final double mapRotationDeg;

  String _role(String? raw) {
    final value = (raw ?? '').trim().toLowerCase();
    if (value.contains('врат') || value == 'gk' || value.contains('goalkeeper')) {
      return 'gk';
    }
    if (value.contains('защит') ||
        value.contains('defender') ||
        RegExp(r'(^|\W)(cb|lb|rb|lwb|rwb)(\W|$)').hasMatch(value)) {
      return 'def';
    }
    if (value.contains('полузащ') ||
        value.contains('midfield') ||
        RegExp(r'(^|\W)(cm|dm|cdm|am|cam|lm|rm)(\W|$)').hasMatch(value)) {
      return 'mid';
    }
    if (value.contains('напад') ||
        value.contains('forward') ||
        value.contains('striker') ||
        value.contains('winger') ||
        RegExp(r'(^|\W)(st|cf|fw|lw|rw)(\W|$)').hasMatch(value)) {
      return 'att';
    }
    return 'unknown';
  }

  @override
  void paint(Canvas canvas, Size size) {
    if (frames.length < 3 || allPoints.isEmpty) return;
    final bounds = _Bounds.fromGps(allPoints);
    final useField = _shouldUseFieldProjection(allPoints, field);
    final usable = frames.where((e) => e.lastSampleDeltaMs <= 10000).toList();
    final rawPts = <Offset>[];
    final pts = <Offset>[];
    final roles = <String>[];
    for (final frame in usable) {
      final raw = _matchProjectPoint(frame.point, size, bounds, field, useField);
      rawPts.add(raw);
      var o = raw;
      if (mapRotationDeg.abs() > .1) o = _rotateMatchPoint(o, size, mapRotationDeg);
      pts.add(o);
      roles.add(_role(frame.player.position));
    }
    if (pts.length < 3) return;

    _drawAnalyticsControlZones(canvas, pts, size);
    final hull = _telemetryConvexHull(pts);
    if (hull.length >= 3) {
      final path = Path()..moveTo(hull.first.dx, hull.first.dy);
      for (final p in hull.skip(1)) path.lineTo(p.dx, p.dy);
      path.close();
      const shapeAmber = Color(0xFFF59E0B);
      canvas.drawPath(
        path,
        Paint()
          ..color = shapeAmber.withOpacity(.11)
          ..style = PaintingStyle.fill,
      );
      canvas.drawPath(
        path,
        Paint()
          ..color = shapeAmber.withOpacity(.16)
          ..strokeWidth = 5.0
          ..style = PaintingStyle.stroke,
      );
      canvas.drawPath(
        path,
        Paint()
          ..color = shapeAmber.withOpacity(.96)
          ..strokeWidth = 1.8
          ..style = PaintingStyle.stroke,
      );
    }

    _drawAnalyticsPassingNetwork(canvas, pts, size);
    _drawAnalyticsTeamCenter(canvas, pts);

    final groups = <String, List<Offset>>{
      'def': <Offset>[],
      'mid': <Offset>[],
      'att': <Offset>[],
    };
    for (var i = 0; i < rawPts.length; i++) {
      final role = roles[i];
      if (groups.containsKey(role)) groups[role]!.add(rawPts[i]);
    }
    final recognized = groups.values.fold<int>(0, (sum, list) => sum + list.length);
    String formation = '—';
    double? defenseMidGapM;
    double? midAttackGapM;
    if (recognized >= math.max(4, rawPts.length ~/ 2) &&
        groups['def']!.isNotEmpty &&
        groups['mid']!.isNotEmpty &&
        groups['att']!.isNotEmpty) {
      _drawAnalyticsRoleLine(canvas, size, groups['def']!, 'ОБОРОНА', const Color(0xFF66D9A0));
      _drawAnalyticsRoleLine(canvas, size, groups['mid']!, 'ПОЛУЗАЩИТА', const Color(0xFFFFD166));
      _drawAnalyticsRoleLine(canvas, size, groups['att']!, 'АТАКА', const Color(0xFFFF8C66));
      formation = '${groups['def']!.length}-${groups['mid']!.length}-${groups['att']!.length}';
      final inner = _pitchInnerRect(size);
      final fieldLengthM = (field?.lengthM ?? 105.0).clamp(20.0, 180.0).toDouble();
      double meanX(List<Offset> values) =>
          values.map((p) => p.dx).reduce((a, b) => a + b) / values.length;
      defenseMidGapM = ((meanX(groups['def']!) - meanX(groups['mid']!)).abs() /
              math.max(1.0, inner.width)) *
          fieldLengthM;
      midAttackGapM = ((meanX(groups['mid']!) - meanX(groups['att']!)).abs() /
              math.max(1.0, inner.width)) *
          fieldLengthM;
    }
    _drawAnalyticsShapeMetrics(
      canvas,
      size,
      rawPts,
      formation: formation,
      defenseMidGapM: defenseMidGapM,
      midAttackGapM: midAttackGapM,
    );
  }

  void _drawAnalyticsControlZones(Canvas canvas, List<Offset> pts, Size size) {
    if (pts.length < 2) return;
    final pitch = _pitchInnerRect(size);
    for (var i = 0; i < pts.length; i++) {
      var polygon = <Offset>[
        pitch.topLeft,
        pitch.topRight,
        pitch.bottomRight,
        pitch.bottomLeft,
      ];
      final pi = pts[i];
      for (var j = 0; j < pts.length && polygon.isNotEmpty; j++) {
        if (i == j) continue;
        final pj = pts[j];
        final normal = pj - pi;
        final c = (pj.dx * pj.dx + pj.dy * pj.dy -
                pi.dx * pi.dx -
                pi.dy * pi.dy) /
            2.0;
        polygon = _clipAnalyticsTacticalPolygon(polygon, normal, c);
      }
      if (polygon.length < 3) continue;
      final path = Path()..moveTo(polygon.first.dx, polygon.first.dy);
      for (final point in polygon.skip(1)) path.lineTo(point.dx, point.dy);
      path.close();
      canvas.drawPath(path, Paint()..color = _AA.green.withOpacity(.018));
      canvas.drawPath(
        path,
        Paint()
          ..color = Colors.white.withOpacity(.07)
          ..style = PaintingStyle.stroke
          ..strokeWidth = .55,
      );
    }
  }

  List<Offset> _clipAnalyticsTacticalPolygon(
      List<Offset> polygon, Offset normal, double c) {
    if (polygon.isEmpty) return const <Offset>[];
    double side(Offset p) => p.dx * normal.dx + p.dy * normal.dy - c;
    final result = <Offset>[];
    for (var i = 0; i < polygon.length; i++) {
      final a = polygon[i];
      final b = polygon[(i + 1) % polygon.length];
      final sa = side(a);
      final sb = side(b);
      final aInside = sa <= .0001;
      final bInside = sb <= .0001;
      if (aInside) result.add(a);
      if (aInside != bInside) {
        final denominator = sa - sb;
        if (denominator.abs() > .000001) {
          final t = (sa / denominator).clamp(0.0, 1.0).toDouble();
          result.add(Offset(
            a.dx + (b.dx - a.dx) * t,
            a.dy + (b.dy - a.dy) * t,
          ));
        }
      }
    }
    return result;
  }

  void _drawAnalyticsShapeMetrics(
    Canvas canvas,
    Size size,
    List<Offset> rawPts, {
    required String formation,
    required double? defenseMidGapM,
    required double? midAttackGapM,
  }) {
    if (rawPts.length < 2) return;
    final inner = _pitchInnerRect(size);
    final fieldLengthM = (field?.lengthM ?? 105.0).clamp(20.0, 180.0).toDouble();
    final fieldWidthM = (field?.widthM ?? 68.0).clamp(15.0, 120.0).toDouble();
    final minX = rawPts.map((p) => p.dx).reduce(math.min);
    final maxX = rawPts.map((p) => p.dx).reduce(math.max);
    final minY = rawPts.map((p) => p.dy).reduce(math.min);
    final maxY = rawPts.map((p) => p.dy).reduce(math.max);
    final depthM = ((maxX - minX).abs() / math.max(1.0, inner.width)) * fieldLengthM;
    final widthM = ((maxY - minY).abs() / math.max(1.0, inner.height)) * fieldWidthM;
    var nearestSum = 0.0;
    for (var i = 0; i < rawPts.length; i++) {
      var nearest = double.infinity;
      for (var j = 0; j < rawPts.length; j++) {
        if (i == j) continue;
        final dxM = (rawPts[i].dx - rawPts[j].dx) /
            math.max(1.0, inner.width) * fieldLengthM;
        final dyM = (rawPts[i].dy - rawPts[j].dy) /
            math.max(1.0, inner.height) * fieldWidthM;
        nearest = math.min(nearest, math.sqrt(dxM * dxM + dyM * dyM)).toDouble();
      }
      if (nearest.isFinite) nearestSum += nearest;
    }
    final avgNearest = rawPts.isEmpty ? 0.0 : nearestSum / rawPts.length;
    final parts = <String>[
      formation,
      '${widthM.toStringAsFixed(0)}×${depthM.toStringAsFixed(0)} м',
      'инт. ${avgNearest.toStringAsFixed(1)} м',
      if (defenseMidGapM != null) 'З→ПЗ ${defenseMidGapM.toStringAsFixed(0)}',
      if (midAttackGapM != null) 'ПЗ→А ${midAttackGapM.toStringAsFixed(0)}',
    ];
    final text = parts.join(' · ');
    final tp = TextPainter(
      text: TextSpan(
        text: text,
        style: const TextStyle(
          color: Colors.white,
          fontSize: 7.0,
          fontWeight: FontWeight.w800,
        ),
      ),
      textDirection: TextDirection.ltr,
      maxLines: 1,
      ellipsis: '…',
    )..layout(maxWidth: math.max(80.0, inner.width - 28).toDouble());
    final rect = RRect.fromRectAndRadius(
      Rect.fromLTWH(inner.left + 7, inner.top + 7, tp.width + 12, tp.height + 8),
      const Radius.circular(6),
    );
    canvas.drawRRect(rect, Paint()..color = const Color(0xFF16221C).withOpacity(.62));
    tp.paint(canvas, Offset(rect.left + 6, rect.top + 4));
  }

  void _drawAnalyticsPassingNetwork(Canvas canvas, List<Offset> pts, Size size) {
    if (pts.length < 3) return;
    final threshold = math.max(70.0, size.width * .26).toDouble();
    final used = <String>{};
    for (var i = 0; i < pts.length; i++) {
      final nearest = <({int index, double distance})>[];
      for (var j = 0; j < pts.length; j++) {
        if (i == j) continue;
        nearest.add((index: j, distance: (pts[i] - pts[j]).distance));
      }
      nearest.sort((a, b) => a.distance.compareTo(b.distance));
      for (final item in nearest.where((e) => e.distance <= threshold).take(2)) {
        final a = math.min(i, item.index).toInt();
        final b = math.max(i, item.index).toInt();
        if (!used.add('$a:$b')) continue;
        final strength = (1 - item.distance / threshold).clamp(.0, 1.0).toDouble();
        canvas.drawLine(
          pts[a],
          pts[b],
          Paint()
            ..color = const Color(0xFFFFC857).withOpacity(.18 + .30 * strength)
            ..strokeWidth = .8 + strength,
        );
      }
    }
  }

  void _drawAnalyticsTeamCenter(Canvas canvas, List<Offset> pts) {
    if (pts.isEmpty) return;
    final center = Offset(
      pts.map((p) => p.dx).reduce((a, b) => a + b) / pts.length,
      pts.map((p) => p.dy).reduce((a, b) => a + b) / pts.length,
    );
    canvas.drawCircle(center, 8, Paint()..color = _AA.green.withOpacity(.12));
    canvas.drawCircle(
      center,
      4.5,
      Paint()
        ..color = _AA.green
        ..style = PaintingStyle.stroke
        ..strokeWidth = 1.4,
    );
    canvas.drawLine(center - const Offset(7, 0), center + const Offset(7, 0),
        Paint()..color = _AA.green.withOpacity(.72));
    canvas.drawLine(center - const Offset(0, 7), center + const Offset(0, 7),
        Paint()..color = _AA.green.withOpacity(.72));
  }

  void _drawAnalyticsRoleLine(
    Canvas canvas,
    Size size,
    List<Offset> group,
    String label,
    Color color,
  ) {
    if (group.isEmpty) return;
    final x = group.map((p) => p.dx).reduce((a, b) => a + b) / group.length;
    final inner = _pitchInnerRect(size);
    var a = Offset(x, inner.top + 2);
    var b = Offset(x, inner.bottom - 2);
    var tag = Offset(x, inner.top + 18);
    if (mapRotationDeg.abs() > .1) {
      a = _rotateMatchPoint(a, size, mapRotationDeg);
      b = _rotateMatchPoint(b, size, mapRotationDeg);
      tag = _rotateMatchPoint(tag, size, mapRotationDeg);
    }
    canvas.drawLine(
      a,
      b,
      Paint()
        ..color = color.withOpacity(.76)
        ..strokeWidth = 1.25,
    );
    final tp = TextPainter(
      text: TextSpan(
        text: label,
        style: const TextStyle(
          color: Colors.white,
          fontSize: 6.6,
          fontWeight: FontWeight.w900,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    final rect = RRect.fromRectAndRadius(
      Rect.fromLTWH(tag.dx - tp.width / 2 - 4, tag.dy - 7, tp.width + 8, 14),
      const Radius.circular(5),
    );
    canvas.drawRRect(rect, Paint()..color = color.withOpacity(.76));
    tp.paint(canvas, Offset(rect.left + 4, rect.top + 3));
  }

  @override
  bool shouldRepaint(covariant _TelemetryTeamShapeOverlayPainter oldDelegate) =>
      oldDelegate.frames != frames ||
      oldDelegate.field != field ||
      oldDelegate.allPoints != allPoints ||
      oldDelegate.mapRotationDeg != mapRotationDeg;
}

List<Offset> _telemetryConvexHull(List<Offset> points) {
  if (points.length <= 3) return List<Offset>.from(points);
  final sorted = List<Offset>.from(points)..sort((a, b) {
    final c = a.dx.compareTo(b.dx);
    return c != 0 ? c : a.dy.compareTo(b.dy);
  });
  double cross(Offset o, Offset a, Offset b) => (a.dx - o.dx) * (b.dy - o.dy) - (a.dy - o.dy) * (b.dx - o.dx);
  final lower = <Offset>[];
  for (final p in sorted) {
    while (lower.length >= 2 && cross(lower[lower.length - 2], lower.last, p) <= 0) lower.removeLast();
    lower.add(p);
  }
  final upper = <Offset>[];
  for (final p in sorted.reversed) {
    while (upper.length >= 2 && cross(upper[upper.length - 2], upper.last, p) <= 0) upper.removeLast();
    upper.add(p);
  }
  lower.removeLast();
  upper.removeLast();
  return <Offset>[...lower, ...upper];
}



class _ReplayJournalPanel extends StatelessWidget {
  const _ReplayJournalPanel({
    required this.events,
    required this.selectedId,
    required this.loadingArchived,
    required this.archivedCount,
    required this.reconstructedCount,
    required this.trackStartMs,
    required this.players,
    required this.onSelect,
  });

  final List<_ReplayJournalEvent> events;
  final String? selectedId;
  final bool loadingArchived;
  final int archivedCount;
  final int reconstructedCount;
  final int trackStartMs;
  final List<TrackerPlayerOption> players;
  final ValueChanged<_ReplayJournalEvent> onSelect;

  @override
  Widget build(BuildContext context) {
    if (events.isEmpty) {
      return Container(
        alignment: Alignment.center,
        padding: const EdgeInsets.all(14),
        decoration: BoxDecoration(
          color: _AA.soft,
          borderRadius: BorderRadius.circular(10),
        ),
        child: Text(
          loadingArchived
              ? 'Проверяем сохранённые Live-события…'
              : 'Для выбранного участка сессии значимых моментов нет.',
          textAlign: TextAlign.center,
          style: _AText.body(
            10.2,
            color: _AA.muted,
            weight: FontWeight.w500,
          ),
        ),
      );
    }

    return Stack(
      children: [
        Positioned.fill(
          child: ListView.separated(
            physics: const BouncingScrollPhysics(
              parent: AlwaysScrollableScrollPhysics(),
            ),
            padding: EdgeInsets.only(
              top: loadingArchived ? 5 : 0,
              bottom: 12,
            ),
            itemCount: events.length,
            separatorBuilder: (_, __) => const SizedBox(height: 5),
            itemBuilder: (context, index) {
              final event = events[index];
              return _ReplayJournalEventRow(
                event: event,
                selected: event.id == selectedId,
                trackStartMs: trackStartMs,
                players: players,
                onTap: () => onSelect(event),
              );
            },
          ),
        ),
        if (loadingArchived)
          const Positioned(
            left: 0,
            right: 0,
            top: 0,
            child: LinearProgressIndicator(
              minHeight: 2,
              color: _AA.green,
              backgroundColor: Colors.transparent,
            ),
          ),
      ],
    );
  }
}

class _ReplayJournalLegendDot extends StatelessWidget {
  const _ReplayJournalLegendDot({required this.color, required this.label});
  final Color color;
  final String label;

  @override
  Widget build(BuildContext context) => Row(mainAxisSize: MainAxisSize.min, children: [
        Container(
          width: 7,
          height: 7,
          decoration: BoxDecoration(color: color, shape: BoxShape.circle),
        ),
        const SizedBox(width: 4),
        Text(
          label,
          style: _AText.caption(size: 9.5, color: _AA.muted),
        ),
      ]);
}

class _ReplayJournalEventRow extends StatelessWidget {
  const _ReplayJournalEventRow({
    required this.event,
    required this.selected,
    required this.trackStartMs,
    required this.players,
    required this.onTap,
  });

  final _ReplayJournalEvent event;
  final bool selected;
  final int trackStartMs;
  final List<TrackerPlayerOption> players;
  final VoidCallback onTap;

  TrackerPlayerOption? get _player {
    final id = event.playerId;
    if (id == null || id <= 0) return null;
    for (final player in players) {
      if (player.id == id || player.identityIds.contains(id)) return player;
    }
    return null;
  }

  IconData get _icon {
    if (event.kind == 'gps_gap' || event.kind == 'gps') {
      return Icons.wifi_off_rounded;
    }
    if (event.kind == 'hr') return Icons.favorite_rounded;
    return _movementEventIcon(event.kind);
  }

  @override
  Widget build(BuildContext context) {
    final color = event.isRed ? _AA.red : _AA.orange;
    final player = _player;
    final elapsedValue = event.elapsedMs ??
        (trackStartMs > 0 && event.timeMs > 0
            ? math.max(0, event.timeMs - trackStartMs).toInt()
            : -1);
    final elapsed = elapsedValue >= 0
        ? _movementMatchClockLabel(elapsedValue)
        : '—';
    final avatar = player?.avatar?.trim() ?? '';
    final displayPlayerName =
        (player?.displayName ?? player?.name ?? event.playerName).trim();
    final compactDisplayPlayerName = _shortPlayerName(displayPlayerName);
    final initials = displayPlayerName
        .trim()
        .split(RegExp(r'\s+'))
        .where((part) => part.isNotEmpty)
        .take(2)
        .map((part) => part.substring(0, 1).toUpperCase())
        .join();

    return _NoHoverTap(
      onTap: onTap,
      borderRadius: BorderRadius.circular(10),
      child: AnimatedContainer(
        duration: const Duration(milliseconds: 150),
        constraints: const BoxConstraints(minHeight: 68),
        padding: const EdgeInsets.symmetric(horizontal: 7, vertical: 6),
        decoration: BoxDecoration(
          color: selected ? color.withOpacity(.09) : _AA.soft,
          borderRadius: BorderRadius.circular(10),
          border: Border.all(
            color: selected ? color.withOpacity(.30) : Colors.transparent,
          ),
        ),
        child: Row(children: [
          Container(
            width: 28,
            height: 28,
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: color.withOpacity(.10),
              shape: BoxShape.circle,
            ),
            child: Icon(_icon, size: 14, color: color),
          ),
          const SizedBox(width: 6),
          Container(
            width: 28,
            height: 28,
            clipBehavior: Clip.antiAlias,
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: Colors.white,
              shape: BoxShape.circle,
              border: Border.all(color: _AA.line),
            ),
            child: avatar.isNotEmpty
                ? Image.network(
                    avatar,
                    width: 28,
                    height: 28,
                    fit: BoxFit.cover,
                    errorBuilder: (_, __, ___) => Text(
                      initials.isEmpty ? '•' : initials,
                      style: const TextStyle(
                        color: _AA.text,
                        fontSize: 8.0,
                        fontWeight: FontWeight.w900,
                      ),
                    ),
                  )
                : Text(
                    initials.isEmpty ? '•' : initials,
                    style: const TextStyle(
                      color: _AA.text,
                      fontSize: 8.0,
                      fontWeight: FontWeight.w900,
                    ),
                  ),
          ),
          const SizedBox(width: 7),
          Expanded(
            child: Column(
              mainAxisAlignment: MainAxisAlignment.center,
              crossAxisAlignment: CrossAxisAlignment.start,
