class _MovementEventList extends StatelessWidget {
  const _MovementEventList({
    required this.events,
    required this.points,
    required this.field,
    required this.heartRate,
    required this.onSelect,
    this.showHrForAll = false,
  });
  final List<_MovementEvent> events;
  final List<ActionTrackerGpsPoint> points;
  final TrackerFieldModel? field;
  final _AnalyticsHeartRate heartRate;
  final ValueChanged<_MovementEvent> onSelect;
  final bool showHrForAll;

  @override
  Widget build(BuildContext context) {
    if (events.isEmpty) {
      return const _Empty(
          icon: Icons.bolt_rounded,
          text: 'Для выбранного фильтра событий нет. Измените период или слой карты.');
    }
    return ListView.separated(
      padding: const EdgeInsets.symmetric(horizontal: 2),
      itemCount: events.length,
      separatorBuilder: (_, __) => const SizedBox(height: 4),
      itemBuilder: (context, index) {
        final event = events[index];
        final point = event.startIndex >= 0 && event.startIndex < points.length
            ? points[event.startIndex]
            : null;
        final zone = point == null
            ? ''
            : _movementFieldZone(point, points, field);
        final showHrProfile =
            showHrForAll || event.kind == 'sprint' || event.kind == 'hir';
        final hrProfile = point == null || !showHrProfile
            ? null
            : _movementHrProfileForEvent(
                heartRate, event, point.playerId, _movementMinTime(points));
        final startTime = _movementMinTime(points);
        final eventTime = startTime > 0 && event.startTimeMs > 0
            ? _movementMatchClockLabel(math.max(0, event.startTimeMs - startTime).toInt())
            : '—';
        return _MovementEventCard(
            index: index + 1,
            event: event,
            timeLabel: eventTime,
            zone: zone,
            hrProfile: hrProfile,
            onTap: () => onSelect(event));
      },
    );
  }
}

