class _MovementFatigue {
  const _MovementFatigue({required this.earlyMax, required this.lateMax});
  final double earlyMax;
  final double lateMax;

  double get deltaPct => earlyMax <= 0 ? 0 : (lateMax - earlyMax) / earlyMax * 100;
  String get deltaLabel => earlyMax <= 0
      ? '—'
      : '${deltaPct >= 0 ? '+' : ''}${deltaPct.toStringAsFixed(1)}%';

  factory _MovementFatigue.fromPoints(List<ActionTrackerGpsPoint> points,
      {required double sprintThresholdKmh}) {
    final track = _validatedTrack(points);
    if (track.segments.isEmpty) return const _MovementFatigue(earlyMax: 0, lateMax: 0);
    final minTime = _movementMinTime(points);
    final maxTime = _movementMaxTime(points);
    final span = math.max(1, maxTime - minTime);
    double early = 0;
    double late = 0;
    for (final segment in track.segments) {
      final t = points[segment.toIndex].timeMs;
      final p = (t - minTime) / span;
      if (p <= .25) early = math.max(early, segment.speedKmh).toDouble();
      if (p >= .75) late = math.max(late, segment.speedKmh).toDouble();
    }
    return _MovementFatigue(earlyMax: early, lateMax: late);
  }
}


