List<TrackerPlayerOption> _movementVisiblePlayers(
  List<TrackerPlayerOption> players,
  List<TrackerPlayerLoadRow> rows,
  TrackerSessionModel? session,
) {
  final participantIds = session?.participantIds.toSet() ?? <int>{};
  final rowIds = rows
      .map((r) => r.playerId)
      .whereType<int>()
      .where((id) => id > 0)
      .toSet();
  final out = <TrackerPlayerOption>[];
  for (final player in players) {
    final identities = <int>{player.id, ...player.identityIds};
    final participantMatch = identities.any(participantIds.contains);
    final rowMatch = identities.any(rowIds.contains);
    final hasSessionConstraint = participantIds.isNotEmpty || rowIds.isNotEmpty;
    if (!hasSessionConstraint || participantMatch || rowMatch) out.add(player);
  }
  if (out.isEmpty) out.addAll(players);
  out.sort((a, b) => a.name.compareTo(b.name));
  return out.take(36).toList(growable: false);
}

TrackerPlayerLoadRow? _movementRowForPlayer(
    List<TrackerPlayerLoadRow> rows, TrackerPlayerOption player) {
  final ids = <int>{player.id, ...player.identityIds};
  for (final row in rows) {
    if (row.playerId != null && ids.contains(row.playerId)) return row;
  }
  return null;
}

Set<int> _movementExpandedPlayerIds(
    List<TrackerPlayerOption> players, Set<int> selectedIds) {
  if (selectedIds.isEmpty) return <int>{};
  final out = Set<int>.from(selectedIds);
  for (final player in players) {
    final identities = <int>{player.id, ...player.identityIds};
    if (identities.any(selectedIds.contains)) out.addAll(identities);
  }
  return out;
}

List<TrackerPlayerLoadRow> _movementRowsForSelection(
    List<TrackerPlayerLoadRow> rows, Set<int> selectedIds) {
  if (selectedIds.isEmpty) return rows;
  return rows
      .where((row) => row.playerId != null && selectedIds.contains(row.playerId))
      .toList(growable: false);
}

List<ActionTrackerGpsPoint> _movementPointsForPlayers(
    List<ActionTrackerGpsPoint> points, Set<int> selectedIds) {
  if (points.isEmpty) return points;

  // V117.1 PERFORMANCE: team GPS packets are usually already chronological,
  // but points from different players are interleaved. Group them in one
  // linear pass instead of cloning + O(n log n) sorting on every Map rebuild.
  // Dart maps preserve insertion order, so each player's original time order
  // stays intact while _segmentBreaks() still separates player tracks.
  final grouped = <int, List<ActionTrackerGpsPoint>>{};
  final noPlayerId = <ActionTrackerGpsPoint>[];
  var matchedAny = false;

  for (final point in points) {
    final id = point.playerId;
    if (selectedIds.isNotEmpty && id != null && !selectedIds.contains(id)) {
      continue;
    }
    if (selectedIds.isNotEmpty && id == null) continue;
    matchedAny = true;
    if (id == null) {
      noPlayerId.add(point);
    } else {
      (grouped[id] ??= <ActionTrackerGpsPoint>[]).add(point);
    }
  }

  // Legacy API fallback: if selected player ids are absent in GPS rows, keep
  // the real route rather than rendering an empty map.
  if (!matchedAny && selectedIds.isNotEmpty) {
    return _movementPointsForPlayers(points, const <int>{});
  }

  if (grouped.length <= 1 && noPlayerId.isEmpty) {
    return grouped.isEmpty ? const <ActionTrackerGpsPoint>[] : grouped.values.first;
  }
  if (grouped.isEmpty) return noPlayerId;

  final out = <ActionTrackerGpsPoint>[];
  for (final rows in grouped.values) {
    out.addAll(rows);
  }
  out.addAll(noPlayerId);
  return out;
}

int _movementMinTime(List<ActionTrackerGpsPoint> points) {
  var minTime = 0;
  for (final p in points) {
    if (p.timeMs <= 0) continue;
    if (minTime == 0 || p.timeMs < minTime) minTime = p.timeMs;
  }
  return minTime;
}

int _movementMaxTime(List<ActionTrackerGpsPoint> points) {
  var maxTime = 0;
  for (final p in points) {
    if (p.timeMs > maxTime) maxTime = p.timeMs;
  }
  return maxTime;
}

String _movementTrackKey(ActionTrackerGpsPoint point, int fallbackIndex) {
  final player = point.playerId ?? 0;
  final session = point.sessionId ?? 0;
  final live = point.liveSessionId ?? 0;
  if (player > 0 || session > 0 || live > 0) {
    return 'p:$player|s:$session|l:$live';
  }
  return 'legacy:$fallbackIndex';
}

List<List<ActionTrackerGpsPoint>> _movementTrackSeries(
    List<ActionTrackerGpsPoint> points) {
  if (points.isEmpty) return const <List<ActionTrackerGpsPoint>>[];
  final grouped = <String, List<ActionTrackerGpsPoint>>{};
  var legacyTrack = 0;
  ActionTrackerGpsPoint? previous;
  for (final point in points) {
    if (previous != null &&
        (point.breakBefore ||
            (point.timeMs > 0 &&
                previous.timeMs > 0 &&
                (point.timeMs - previous.timeMs).abs() > 20 * 60 * 1000))) {
      legacyTrack++;
    }
    final key = _movementTrackKey(point, legacyTrack);
    (grouped[key] ??= <ActionTrackerGpsPoint>[]).add(point);
    previous = point;
  }
  final result = <List<ActionTrackerGpsPoint>>[];
  for (final rows in grouped.values) {
    final sorted = [...rows]..sort((a, b) => a.timeMs.compareTo(b.timeMs));
    result.add(sorted);
  }
  return result;
}

int _movementRecordingSpanMs(
  List<ActionTrackerGpsPoint> points, {
  int fallbackDurationSec = 0,
}) {
  if (points.length < 2) return fallbackDurationSec > 0 ? fallbackDurationSec * 1000 : 0;
  final spans = <int>[];
  for (final track in _movementTrackSeries(points)) {
    final first = _movementMinTime(track);
    final last = _movementMaxTime(track);
    if (first > 0 && last > first) spans.add(last - first);
  }
  if (spans.isEmpty) {
    final first = _movementMinTime(points);
    final last = _movementMaxTime(points);
    final raw = first > 0 && last > first ? last - first : 0;
    return raw > 0 ? raw : (fallbackDurationSec > 0 ? fallbackDurationSec * 1000 : 0);
  }
  spans.sort();
  final median = spans[spans.length ~/ 2];
  final plausible = spans
      .where((span) => span <= math.max(6 * 60 * 60 * 1000, median * 3))
      .toList(growable: false);
  var resolved = plausible.isEmpty ? median : plausible.reduce(math.max);
  if (fallbackDurationSec > 0) {
    final fallbackMs = fallbackDurationSec * 1000;
    final upper = math.max(fallbackMs * 3, fallbackMs + 30 * 60 * 1000);
    if (resolved > upper) resolved = fallbackMs;
  }
  return resolved;
}

int _movementTimeAtProgress(List<ActionTrackerGpsPoint> points, double progress) {
  final minTime = _movementMinTime(points);
  final maxTime = _movementMaxTime(points);
  if (minTime <= 0 || maxTime <= minTime) return minTime;
  return minTime + ((maxTime - minTime) * progress.clamp(0.0, 1.0)).round();
}

double _movementProgressForTime(
    List<ActionTrackerGpsPoint> points, int timeMs) {
  final minTime = _movementMinTime(points);
  final maxTime = _movementMaxTime(points);
  if (minTime <= 0 || maxTime <= minTime) return 0;
  return ((timeMs - minTime) / (maxTime - minTime))
      .clamp(0.0, 1.0)
      .toDouble();
}

List<ActionTrackerGpsPoint> _movementPointsForRange(
    List<ActionTrackerGpsPoint> points, RangeValues range) {
  if (points.length < 2 ||
      (range.start <= .0001 && range.end >= .9999)) return points;

  // V88: диапазон командной тренировки применяется к каждому треку игрока
  // относительно его собственного начала/конца. Абсолютные часы разных
  // трекеров могут отличаться на часы/сутки и не должны растягивать общий
  // таймлайн или оставлять на карте только одну точку.
  final out = <ActionTrackerGpsPoint>[];
  for (final track in _movementTrackSeries(points)) {
    if (track.length < 2) {
      out.addAll(track);
      continue;
    }
    final minTime = _movementMinTime(track);
    final maxTime = _movementMaxTime(track);
    if (minTime <= 0 || maxTime <= minTime) {
      out.addAll(track);
      continue;
    }
    final span = maxTime - minTime;
    final startTime = minTime + (span * range.start).round();
    final endTime = minTime + (span * range.end).round();
    final selected = track
        .where((p) => p.timeMs >= startTime && p.timeMs <= endTime)
        .toList(growable: false);
    out.addAll(selected.length >= 2 ? selected : track);
  }
  return out.length >= 2 ? out : points;
}

ActionTrackerGpsPoint? _movementPointAtProgress(
    List<ActionTrackerGpsPoint> points, double progress,
    {RangeValues range = const RangeValues(0, 1)}) {
  if (points.isEmpty) return null;
  final targetProgress = progress.clamp(range.start, range.end).toDouble();
  final targetTime = _movementTimeAtProgress(points, targetProgress);
  ActionTrackerGpsPoint? best;
  var bestDelta = 1 << 62;
  for (final p in points) {
    if (p.timeMs <= 0) continue;
    final d = (p.timeMs - targetTime).abs();
    if (d < bestDelta) {
      bestDelta = d;
      best = p;
    }
  }
  return best ?? points.first;
}

double _movementCursorInsideRange(double cursor, RangeValues range) {
  final span = range.end - range.start;
  if (span <= .000001) return 0;
  return ((cursor - range.start) / span).clamp(0.0, 1.0).toDouble();
}

double _movementGlobalProgress(double localProgress, RangeValues range) {
  return (range.start + (range.end - range.start) * localProgress)
      .clamp(range.start, range.end)
      .toDouble();
}

String _movementDurationLabel(int milliseconds) {
  if (milliseconds <= 0) return '00:00';
  final totalSeconds = milliseconds ~/ 1000;
  final hours = totalSeconds ~/ 3600;
  final minutes = (totalSeconds % 3600) ~/ 60;
  final seconds = totalSeconds % 60;
  if (hours > 0) {
    return '$hours:${minutes.toString().padLeft(2, '0')}:${seconds.toString().padLeft(2, '0')}';
  }
  return '${minutes.toString().padLeft(2, '0')}:${seconds.toString().padLeft(2, '0')}';
}

// V117.5: футбольный/трекерный таймер не превращает 90 минут в 1:30:00.
// В интерфейсе матча логичнее видеть 45:00, 90:00, 113:47 и т.д.
String _movementMatchClockLabel(int milliseconds) {
  if (milliseconds <= 0) return '00:00';
  final totalSeconds = milliseconds ~/ 1000;
  final totalMinutes = totalSeconds ~/ 60;
  final seconds = totalSeconds % 60;
  return '${totalMinutes.toString().padLeft(2, '0')}:${seconds.toString().padLeft(2, '0')}';
}

String _movementRecordingSpanLabel(
  List<ActionTrackerGpsPoint> points, {
  int fallbackDurationSec = 0,
}) {
  final span = _movementRecordingSpanMs(
    points,
    fallbackDurationSec: fallbackDurationSec,
  );
  return span <= 0 ? '00:00' : _movementMatchClockLabel(span);
}

bool _segmentBreaks(ActionTrackerGpsPoint a, ActionTrackerGpsPoint b) {
  if (b.breakBefore) return true;
  if (a.playerId != null && b.playerId != null && a.playerId != b.playerId)
    return true;
  if (a.liveSessionId != null &&
      b.liveSessionId != null &&
      a.liveSessionId != b.liveSessionId) return true;
  if (a.sessionId != null && b.sessionId != null && a.sessionId != b.sessionId)
    return true;
  return false;
}

bool _segmentMatchesActivity(double speed, String filter,
    {double hsrThresholdKmh = 14.0, double sprintThresholdKmh = 18.0}) {
  if (filter == 'all') return true;
  if (speed <= 0) return false;
  if (filter == 'walk') return speed < 7.0;
  if (filter == 'run') return speed >= 7.0 && speed < hsrThresholdKmh;
  if (filter == 'hir')
    return speed >= hsrThresholdKmh && speed < sprintThresholdKmh;
  if (filter == 'sprint') return speed >= sprintThresholdKmh;
  if (filter == 'turn' || filter == 'accel' || filter == 'decel' || filter == 'stop')
    return false;
  return true;
}

List<int> _movementStationaryIndexes(List<ActionTrackerGpsPoint> points) {
  final out = <int>[];
  if (points.length < 2) return out;
  for (var i = 1; i < points.length; i++) {
    final a = points[i - 1];
    final b = points[i];
    if (_segmentBreaks(a, b)) continue;
    final dt = b.timeMs - a.timeMs;
    if (dt <= 0 || dt > 10000) continue;
    final distance = _LocalTrackAnalysis._distanceMeters(
        a.latitude, a.longitude, b.latitude, b.longitude);
    final speed = (distance / (dt / 1000.0)) * 3.6;
    if (distance <= .45 || speed < 1.5) out.add(i);
  }
  return out;
}

List<ActionTrackerGpsPoint> _filterActivityPoints(
    List<ActionTrackerGpsPoint> points,
    String filter,
    double sprintThresholdKmh,
    {double hsrThresholdKmh = 14.0}) {
  if (filter == 'all' || points.length < 2) return points;
  if (filter == 'stop') {
    final indexes = _movementStationaryIndexes(points);
    return indexes.map((i) => points[i]).toList(growable: false);
  }
  final validated = _validatedTrack(points);
  final out = <ActionTrackerGpsPoint>[];

  void addPoint(ActionTrackerGpsPoint p) {
    if (out.isEmpty || !identical(out.last, p)) out.add(p);
  }

  for (final segment in validated.segments) {
    final speed = segment.speedKmh;
    final keep = filter == 'turn'
        ? (validated.turnPointIndexes.contains(segment.fromIndex) ||
            validated.turnPointIndexes.contains(segment.toIndex))
        : filter == 'accel'
            ? segment.accelMps2 >= 1.0
            : filter == 'decel'
                ? segment.accelMps2 <= -1.0
                : _segmentMatchesActivity(speed, filter,
                    hsrThresholdKmh: hsrThresholdKmh,
                    sprintThresholdKmh: sprintThresholdKmh);
    if (!keep) continue;
    addPoint(points[segment.fromIndex]);
    addPoint(points[segment.toIndex]);
  }
  return out;
}

String _activityFilterLabel(String filter) {
  switch (filter) {
    case 'walk':
      return 'Ходьба';
    case 'run':
      return 'Бег';
    case 'hir':
      return 'Высокая интенсивность';
    case 'sprint':
      return 'Спринты';
    case 'accel':
      return 'Ускорения';
    case 'decel':
      return 'Торможения';
    case 'turn':
      return 'Повороты';
    case 'stop':
      return 'Остановки';
    default:
      return 'Весь маршрут';
  }
}

IconData _activityFilterIcon(String filter) {
  switch (filter) {
    case 'walk':
      return Icons.directions_walk_rounded;
    case 'run':
      return Icons.directions_run_rounded;
    case 'hir':
      return Icons.local_fire_department_rounded;
    case 'sprint':
      return Icons.flash_on_rounded;
    case 'accel':
      return Icons.trending_up_rounded;
    case 'decel':
      return Icons.trending_down_rounded;
    case 'turn':
      return Icons.change_circle_rounded;
    case 'stop':
      return Icons.pause_circle_outline_rounded;
    default:
      return Icons.timeline_rounded;
  }
}

List<double> _activitySpeedSamples(List<ActionTrackerGpsPoint> points,
    String filter, double sprintThresholdKmh,
    {double hsrThresholdKmh = 14.0}) {
  if (points.length < 2) return const <double>[];
  final validated = _validatedTrack(points);
  if (filter == 'turn') {
    final indexes = validated.turnPointIndexes.toList()..sort();
    return indexes
        .map((index) => validated.turnSpeedByPointIndex[index] ?? 0.0)
        .where((speed) => speed.isFinite && speed > 0)
        .toList(growable: false);
  }
  if (filter == 'accel') {
    return validated.segments
        .where((s) => s.accelMps2 >= 1.0)
        .map((s) => s.speedKmh)
        .toList(growable: false);
  }
  if (filter == 'decel') {
    return validated.segments
        .where((s) => s.accelMps2 <= -1.0)
        .map((s) => s.speedKmh)
        .toList(growable: false);
  }
  if (filter == 'stop') return const <double>[];
  return validated.segments
      .map((segment) => segment.speedKmh)
      .where((speed) =>
          _segmentMatchesActivity(speed, filter,
              hsrThresholdKmh: hsrThresholdKmh,
              sprintThresholdKmh: sprintThresholdKmh))
      .toList(growable: false);
}

String _formatPointTime(int timeMs) {
  if (timeMs <= 0) return 'без времени';
  // BLE может хранить elapsed milliseconds вместо Unix epoch. Для elapsed
  // показываем относительное hh:mm:ss, а не дату 1970 года.
  if (timeMs < 100000000000) {
    return _movementDurationLabel(timeMs);
  }
  final dt = DateTime.fromMillisecondsSinceEpoch(timeMs);
  return '${dt.hour.toString().padLeft(2, '0')}:${dt.minute.toString().padLeft(2, '0')}:${dt.second.toString().padLeft(2, '0')}';
}

String _pointsTimeRange(List<ActionTrackerGpsPoint> points) {
  // V117.1 PERFORMANCE: min/max scan is O(n) and does not allocate/sort a
  // second list of every timestamp each time the Map widget rebuilds.
  final minTime = _movementMinTime(points);
  final maxTime = _movementMaxTime(points);
  if (minTime <= 0 || maxTime <= 0) return 'время не записано';
  final first = _formatPointTime(minTime);
  final last = _formatPointTime(maxTime);
  return first == last ? first : '$first–$last';
}

double _segmentSpeed(List<ActionTrackerGpsPoint> points, int i) {
  if (i <= 0 || i >= points.length) return 0.0;
  return _validatedTrack(points).byToIndex[i]?.speedKmh ?? 0.0;
}

_AnalyticsHrPoint? _nearestHrForGps(
  _AnalyticsHeartRate heartRate,
  int? playerId,
  int gpsTimeMs,
  int trackStartMs,
) {
  if (heartRate.timeline.isEmpty || gpsTimeMs <= 0) return null;
  final candidates = heartRate.timeline.where((p) {
    if (playerId == null || playerId <= 0 || p.playerId == null || p.playerId! <= 0) {
      return true;
    }
    return p.playerId == playerId;
  }).toList(growable: false);
  if (candidates.isEmpty) return null;
  final gpsIsEpoch = gpsTimeMs >= 100000000000;
  var bestDelta = 1 << 62;
  _AnalyticsHrPoint? best;
  for (final hr in candidates) {
    int candidateTime;
    if (gpsIsEpoch && hr.timeMs >= 100000000000) {
      candidateTime = hr.timeMs;
    } else if (!gpsIsEpoch && hr.timeMs > 0 && hr.timeMs < 100000000000) {
      candidateTime = hr.timeMs;
    } else {
      candidateTime = trackStartMs + hr.minute * 60000;
    }
    final delta = (candidateTime - gpsTimeMs).abs();
    if (delta < bestDelta) {
      bestDelta = delta;
      best = hr;
    }
  }
  // Не приписываем точке пульс, если ближайший Polar-замер слишком далеко.
  return bestDelta <= 45000 ? best : null;
}

String _movementFieldZone(ActionTrackerGpsPoint point,
    List<ActionTrackerGpsPoint> points, TrackerFieldModel? field) {
  double nx;
  double ny;
  final projected = TrackerPitchProjector.projectGps(field,
      latitude: point.latitude, longitude: point.longitude);
  if (projected != null) {
    nx = projected.clampedNx;
    ny = projected.clampedNy;
  } else if (points.length > 1) {
    final bounds = _Bounds.fromGps(points);
    final lngSpan = math.max(1e-10, bounds.maxLng - bounds.minLng);
    final latSpan = math.max(1e-10, bounds.maxLat - bounds.minLat);
    nx = ((point.longitude - bounds.minLng) / lngSpan).clamp(0.0, 1.0).toDouble();
    ny = (1 - (point.latitude - bounds.minLat) / latSpan)
        .clamp(0.0, 1.0)
        .toDouble();
  } else {
    nx = .5;
    ny = .5;
  }
  final longitudinal = nx < .333
      ? 'треть A'
      : nx > .666
          ? 'треть C'
          : 'средняя треть';
  final lateral = ny < .333
      ? 'верхний фланг'
      : ny > .666
          ? 'нижний фланг'
          : 'центр';
  return '$longitudinal · $lateral';
}

_MapPointInfo? _mapPointInfoFromIndex(
  List<ActionTrackerGpsPoint> points,
  int index,
  TrackerFieldModel? field,
  double hsrThresholdKmh,
  double sprintThresholdKmh, {
  _AnalyticsHeartRate? heartRate,
  List<ActionTrackerGpsPoint>? allTrackPoints,
  Offset? paintedPosition,
}) {
  if (points.isEmpty || index < 0 || index >= points.length) return null;
  final point = points[index];
  final speed = _segmentSpeed(points, index);
  final segment = _validatedTrack(points).byToIndex[index];
  final dist = segment?.distanceM ?? 0;
  final accel = segment?.accelMps2 ?? 0;
  final activity = speed >= sprintThresholdKmh
      ? 'спринт'
      : speed >= hsrThresholdKmh
          ? 'высокая интенсивность'
          : speed >= 7
              ? 'бег'
              : speed >= 1.5
                  ? 'ходьба'
                  : 'остановка';
  final all = allTrackPoints ?? points;
  final startTime = _movementMinTime(all);
  final hr = heartRate == null
      ? null
      : _nearestHrForGps(heartRate, point.playerId, point.timeMs, startTime);
  final elapsed = point.timeMs > 0 && startTime > 0
      ? _movementMatchClockLabel(math.max(0, point.timeMs - startTime).toInt())
      : '—';
  return _MapPointInfo(
    index: index,
    timeMs: point.timeMs,
    speedKmh: speed,
    distanceM: dist,
    accelMps2: accel,
    activity: activity,
    position: paintedPosition ?? Offset.zero,
    timeLabel: elapsed,
    elapsedLabel: elapsed,
    zoneLabel: _movementFieldZone(point, all, field),
    playerId: point.playerId,
    hrBpm: hr?.bpm,
    hrZone: hr?.zone ?? '',
  );
}

_MapPointInfo? _mapPointInfoFromTime(
  List<ActionTrackerGpsPoint> points,
  int timeMs,
  TrackerFieldModel? field,
  double hsrThresholdKmh,
  double sprintThresholdKmh, {
  _AnalyticsHeartRate? heartRate,
  List<ActionTrackerGpsPoint>? allTrackPoints,
}) {
  if (points.isEmpty) return null;
  var bestIndex = 0;
  var bestDelta = (points.first.timeMs - timeMs).abs();
  for (var i = 1; i < points.length; i++) {
    final delta = (points[i].timeMs - timeMs).abs();
    if (delta < bestDelta) {
      bestDelta = delta;
      bestIndex = i;
    }
  }
  return _mapPointInfoFromIndex(points, bestIndex, field, hsrThresholdKmh,
      sprintThresholdKmh,
      heartRate: heartRate, allTrackPoints: allTrackPoints);
}

_MapPointInfo? _nearestPointInfo(
    Offset tap,
    Size size,
    List<ActionTrackerGpsPoint> points,
    TrackerFieldModel? field,
    double hsrThresholdKmh,
    double sprintThresholdKmh,
    {_AnalyticsHeartRate? heartRate,
    List<ActionTrackerGpsPoint>? allTrackPoints,
    List<ActionTrackerGpsPoint>? projectionPoints}) {
  if (points.isEmpty) return null;
  final projectionBase = projectionPoints ?? allTrackPoints ?? points;
  final bounds =
      projectionBase.length > 1 ? _Bounds.fromGps(projectionBase) : null;
  final useFieldProjection = _shouldUseFieldProjection(projectionBase, field);
  var bestIndex = -1;
  var bestDistance = double.infinity;
  Offset? bestOffset;
  for (var i = 0; i < points.length; i++) {
    final offset = _projectGpsForSize(points[i], size, field, bounds,
        useFieldProjection: useFieldProjection);
    final d = (offset - tap).distance;
    if (d < bestDistance) {
      bestDistance = d;
      bestIndex = i;
      bestOffset = offset;
    }
  }
  if (bestIndex < 0 || bestOffset == null || bestDistance > 30) return null;
  final tappedPoint = points[bestIndex];
  final basePoints = allTrackPoints ?? points;
  var baseIndex = basePoints.indexWhere((p) => identical(p, tappedPoint));
  if (baseIndex < 0) {
    baseIndex = basePoints.indexWhere((p) =>
        p.timeMs == tappedPoint.timeMs &&
        (p.playerId == tappedPoint.playerId || tappedPoint.playerId == null));
  }
  if (baseIndex < 0) {
    baseIndex = bestIndex.clamp(0, basePoints.length - 1).toInt();
  }
  return _mapPointInfoFromIndex(basePoints, baseIndex, field, hsrThresholdKmh,
      sprintThresholdKmh,
      heartRate: heartRate,
      allTrackPoints: basePoints,
      paintedPosition: bestOffset);
}

List<_MovementEvent> _movementEvents(
  List<ActionTrackerGpsPoint> points, {
  required double hsrThresholdKmh,
  required double sprintThresholdKmh,
}) {
  if (points.length < 2) return const <_MovementEvent>[];
  final validated = _validatedTrack(points);
  final events = <_MovementEvent>[];

  void addGrouped(String kind, bool Function(_ValidatedTrackSegment) matches) {
    var i = 0;
    final segments = validated.segments;
    while (i < segments.length) {
      if (!matches(segments[i])) {
        i++;
        continue;
      }

      // V117.1 FIX: a matching segment with dt > 3 s previously executed
      // `break` without advancing i. The outer loop then processed the same
      // segment forever, freezing the Map tab on perfectly valid sessions that
      // contained a 3–10 s GPS interval. Skip such a gap for event grouping.
      if (segments[i].dtMs > 3000) {
        i++;
        continue;
      }

      final first = segments[i];
      var last = first;
      var distance = 0.0;
      var weightedSpeed = 0.0;
      var maxSpeed = 0.0;
      var peakAccel = first.accelMps2;
      var totalMs = 0;

      while (i < segments.length) {
        final segment = segments[i];
        if (!matches(segment)) break;
        // A long interval is a GPS gap, not one continuous movement event.
        // Advance before leaving the inner loop so it can never spin forever.
        if (segment.dtMs > 3000) {
          i++;
          break;
        }
        if (totalMs > 0 && segment.fromIndex != last.toIndex) {
          // Do not advance here: this matching segment is the first candidate
          // of the next continuous event and will be handled by the outer loop.
          break;
        }

        last = segment;
        distance += segment.distanceM;
        weightedSpeed += segment.speedKmh * segment.dtMs;
        totalMs += segment.dtMs;
        maxSpeed = math.max(maxSpeed, segment.speedKmh).toDouble();
        if (kind == 'decel') {
          peakAccel = math.min(peakAccel, segment.accelMps2).toDouble();
        } else {
          peakAccel = math.max(peakAccel, segment.accelMps2).toDouble();
        }
        i++;
      }

      if (totalMs <= 0) continue;
      final startIndex = first.fromIndex;
      final endIndex = last.toIndex;
      events.add(_MovementEvent(
        kind: kind,
        startIndex: startIndex,
        endIndex: endIndex,
        startTimeMs: points[startIndex].timeMs,
        endTimeMs: points[endIndex].timeMs,
        distanceM: distance,
        maxSpeedKmh: maxSpeed,
        avgSpeedKmh: weightedSpeed / totalMs,
        peakAccelMps2: peakAccel,
      ));
    }
  }

  addGrouped('walk', (s) => s.speedKmh >= 1.5 && s.speedKmh < 7.0);
  addGrouped('run', (s) =>
      s.speedKmh >= 7.0 && s.speedKmh < hsrThresholdKmh);
  addGrouped('sprint', (s) => s.speedKmh >= sprintThresholdKmh);
  addGrouped('hir', (s) =>
      s.speedKmh >= hsrThresholdKmh && s.speedKmh < sprintThresholdKmh);
  addGrouped('accel', (s) => s.accelMps2 >= 1.0);
  addGrouped('decel', (s) => s.accelMps2 <= -1.0);

  final turns = validated.turnPointIndexes.toList()..sort();
  // V117.1 PERFORMANCE: the previous code scanned every validated segment for
  // every turn (O(turns × segments)). On a full team session that can block the
  // Flutter UI for seconds/minutes. Build the lookup once and keep this O(n).
  final outgoingByFromIndex = <int, _ValidatedTrackSegment>{};
  for (final segment in validated.segments) {
    outgoingByFromIndex[segment.fromIndex] = segment;
  }
  for (final index in turns) {
    if (index <= 0 || index >= points.length - 1) continue;
    final incoming = validated.byToIndex[index];
    final outgoing = outgoingByFromIndex[index];
    final angle = _movementTurnAngle(points[index - 1], points[index], points[index + 1]);
    final entry = incoming?.speedKmh ?? 0;
    final exit = outgoing?.speedKmh ?? _segmentSpeed(points, index + 1);
    events.add(_MovementEvent(
      kind: 'turn',
      startIndex: index,
      endIndex: index,
      startTimeMs: points[index].timeMs,
      endTimeMs: points[index].timeMs,
      distanceM: 0,
      maxSpeedKmh: math.max(entry, exit).toDouble(),
      avgSpeedKmh: (entry + exit) / 2,
      peakAccelMps2: outgoing?.accelMps2 ?? 0,
      turnAngleDeg: angle,
      entrySpeedKmh: entry,
      exitSpeedKmh: exit,
    ));
  }

  // Остановки считаем по исходным GPS-точкам, потому что validated track
  // намеренно отбрасывает stationary jitter из скорости и дистанции.
  var stopStart = -1;
  for (var i = 1; i < points.length; i++) {
    final a = points[i - 1];
    final b = points[i];
    final dt = b.timeMs - a.timeMs;
    var stationary = false;
    if (!_segmentBreaks(a, b) && dt > 0 && dt <= 10000) {
      final distance = _LocalTrackAnalysis._distanceMeters(
          a.latitude, a.longitude, b.latitude, b.longitude);
      final speed = (distance / (dt / 1000.0)) * 3.6;
      stationary = distance <= .45 || speed < 1.5;
    }
    if (stationary) {
      if (stopStart < 0) stopStart = i - 1;
    } else if (stopStart >= 0) {
      final end = i - 1;
      if (points[end].timeMs - points[stopStart].timeMs >= 2000) {
        events.add(_MovementEvent(
          kind: 'stop',
          startIndex: stopStart,
          endIndex: end,
          startTimeMs: points[stopStart].timeMs,
          endTimeMs: points[end].timeMs,
          distanceM: 0,
          maxSpeedKmh: 0,
          avgSpeedKmh: 0,
          peakAccelMps2: 0,
        ));
      }
      stopStart = -1;
    }
  }
  if (stopStart >= 0) {
    final end = points.length - 1;
    if (points[end].timeMs - points[stopStart].timeMs >= 2000) {
      events.add(_MovementEvent(
        kind: 'stop',
        startIndex: stopStart,
        endIndex: end,
        startTimeMs: points[stopStart].timeMs,
        endTimeMs: points[end].timeMs,
        distanceM: 0,
        maxSpeedKmh: 0,
        avgSpeedKmh: 0,
        peakAccelMps2: 0,
      ));
    }
  }

  events.sort((a, b) => a.startTimeMs.compareTo(b.startTimeMs));
  return events;
}

double _movementTurnAngle(ActionTrackerGpsPoint a, ActionTrackerGpsPoint b,
    ActionTrackerGpsPoint c) {
  final latRad = b.latitude * math.pi / 180;
  final ax = (b.longitude - a.longitude) * math.cos(latRad);
  final ay = b.latitude - a.latitude;
  final bx = (c.longitude - b.longitude) * math.cos(latRad);
  final by = c.latitude - b.latitude;
  final lenA = math.sqrt(ax * ax + ay * ay);
  final lenB = math.sqrt(bx * bx + by * by);
  if (lenA <= 1e-12 || lenB <= 1e-12) return 0;
  final dot = ((ax * bx + ay * by) / (lenA * lenB)).clamp(-1.0, 1.0);
  return math.acos(dot) * 180 / math.pi;
}

bool _movementEventMatchesFilter(_MovementEvent event, String filter) {
  if (filter == 'all') return true;
  if (filter == 'walk') return event.kind == 'walk';
  if (filter == 'run') return event.kind == 'run';
  if (filter == 'sprint') return event.kind == 'sprint';
  if (filter == 'hir') return event.kind == 'hir';
  if (filter == 'accel') return event.kind == 'accel';
  if (filter == 'decel') return event.kind == 'decel';
  if (filter == 'turn') return event.kind == 'turn';
  if (filter == 'stop') return event.kind == 'stop';
  return false;
}

