class _MovementHrProfile {
  const _MovementHrProfile({
    required this.startBpm,
    required this.peakBpm,
    required this.after30Bpm,
  });

  final int? startBpm;
  final int? peakBpm;
  final int? after30Bpm;

  bool get hasData =>
      (startBpm ?? 0) > 0 || (peakBpm ?? 0) > 0 || (after30Bpm ?? 0) > 0;

  int? get recoveryBpm {
    if ((peakBpm ?? 0) <= 0 || (after30Bpm ?? 0) <= 0) return null;
    return peakBpm! - after30Bpm!;
  }

  String get label {
    final parts = <String>[];
    if ((startBpm ?? 0) > 0) parts.add('HR старт $startBpm');
    if ((peakBpm ?? 0) > 0) parts.add('пик $peakBpm');
    if ((after30Bpm ?? 0) > 0) parts.add('+30с $after30Bpm');
    if (recoveryBpm != null) {
      parts.add('восст. ${recoveryBpm! >= 0 ? '−' : '+'}${recoveryBpm!.abs()} bpm');
    }
    return parts.join(' · ');
  }
}

int _movementComparableHrTime(
    _AnalyticsHrPoint hr, int gpsReferenceMs, int trackStartMs) {
  final gpsIsEpoch = gpsReferenceMs >= 100000000000;
  if (gpsIsEpoch && hr.timeMs >= 100000000000) return hr.timeMs;
  if (!gpsIsEpoch && hr.timeMs > 0 && hr.timeMs < 100000000000) {
    return hr.timeMs;
  }
  if (trackStartMs > 0) return trackStartMs + hr.minute * 60000;
  return hr.timeMs > 0 ? hr.timeMs : hr.minute * 60000;
}

_MovementHrProfile? _movementHrProfileForEvent(
  _AnalyticsHeartRate heartRate,
  _MovementEvent event,
  int? playerId,
  int trackStartMs,
) {
  if (heartRate.timeline.isEmpty || event.startTimeMs <= 0) return null;
  final candidates = heartRate.timeline.where((hr) {
    if (playerId == null || playerId <= 0) return true;
    if (hr.playerId == null || hr.playerId! <= 0) return true;
    return hr.playerId == playerId;
  }).toList(growable: false);
  if (candidates.isEmpty) return null;

  int? nearestTo(int target, int toleranceMs) {
    var bestDelta = 1 << 62;
    int? best;
    for (final hr in candidates) {
      final t = _movementComparableHrTime(hr, event.startTimeMs, trackStartMs);
      final d = (t - target).abs();
      if (d < bestDelta) {
        bestDelta = d;
        best = hr.bpm;
      }
    }
    return bestDelta <= toleranceMs ? best : null;
  }

  final start = nearestTo(event.startTimeMs, 45000);
  var peak = 0;
  final peakWindowStart = event.startTimeMs - 5000;
  final peakWindowEnd = event.endTimeMs + 30000;
  for (final hr in candidates) {
    final t = _movementComparableHrTime(hr, event.startTimeMs, trackStartMs);
    if (t >= peakWindowStart && t <= peakWindowEnd && hr.bpm > peak) {
      peak = hr.bpm;
    }
  }
  final after30 = nearestTo(event.endTimeMs + 30000, 20000);
  final result = _MovementHrProfile(
      startBpm: start, peakBpm: peak > 0 ? peak : null, after30Bpm: after30);
  return result.hasData ? result : null;
}

double _averageSprintRecovery(List<_MovementEvent> sprints) {
  if (sprints.length < 2) return 0;
  var total = 0.0;
  var count = 0;
  for (var i = 1; i < sprints.length; i++) {
    final gap = sprints[i].startTimeMs - sprints[i - 1].endTimeMs;
    if (gap >= 0) {
      total += gap / 1000.0;
      count++;
    }
  }
  return count == 0 ? 0 : total / count;
}


Offset _projectGpsForSize(
  ActionTrackerGpsPoint p,
  Size size,
  TrackerFieldModel? field,
  _Bounds? bounds, {
  bool useFieldProjection = true,
}) {
  if (useFieldProjection) {
    final raw = TrackerPitchProjector.projectGps(field,
        latitude: p.latitude, longitude: p.longitude);
    if (raw != null) {
      return _fitPointToPitch(
          Offset(raw.clampedNx * size.width, raw.clampedNy * size.height),
          size);
    }
  }
  if (bounds != null) return _fitPointToPitch(bounds.project(p, size), size);
  return Offset(size.width / 2, size.height / 2);
}

bool _shouldUseFieldProjection(
    List<ActionTrackerGpsPoint> points, TrackerFieldModel? field) {
  if (field == null || !field.hasCalibration || points.length < 2) return false;
  final xs = <double>[];
  final ys = <double>[];
  var inside = 0;
  var clipped = 0;
  for (final p in points) {
    final q = TrackerPitchProjector.projectGps(field,
        latitude: p.latitude, longitude: p.longitude);
    if (q == null) continue;
    xs.add(q.nx);
    ys.add(q.ny);
    if (q.isInside) inside++;
    if (q.nx < 0 || q.nx > 1 || q.ny < 0 || q.ny > 1) clipped++;
  }
  if (xs.length < 2) return false;
  final minX = xs.reduce(math.min), maxX = xs.reduce(math.max);
  final minY = ys.reduce(math.min), maxY = ys.reduce(math.max);
  final spreadX = (maxX - minX).abs();
  final spreadY = (maxY - minY).abs();
  final insideRatio = inside / xs.length;
  final clippedRatio = clipped / xs.length;
  // Если калибровка отправляет все GPS-точки в один угол/за границу,
  // используем GPS-bounds. Так карта не схлопывается справа/слева.
  if (spreadX < .018 && spreadY < .018) return false;
  if (insideRatio < .35 && clippedRatio > .45) return false;
  return true;
}

Offset _fitPointToPitch(Offset raw, Size size) {
  final inner = _pitchInnerRect(size);
  final nx = size.width <= 0 ? .5 : (raw.dx / size.width).clamp(0.0, 1.0);
  final ny = size.height <= 0 ? .5 : (raw.dy / size.height).clamp(0.0, 1.0);
  return Offset(inner.left + nx * inner.width, inner.top + ny * inner.height);
}

Rect _pitchInnerRect(Size size) => Rect.fromLTWH(
    10, 10, math.max(1.0, size.width - 20), math.max(1.0, size.height - 20));

Rect _analyticsPitchFrame(Size size) {
  const aspect = 105.0 / 68.0;
  final maxWidth = math.max(1.0, size.width);
  final maxHeight = math.max(1.0, size.height);
  var width = maxWidth;
  var height = width / aspect;
  if (height > maxHeight) {
    height = maxHeight;
    width = height * aspect;
  }
  return Rect.fromLTWH(
      (maxWidth - width) / 2, (maxHeight - height) / 2, width, height);
}

class _AnalyticsPitchPerspective extends StatefulWidget {
  const _AnalyticsPitchPerspective({
    required this.enabled,
    required this.child,
  });

  final bool enabled;
  final Widget child;

  @override
  State<_AnalyticsPitchPerspective> createState() =>
      _AnalyticsPitchPerspectiveState();
}

class _AnalyticsPitchPerspectiveState
    extends State<_AnalyticsPitchPerspective> {
  double _yawDeg = 0.0;
  double _tiltRad = -.34;
  double _zoom = .96;

  void _orbit(Offset delta) {
    if (!widget.enabled) return;
    // V151: это локальный setState только слоя камеры. Тяжёлый child с
    // маршрутом/9200+ GPS не перестраивается при каждом движении джойстика.
    setState(() {
      _yawDeg = (_yawDeg + delta.dx * .48) % 360.0;
      _tiltRad = (_tiltRad - delta.dy * .0065)
          .clamp(-.70, -.10)
          .toDouble();
    });
  }

  void _zoomBy(double delta) {
    if (!widget.enabled) return;
    setState(() {
      _zoom = (_zoom + delta).clamp(.96, 1.38).toDouble();
    });
  }

  void _reset() {
    if (!widget.enabled) return;
    setState(() {
      _yawDeg = 0.0;
      _tiltRad = -.34;
      _zoom = .96;
    });
  }

  @override
  Widget build(BuildContext context) {
    if (!widget.enabled) return widget.child;

    final safeTilt = _tiltRad.clamp(-.70, -.10).toDouble();
    final safeZoom = _zoom.clamp(.96, 1.38).toDouble();
    final yaw = _yawDeg * math.pi / 180.0;
    final transform = Matrix4.identity()
      ..setEntry(3, 2, .00135)
      ..rotateX(safeTilt)
      ..rotateZ(yaw)
      ..scale(safeZoom);

    return AnimatedContainer(
      duration: const Duration(milliseconds: 180),
      padding: const EdgeInsets.fromLTRB(6, 5, 6, 4),
      decoration: const BoxDecoration(
        gradient: LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: <Color>[Color(0xFFDDE7E1), Color(0xFFF6F8F7)],
        ),
      ),
      child: Stack(
        fit: StackFit.expand,
        clipBehavior: Clip.hardEdge,
        children: [
          IgnorePointer(
            child: Transform.translate(
              offset: const Offset(0, 8),
              child: Transform(
                alignment: Alignment.center,
                transform: transform,
                child: Container(
                  decoration: BoxDecoration(
                    color: const Color(0xFF284B38),
                    borderRadius: BorderRadius.circular(14),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black.withOpacity(.20),
                        blurRadius: 18,
                        spreadRadius: -6,
                        offset: const Offset(0, 12),
                      ),
                    ],
                  ),
                ),
              ),
            ),
          ),
          Transform.translate(
            offset: const Offset(0, -5),
            child: Transform(
              alignment: Alignment.center,
              transform: transform,
              transformHitTests: true,
              // RepaintBoundary удерживает уже отрисованный тяжёлый маршрут
              // в отдельном raster-layer. Поворот/наклон теперь композитятся
              // GPU без повторного paint тысяч сегментов на каждый drag tick.
              child: RepaintBoundary(child: widget.child),
            ),
          ),
          Positioned(
            right: 12,
            bottom: 12,
            child: _AnalyticsCameraControl(
              onOrbitDelta: _orbit,
              onZoomIn: () => _zoomBy(.08),
              onZoomOut: () => _zoomBy(-.08),
              onReset: _reset,
            ),
          ),
        ],
      ),
    );
  }
}

