class _AnalyticsOrbitPadState extends State<_AnalyticsOrbitPad> {
  Offset _thumb = Offset.zero;

  void _updateThumb(Offset local, Size size) {
    final center = Offset(size.width / 2, size.height / 2);
    var delta = local - center;
    const maxRadius = 20.0;
    if (delta.distance > maxRadius) {
      delta = Offset.fromDirection(delta.direction, maxRadius);
    }
    setState(() => _thumb = delta);
  }

  @override
  Widget build(BuildContext context) {
    const size = 78.0;
    return Tooltip(
      message: 'Тяните внутри круга: влево/вправо — поворот, вверх/вниз — камера',
      child: GestureDetector(
        behavior: HitTestBehavior.opaque,
        onDoubleTap: widget.onReset,
        onPanStart: (details) =>
            _updateThumb(details.localPosition, const Size(size, size)),
        onPanUpdate: (details) {
          _updateThumb(details.localPosition, const Size(size, size));
          widget.onOrbitDelta(details.delta);
        },
        onPanEnd: (_) => setState(() => _thumb = Offset.zero),
        onPanCancel: () => setState(() => _thumb = Offset.zero),
        child: Container(
          width: size,
          height: size,
          decoration: BoxDecoration(
            color: Colors.white.withOpacity(.94),
            shape: BoxShape.circle,
            border: Border.all(color: _AA.line.withOpacity(.95), width: 1),
            boxShadow: [
              BoxShadow(
                color: Colors.black.withOpacity(.12),
                blurRadius: 12,
                spreadRadius: -4,
                offset: const Offset(0, 5),
              ),
            ],
          ),
          child: Stack(
            alignment: Alignment.center,
            children: [
              const Positioned(
                top: 6,
                child: Icon(Icons.keyboard_arrow_up_rounded,
                    size: 17, color: _AA.muted),
              ),
              const Positioned(
                bottom: 6,
                child: Icon(Icons.keyboard_arrow_down_rounded,
                    size: 17, color: _AA.muted),
              ),
              const Positioned(
                left: 6,
                child: Icon(Icons.keyboard_arrow_left_rounded,
                    size: 17, color: _AA.muted),
              ),
              const Positioned(
                right: 6,
                child: Icon(Icons.keyboard_arrow_right_rounded,
                    size: 17, color: _AA.muted),
              ),
              AnimatedContainer(
                duration: const Duration(milliseconds: 70),
                transform: Matrix4.translationValues(_thumb.dx, _thumb.dy, 0),
                width: 30,
                height: 30,
                alignment: Alignment.center,
                decoration: BoxDecoration(
                  color: _AA.green,
                  shape: BoxShape.circle,
                  border: Border.all(color: Colors.white, width: 2),
                  boxShadow: [
                    BoxShadow(
                      color: _AA.green.withOpacity(.24),
                      blurRadius: 8,
                      spreadRadius: -2,
                    ),
                  ],
                ),
                child: const Icon(Icons.open_with_rounded,
                    size: 14, color: Colors.white),
              ),
            ],
          ),
        ),
      ),
    );
  }
}

