    required this.hsrThresholdKmh,
    required this.showSprintArrows,
    required this.mapRotationDeg,
    required this.onOpenInsight,
  });

  final _AnalyticsBundle bundle;
  final _LocalTrackAnalysis local;
  final List<ActionTrackerGpsPoint> localPoints;
  final TrackerSessionModel? selectedSession;
  final double sprintThresholdKmh;
  final double hsrThresholdKmh;
  final bool showSprintArrows;
  final double mapRotationDeg;
  final ValueChanged<_CoachInsight> onOpenInsight;

  @override
  Widget build(BuildContext context) {
    final players = [..._rowsForAnalytics(bundle, selectedSession, local, null)]
      ..sort((a, b) => b.sprintCount.compareTo(a.sprintCount));
    final sprintCount = local.sprintCount > 0
        ? local.sprintCount
        : (selectedSession?.sprintCount ?? 0);
    final sprintDistance = local.sprintDistanceM > 0
        ? local.sprintDistanceM
        : (selectedSession?.sprintDistanceM ?? 0);
    final hirDistance = local.hsrDistanceM > 0
        ? local.hsrDistanceM
        : ((selectedSession?.hirDistanceM ?? 0) +
            (selectedSession?.vhirDistanceM ?? 0));
    final maxSpeed = local.maxSpeedKmh > 0
        ? local.maxSpeedKmh
        : (selectedSession?.maxSpeedKmh ?? 0);
    final segments = _SprintSegment.fromPoints(localPoints,
        thresholdKmh: sprintThresholdKmh);

    _CoachInsight sprintInsight(String title, IconData icon,
        List<_CoachInsightMetric> metrics, List<String> bullets,
        {Color accent = _AA.red}) {
      return _CoachInsight(
        title: title,
        subtitle:
            '${selectedSession?.playerName ?? 'Команда'} · порог ${sprintThresholdKmh.toStringAsFixed(1)} км/ч',
        icon: icon,
        accent: accent,
        metrics: metrics,
        bullets: bullets,
        footer:
            'Правая панель работает как тренерский инспектор: нажмите карту, KPI или игрока — детали откроются здесь, без отдельного окна и без потери контекста графика.',
      );
    }

    void openPlayer(TrackerPlayerLoadRow p) {
      onOpenInsight(_CoachInsight(
        title: p.playerName,
