bool _looksGenericPlayerName(String? value) {
  final name = (value ?? '').trim().toLowerCase();
  if (name.isEmpty || name == 'null') return true;
  if (RegExp(r'^(игрок|player|athlete|спортсмен|команда|team)\s*#?\s*\d*$',
          caseSensitive: false)
      .hasMatch(name)) return true;
  if (RegExp(r'^(№|#)?\s*\d+$').hasMatch(name)) return true;
  return false;
}

TrackerPlayerOption? _rosterPlayerById(
    int? id, List<TrackerPlayerOption> players) {
  if (id == null || id <= 0) return null;
  for (final p in players) {
    if (p.id == id || p.identityIds.contains(id)) return p;
  }
  return null;
}

String _rosterNameForPlayer(int? id, List<TrackerPlayerOption> players,
    {String? fallback}) {
  final player = _rosterPlayerById(id, players);
  final rosterName = player?.name.trim() ?? '';
  final fb = (fallback ?? '').trim();
  if (rosterName.isNotEmpty && !_looksGenericPlayerName(rosterName))
    return rosterName;
  if (fb.isNotEmpty && !_looksGenericPlayerName(fb)) return fb;
  return id == null || id <= 0 ? 'Команда' : 'Игрок $id';
}

List<TrackerPlayerLoadRow> _periodRowsFromSessions(
    List<TrackerSessionModel> sessions,
    {List<TrackerPlayerOption> players = const <TrackerPlayerOption>[]}) {
  final byPlayer = <int, _SessionAccumulator>{};
  for (final s in sessions) {
    final id = s.playerId ?? -1;
    final name =
        _rosterNameForPlayer(id, players, fallback: s.playerName ?? 'Команда');
    final acc = byPlayer.putIfAbsent(id, () => _SessionAccumulator(id, name));
    acc.sessions++;
    acc.distance += s.distanceM;
    acc.maxSpeed = math.max(acc.maxSpeed, s.maxSpeedKmh);
    acc.sprints += s.sprintCount;
    acc.sprintDistance += s.sprintDistanceM;
    acc.hsr += s.hsrDistanceM + s.hirDistanceM + s.vhirDistanceM;
    acc.accel += s.accelCount;
    acc.decel += s.decelCount;
    acc.load += s.loadScore;
  }
  return byPlayer.values
      .map((a) => TrackerPlayerLoadRow(
            playerId: a.playerId > 0 ? a.playerId : null,
            playerName: _rosterNameForPlayer(a.playerId, players,
                fallback: a.playerName),
            sessionsCount: a.sessions,
            distanceM: a.distance,
            avgSpeedKmh: 0,
            maxSpeedKmh: a.maxSpeed,
            highSpeedDistanceM: a.hsr,
            sprintDistanceM: a.sprintDistance,
            sprintCount: a.sprints,
            accelerationCount: a.accel,
            decelerationCount: a.decel,
            loadScore: a.sessions <= 0 ? 0 : a.load / a.sessions,
          ))
      .toList()
    ..sort((a, b) => b.distanceM.compareTo(a.distanceM));
}

TrackerPlayerLoadRow _rowWithRosterName(
    TrackerPlayerLoadRow row, List<TrackerPlayerOption> players) {
  final player = _rosterPlayerById(row.playerId, players);
  final resolvedName =
      _rosterNameForPlayer(row.playerId, players, fallback: row.playerName);
  if (resolvedName == row.playerName &&
      (player?.avatar ?? row.avatar) == row.avatar) return row;
  return TrackerPlayerLoadRow(
    playerId: row.playerId,
    playerName: resolvedName,
    avatar: player?.avatar ?? row.avatar,
    sessionsCount: row.sessionsCount,
    distanceM: row.distanceM,
    avgSpeedKmh: row.avgSpeedKmh,
    maxSpeedKmh: row.maxSpeedKmh,
    highSpeedDistanceM: row.highSpeedDistanceM,
    sprintDistanceM: row.sprintDistanceM,
    sprintCount: row.sprintCount,
    accelerationCount: row.accelerationCount,
    decelerationCount: row.decelerationCount,
    loadScore: row.loadScore,
  );
}

List<TrackerPlayerLoadRow> _rowsWithRosterNames(
        List<TrackerPlayerLoadRow> rows, List<TrackerPlayerOption> players) =>
    rows.map((r) => _rowWithRosterName(r, players)).toList(growable: false);

List<TrackerPlayerLoadRow> _heartRateRows(
    _AnalyticsHeartRate heartRate, List<TrackerPlayerOption> players) {
  return heartRate.players
      .where((p) => p.samplesCount > 0 || p.avgBpm > 0 || p.maxBpm > 0)
      .map((p) {
    final name =
        _rosterNameForPlayer(p.playerId, players, fallback: p.playerName);
    final hrLoad = math.max(
        0.0,
        p.avgBpm.toDouble() * 1.6 +
            p.maxBpm.toDouble() * .45 +
            p.highZoneSamples.toDouble() * 2.5);
    return TrackerPlayerLoadRow(
      playerId: p.playerId,
      playerName: name,
      avatar: _rosterPlayerById(p.playerId, players)?.avatar,
      sessionsCount: 0,
      distanceM: 0,
      avgSpeedKmh: 0,
      maxSpeedKmh: 0,
      highSpeedDistanceM: 0,
      sprintDistanceM: 0,
      sprintCount: 0,
      accelerationCount: 0,
      decelerationCount: 0,
      loadScore: hrLoad,
    );
  }).toList(growable: false);
}

List<TrackerPlayerLoadRow> _mergeHeartRateRows(
    List<TrackerPlayerLoadRow> rows, List<TrackerPlayerLoadRow> hrRows) {
  if (hrRows.isEmpty) return rows;
  if (rows.isEmpty) return hrRows;
  final byKey = <String, TrackerPlayerLoadRow>{};
  String keyOf(TrackerPlayerLoadRow r) => (r.playerId ?? 0) > 0
      ? 'id:${r.playerId}'
      : 'name:${r.playerName.trim().toLowerCase()}';
  for (final row in rows) {
    byKey[keyOf(row)] = row;
  }
  for (final hr in hrRows) {
    final key = keyOf(hr);
    final base = byKey[key];
    if (base == null) {
      byKey[key] = hr;
    } else {
      final load = base.loadScore > 0
          ? math.max(base.loadScore, hr.loadScore)
          : hr.loadScore;
      byKey[key] = TrackerPlayerLoadRow(
        playerId: base.playerId ?? hr.playerId,
        playerName: !_looksGenericPlayerName(base.playerName)
            ? base.playerName
            : hr.playerName,
        avatar: base.avatar ?? hr.avatar,
        sessionsCount: base.sessionsCount,
        distanceM: base.distanceM,
        avgSpeedKmh: base.avgSpeedKmh,
        maxSpeedKmh: base.maxSpeedKmh,
        highSpeedDistanceM: base.highSpeedDistanceM,
        sprintDistanceM: base.sprintDistanceM,
        sprintCount: base.sprintCount,
        accelerationCount: base.accelerationCount,
        decelerationCount: base.decelerationCount,
        loadScore: load,
      );
    }
  }
  return byKey.values.toList(growable: false);
}

TrackerPlayerLoadRow? _rowFromSession(TrackerSessionModel? session,
    _LocalTrackAnalysis local, TrackerPlayerOption? selectedPlayer,
    {List<TrackerPlayerOption> players = const <TrackerPlayerOption>[]}) {
  if (session == null && local.distanceM <= 0 && local.speedSamples.isEmpty)
    return null;
  final distance =
      local.distanceM > 0 ? local.distanceM : (session?.distanceM ?? 0);
  final maxSpeed =
      local.maxSpeedKmh > 0 ? local.maxSpeedKmh : (session?.maxSpeedKmh ?? 0);
  final avgSpeed =
      local.avgSpeedKmh > 0 ? local.avgSpeedKmh : (session?.avgSpeedKmh ?? 0);
  final sprintDistance = local.sprintDistanceM > 0
      ? local.sprintDistanceM
      : (session?.sprintDistanceM ?? 0);
  final sprintCount =
      local.sprintCount > 0 ? local.sprintCount : (session?.sprintCount ?? 0);
  final hir = local.hsrDistanceM > 0
      ? local.hsrDistanceM
      : ((session?.hirDistanceM ?? 0) +
          (session?.vhirDistanceM ?? 0) +
          (session?.hsrDistanceM ?? 0));
  final accel =
      local.accelCount > 0 ? local.accelCount : (session?.accelCount ?? 0);
  final decel =
      local.decelCount > 0 ? local.decelCount : (session?.decelCount ?? 0);
  final load = (session?.loadScore ?? 0) > 0
      ? session!.loadScore
      : (distance / 10.0 +
          sprintDistance * .35 +
          hir * .18 +
          (accel + decel) * 2.5);
  final playerId = session?.playerId ?? selectedPlayer?.id;
  final playerName = selectedPlayer?.name ??
      _rosterNameForPlayer(playerId, players,
          fallback: session?.playerName ?? 'Игрок');
  return TrackerPlayerLoadRow(
    playerId: playerId,
    playerName: playerName,
    avatar:
        selectedPlayer?.avatar ?? _rosterPlayerById(playerId, players)?.avatar,
    sessionsCount: session == null ? 0 : 1,
    distanceM: distance,
    avgSpeedKmh: avgSpeed,
    maxSpeedKmh: maxSpeed,
    highSpeedDistanceM: hir,
    sprintDistanceM: sprintDistance,
    sprintCount: sprintCount,
    accelerationCount: accel,
    decelerationCount: decel,
    loadScore: load,
  );
}

List<TrackerPlayerLoadRow> _rowsForAnalytics(
    _AnalyticsBundle bundle,
    TrackerSessionModel? selectedSession,
    _LocalTrackAnalysis local,
    TrackerPlayerOption? selectedPlayer) {
  final periodRows =
      _periodRowsFromSessions(bundle.sessions, players: bundle.players);
  var rows = periodRows.isNotEmpty
      ? periodRows
      : _rowsWithRosterNames(bundle.dashboard.players, bundle.players);
  final sessionRow = _rowFromSession(selectedSession, local, selectedPlayer,
      players: bundle.players);
  if (sessionRow != null) {
    final exists = rows.any((r) =>
        r.playerId == sessionRow.playerId && sessionRow.playerId != null);
    rows = exists
        ? rows
            .map((r) => r.playerId == sessionRow.playerId ? sessionRow : r)
            .toList(growable: false)
        : <TrackerPlayerLoadRow>[sessionRow, ...rows];
  }
  rows = _mergeHeartRateRows(_rowsWithRosterNames(rows, bundle.players),
      _heartRateRows(bundle.heartRate, bundle.players));
  return rows;
}

List<TrackerPlayerLoadRow> _filterRowsByPlayerIds(
    List<TrackerPlayerLoadRow> rows, Set<int> ids) {
  if (ids.isEmpty) return rows;
  return rows
      .where((r) => r.playerId != null && ids.contains(r.playerId))
      .toList(growable: false);
}

class _DayTotal {
  const _DayTotal({
    required this.sessionsCount,
    required this.playersCount,
    required this.distanceM,
    required this.maxSpeedKmh,
    required this.sprintCount,
    required this.sprintDistanceM,
    required this.hirDistanceM,
    required this.accelCount,
    required this.decelCount,
    required this.loadScore,
  });

  final int sessionsCount;
  final int playersCount;
  final double distanceM;
  final double maxSpeedKmh;
  final int sprintCount;
  final double sprintDistanceM;
  final double hirDistanceM;
  final int accelCount;
  final int decelCount;
  final double loadScore;

  factory _DayTotal.fromRows(List<TrackerPlayerLoadRow> rows,
      {required int sessionsCount,
      TrackerSessionModel? fallbackSession,
      required _LocalTrackAnalysis local}) {
    if (rows.isEmpty) {
      final r = _rowFromSession(fallbackSession, local, null);
      if (r == null) {
        return const _DayTotal(
            sessionsCount: 0,
            playersCount: 0,
            distanceM: 0,
            maxSpeedKmh: 0,
            sprintCount: 0,
            sprintDistanceM: 0,
            hirDistanceM: 0,
            accelCount: 0,
            decelCount: 0,
            loadScore: 0);
      }
      return _DayTotal.fromRows(<TrackerPlayerLoadRow>[r],
          sessionsCount: sessionsCount <= 0 ? 1 : sessionsCount,
          fallbackSession: null,
          local: const _LocalTrackAnalysis(
              distanceM: 0,
              durationSec: 0,
              maxSpeedKmh: 0,
              avgSpeedKmh: 0,
              sprintCount: 0,
              sprintDistanceM: 0,
              hsrDistanceM: 0,
              accelCount: 0,
              decelCount: 0,
              speedSamples: <double>[]));
    }
    final ids =
        rows.where((r) => (r.playerId ?? 0) > 0).map((r) => r.playerId).toSet();
    final names = rows
        .where((r) =>
            (r.playerId ?? 0) <= 0 &&
            (r.distanceM > 0 ||
                r.maxSpeedKmh > 0 ||
                r.loadScore > 0 ||
                r.sprintCount > 0))
        .map((r) => r.playerName.trim().toLowerCase())
        .where((name) => name.isNotEmpty)
        .toSet();
    return _DayTotal(
      sessionsCount: sessionsCount <= 0
          ? rows.fold<int>(0, (s, r) => s + math.max(1, r.sessionsCount))
          : sessionsCount,
      playersCount: ids.isNotEmpty ? ids.length : names.length,
      distanceM: rows.fold<double>(0, (s, r) => s + r.distanceM),
      maxSpeedKmh: rows.fold<double>(0, (s, r) => math.max(s, r.maxSpeedKmh)),
      sprintCount: rows.fold<int>(0, (s, r) => s + r.sprintCount),
      sprintDistanceM: rows.fold<double>(0, (s, r) => s + r.sprintDistanceM),
      hirDistanceM: rows.fold<double>(0, (s, r) => s + r.highSpeedDistanceM),
      accelCount: rows.fold<int>(0, (s, r) => s + r.accelerationCount),
      decelCount: rows.fold<int>(0, (s, r) => s + r.decelerationCount),
      loadScore: rows.fold<double>(0, (s, r) => s + r.loadScore),
    );
  }
}

class _SessionAccumulator {
  _SessionAccumulator(this.playerId, this.playerName);
  final int playerId;
  final String playerName;
  int sessions = 0;
  double distance = 0;
  double maxSpeed = 0;
  int sprints = 0;
  double sprintDistance = 0;
  double hsr = 0;
  int accel = 0;
  int decel = 0;
  double load = 0;
}

class _TeamTab extends StatelessWidget {
