    final selectedRows = selectedPlayer?.id == null
        ? rows
        : rows
            .where((r) => r.playerId == selectedPlayer!.id)
            .toList(growable: false);
    final radarPlayerRows = selectedRows.isNotEmpty ? selectedRows : rows;
    final teamPanel = _Panel(
        title: 'Командная статистика',
