        subtitle: selectedSession == null
            ? 'период / live'
            : 'сессия #${selectedSession!.id}',
        child: CustomPaint(
            painter:
                _RadarPainter(rows: radarPlayerRows, baselineRows: teamRows),
            child: const SizedBox.expand()));
    final summaryPanel = _Panel(
        title: 'Расшифровка сессии',
        subtitle: selectedSession?.title ?? 'выберите запись',
        child: selectedSession == null
            ? const _Empty(
                icon: Icons.radar_rounded,
                text:
                    'Выберите дату или сессию, чтобы увидеть профиль игрока и команды.')
