class _RatingsTab extends StatefulWidget {
  const _RatingsTab(
      {required this.bundle,
      required this.local,
      required this.teamName,
      required this.selectedPlayer,
      required this.selectedSession});
  final _AnalyticsBundle bundle;
  final _LocalTrackAnalysis local;
