  final TrackerSessionModel? selectedSession;

  @override
  State<_RatingsTab> createState() => _RatingsTabState();
}

class _RatingsTabState extends State<_RatingsTab> {
  _RankingMode _mode = _RankingMode.distance;

  @override
  Widget build(BuildContext context) {
    final rows = _rowsForAnalytics(widget.bundle, widget.selectedSession,
        widget.local, widget.selectedPlayer);
    final allRows = _rowsForAnalytics(
        widget.bundle, widget.selectedSession, widget.local, null);
    final selectedRows = widget.selectedPlayer?.id == null
        ? <TrackerPlayerLoadRow>[]
        : allRows
            .where((r) => r.playerId == widget.selectedPlayer!.id)
            .toList(growable: false);
    final sorted = [...rows]..sort((a, b) => _value(b).compareTo(_value(a)));
    final total = _DayTotal.fromRows(allRows,
        sessionsCount: _groupTrackerSessions(widget.bundle.sessions).length,
        fallbackSession: widget.selectedSession,
        local: widget.local);
    final playersPanel = _Panel(
      title: 'Рейтинг игроков',
      subtitle: 'по выбранным сессиям',
      child: Column(children: [
        SizedBox(
          height: 34,
          child: ListView(scrollDirection: Axis.horizontal, children: [
            _RankModeChip(
                label: 'Дистанция',
                mode: _RankingMode.distance,
                value: _mode,
                onChanged: _setMode),
            _RankModeChip(
                label: 'Скорость',
                mode: _RankingMode.speed,
                value: _mode,
                onChanged: _setMode),
            _RankModeChip(
                label: 'Спринты',
                mode: _RankingMode.sprints,
                value: _mode,
                onChanged: _setMode),
            _RankModeChip(
                label: 'Нагрузка',
                mode: _RankingMode.load,
                value: _mode,
                onChanged: _setMode),
          ]),
        ),
        Expanded(child: _PlayerRanking(players: sorted, mode: _mode)),
      ]),
    );
    final teamPanel = _Panel(
      title: 'Рейтинг команды',
      subtitle: 'сравнение доступных команд / групп',
      child: Column(children: [
        _TeamCompareRow(
            name: widget.teamName,
            value: _meters(total.distanceM),
            note:
                '${total.playersCount} игроков · ${total.sessionsCount} ${_trackerTrainingWord(total.sessionsCount)}',
            rank: 1),
        const _InlineNotice(
            text:
                'Когда появятся данные других команд, они будут показаны здесь для сравнения по тем же выбранным сессиям.'),
        Expanded(
            child: CustomPaint(
                painter: _RadarPainter(rows: allRows),
                child: const SizedBox.expand())),
      ]),
    );
    final comparePanel = _Panel(
      title: 'Сравнение игрока',
      subtitle: 'игрок против среднего команды',
      child: CustomPaint(
          painter: _RadarPainter(
              rows: selectedRows.isNotEmpty ? selectedRows : rows,
              baselineRows: allRows),
          child: const SizedBox.expand()),
    );

    return LayoutBuilder(builder: (context, c) {
      final stacked = c.maxWidth < 1040;
      final phone = c.maxWidth < 720;
      if (stacked) {
        return ListView(
          primary: false,
          padding: const EdgeInsets.only(bottom: 12),
          children: [
            SizedBox(height: phone ? 340 : 380, child: playersPanel),
            SizedBox(height: phone ? 305 : 340, child: teamPanel),
            SizedBox(height: phone ? 300 : 330, child: comparePanel),
          ],
        );
      }
      return Row(children: [
        Expanded(flex: 5, child: playersPanel),
        Expanded(flex: 4, child: teamPanel),
        Expanded(flex: 4, child: comparePanel),
      ]);
    });
  }

  void _setMode(_RankingMode mode) => setState(() => _mode = mode);

  double _value(TrackerPlayerLoadRow row) {
    switch (_mode) {
      case _RankingMode.speed:
        return row.maxSpeedKmh;
      case _RankingMode.sprints:
        return row.sprintCount.toDouble() * 1000 + row.sprintDistanceM;
      case _RankingMode.load:
        return row.loadScore;
      case _RankingMode.distance:
      default:
        return row.distanceM;
    }
  }
}

