                    _InfoLine(
                        title: usingLatestFallback
                            ? 'Показано'
                            : 'Сессий за период',
                        value: usingLatestFallback
                            ? 'последняя сессия'
                            : '${sessions.length}'),
                    _InfoLine(
                        title: 'Игроков с данными',
                        value: '${byPlayer.keys.where((e) => e > 0).length}'),
                    if (usingLatestFallback) _Hint(text: fallbackMessage),
                    const SizedBox(height: 0),
                    const _Hint(
                        text:
                            'Данные больше не смешиваются бесконечно: выбирайте дату или конкретную сессию. Live-точки остаются на экране отдельно, пока сессия идёт.'),
                  ]))),
      const SizedBox.shrink(),
      Expanded(
          flex: 6,
          child: _Panel(
              title: 'История сессий',
              subtitle: '${sessions.length} записей',
              child: sessions.isEmpty
                  ? const _Empty(
                      icon: Icons.event_note_rounded,
                      text:
                          'Сессии появятся после Live, стопа с сохранением или выгрузки офлайн GPS.')
                  : ListView(
                      children: sessions.map((s) {
                      final active = selectedSession?.id == s.id;
                      return _ListRow(
                        icon: Icons.assignment_rounded,
                        title: s.title,
                        subtitle:
                            '${s.playerName ?? 'Команда'} · ${s.createdAt} · ${_meters(s.distanceM)} · ${s.sprintCount} спринтов',
                        trailing: s.processingStatus == 'done'
                            ? 'готово'
                            : s.processingStatus,
                        active: active,
                        onTap: () => onSelectSession(s),
                      );
                    }).toList()))),
      const SizedBox.shrink(),
      Expanded(
          flex: 5,
          child: _Panel(
              title: 'Расшифровка',
              subtitle: selectedSession?.title ?? 'выберите сессию',
              child: selectedSession == null
                  ? const _Empty(
                      icon: Icons.analytics_rounded,
                      text:
                          'Выберите сессию слева: карта, спринты, скорость и команда будут строиться по выбранной записи.')
                  : _SessionSummary(session: selectedSession!))),
      const SizedBox.shrink(),
      Expanded(
          flex: 3,
          child: _Panel(
              title: 'Действия',
              subtitle: 'GPS-записи',
              child: Column(children: [
                _SmallButton(
                    icon: Icons.table_chart_rounded,
                    label: 'Открыть сессии',
                    primary: true,
                    onTap: onOpenSessions),
                const SizedBox(height: 0),
                const _Hint(
                    text:
                        'Для командной аналитики передавайте датчик другому игроку после остановки и сохранения текущей сессии. У каждого игрока будет своя запись в календаре.'),
              ]))),
    ]);
  }
}

class _OfflineTab extends StatelessWidget {
  const _OfflineTab({
    required this.liveRunning,
    required this.commandChannelReady,
    required this.offlineRecordsCount,
    required this.localPointsCount,
    required this.offlineGpsMode,
    required this.onToggleOfflineGpsMode,
    required this.onRequestOfflineRecords,
    required this.onSaveOfflineSession,
    required this.onOpenSessions,
  });

  final bool liveRunning;
  final bool commandChannelReady;
  final int offlineRecordsCount;
  final int localPointsCount;
  final bool offlineGpsMode;
  final ValueChanged<bool> onToggleOfflineGpsMode;
  final VoidCallback onRequestOfflineRecords;
  final VoidCallback onSaveOfflineSession;
  final VoidCallback onOpenSessions;

  @override
  Widget build(BuildContext context) {
    final devicePanel = _Panel(
        title: 'Офлайн GPS с датчика',
        subtitle: commandChannelReady
            ? 'BLE TX/RX готов'
            : 'нужен реальный BLE-канал',
        child: Column(children: [
          SwitchListTile.adaptive(
            dense: true,
            contentPadding: EdgeInsets.zero,
            value: offlineGpsMode,
            onChanged: onToggleOfflineGpsMode,
            title: const Text('Режим офлайн-выгрузки',
                style: TextStyle(fontWeight: FontWeight.w700, color: _AA.text)),
            subtitle: const Text(
                'Сначала читаем список записей с датчика, затем загружаем GPS-точки и сохраняем как сессию.',
                style: TextStyle(color: _AA.muted, fontSize: 11.2)),
          ),
          _InfoLine(
              title: 'BLE канал',
              value: commandChannelReady ? 'TX/RX готов' : 'нет TX/RX'),
          _InfoLine(title: 'Live', value: liveRunning ? 'идёт' : 'не запущен'),
          _InfoLine(title: 'Записей в датчике', value: '$offlineRecordsCount'),
          _InfoLine(title: 'Загружено точек', value: '$localPointsCount'),
          const Spacer(),
          _SmallButton(
              icon: Icons.download_rounded,
              label: 'Прочитать записи',
              primary: true,
              onTap: onRequestOfflineRecords),
          const SizedBox(height: 0),
          _SmallButton(
              icon: Icons.cloud_upload_rounded,
              label: 'Сохранить как сессию',
              onTap: onSaveOfflineSession),
        ]));
    final howPanel = _Panel(
        title: 'Как работает офлайн',
        subtitle: 'без постоянного Live',
        child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: const [
              _Hint(
                  text:
                      '1. Датчик записывает GPS внутри себя.\n2. После тренировки подключаем датчик.\n3. Нажимаем «Прочитать записи».\n4. Выбираем запись в «Сессиях».\n5. Загружаем GPS-точки и сохраняем тренировку.'),
              SizedBox(height: 10),
              _Hint(
                  text:
                      'Кнопка чтения использует реальную команду списка записей датчика, а сохранение отправляет загруженные GPS-точки в API сессий.'),
            ]));
    final sessionsPanel = _Panel(
        title: 'Сессии',
        subtitle: 'открыть полный список',
        child: Column(children: [
          const _Empty(
              icon: Icons.event_note_rounded,
              text:
                  'В полном разделе видны записи датчика и серверные GPS-сессии. Экспорт доступен в разделе «Отчёт».'),
          const SizedBox(height: 0),
          _SmallButton(
              icon: Icons.event_note_rounded,
              label: 'Открыть сессии',
              onTap: onOpenSessions),
        ]));

    return LayoutBuilder(builder: (context, c) {
      final stacked = c.maxWidth < 1040;
      final phone = c.maxWidth < 720;
      if (stacked) {
        return ListView(
          primary: false,
          padding: const EdgeInsets.only(bottom: 12),
          children: [
            SizedBox(height: phone ? 330 : 360, child: devicePanel),
            SizedBox(height: phone ? 260 : 290, child: howPanel),
            SizedBox(height: phone ? 220 : 250, child: sessionsPanel),
          ],
