      }
      return Row(children: [
        Expanded(flex: 5, child: devicePanel),
        Expanded(flex: 5, child: howPanel),
        Expanded(flex: 4, child: sessionsPanel),
      ]);
    });
  }
}

class _SettingsTab extends StatelessWidget {
