class _Panel extends StatelessWidget {
  const _Panel(
      {required this.title,
      required this.subtitle,
      required this.child,
      this.trailing,
      this.hideHeader = false,
      this.flat = false,
      this.surfaceColor,
      this.cmrStyle = false,
      this.dotAccent = false});
  final String title;
  final String subtitle;
  final Widget child;
  final Widget? trailing;
  final bool hideHeader;
  final bool flat;
  final Color? surfaceColor;
  final bool cmrStyle;
  final bool dotAccent;

  @override
  Widget build(BuildContext context) {
    final effectiveColor = surfaceColor ??
        (cmrStyle
            ? const Color(0xFFF8FAF9)
            : (flat ? Colors.transparent : _AA.card));
    return Container(
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        color: effectiveColor,
        borderRadius: BorderRadius.circular(cmrStyle ? 12 : _AA.tabletCardRadius),
        border: flat || cmrStyle
            ? null
            : Border.all(
                color: _AA.line.withOpacity(.58),
                width: .6,
              ),
        boxShadow: flat || cmrStyle
            ? null
            : const [
                BoxShadow(
                  color: Color(0x03111827),
                  blurRadius: 14,
                  spreadRadius: -11,
                  offset: Offset(0, 8),
                ),
              ],
      ),
      child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
        if (!hideHeader)
          Container(
            constraints: BoxConstraints(minHeight: cmrStyle ? 46 : 48),
            padding: EdgeInsets.symmetric(
                horizontal: cmrStyle ? 12 : 13, vertical: cmrStyle ? 7 : 7),
            decoration: BoxDecoration(
              color: cmrStyle ? Colors.transparent : Colors.white,
              border: cmrStyle
                  ? null
                  : const Border(
                      bottom: BorderSide(color: _AA.line, width: .55),
                    ),
            ),
            child: Row(children: [
              Expanded(
                  child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                    Row(children: [
                      Flexible(
                        child: Text(
                          title,
                          maxLines: 1,
                          overflow: TextOverflow.ellipsis,
                          style: cmrStyle
                              ? _AText.title(14)
                              : _AText.body(12, color: _AA.text, weight: FontWeight.w600),
                        ),
                      ),
                      if (cmrStyle && dotAccent) ...[
                        const SizedBox(width: 9),
                        const _CmrDotCluster(),
                      ],
                    ]),
                    const SizedBox(height: 2),
                    Text(
                      subtitle,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      style: _AText.body(10.2),
                    ),
                  ])),
              if (trailing != null) ...[
                const SizedBox(width: 8),
                trailing!,
              ],
            ]),
          ),
        Expanded(
          child: Padding(
            padding: hideHeader
                ? EdgeInsets.zero
                : EdgeInsets.all(cmrStyle ? 8 : 8),
            child: child,
          ),
        ),
      ]),
    );
  }
}

