class _ActivityAxisValue {
  const _ActivityAxisValue(this.label, this.value);
  final String label;
  final double value;
}

List<_ActivityAxisValue> _activityAxes(
    {required _LocalTrackAnalysis local,
    required TrackerSessionModel? session,
    List<TrackerPlayerLoadRow> rows = const <TrackerPlayerLoadRow>[]}) {
  double clamp(double v) =>
      v.isNaN || v.isInfinite ? 0 : v.clamp(0.0, 1.0).toDouble();
  double sum(double Function(TrackerPlayerLoadRow r) pick) =>
      rows.fold<double>(0, (a, r) => a + pick(r));
  double maxRow(double Function(TrackerPlayerLoadRow r) pick) =>
      rows.fold<double>(0, (a, r) => math.max(a, pick(r)));
  final rowDistance = sum((r) => r.distanceM);
  final rowMaxSpeed = maxRow((r) => r.maxSpeedKmh);
  final rowSprintDistance = sum((r) => r.sprintDistanceM);
  final rowSprintCount = rows.fold<int>(0, (a, r) => a + r.sprintCount);
  final rowHir = sum((r) => r.highSpeedDistanceM);
  final rowAccel = rows.fold<int>(0, (a, r) => a + r.accelerationCount);
  final rowDecel = rows.fold<int>(0, (a, r) => a + r.decelerationCount);
  final rowLoad = sum((r) => r.loadScore);
  final distance = local.distanceM > 0
      ? local.distanceM
      : ((session?.distanceM ?? 0) > 0 ? session!.distanceM : rowDistance);
  final maxSpeed = local.maxSpeedKmh > 0
      ? local.maxSpeedKmh
      : ((session?.maxSpeedKmh ?? 0) > 0 ? session!.maxSpeedKmh : rowMaxSpeed);
  final sprintDistance = local.sprintDistanceM > 0
      ? local.sprintDistanceM
      : ((session?.sprintDistanceM ?? 0) > 0
          ? session!.sprintDistanceM
          : rowSprintDistance);
  final sprintCount = local.sprintCount > 0
      ? local.sprintCount
      : ((session?.sprintCount ?? 0) > 0
          ? session!.sprintCount
          : rowSprintCount);
  final hir = local.hsrDistanceM > 0
      ? local.hsrDistanceM
      : (((session?.hirDistanceM ?? 0) +
                  (session?.vhirDistanceM ?? 0) +
                  (session?.hsrDistanceM ?? 0)) >
              0
          ? ((session?.hirDistanceM ?? 0) +
              (session?.vhirDistanceM ?? 0) +
              (session?.hsrDistanceM ?? 0))
          : rowHir);
  final accel = local.accelCount > 0
      ? local.accelCount
      : ((session?.accelCount ?? 0) > 0 ? session!.accelCount : rowAccel);
  final decel = local.decelCount > 0
      ? local.decelCount
      : ((session?.decelCount ?? 0) > 0 ? session!.decelCount : rowDecel);
  final fallbackLoad = distance / 10.0 +
      sprintDistance * .35 +
      hir * .18 +
      (accel + decel) * 2.5;
  final load = (session?.loadScore ?? 0) > 0
      ? session!.loadScore
      : (rowLoad > 0 ? rowLoad : fallbackLoad);
  return <_ActivityAxisValue>[
    _ActivityAxisValue('Объём', clamp(distance / 9000.0)),
    _ActivityAxisValue('Скорость', clamp(maxSpeed / 34.0)),
    _ActivityAxisValue(
        'Спринт', clamp((sprintDistance / 650.0 + sprintCount / 35.0) / 2.0)),
    _ActivityAxisValue('Интенс.', clamp(hir / 1800.0)),
    _ActivityAxisValue('Манёвр', clamp((accel + decel) / 140.0)),
    _ActivityAxisValue('Нагрузка', clamp(load / 1000.0)),
  ];
}

class _SpeedZonesPanel extends StatelessWidget {
  const _SpeedZonesPanel(
      {required this.hsrThresholdKmh,
      required this.sprintThresholdKmh,
      required this.maxSpeedKmh,
      this.speedSamples = const <double>[]});
  final double hsrThresholdKmh;
  final double sprintThresholdKmh;
  final double maxSpeedKmh;
  final List<double> speedSamples;

  @override
  Widget build(BuildContext context) {
    final samples =
        speedSamples.where((v) => v.isFinite && v >= 0).toList(growable: false);
    final total = samples.length;
    double share(bool Function(double v) test) {
      if (total <= 0) return 0;
      return samples.where(test).length / total;
    }

    String note(bool Function(double v) test, String range) {
      if (total <= 0) return range;
      final count = samples.where(test).length;
      final percent = (count * 100 / total).round();
      return '$range · $percent% · $count точ.';
    }

    return ListView(children: [
      _ZoneProgress(
          label: 'Ходьба / лёгкая работа',
          range: note((v) => v < 7, '< 7 км/ч'),
          value: share((v) => v < 7),
          color: _AA.green.withOpacity(.50)),
      _ZoneProgress(
          label: 'Бег',
          range: note((v) => v >= 7 && v < hsrThresholdKmh,
              '7–${hsrThresholdKmh.toStringAsFixed(1)} км/ч'),
          value: share((v) => v >= 7 && v < hsrThresholdKmh),
          color: _AA.green),
      _ZoneProgress(
          label: 'Высокая интенсивность',
          range: note((v) => v >= hsrThresholdKmh && v < sprintThresholdKmh,
              '${hsrThresholdKmh.toStringAsFixed(1)}–${sprintThresholdKmh.toStringAsFixed(1)} км/ч'),
          value: share((v) => v >= hsrThresholdKmh && v < sprintThresholdKmh),
          color: _AA.orange),
      _ZoneProgress(
          label: 'Спринт',
          range: note((v) => v >= sprintThresholdKmh,
              '> ${sprintThresholdKmh.toStringAsFixed(1)} км/ч'),
          value: share((v) => v >= sprintThresholdKmh),
          color: _AA.red),
      const SizedBox(height: 6),
      _Hint(
          text: total > 0
              ? 'Полосы показывают долю GPS-точек в зоне, а не просто факт достижения максимальной скорости.'
              : 'Нет GPS-точек speed_kmh для расчёта долей зон. Максимальная скорость: ${maxSpeedKmh.toStringAsFixed(1)} км/ч.'),
    ]);
  }
}

class _PlayerComparisonPanel extends StatelessWidget {
  const _PlayerComparisonPanel({required this.rows});
  final List<TrackerPlayerLoadRow> rows;

  @override
  Widget build(BuildContext context) {
    if (rows.isEmpty)
      return const _Empty(
          icon: Icons.compare_arrows_rounded,
          text: 'Выберите двух или больше игроков для сравнения.');
    final sorted = [...rows]
      ..sort((a, b) => b.distanceM.compareTo(a.distanceM));
    final maxDistance = math.max(
        1.0, sorted.fold<double>(0, (v, r) => math.max(v, r.distanceM)));
    final maxSpeed = math.max(
        1.0, sorted.fold<double>(0, (v, r) => math.max(v, r.maxSpeedKmh)));
    final maxSprints =
        math.max(1, sorted.fold<int>(0, (v, r) => math.max(v, r.sprintCount)));
    final visible = sorted.take(6).toList(growable: false);
    return ListView(
      padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 6),
      children: [
        Row(children: [
          const Icon(Icons.compare_arrows_rounded, color: _AA.green, size: 15),
          const SizedBox(width: 6),
          Expanded(
              child: Text('Сравнение игроков · ${rows.length}',
                  maxLines: 1,
                  overflow: TextOverflow.ellipsis,
                  style: const TextStyle(
                      color: _AA.text,
                      fontSize: 10.4,
                      fontWeight: FontWeight.w700))),
          const Text('дист. / max / SPR',
              style: TextStyle(
                  color: _AA.muted,
                  fontSize: 9.6,
                  fontWeight: FontWeight.w700)),
        ]),
        const SizedBox(height: 6),
        for (final r in visible)
          Container(
            padding: const EdgeInsets.symmetric(vertical: 5),
            decoration: const BoxDecoration(
                border: Border(bottom: BorderSide(color: _AA.line))),
            child:
                Column(crossAxisAlignment: CrossAxisAlignment.start, children: [
              Row(children: [
                Expanded(
                    child: Text(r.playerName,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        style: const TextStyle(
                            color: _AA.text,
                            fontSize: 10.4,
                            fontWeight: FontWeight.w700))),
                Text(
                    '${_meters(r.distanceM)} · ${r.maxSpeedKmh.toStringAsFixed(1)} · ${r.sprintCount}',
                    style: const TextStyle(
                        color: _AA.green,
                        fontSize: 10.4,
                        fontWeight: FontWeight.w700)),
              ]),
              const SizedBox(height: 4),
              _TinyCompareBar(
                  label: 'Дистанция', value: r.distanceM / maxDistance),
              _TinyCompareBar(
                  label: 'Скорость', value: r.maxSpeedKmh / maxSpeed),
              _TinyCompareBar(label: 'SPR', value: r.sprintCount / maxSprints),
            ]),
          ),
      ],
    );
  }
}

