class _MapQuickMetricsStrip extends StatelessWidget {
  const _MapQuickMetricsStrip({
    required this.distance,
    required this.maxSpeed,
    required this.sprints,
    required this.events,
  });

  final String distance;
  final String maxSpeed;
  final String sprints;
  final String events;

  @override
  Widget build(BuildContext context) {
    final items = <({String label, String value})>[
      (label: 'Дистанция', value: distance),
      (label: 'Макс. скорость', value: maxSpeed),
      (label: 'Спринты', value: sprints),
      (label: 'События', value: events),
    ];

    Widget metric(({String label, String value}) item) {
      return Expanded(
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 2),
          child: Column(
            mainAxisAlignment: MainAxisAlignment.center,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Text(
                item.label,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: AppTypography.custom(
                  size: 8.8,
                  weight: FontWeight.w500,
                  color: _AA.muted,
                  height: 1.05,
                ),
              ),
              const SizedBox(height: 3),
              Text(
                item.value,
                maxLines: 1,
                overflow: TextOverflow.ellipsis,
                style: AppTypography.custom(
                  size: 10.7,
                  weight: FontWeight.w600,
                  color: _AA.text,
                  height: 1.05,
                  features: const <FontFeature>[
                    FontFeature.tabularFigures(),
                  ],
                ),
              ),
            ],
          ),
        ),
      );
    }

    Widget divider() => Container(
          width: 1,
          height: 26,
          color: _AA.line.withOpacity(.68),
        );

    return LayoutBuilder(
      builder: (context, constraints) {
        final twoRows = constraints.maxWidth < 300;
        return Container(
          height: twoRows ? 76 : 46,
          padding: const EdgeInsets.symmetric(horizontal: 5, vertical: 5),
          decoration: BoxDecoration(
            color: Colors.white,
            borderRadius: BorderRadius.circular(10),
          ),
          child: twoRows
              ? Column(
                  children: [
                    Expanded(
                      child: Row(children: [
                        metric(items[0]),
                        divider(),
                        metric(items[1]),
                      ]),
                    ),
                    Container(
                      height: 1,
                      margin: const EdgeInsets.symmetric(horizontal: 5),
                      color: _AA.line.withOpacity(.55),
                    ),
                    Expanded(
                      child: Row(children: [
                        metric(items[2]),
                        divider(),
                        metric(items[3]),
                      ]),
                    ),
                  ],
                )
              : Row(
                  children: [
                    for (var i = 0; i < items.length; i++) ...[
                      if (i > 0) divider(),
                      metric(items[i]),
                    ],
                  ],
                ),
        );
      },
    );
  }
}


