    (value: 'decel', label: 'Торможения', icon: Icons.trending_down_rounded),
    (value: 'turn', label: 'Повороты', icon: Icons.change_circle_rounded),
    (value: 'stop', label: 'Остановки', icon: Icons.pause_circle_outline_rounded),
  ];

  @override
