      shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),
      itemBuilder: (_) => [
        for (final item in _items)
          PopupMenuItem<String>(
            value: item.value,
            height: 38,
            child: Row(
              children: [
                Icon(
                  item.icon,
                  size: 16,
