class _TeamLeadersCard extends StatelessWidget {
  const _TeamLeadersCard({required this.bundle});
  final _AnalyticsBundle bundle;

  @override
  Widget build(BuildContext context) {
    final rows = [
      ..._rowsForAnalytics(
          bundle,
          null,
          const _LocalTrackAnalysis(
              distanceM: 0,
              durationSec: 0,
              maxSpeedKmh: 0,
              avgSpeedKmh: 0,
              sprintCount: 0,
              sprintDistanceM: 0,
              hsrDistanceM: 0,
              accelCount: 0,
              decelCount: 0,
              speedSamples: <double>[]),
          null)
    ]..sort((a, b) => (b.distanceM > 0 || a.distanceM > 0)
        ? b.distanceM.compareTo(a.distanceM)
        : b.loadScore.compareTo(a.loadScore));
    final visible = rows.take(12).toList(growable: false);
    return _Panel(
        title: 'Лидеры команды',
        subtitle: '${rows.length} игроков',
        child: rows.isEmpty
            ? const _Empty(
                icon: Icons.groups_rounded,
                text: 'Командная статистика появится после обработки сессий.')
            : ListView(children: [
                for (var i = 0; i < visible.length; i++)
                  _ListRow(
                    icon: Icons.person_rounded,
                    title: '${i + 1}. ${visible[i].playerName}',
                    subtitle:
                        '${_meters(visible[i].distanceM)} · ${visible[i].maxSpeedKmh.toStringAsFixed(1)} км/ч · ${visible[i].sprintCount} спринтов',
                  ),
              ]));
  }
}

class _PlayerRanking extends StatelessWidget {
  const _PlayerRanking({required this.players, required this.mode, this.onTap});
  final List<TrackerPlayerLoadRow> players;
  final _RankingMode mode;
  final ValueChanged<TrackerPlayerLoadRow>? onTap;

  @override
  Widget build(BuildContext context) {
    if (players.isEmpty)
      return const _Empty(
          icon: Icons.leaderboard_rounded,
          text: 'Нет обработанных данных для рейтинга.');
    final visible = players.take(14).toList(growable: false);
    return ListView(children: [
      for (var i = 0; i < visible.length; i++)
        _ListRow(
          icon: mode == _RankingMode.sprints
              ? Icons.flash_on_rounded
              : (mode == _RankingMode.speed
                  ? Icons.speed_rounded
                  : (mode == _RankingMode.load
                      ? Icons.bolt_rounded
                      : Icons.route_rounded)),
          title: '${i + 1}. ${visible[i].playerName}',
          subtitle:
              '${_meters(visible[i].distanceM)} · max ${visible[i].maxSpeedKmh.toStringAsFixed(1)} км/ч · SPR ${visible[i].sprintCount} · Нагрузка ${visible[i].loadScore.toStringAsFixed(0)}',
          trailing: _valueText(visible[i]),
          onTap: onTap == null ? null : () => onTap!(visible[i]),
        ),
    ]);
  }

  String _valueText(TrackerPlayerLoadRow p) {
    switch (mode) {
      case _RankingMode.speed:
        return '${p.maxSpeedKmh.toStringAsFixed(1)} км/ч';
      case _RankingMode.sprints:
        return '${p.sprintCount}';
      case _RankingMode.load:
        return p.loadScore.toStringAsFixed(0);
      case _RankingMode.distance:
      default:
        return _meters(p.distanceM);
    }
  }
}

enum _RankingMode { distance, sprints, speed, load }

