class _SessionSummary extends StatelessWidget {
  const _SessionSummary({required this.session, this.local});
  final TrackerSessionModel session;
  final _LocalTrackAnalysis? local;

  @override
  Widget build(BuildContext context) {
    final l = local;
    final distance = (l?.distanceM ?? 0) > 0 ? l!.distanceM : session.distanceM;
    final maxSpeed =
        (l?.maxSpeedKmh ?? 0) > 0 ? l!.maxSpeedKmh : session.maxSpeedKmh;
    final sprintCount =
        (l?.sprintCount ?? 0) > 0 ? l!.sprintCount : session.sprintCount;
    final sprintDistance = (l?.sprintDistanceM ?? 0) > 0
        ? l!.sprintDistanceM
        : session.sprintDistanceM;
    final accel = (l?.accelCount ?? 0) > 0 ? l!.accelCount : session.accelCount;
    final decel = (l?.decelCount ?? 0) > 0 ? l!.decelCount : session.decelCount;
    final load = session.loadScore > 0
        ? session.loadScore
        : (distance / 10.0 + sprintDistance * .35 + (accel + decel) * 2.5);
    return Column(children: [
      _InfoLine(title: 'Игрок', value: session.playerName ?? 'Команда'),
      _InfoLine(
          title: 'Дата', value: _formatSessionDateTime(session.createdAt)),
      _InfoLine(title: 'Дистанция', value: _meters(distance)),
      _InfoLine(
          title: 'Макс. скорость',
          value: '${maxSpeed.toStringAsFixed(1)} км/ч'),
      _InfoLine(
          title: 'Спринты', value: '$sprintCount · ${_meters(sprintDistance)}'),
      _InfoLine(title: 'Ускорения / торможения', value: '$accel / $decel'),
      _InfoLine(
          title: 'Нагрузка',
          value:
              '${load.toStringAsFixed(0)} · ${session.loadPerMinute.toStringAsFixed(1)}/мин'),
      const SizedBox(height: 0),
      const _Hint(
          text:
              'Выгрузка находится в разделе «Отчёт»: там выбираются игроки, таблицы, пульс, сравнение и нужные графики для PDF / Excel.'),
    ]);
  }
}

