class _SprintSegment {
  const _SprintSegment(this.from, this.to, this.speedKmh);
  final ActionTrackerGpsPoint from;
  final ActionTrackerGpsPoint to;
  final double speedKmh;

  static List<_SprintSegment> fromPoints(List<ActionTrackerGpsPoint> points,
      {required double thresholdKmh}) {
    if (points.length < 2) return const <_SprintSegment>[];
    final validated = _validatedTrack(points);
    return validated.segments
        .where((segment) => segment.speedKmh >= thresholdKmh)
        .map((segment) => _SprintSegment(points[segment.fromIndex],
            points[segment.toIndex], segment.speedKmh))
        .toList(growable: false);
  }
}

List<int> _turnPoints(List<ActionTrackerGpsPoint> points) {
  if (points.length < 3) return const <int>[];
  final out = _validatedTrack(points).turnPointIndexes.toList()..sort();
  return out;
}

class _ActionPitchPainter extends CustomPainter {
  _ActionPitchPainter({
    required this.heat,
    required this.local,
    required this.field,
    this.sprintThresholdKmh = 18.0,
    this.hsrThresholdKmh = 14.0,
    this.activityFilter = 'all',
    this.showSprintArrows = true,
    this.showTrackDots = true,
    this.fastRouteRender = false,
    this.mapRotationDeg = 0,
    this.cursorPoint,
    this.ghostPoint,
    this.sectorMetrics = const <_TelemetrySectorMetric>[],
    this.pitWallActive = false,
    this.pitWallPoints = const <ActionTrackerGpsPoint>[],
    this.pitWallProjectionPoints = const <ActionTrackerGpsPoint>[],
    this.projectionPoints = const <ActionTrackerGpsPoint>[],
    this.mapMarkers = const <_MovementMapMarker>[],
    this.selectedMarkerTimeMs = 0,
  });

  final List<TrackerHeatPoint> heat;
  final List<ActionTrackerGpsPoint> local;
  final TrackerFieldModel? field;
  final double sprintThresholdKmh;
  final double hsrThresholdKmh;
  final String activityFilter;
  final bool showSprintArrows;
  final bool showTrackDots;
  // V151: batched polyline renderer for dense 3D route. Analytics still use
  // full GPS; only the visual paint path is simplified.
  final bool fastRouteRender;
  final double mapRotationDeg;
  final ActionTrackerGpsPoint? cursorPoint;
  final ActionTrackerGpsPoint? ghostPoint;
  final List<_TelemetrySectorMetric> sectorMetrics;
  final bool pitWallActive;
  final List<ActionTrackerGpsPoint> pitWallPoints;
  final List<ActionTrackerGpsPoint> pitWallProjectionPoints;
  final List<ActionTrackerGpsPoint> projectionPoints;
  final List<_MovementMapMarker> mapMarkers;
  final int selectedMarkerTimeMs;

  @override
  void paint(Canvas canvas, Size size) {
    canvas.save();
    if (mapRotationDeg.abs() > .1) {
      final center = Offset(size.width / 2, size.height / 2);
      canvas.translate(center.dx, center.dy);
      canvas.rotate(mapRotationDeg * math.pi / 180.0);
      canvas.translate(-center.dx, -center.dy);
    }

    _drawPitch(canvas, size);
    if (sectorMetrics.isNotEmpty) {
      _TelemetrySectorOverlayPainter(sectors: sectorMetrics).paint(canvas, size);
    }
    if (heat.isNotEmpty) {
      final inner = _pitchInnerRect(size);
      final maxHeat = heat.map((p) => p.value).fold<double>(1.0, math.max);
      canvas.save();
      canvas
          .clipRRect(RRect.fromRectAndRadius(inner, const Radius.circular(12)));
      for (final p in heat.take(1600)) {
        final nx =
            (p.x.abs() <= 1.2 ? p.x : p.x / 105.0).clamp(0.0, 1.0).toDouble();
        final ny =
            (p.y.abs() <= 1.2 ? p.y : p.y / 68.0).clamp(0.0, 1.0).toDouble();
        final ratio = (p.value / maxHeat).clamp(0.0, 1.0).toDouble();
        final center = Offset(
            inner.left + nx * inner.width, inner.top + ny * inner.height);
        final r = heat.length <= 2 ? 18.0 : (12.0 + ratio * 26.0);
        final color = Color.lerp(
                const Color(0xFF22C55E), const Color(0xFFDC2626), ratio) ??
            _AA.green;
        final paint = Paint()
          ..shader = RadialGradient(colors: [
            color.withOpacity(.55),
            color.withOpacity(.24),
            color.withOpacity(0.0)
          ], stops: const [
            0.0,
            .50,
            1.0
          ]).createShader(Rect.fromCircle(center: center, radius: r));
        canvas.drawCircle(center, r, paint);
      }
      canvas.restore();
    }

    if (local.length > 1) {
      final validated = _validatedTrack(local);
      if (validated.segments.isNotEmpty) {
        final bounds = _Bounds.fromGps(local);
        final useFieldProjection = _shouldUseFieldProjection(local, field);
        final turns = validated.turnPointIndexes;

        if (fastRouteRender && activityFilter == 'all') {
          _drawFastRouteBatched(
            canvas,
            size,
            validated,
            bounds,
            useFieldProjection,
          );
        } else {
        final visiblePointSpeeds = <int, double>{};

        void rememberSpeed(int index, double speed) {
          final old = visiblePointSpeeds[index] ?? 0.0;
          if (speed > old) visiblePointSpeeds[index] = speed;
        }

        for (final segment in validated.segments) {
          final isTurnSegment = turns.contains(segment.fromIndex) ||
              turns.contains(segment.toIndex);
          final matchesActivity = activityFilter == 'turn'
              ? isTurnSegment
              : activityFilter == 'accel'
                  ? segment.accelMps2 >= 1.0
                  : activityFilter == 'decel'
                      ? segment.accelMps2 <= -1.0
                      : activityFilter == 'stop'
                          ? false
                          : _segmentMatchesActivity(
                              segment.speedKmh, activityFilter,
                              hsrThresholdKmh: hsrThresholdKmh,
                              sprintThresholdKmh: sprintThresholdKmh);
          if (!matchesActivity) continue;

          var displaySpeed = segment.speedKmh;
          if (activityFilter == 'turn') {
            final turnIndex = turns.contains(segment.toIndex)
                ? segment.toIndex
                : segment.fromIndex;
            displaySpeed =
                validated.turnSpeedByPointIndex[turnIndex] ?? displaySpeed;
          }

          final aPoint = local[segment.fromIndex];
          final bPoint = local[segment.toIndex];
          final a = _project(aPoint, size, bounds, useFieldProjection);
          final b = _project(bPoint, size, bounds, useFieldProjection);
          final color = displaySpeed >= sprintThresholdKmh
              ? _AA.red
              : (displaySpeed >= hsrThresholdKmh
                  ? _AA.orange
                  : (displaySpeed >= 7 ? _AA.green : _AA.blue));
          final glowPaint = Paint()
            ..color = color.withOpacity(displaySpeed >= sprintThresholdKmh
                ? .18
                : .08)
            ..strokeWidth = displaySpeed >= sprintThresholdKmh ? 8.0 : 5.0
            ..style = PaintingStyle.stroke
            ..strokeCap = StrokeCap.round;
          canvas.drawLine(a, b, glowPaint);

          final segmentPaint = Paint()
            ..color = color.withOpacity(displaySpeed >= sprintThresholdKmh
                ? .97
                : .84)
            ..strokeWidth = displaySpeed >= sprintThresholdKmh
                ? 3.2
                : (displaySpeed >= hsrThresholdKmh ? 2.7 : 1.9)
            ..style = PaintingStyle.stroke
            ..strokeCap = StrokeCap.round;
          canvas.drawLine(a, b, segmentPaint);
          if (showSprintArrows &&
              (segment.toIndex % 14 == 0 ||
                  displaySpeed >= sprintThresholdKmh)) {
            _drawArrowHead(
                canvas,
                a,
                b,
                Paint()
                  ..color = color.withOpacity(.92)
                  ..style = PaintingStyle.fill);
          }

          rememberSpeed(segment.fromIndex, displaySpeed);
          rememberSpeed(segment.toIndex, displaySpeed);
        }

        final visibleIndexes = visiblePointSpeeds.keys.toList()..sort();
        if (showTrackDots) {
          for (final index in visibleIndexes) {
            final current = local[index];
            final o = _project(current, size, bounds, useFieldProjection);
            final speed = visiblePointSpeeds[index] ?? 0.0;
            final c = speed >= sprintThresholdKmh
                ? _AA.red
                : (speed >= hsrThresholdKmh
                    ? _AA.orange
                    : (speed >= 7 ? _AA.green : _AA.blue));
            final r = speed >= sprintThresholdKmh ? 4.8 : (speed >= 7 ? 3.8 : 3.0);
            canvas.drawCircle(o, r + 2.8, Paint()..color = c.withOpacity(.08));
            canvas.drawCircle(o, r, Paint()..color = c.withOpacity(.95));
            final showLabel = activityFilter == 'all'
                ? (index == visibleIndexes.first ||
                    index == visibleIndexes.last ||
                    speed >= sprintThresholdKmh ||
                    index % 30 == 0)
                : (index == visibleIndexes.first ||
                    index == visibleIndexes.last ||
                    speed >= sprintThresholdKmh ||
                    turns.contains(index) ||
                    index % 10 == 0);
            if (showLabel) {
              _paintChartText(canvas, speed.toStringAsFixed(1),
                  o + const Offset(6, -10), 8.0, c);
            }
          }
        }

        if (activityFilter == 'turn') {
          for (final turnIndex in turns) {
            final o = _project(
                local[turnIndex], size, bounds, useFieldProjection);
            canvas.drawCircle(
                o, 3.3, Paint()..color = _AA.orange.withOpacity(.95));
            canvas.drawCircle(
                o, 5.2, Paint()..color = _AA.orange.withOpacity(.08));
          }
        }

        if (activityFilter == 'accel' || activityFilter == 'decel') {
          for (final segment in validated.segments) {
            if (segment.accelMps2.abs() < 1.0) continue;
            if (activityFilter == 'accel' && segment.accelMps2 < 1.0) continue;
            if (activityFilter == 'decel' && segment.accelMps2 > -1.0) continue;
            final o = _project(local[segment.toIndex], size, bounds,
                useFieldProjection);
            final c = segment.accelMps2 > 0 ? _AA.green : _AA.red;
            canvas.drawCircle(o, 4.0, Paint()..color = c.withOpacity(.92));
            canvas.drawCircle(o, 7.0, Paint()..color = c.withOpacity(.08));
          }
        }

        if (activityFilter == 'stop') {
          for (final index in _movementStationaryIndexes(local)) {
            if (index < 0 || index >= local.length) continue;
            final o = _project(local[index], size, bounds, useFieldProjection);
            canvas.drawCircle(o, 7.0, Paint()..color = _AA.blue.withOpacity(.12));
            canvas.drawCircle(o, 3.8, Paint()..color = _AA.blue.withOpacity(.96));
          }
        }
        } // regular detailed route renderer
      }

      if (ghostPoint != null) {
        final bounds = _Bounds.fromGps(local);
        final useFieldProjection = _shouldUseFieldProjection(local, field);
        final o = _project(ghostPoint!, size, bounds, useFieldProjection);
        canvas.drawCircle(o, 11, Paint()..color = Colors.white.withOpacity(.72));
        canvas.drawCircle(o, 8, Paint()..color = _AA.muted.withOpacity(.20));
        canvas.drawCircle(o, 5, Paint()..color = _AA.muted.withOpacity(.70));
        _paintChartText(canvas, 'GHOST', o + const Offset(8, -9), 6.8, Colors.white.withOpacity(.92), alignLeft: true);
      }

      if (cursorPoint != null) {
        final bounds = _Bounds.fromGps(local);
        final useFieldProjection = _shouldUseFieldProjection(local, field);
        final o = _project(cursorPoint!, size, bounds, useFieldProjection);
        canvas.drawCircle(o, 11, Paint()..color = Colors.white.withOpacity(.92));
        canvas.drawCircle(o, 8, Paint()..color = _AA.green.withOpacity(.18));
        canvas.drawCircle(o, 5, Paint()..color = _AA.green);
      }
    }

    if (mapMarkers.isNotEmpty) {
      final projectionBase =
          projectionPoints.length > 1 ? projectionPoints : local;
      if (projectionBase.isNotEmpty) {
        final bounds = _Bounds.fromGps(projectionBase);
        final useFieldProjection =
            _shouldUseFieldProjection(projectionBase, field);
        for (final marker in mapMarkers.take(64)) {
          final o = _project(marker.point, size, bounds, useFieldProjection);
          // Как в Live-журнале: оранжевый = обычный значимый момент,
          // красный = приоритетный/опасный. Тип движения остаётся в журнале.
          final color = marker.isRed ? _AA.red : _AA.orange;
          final selected = selectedMarkerTimeMs > 0 &&
              (marker.timeMs - selectedMarkerTimeMs).abs() <= 1500;
          final radius = selected ? 6.5 : 3.9;
          canvas.drawCircle(
              o, radius + 2.6, Paint()..color = Colors.white.withOpacity(.90));
          canvas.drawCircle(
              o, radius + 1.0, Paint()..color = color.withOpacity(.18));
          canvas.drawCircle(
              o, radius, Paint()..color = color.withOpacity(.96));
          if (marker.source == 'live') {
            canvas.drawCircle(
                o, selected ? 2.2 : 1.5, Paint()..color = _AA.green.withOpacity(.95));
          }
          if (marker.hasHeartRate) {
            final hrCenter = o + Offset(radius * .78, -radius * .78);
            canvas.drawCircle(
                hrCenter, 3.1, Paint()..color = Colors.white.withOpacity(.96));
            canvas.drawCircle(
                hrCenter, 2.0, Paint()..color = _AA.red.withOpacity(.96));
          }
        }
      }
    }
    canvas.restore();
  }

  void _drawFastRouteBatched(
    Canvas canvas,
    Size size,
    _ValidatedTrackCache validated,
    _Bounds bounds,
    bool useFieldProjection,
  ) {
    // Four paths instead of thousands of drawLine + glow + arrow calls.
    // This preserves the full GPS geometry and speed colours but is far
    // cheaper to repaint while the replay cursor advances in 3D.
    final bluePath = Path();
    final greenPath = Path();
    final orangePath = Path();
    final redPath = Path();

    Path pathForSpeed(double speed) {
      if (speed >= sprintThresholdKmh) return redPath;
      if (speed >= hsrThresholdKmh) return orangePath;
      if (speed >= 7.0) return greenPath;
      return bluePath;
    }

    for (final segment in validated.segments) {
      final a = _project(
          local[segment.fromIndex], size, bounds, useFieldProjection);
      final b = _project(
          local[segment.toIndex], size, bounds, useFieldProjection);
      final path = pathForSpeed(segment.speedKmh);
      path.moveTo(a.dx, a.dy);
      path.lineTo(b.dx, b.dy);
    }

    void draw(Path path, Color color, double width) {
      canvas.drawPath(
        path,
        Paint()
          ..color = color.withOpacity(.90)
          ..strokeWidth = width
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round
          ..strokeJoin = StrokeJoin.round,
      );
    }

    draw(bluePath, _AA.blue, 1.45);
    draw(greenPath, _AA.green, 1.55);
    draw(orangePath, _AA.orange, 1.85);
    draw(redPath, _AA.red, 2.15);
  }

  Offset _project(ActionTrackerGpsPoint p, Size size, _Bounds bounds,
      bool useFieldProjection) {
    if (useFieldProjection) {
      final projected = TrackerPitchProjector.projectGps(field,
          latitude: p.latitude, longitude: p.longitude);
      if (projected != null) {
        return _fitPointToPitch(
            Offset(projected.clampedNx * size.width,
                projected.clampedNy * size.height),
            size);
      }
    }
    return _fitPointToPitch(bounds.project(p, size), size);
  }

  void _drawArrowHead(Canvas canvas, Offset a, Offset b, Paint paint) {
    final dx = b.dx - a.dx;
    final dy = b.dy - a.dy;
    final len = math.sqrt(dx * dx + dy * dy);
    if (len < 7) return;
    final ux = dx / len;
    final uy = dy / len;
    final tip = b;
    final left = Offset(tip.dx - ux * 10 - uy * 5, tip.dy - uy * 10 + ux * 5);
    final right = Offset(tip.dx - ux * 10 + uy * 5, tip.dy - uy * 10 - ux * 5);
    final path = Path()
      ..moveTo(tip.dx, tip.dy)
      ..lineTo(left.dx, left.dy)
      ..lineTo(right.dx, right.dy)
      ..close();
    canvas.drawPath(path, paint);
  }

  void _drawPitch(Canvas canvas, Size size) {
    final border =
        RRect.fromRectAndRadius(Offset.zero & size, const Radius.circular(16));
    canvas.drawRRect(border, Paint()..color = const Color(0xFF76947B));
    final clip = Path()..addRRect(border.deflate(8));
    canvas.save();
    canvas.clipPath(clip);
    final stripeW = math.max(36.0, size.width / 12);
    for (var i = 0; i < 14; i++) {
      final color =
          i.isEven ? const Color(0xFF719078) : const Color(0xFF819E86);
      canvas.drawRect(
          Rect.fromLTWH(8 + i * stripeW, 8, stripeW, size.height - 16),
          Paint()..color = color);
    }
    canvas.restore();
    final line = Paint()
      ..color = Colors.white.withOpacity(.78)
      ..strokeWidth = 1.5
      ..style = PaintingStyle.stroke;
    final inner = Rect.fromLTWH(10, 10, size.width - 20, size.height - 20);
    canvas.drawRRect(
        RRect.fromRectAndRadius(inner, const Radius.circular(12)), line);
    canvas.drawLine(Offset(size.width / 2, 10),
        Offset(size.width / 2, size.height - 10), line);
    canvas.drawCircle(Offset(size.width / 2, size.height / 2),
        math.min(size.width, size.height) * .12, line);
    canvas.drawRect(
        Rect.fromLTWH(
            10, size.height * .28, size.width * .17, size.height * .44),
        line);
    canvas.drawRect(
        Rect.fromLTWH(
            10, size.height * .38, size.width * .08, size.height * .24),
        line);
    canvas.drawRect(
        Rect.fromLTWH(size.width - 10 - size.width * .17, size.height * .28,
            size.width * .17, size.height * .44),
        line);
    canvas.drawRect(
        Rect.fromLTWH(size.width - 10 - size.width * .08, size.height * .38,
            size.width * .08, size.height * .24),
        line);
    canvas.drawCircle(Offset(size.width * .13, size.height / 2), 3,
        Paint()..color = Colors.white.withOpacity(.75));
    canvas.drawCircle(Offset(size.width * .87, size.height / 2), 3,
        Paint()..color = Colors.white.withOpacity(.75));
  }

  @override
  bool shouldRepaint(covariant _ActionPitchPainter oldDelegate) =>
      oldDelegate.heat != heat ||
      oldDelegate.local != local ||
      oldDelegate.field != field ||
      oldDelegate.sprintThresholdKmh != sprintThresholdKmh ||
      oldDelegate.hsrThresholdKmh != hsrThresholdKmh ||
      oldDelegate.activityFilter != activityFilter ||
      oldDelegate.showSprintArrows != showSprintArrows ||
      oldDelegate.showTrackDots != showTrackDots ||
      oldDelegate.fastRouteRender != fastRouteRender ||
      oldDelegate.mapRotationDeg != mapRotationDeg ||
      oldDelegate.cursorPoint != cursorPoint ||
      oldDelegate.ghostPoint != ghostPoint ||
      oldDelegate.sectorMetrics != sectorMetrics ||
      oldDelegate.pitWallActive != pitWallActive ||
      oldDelegate.pitWallPoints != pitWallPoints ||
      oldDelegate.pitWallProjectionPoints != pitWallProjectionPoints ||
      oldDelegate.projectionPoints != projectionPoints ||
      oldDelegate.mapMarkers != mapMarkers ||
      oldDelegate.selectedMarkerTimeMs != selectedMarkerTimeMs;
}

class _Bounds {
  const _Bounds(this.minLat, this.maxLat, this.minLng, this.maxLng);
  final double minLat;
  final double maxLat;
  final double minLng;
  final double maxLng;

  factory _Bounds.fromGps(List<ActionTrackerGpsPoint> points) {
    var minLat = points.first.latitude,
        maxLat = points.first.latitude,
        minLng = points.first.longitude,
        maxLng = points.first.longitude;
    for (final p in points) {
      minLat = math.min(minLat, p.latitude);
      maxLat = math.max(maxLat, p.latitude);
      minLng = math.min(minLng, p.longitude);
      maxLng = math.max(maxLng, p.longitude);
    }
    if ((maxLat - minLat).abs() < .00001) maxLat += .00001;
    if ((maxLng - minLng).abs() < .00001) maxLng += .00001;
    return _Bounds(minLat, maxLat, minLng, maxLng);
  }

  Offset project(ActionTrackerGpsPoint p, Size size) {
    final x = ((p.longitude - minLng) / (maxLng - minLng)).clamp(0.0, 1.0) *
        size.width;
    final y =
        (1 - ((p.latitude - minLat) / (maxLat - minLat)).clamp(0.0, 1.0)) *
            size.height;
    return Offset(x, y);
  }
}

List<double> _stableChartSpeedSamples(List<double> samples) {
  // V87: the chart no longer applies a second hidden outlier smoother.
  // Every MAX label, zone counter and plotted point uses the same validated
  // V85/V86 segment sequence. Only non-finite/out-of-range values are removed.
  return samples
      .where((v) => v.isFinite && v >= 0 && v <= 36.0)
      .toList(growable: false);
}

double _speedChartMax(List<double> samples, double maxSpeedKmh,
    double hsrThresholdKmh, double sprintThresholdKmh) {
  final stable = _stableChartSpeedSamples(samples);
  final sampleMax = stable.isEmpty ? 0.0 : stable.reduce(math.max);
  final dataMax = math.max(
      sampleMax, maxSpeedKmh > 0 && maxSpeedKmh <= 36 ? maxSpeedKmh : 0.0);
  final thresholdMax =
      math.max(sprintThresholdKmh * 1.18, hsrThresholdKmh * 1.34);
  final wanted = math.max(thresholdMax, dataMax * 1.10);
  return math.max(10.0, math.min(38.0, wanted)).toDouble();
}

class _SpeedPainter extends CustomPainter {
  _SpeedPainter({
    required this.samples,
    required this.hsrThresholdKmh,
    required this.sprintThresholdKmh,
    required this.maxSpeedKmh,
  });

  final List<double> samples;
  final double hsrThresholdKmh;
  final double sprintThresholdKmh;
  final double maxSpeedKmh;

  @override
  void paint(Canvas canvas, Size size) {
    final chartSamples = _stableChartSpeedSamples(samples);
    final maxV = _speedChartMax(
        chartSamples, maxSpeedKmh, hsrThresholdKmh, sprintThresholdKmh);
    final rect = Offset.zero & size;
    canvas.drawRRect(RRect.fromRectAndRadius(rect, const Radius.circular(14)),
        Paint()..color = Colors.white);

    void drawZone(double from, double to, Color color) {
      final top = size.height - (to / maxV).clamp(0.0, 1.0) * size.height;
      final bottom = size.height - (from / maxV).clamp(0.0, 1.0) * size.height;
      canvas.drawRect(Rect.fromLTRB(0, top, size.width, bottom),
          Paint()..color = color.withOpacity(.05));
    }

    drawZone(hsrThresholdKmh, sprintThresholdKmh, _AA.orange);
    drawZone(sprintThresholdKmh, maxV, _AA.red);

    for (var i = 0; i <= 4; i++) {
      final y = size.height * i / 4;
      canvas.drawLine(
          Offset(0, y),
          Offset(size.width, y),
          Paint()
            ..color = _AA.line.withOpacity(.50)
            ..strokeWidth = .7);
      final value = maxV * (4 - i) / 4;
      _paintChartText(
          canvas, value.toStringAsFixed(0), Offset(5, y + 2), 8.4, _AA.muted,
          alignLeft: true);
    }

    _drawThreshold(canvas, size, maxV, hsrThresholdKmh, _AA.orange,
        'HIR ${hsrThresholdKmh.toStringAsFixed(1)}');
    _drawThreshold(canvas, size, maxV, sprintThresholdKmh, _AA.red,
        'SPR ${sprintThresholdKmh.toStringAsFixed(1)}');

    if (chartSamples.length < 2) {
      _paintChartText(canvas, 'Нет GPS-точек скорости',
          Offset(size.width / 2, size.height / 2), 11, _AA.muted);
      return;
    }

    final points = <Offset>[];
    for (var i = 0; i < chartSamples.length; i++) {
      final x = i / (chartSamples.length - 1) * size.width;
      final y =
          size.height - (chartSamples[i] / maxV).clamp(0.0, 1.0) * size.height;
      points.add(Offset(x, y));
    }

    Path smoothPath(List<Offset> values) {
      final path = Path()..moveTo(values.first.dx, values.first.dy);
      for (var i = 1; i < values.length; i++) {
        final previous = values[i - 1];
        final current = values[i];
        final middleX = (previous.dx + current.dx) / 2;
        path.cubicTo(
            middleX, previous.dy, middleX, current.dy, current.dx, current.dy);
      }
      return path;
    }

    final linePath = smoothPath(points);
    final fillPath = Path.from(linePath)
      ..lineTo(points.last.dx, size.height)
      ..lineTo(points.first.dx, size.height)
      ..close();

    canvas.drawPath(
        fillPath,
        Paint()
          ..shader = LinearGradient(
              begin: Alignment.topCenter,
              end: Alignment.bottomCenter,
              colors: [
                _AA.green.withOpacity(.18),
                _AA.green.withOpacity(.02)
              ]).createShader(rect));
    canvas.drawPath(
        linePath,
        Paint()
          ..color = _AA.green.withOpacity(.14)
          ..strokeWidth = 7
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round);
    canvas.drawPath(
        linePath,
        Paint()
          ..color = _AA.green
          ..strokeWidth = 2.4
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round);

    final keyIndexes = <int>{0, chartSamples.length - 1};
    var maxIndex = 0;
    for (var i = 1; i < chartSamples.length; i++) {
      if (chartSamples[i] > chartSamples[maxIndex]) maxIndex = i;
      final localPeak = i < chartSamples.length - 1 &&
          chartSamples[i] > chartSamples[i - 1] &&
          chartSamples[i] > chartSamples[i + 1];
      if (localPeak && chartSamples[i] >= hsrThresholdKmh) keyIndexes.add(i);
    }
    keyIndexes.add(maxIndex);

    for (final index in keyIndexes) {
      final value = chartSamples[index];
      final color = value >= sprintThresholdKmh
          ? _AA.red
          : value >= hsrThresholdKmh
              ? _AA.orange
              : _AA.green;
      canvas.drawCircle(
          points[index], 7, Paint()..color = color.withOpacity(.11));
      canvas.drawCircle(points[index], 3.8, Paint()..color = Colors.white);
      canvas.drawCircle(points[index], 2.8, Paint()..color = color);
      _paintChartText(
          canvas,
          value.toStringAsFixed(1),
          points[index] + const Offset(0, -14),
          index == maxIndex ? 9.5 : 8.5,
          color);
    }

    final displayedMax =
        maxSpeedKmh > 0 ? maxSpeedKmh : chartSamples.reduce(math.max);
    _paintChartText(canvas, 'МАКС. ${displayedMax.toStringAsFixed(1)} КМ/Ч',
        const Offset(10, 12), 9.8, _AA.text,
        alignLeft: true);
  }

  void _drawThreshold(Canvas canvas, Size size, double maxV, double value,
      Color color, String label) {
    if (value <= 0 || maxV <= 0) return;
    final y = size.height - (value / maxV).clamp(0.0, 1.0) * size.height;
    canvas.drawLine(
        Offset(0, y),
        Offset(size.width, y),
        Paint()
          ..color = color.withOpacity(.46)
          ..strokeWidth = .9);
    _paintChartText(canvas, label,
        Offset(size.width - 7, math.max(9.0, y - 8).toDouble()), 8.8, color,
        alignLeft: false);
  }

  @override
  bool shouldRepaint(covariant _SpeedPainter oldDelegate) {
    return oldDelegate.samples != samples ||
        oldDelegate.hsrThresholdKmh != hsrThresholdKmh ||
        oldDelegate.sprintThresholdKmh != sprintThresholdKmh ||
        oldDelegate.maxSpeedKmh != maxSpeedKmh;
  }
}

class _SprintPainter extends CustomPainter {
  _SprintPainter(
      {required this.samples,
      required this.hsrThresholdKmh,
      required this.sprintThresholdKmh,
      required this.maxSpeedKmh});
  final List<double> samples;
  final double hsrThresholdKmh;
  final double sprintThresholdKmh;
  final double maxSpeedKmh;

  @override
  void paint(Canvas canvas, Size size) {
    _chartBg(canvas, size);
    final chartSamples = _stableChartSpeedSamples(samples);
    if (chartSamples.length < 2) {
      _paintChartText(canvas, 'Нет сохранённых точек скорости',
          Offset(size.width / 2, size.height / 2), 10.5, _AA.muted);
      return;
    }
    final double maxV = _speedChartMax(
        chartSamples, maxSpeedKmh, hsrThresholdKmh, sprintThresholdKmh);
    void threshold(double value, Color color, String label) {
      final y = size.height - (value / maxV).clamp(0.0, 1.0) * size.height;
      canvas.drawLine(
          Offset(0, y),
          Offset(size.width, y),
          Paint()
            ..color = color.withOpacity(.52)
            ..strokeWidth = 1);
      _paintChartText(
          canvas, label, Offset(6, math.max(9.0, y - 9).toDouble()), 8.2, color,
          alignLeft: true);
    }

    threshold(hsrThresholdKmh, _AA.orange,
        'HIR ${hsrThresholdKmh.toStringAsFixed(1)}');
    threshold(sprintThresholdKmh, _AA.red,
        'SPR ${sprintThresholdKmh.toStringAsFixed(1)}');

    for (var i = 0; i <= 4; i++) {
      final value = maxV * (4 - i) / 4;
      final y = i / 4 * size.height;
      _paintChartText(canvas, value.toStringAsFixed(0),
          Offset(size.width - 5, y + 2), 7.5, _AA.muted,
          alignLeft: false);
    }

    final path = Path();
    final points = <Offset>[];
    for (var i = 0; i < chartSamples.length; i++) {
      final x = i / (chartSamples.length - 1) * size.width;
      final y =
          size.height - (chartSamples[i] / maxV).clamp(0.0, 1.0) * size.height;
      final o = Offset(x, y);
      points.add(o);
      if (i == 0) {
        path.moveTo(o.dx, o.dy);
      } else {
        path.lineTo(o.dx, o.dy);
      }
    }
    canvas.drawPath(
        path,
        Paint()
          ..color = _AA.green
          ..strokeWidth = 1.8
          ..style = PaintingStyle.stroke
          ..strokeCap = StrokeCap.round
          ..strokeJoin = StrokeJoin.round);

    final sprintPaint = Paint()
      ..color = _AA.red
      ..strokeWidth = 3.0
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
    final hirPaint = Paint()
      ..color = _AA.orange.withOpacity(.70)
      ..strokeWidth = 2.4
      ..style = PaintingStyle.stroke
      ..strokeCap = StrokeCap.round
      ..strokeJoin = StrokeJoin.round;
    var sprintPoints = 0;
    var hsrPoints = 0;
    for (var i = 1; i < points.length; i++) {
      final a = chartSamples[i - 1];
      final b = chartSamples[i];
      if (a >= sprintThresholdKmh || b >= sprintThresholdKmh) {
        sprintPoints++;
        canvas.drawLine(points[i - 1], points[i], sprintPaint);
      } else if (a >= hsrThresholdKmh || b >= hsrThresholdKmh) {
        hsrPoints++;
        canvas.drawLine(points[i - 1], points[i], hirPaint);
      }
    }

    final every = math.max(1, chartSamples.length ~/ 7);
    for (var i = 0; i < points.length; i += every) {
      final v = chartSamples[i];
      final c = v >= sprintThresholdKmh
          ? _AA.red
          : (v >= hsrThresholdKmh ? _AA.orange : _AA.green);
      canvas.drawCircle(points[i], 3.3, Paint()..color = c);
      canvas.drawCircle(points[i], 6.0, Paint()..color = c.withOpacity(.06));
      _paintChartText(canvas, v.toStringAsFixed(1),
          points[i] + const Offset(0, -13), 7.7, c);
    }

    final displayMax =
        maxSpeedKmh > 0 ? maxSpeedKmh : chartSamples.reduce(math.max);
    _paintChartText(canvas, 'max ${displayMax.toStringAsFixed(1)} км/ч',
        Offset(size.width - 8, 8), 8.4, _AA.text);
    _paintChartText(canvas, 'SPR участков $sprintPoints · HIR $hsrPoints',
        const Offset(6, 8), 8.4, _AA.muted,
        alignLeft: true);
  }

  @override
  bool shouldRepaint(covariant _SprintPainter oldDelegate) =>
      oldDelegate.samples != samples ||
      oldDelegate.hsrThresholdKmh != hsrThresholdKmh ||
      oldDelegate.sprintThresholdKmh != sprintThresholdKmh ||
      oldDelegate.maxSpeedKmh != maxSpeedKmh;
}

class _ActivityRadarPainter extends CustomPainter {
  const _ActivityRadarPainter({required this.axes});
  final List<_ActivityAxisValue> axes;

  @override
  void paint(Canvas canvas, Size size) {
    final c = Offset(size.width / 2, size.height / 2);
    final r = math.min(size.width, size.height) * .34;
    final grid = Paint()
      ..color = _AA.line
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1;
    for (var ring = 1; ring <= 4; ring++) {
      canvas.drawCircle(c, r * ring / 4, grid);
    }
    if (axes.isEmpty) return;
    final path = Path();
    for (var i = 0; i < axes.length; i++) {
      final a = -math.pi / 2 + i * math.pi * 2 / axes.length;
      final end = c + Offset(math.cos(a) * r, math.sin(a) * r);
      canvas.drawLine(c, end, grid);
      final labelPos =
          c + Offset(math.cos(a) * (r + 18), math.sin(a) * (r + 18));
      _paintChartText(canvas, axes[i].label, labelPos, 8.6, _AA.muted);
      final p = c +
          Offset(math.cos(a) * r * axes[i].value.clamp(0.0, 1.0),
              math.sin(a) * r * axes[i].value.clamp(0.0, 1.0));
      if (i == 0)
        path.moveTo(p.dx, p.dy);
      else
        path.lineTo(p.dx, p.dy);
    }
    path.close();
    canvas.drawPath(
        path,
        Paint()
          ..color = _AA.green.withOpacity(.08)
          ..style = PaintingStyle.fill);
    canvas.drawPath(
        path,
        Paint()
          ..color = _AA.green
          ..style = PaintingStyle.stroke
          ..strokeWidth = 1.8);
  }

  @override
  bool shouldRepaint(covariant _ActivityRadarPainter oldDelegate) =>
      oldDelegate.axes != axes;
}

class _MiniHeatmapPainter extends CustomPainter {
  const _MiniHeatmapPainter({required this.points});
  final List<TrackerHeatPoint> points;

  @override
  void paint(Canvas canvas, Size size) {
    final bg = Paint()..color = const Color(0xFFEFFAF3);
    final rect =
        RRect.fromRectAndRadius(Offset.zero & size, const Radius.circular(4));
    canvas.drawRRect(rect, bg);
    final line = Paint()
      ..color = _AA.green.withOpacity(.40)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1;
    final inner = Rect.fromLTWH(8, 8, size.width - 16, size.height - 16);
    canvas.drawRect(inner, line);
    canvas.drawLine(Offset(size.width / 2, 8),
        Offset(size.width / 2, size.height - 8), line);
    if (points.isEmpty) {
      _paintChartText(canvas, 'Нет теплокарты сессии',
          Offset(size.width / 2, size.height / 2), 9.2, _AA.muted);
      return;
    }
    final maxValue = points.map((p) => p.value).fold<double>(1, math.max);
    final paint = Paint()..style = PaintingStyle.fill;
    for (final p in points.take(350)) {
      final x = inner.left + (p.x / 105.0).clamp(0.0, 1.0) * inner.width;
      final y = inner.top + (p.y / 68.0).clamp(0.0, 1.0) * inner.height;
      final ratio = (p.value / maxValue).clamp(0.0, 1.0).toDouble();
      paint.color = Color.lerp(
              _AA.green.withOpacity(.07), _AA.red.withOpacity(.48), ratio) ??
          _AA.green.withOpacity(.2);
      canvas.drawCircle(Offset(x, y), 2.5 + ratio * 5, paint);
    }
  }

  @override
  bool shouldRepaint(covariant _MiniHeatmapPainter oldDelegate) =>
      oldDelegate.points != points;
}

class _RadarPainter extends CustomPainter {
  _RadarPainter(
      {required this.rows, this.baselineRows = const <TrackerPlayerLoadRow>[]});
  final List<TrackerPlayerLoadRow> rows;
  final List<TrackerPlayerLoadRow> baselineRows;

  @override
  void paint(Canvas canvas, Size size) {
    final c = Offset(size.width / 2, size.height / 2);
    final r = math.min(size.width, size.height) * .36;
    final grid = Paint()
      ..color = _AA.line
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1;
    for (var ring = 1; ring <= 4; ring++) {
      canvas.drawCircle(c, r * ring / 4, grid);
    }
    final axes = 5;
    final labels = ['объём', 'скорость', 'спринты', 'HIR', 'нагрузка'];
    for (var i = 0; i < axes; i++) {
      final a = -math.pi / 2 + i * math.pi * 2 / axes;
      final end = c + Offset(math.cos(a) * r, math.sin(a) * r);
      canvas.drawLine(c, end, grid);
      final tp = c + Offset(math.cos(a) * (r + 18), math.sin(a) * (r + 18));
      _paintText(canvas, labels[i], tp, 10);
    }
    if (rows.isEmpty && baselineRows.isEmpty) return;

    final baseline =
        baselineRows.isNotEmpty ? _radarValues(baselineRows) : const <double>[];
    final values = _radarValues(rows);
    if (baseline.isNotEmpty) {
      _drawRadarPath(canvas, c, r, baseline,
          fill: _AA.muted.withOpacity(.08),
          stroke: _AA.muted.withOpacity(.55),
          strokeWidth: 1.35);
    }
    if (values.isNotEmpty) {
      _drawRadarPath(canvas, c, r, values,
          fill: _AA.green.withOpacity(.08),
          stroke: _AA.green,
          strokeWidth: 2.1);
    }
  }

  List<double> _radarValues(List<TrackerPlayerLoadRow> src) {
    if (src.isEmpty) return const <double>[];
    double avg(double Function(TrackerPlayerLoadRow r) pick) =>
        src.map(pick).fold<double>(0, (a, b) => a + b) / src.length;
    double clamp(double v) =>
        v.isNaN || v.isInfinite ? 0 : v.clamp(0.0, 1.0).toDouble();

    // Не нормируем по максимуму текущего списка: при одном игроке это всегда полный одинаковый пятиугольник.
    return <double>[
      clamp(avg((r) => r.distanceM) / 6000.0),
      clamp(avg((r) => r.maxSpeedKmh) / 34.0),
      clamp(avg((r) => r.sprintCount.toDouble()) / 25.0),
      clamp(avg((r) => r.highSpeedDistanceM) / 1200.0),
      clamp(avg((r) => r.loadScore) / 1000.0),
    ];
  }

  void _drawRadarPath(Canvas canvas, Offset c, double r, List<double> values,
      {required Color fill,
      required Color stroke,
      required double strokeWidth}) {
    if (values.isEmpty) return;
    final path = Path();
    for (var i = 0; i < values.length; i++) {
      final a = -math.pi / 2 + i * math.pi * 2 / values.length;
      final level = values[i].clamp(0.0, 1.0).toDouble();
      final p = c + Offset(math.cos(a) * r * level, math.sin(a) * r * level);
      if (i == 0) {
        path.moveTo(p.dx, p.dy);
      } else {
        path.lineTo(p.dx, p.dy);
      }
    }
    path.close();
    canvas.drawPath(
        path,
        Paint()
          ..color = fill
          ..style = PaintingStyle.fill);
    canvas.drawPath(
        path,
        Paint()
          ..color = stroke
          ..style = PaintingStyle.stroke
          ..strokeWidth = strokeWidth);
  }

  void _paintText(Canvas canvas, String text, Offset center, double size) {
    final tp = TextPainter(
        text: TextSpan(
            text: text,
            style: TextStyle(
                color: _AA.muted, fontSize: size, fontWeight: FontWeight.w700)),
        textDirection: TextDirection.ltr)
      ..layout();
    tp.paint(canvas, center - Offset(tp.width / 2, tp.height / 2));
  }

  @override
  bool shouldRepaint(covariant _RadarPainter oldDelegate) =>
      oldDelegate.rows != rows || oldDelegate.baselineRows != baselineRows;
}

class _CalibrationMiniPainter extends CustomPainter {
  _CalibrationMiniPainter({required this.field});
  final TrackerFieldModel? field;

  @override
  void paint(Canvas canvas, Size size) {
    final bg = Paint()..color = const Color(0xFFEFFAF3);
    final line = Paint()
      ..color = _AA.green.withOpacity(.45)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 1.2;
    final rect =
        RRect.fromRectAndRadius(Offset.zero & size, const Radius.circular(14));
    canvas.drawRRect(rect, bg);
    canvas.drawRRect(rect.deflate(10), line);
    final ready = field?.hasCalibration == true;
    final points = [
      Offset(16, 16),
      Offset(size.width - 16, 16),
      Offset(size.width - 16, size.height - 16),
      Offset(16, size.height - 16),
    ];
    final labels = ['A', 'B', 'C', 'D'];
    for (var i = 0; i < 4; i++) {
      canvas.drawCircle(
          points[i], 10, Paint()..color = ready ? _AA.green : _AA.orange);
      final tp = TextPainter(
          text: TextSpan(
              text: labels[i],
              style: const TextStyle(
                  color: Colors.white,
                  fontSize: 10.4,
                  fontWeight: FontWeight.w700)),
          textDirection: TextDirection.ltr)
        ..layout();
      tp.paint(canvas, points[i] - Offset(tp.width / 2, tp.height / 2));
    }
  }

  @override
  bool shouldRepaint(covariant _CalibrationMiniPainter oldDelegate) =>
      oldDelegate.field != field;
}

void _chartBg(Canvas canvas, Size size) {
  final line = Paint()
    ..color = _AA.line
    ..strokeWidth = 1;
  for (var i = 0; i <= 4; i++) {
    final y = i / 4 * size.height;
    canvas.drawLine(Offset(0, y), Offset(size.width, y), line);
  }
}

void _paintChartText(
    Canvas canvas, String text, Offset center, double size, Color color,
    {bool alignLeft = false}) {
  final tp = TextPainter(
    text: TextSpan(
        text: text,
        style: TextStyle(
            color: color, fontSize: size, fontWeight: FontWeight.w700)),
    textDirection: TextDirection.ltr,
    maxLines: 1,
  )..layout();
  final offset =
      alignLeft ? center : center - Offset(tp.width / 2, tp.height / 2);
  tp.paint(canvas, offset);
}

String _meters(double value) {
  if (value >= 1000) return '${(value / 1000).toStringAsFixed(2)} км';
  return '${value.toStringAsFixed(0)} м';
}

String _time(int sec) {
  if (sec <= 0) return '0:00';
  final m = sec ~/ 60;
  final s = sec % 60;
  return '$m:${s.toString().padLeft(2, '0')}';
}

double _num(dynamic value, double fallback) {
  if (value is num) return value.toDouble();
  return double.tryParse('$value') ?? fallback;
}

int _int(dynamic value, int fallback) {
  if (value is num) return value.toInt();
  return int.tryParse('$value') ?? fallback;
}

class _TrackerTimePickerSheet extends StatefulWidget {
  const _TrackerTimePickerSheet({required this.initial, required this.title});
  final TimeOfDay initial;
  final String title;

  @override
  State<_TrackerTimePickerSheet> createState() =>
      _TrackerTimePickerSheetState();
}

class _TrackerTimePickerSheetState extends State<_TrackerTimePickerSheet> {
  late int _hour;
  late int _minute;
  late final FixedExtentScrollController _hourController;
  late final FixedExtentScrollController _minuteController;

  @override
  void initState() {
    super.initState();
    _hour = widget.initial.hour.clamp(0, 23).toInt();
    _minute = widget.initial.minute.clamp(0, 59).toInt();
    _hourController = FixedExtentScrollController(initialItem: _hour);
    _minuteController = FixedExtentScrollController(initialItem: _minute);
  }

  @override
  void dispose() {
    _hourController.dispose();
    _minuteController.dispose();
    super.dispose();
  }

  void _popAfterMouseSettled<T>(BuildContext context, [T? result]) {
    Timer(const Duration(milliseconds: 140), () async {
      if (!context.mounted) return;
      await WidgetsBinding.instance.endOfFrame;
      if (!context.mounted) return;
      await Future<void>.delayed(Duration.zero);
      if (!context.mounted) return;
      FocusManager.instance.primaryFocus?.unfocus();
      await WidgetsBinding.instance.endOfFrame;
      if (!context.mounted) return;
      Navigator.pop<T>(context, result);
    });
  }

  @override
  Widget build(BuildContext context) {
    Widget wheel(
        {required FixedExtentScrollController controller,
        required int count,
        required ValueChanged<int> onChanged}) {
      return Expanded(
        child: ListWheelScrollView.useDelegate(
          controller: controller,
          itemExtent: 38,
          diameterRatio: 1.4,
          perspective: .004,
          physics: const FixedExtentScrollPhysics(),
          onSelectedItemChanged: onChanged,
          childDelegate: ListWheelChildBuilderDelegate(
            childCount: count,
            builder: (context, index) => Center(
              child: Text(index.toString().padLeft(2, '0'),
                  style: const TextStyle(
                      color: _AA.text,
                      fontSize: 21,
                      fontWeight: FontWeight.w700)),
            ),
          ),
        ),
      );
    }

    return SafeArea(
      child: SizedBox(
        height: 300,
        child:
            Column(crossAxisAlignment: CrossAxisAlignment.stretch, children: [
          Container(
            height: 44,
            padding: const EdgeInsets.symmetric(horizontal: 7),
            decoration: const BoxDecoration(
                border: Border(bottom: BorderSide(color: _AA.line))),
            child: Row(children: [
              const Icon(Icons.schedule_rounded, color: _AA.green, size: 18),
              const SizedBox(width: 8),
              Expanded(
                  child: Text(widget.title,
                      style: const TextStyle(
                          color: _AA.text,
                          fontSize: 12.4,
                          fontWeight: FontWeight.w700))),
              _NoHoverTap(
                  onTap: () => _popAfterMouseSettled<void>(context),
                  child: const SizedBox(
                      width: 34,
                      height: 34,
                      child: Icon(Icons.close_rounded,
                          color: _AA.muted, size: 18))),
            ]),
          ),
          Expanded(
            child: Row(children: [
              wheel(
                  controller: _hourController,
                  count: 24,
                  onChanged: (v) => setState(() => _hour = v)),
              const Text(':',
                  style: TextStyle(
                      color: _AA.text,
                      fontSize: 24,
                      fontWeight: FontWeight.w700)),
              wheel(
                  controller: _minuteController,
                  count: 60,
                  onChanged: (v) => setState(() => _minute = v)),
            ]),
          ),
          Padding(
            padding: const EdgeInsets.fromLTRB(12, 8, 12, 12),
            child: Row(children: [
              Expanded(
                  child: _NoHoverTap(
                      onTap: () => _popAfterMouseSettled<void>(context),
                      child: Container(
                          height: 38,
                          alignment: Alignment.center,
                          decoration: BoxDecoration(
                              color: _AA.card,
                              borderRadius: BorderRadius.circular(4)),
                          child: const Text('Отмена',
                              style: TextStyle(
                                  color: _AA.muted,
                                  fontWeight: FontWeight.w700))))),
              const SizedBox(width: 8),
              Expanded(
                  child: _NoHoverTap(
                      onTap: () => _popAfterMouseSettled<TimeOfDay>(
                          context, TimeOfDay(hour: _hour, minute: _minute)),
                      child: Container(
                          height: 38,
                          alignment: Alignment.center,
                          decoration: BoxDecoration(
                              color: _AA.green,
                              borderRadius: BorderRadius.circular(4)),
                          child: const Text('Выбрать',
                              style: TextStyle(
                                  color: Colors.white,
                                  fontWeight: FontWeight.w700))))),
            ]),
          ),
        ]),
      ),
    );
  }
}

class _NoHoverTap extends StatelessWidget {
  const _NoHoverTap({
    super.key,
    required this.child,
    this.onTap,
    this.onLongPress,
    this.borderRadius,
    this.hoverColor,
    this.splashColor,
  });

  final Widget child;
  final VoidCallback? onTap;
  final VoidCallback? onLongPress;
  final BorderRadiusGeometry? borderRadius;
  final Color? hoverColor;
  final Color? splashColor;

  void _runAfterMouseUpdate(BuildContext context, VoidCallback? callback) {
    if (callback == null) return;
    Timer(const Duration(milliseconds: 90), () async {
      if (!context.mounted) return;
      await WidgetsBinding.instance.endOfFrame;
      if (!context.mounted) return;
      await Future<void>.delayed(Duration.zero);
      if (!context.mounted) return;
      FocusManager.instance.primaryFocus?.unfocus();
      await WidgetsBinding.instance.endOfFrame;
      if (!context.mounted) return;
      callback();
    });
  }

  @override
  Widget build(BuildContext context) {
    return GestureDetector(
      behavior: HitTestBehavior.opaque,
      onTap: onTap == null ? null : () => _runAfterMouseUpdate(context, onTap),
      onLongPress: onLongPress == null
          ? null
          : () => _runAfterMouseUpdate(context, onLongPress),
      child: child,
    );
  }
}
